// OSHA 30 Hours Safety -- 769 Preguntas -- Maestro HVACR | maestrohvacr.com
// Categorias: OSHA_PPE (79), OSHA_RIESGO_ELECTRICO (115), OSHA_CAIDAS (45), OSHA_ESPACIOS_CONFINADOS (24), OSHA_ESCALERAS (18), OSHA_LOTO (23), OSHA_COMUNICACION_RIESGOS (32), OSHA_PRIMEROS_AUXILIOS (28), OSHA_QUEMADURAS (40), OSHA_INTRODUCCION (30), OSHA_RESPIRATORIA (40), OSHA_HERRAMIENTAS (35), OSHA_SUPERFICIES (30), OSHA_MAQUINARIA (30), OSHA_SOLDADURA (35), OSHA_EXCAVACIONES (25), OSHA_ANDAMIOS (25), OSHA_MATERIALES (30), OSHA_TOXICOS (35), OSHA_EMERGENCIAS (25), OSHA_RUIDO (25)
// 25 preguntas por quiz

var OSHA_QUESTIONS = [

  // -- PPE -- Equipo de Proteccion Personal (1-79) --
  { id:"osha_1", categoria:"OSHA_PPE", pregunta:"Si un técnico usa ropa de 100% poliéster bajo un traje de Arc Flash, ¿cuál es el peligro?", opciones:["Se ensucia más rápido", "El poliéster se puede derretir sobre la piel debido al calor transferido por el arco", "Aumenta la estática del multímetro", "No hay peligro si el traje exterior es Categoría 4"], respuesta_correcta:1, explicacion:"La ropa sintética se derrite a bajas temperaturas. Solo se permite algodón tratado o capas FR (Flame Resistant) debajo del EPP.", en_pregunta:"If a technician wears 100% polyester clothing under an Arc Flash suit, what is the hazard?", en_opciones:["It gets dirty faster","Polyester can melt onto the skin from the heat transferred by the arc","It increases multimeter static","There is no hazard if the outer suit is Category 4"], en_explicacion:"Synthetic clothing melts at low temperatures. Only treated cotton or FR (Flame Resistant) layers are allowed underneath PPE." },
  { id:"osha_2", categoria:"OSHA_PPE", pregunta:"En un sistema de refrigeración industrial con Amoníaco (R-717), el técnico debe saber que este gas es:", opciones:["Inodoro e inofensivo", "Altamente tóxico y también inflamable en ciertas concentraciones", "Más pesado que el aire y se queda en el suelo", "Seguro para respirar por 10 minutos"], respuesta_correcta:1, explicacion:"El amoníaco es tóxico, corrosivo y puede volverse explosivo si se mezcla con aire en proporciones del 15% al 28%.", en_pregunta:"In an industrial refrigeration system with Ammonia (R-717), the technician must know that this gas is:", en_opciones:["Odorless and harmless","Highly toxic and also flammable at certain concentrations","Heavier than air and settles on the floor","Safe to breathe for 10 minutes"], en_explicacion:"Ammonia is toxic, corrosive, and can become explosive when mixed with air at concentrations of 15% to 28%." },
  { id:"osha_3", categoria:"OSHA_PPE", pregunta:"¿Qué se debe hacer con una herramienta eléctrica que produce chispas excesivas en el conmutador?", opciones:["Soplar con aire comprimido", "Usarla hasta que termine el turno", "Retirarla de servicio para inspección de escobillas o bobinado", "Ponerse guantes más gruesos"], respuesta_correcta:2, explicacion:"Las chispas excesivas indican una falla eléctrica inminente o daño en el aislamiento que puede causar un choque al usuario.", en_pregunta:"What should be done with a power tool that produces excessive sparks at the commutator?", en_opciones:["Blow it out with compressed air","Keep using it until the end of the shift","Remove it from service for brush or winding inspection","Put on thicker gloves"], en_explicacion:"Excessive sparking indicates imminent electrical failure or insulation damage that can shock the user." },
  { id:"osha_4", categoria:"OSHA_PPE", pregunta:"¿Qué significa que un interruptor sea 'Current Limiting'?", opciones:["Que limita la factura de luz", "Que reduce el pico de corriente de falla para disminuir la energía del Arc Flash", "Que solo permite 10 Amperios", "Que no se dispara nunca"], respuesta_correcta:1, explicacion:"Los dispositivos limitadores de corriente abren tan rápido que la falla no alcanza su valor máximo, protegiendo al personal y al equipo.", en_pregunta:"What does it mean for a breaker to be 'Current Limiting'?", en_opciones:["That it limits your electric bill","That it reduces the peak fault current to lower Arc Flash energy","That it only allows 10 Amps","That it never trips"], en_explicacion:"Current-limiting devices open so quickly that the fault never reaches its maximum value, protecting personnel and equipment." },
  { id:"osha_5", categoria:"OSHA_PPE", pregunta:"Una amoladora (grinder) sin la guarda de seguridad instalada es una violación de qué tipo:", opciones:["Menor", "Seria / Grave", "De mantenimiento solamente", "No es violación si usas careta"], respuesta_correcta:1, explicacion:"OSHA considera la falta de guardas en partes rotativas como una violación seria que puede causar amputaciones.", en_pregunta:"A grinder without its safety guard installed is a violation of what type:", en_opciones:["Minor","Serious","Maintenance only","Not a violation if you wear a face shield"], en_explicacion:"OSHA considers missing guards on rotating parts to be a serious violation that can cause amputations." },
  { id:"osha_6", categoria:"OSHA_PPE", pregunta:"¿Cuál es la presión máxima permitida para usar aire comprimido en limpieza de manos o ropa?", opciones:["100 psi", "50 psi", "30 psi", "Está prohibido totalmente"], respuesta_correcta:2, explicacion:"OSHA prohíbe el uso de aire comprimido para limpieza personal a menos que la presión se reduzca a menos de 30 psi y se use protección ocular.", en_pregunta:"What is the maximum pressure allowed when using compressed air to clean hands or clothing?", en_opciones:["100 psi","50 psi","30 psi","It is completely prohibited"], en_explicacion:"OSHA prohibits the use of compressed air for personal cleaning unless the pressure is reduced to less than 30 psi and eye protection is used." },
  { id:"osha_7", categoria:"OSHA_PPE", pregunta:"¿Cuándo se debe inspeccionar el arnés de seguridad?", opciones:["Una vez al mes", "Cada vez que se use", "Solo después de una caída", "Cada vez que el inspector de OSHA venga"], respuesta_correcta:1, explicacion:"La inspección pre-uso es vital para detectar costuras rotas o corrosión en anillos D antes de que fallen.", en_pregunta:"When should a safety harness be inspected?", en_opciones:["Once a month","Every time it is used","Only after a fall","Only when the OSHA inspector comes"], en_explicacion:"Pre-use inspection is vital to detect broken stitching or corroded D-rings before they fail." },
  { id:"osha_8", categoria:"OSHA_PPE", pregunta:"En un sistema de refrigeración, el nitrógeno se usa para pruebas de fuga. ¿Qué dispositivo es OBLIGATORIO usar?", opciones:["Una manguera larga", "Un regulador de presión con válvula de alivio", "Un manómetro de baja presión", "Cinta aislante en las conexiones"], respuesta_correcta:1, explicacion:"Conectar nitrógeno directo del tanque (2500+ psi) a un sistema de refrigeración (diseñado para 500 psi) sin regulador causará una explosión fatal.", en_pregunta:"In a refrigeration system, nitrogen is used for leak testing. Which device is MANDATORY to use?", en_opciones:["A long hose","A pressure regulator with a relief valve","A low-pressure gauge","Electrical tape on the connections"], en_explicacion:"Connecting nitrogen directly from the tank (2,500+ psi) to a refrigeration system (designed for 500 psi) without a regulator will cause a fatal explosion." },
  { id:"osha_9", categoria:"OSHA_PPE", pregunta:"Si ves un cable eléctrico en el suelo con agua alrededor, debes:", opciones:["Saltar el charco", "Ponerse botas de goma y quitarlo", "Aislar el área y notificar al personal calificado para desenergizar", "Echarle arena"], respuesta_correcta:2, explicacion:"La seguridad perimetral es la primera responsabilidad del trabajador no calificado ante un peligro eléctrico.", en_pregunta:"If you see an electrical cable on the ground with water around it, you should:", en_opciones:["Jump over the puddle","Put on rubber boots and remove it","Isolate the area and notify qualified personnel to de-energize","Cover it with sand"], en_explicacion:"Perimeter safety is the first responsibility of an unqualified worker facing an electrical hazard." },
  { id:"osha_10", categoria:"OSHA_PPE", pregunta:"Si una extensión eléctrica se siente caliente al tacto mientras está en uso, significa:", opciones:["Que es de buena calidad", "Que el calibre del cable es muy pequeño para la carga (caída de tensión y calor)", "Que afuera hace calor", "Que el motor está enfriando el cable"], respuesta_correcta:1, explicacion:"El calor es un signo de resistencia excesiva. Un cable caliente es un riesgo de incendio inminente.", en_pregunta:"If an extension cord feels hot to the touch while in use, it means:", en_opciones:["That it is high quality","That the cable gauge is too small for the load (voltage drop and heat)","That it is hot outside","That the motor is cooling the cord"], en_explicacion:"Heat is a sign of excessive resistance. A hot cable is an imminent fire risk." },
  { id:"osha_11", categoria:"OSHA_PPE", pregunta:"Al soldar tubería de cobre (brazing), ¿por qué es importante usar lentes con filtro de sombra?", opciones:["Para verse profesional", "Para proteger contra la radiación infrarroja y el deslumbramiento que daña la retina", "Para ver el flujo del nitrógeno", "Porque OSHA lo dice solo para el acero"], respuesta_correcta:1, explicacion:"Incluso sin arco eléctrico, la llama de alta temperatura emite radiaciones que causan fatiga visual y daño a largo plazo.", en_pregunta:"When brazing copper tubing, why is it important to use shaded filter lenses?", en_opciones:["To look professional","To protect against infrared radiation and glare that damages the retina","To see the nitrogen flow","Because OSHA only requires it for steel"], en_explicacion:"Even without an electrical arc, the high-temperature flame emits radiation that causes eye strain and long-term damage." },
  { id:"osha_12", categoria:"OSHA_PPE", pregunta:"En un sistema de Amoníaco (R-717), ¿por qué está estrictamente prohibido usar tuberías o accesorios de cobre?", opciones:["Porque el cobre es muy caro", "El amoníaco corroe el cobre y sus aleaciones en presencia de humedad, causando fugas catastróficas", "El cobre hace que el amoníaco se caliente", "OSHA solo permite acero inoxidable por estética"], respuesta_correcta:1, explicacion:"El R-717 reacciona violentamente con metales no ferrosos como el cobre y el bronce.", en_pregunta:"In an Ammonia (R-717) system, why is using copper piping or fittings strictly prohibited?", en_opciones:["Because copper is very expensive","Ammonia corrodes copper and its alloys in the presence of moisture, causing catastrophic leaks","Copper makes ammonia heat up","OSHA only allows stainless steel for aesthetics"], en_explicacion:"R-717 reacts violently with non-ferrous metals such as copper and brass." },
  { id:"osha_13", categoria:"OSHA_PPE", pregunta:"Antes de soldar un sistema que contenía refrigerante A2L (levemente inflamable), ¿qué paso es obligatorio?", opciones:["Solo abrir las ventanas", "Evacuar el refrigerante, lavar con nitrógeno y verificar con un detector de fugas inflamables", "Soldar rápido antes de que se acumule gas", "Usar una llama más pequeña"], respuesta_correcta:1, explicacion:"Los refrigerantes como el R-32 o R-454B requieren protocolos de purga estrictos para evitar deflagraciones durante la soldadura.", en_pregunta:"Before brazing a system that contained an A2L (mildly flammable) refrigerant, what step is mandatory?", en_opciones:["Just open the windows","Recover the refrigerant, purge with nitrogen, and verify with a combustible leak detector","Braze quickly before gas accumulates","Use a smaller flame"], en_explicacion:"Refrigerants such as R-32 or R-454B require strict purging protocols to prevent deflagrations during brazing." },
  { id:"osha_14", categoria:"OSHA_PPE", pregunta:"¿Qué tipo de protección ocular es mejor para manejar refrigerante líquido?", opciones:["Lentes de sol", "Gafas de seguridad con protección lateral o careta completa", "Lentes de contacto", "No se requiere si cierras los ojos al abrir la válvula"], respuesta_correcta:1, explicacion:"El refrigerante líquido se evapora instantáneamente a temperaturas muy bajas, causando congelamiento inmediato de la córnea (ceguera).", en_pregunta:"What type of eye protection is best when handling liquid refrigerant?", en_opciones:["Sunglasses","Safety glasses with side shields or a full face shield","Contact lenses","None required if you close your eyes when opening the valve"], en_explicacion:"Liquid refrigerant evaporates instantly at very low temperatures, causing immediate freezing of the cornea (blindness)." },
  { id:"osha_15", categoria:"OSHA_PPE", pregunta:"Al usar una bomba de vacío, el técnico nota humo saliendo del escape. ¿Qué debe hacer?", opciones:["Nada, es normal que las bombas fumen", "Apagarla y revisar si hay una fuga masiva en el sistema o si el aceite está contaminado", "Echarle agua fría", "Tapar el escape con el dedo"], respuesta_correcta:1, explicacion:"El 'humo' suele ser neblina de aceite causada por bombear grandes cantidades de aire o vapor, indicando una falta de hermeticidad.", en_pregunta:"When using a vacuum pump, the technician notices smoke coming out of the exhaust. What should they do?", en_opciones:["Nothing, it is normal for pumps to smoke","Shut it off and check for a massive leak in the system or contaminated oil","Pour cold water on it","Cover the exhaust with a finger"], en_explicacion:"The 'smoke' is usually oil mist caused by pumping large amounts of air or vapor, indicating a lack of tightness." },
  { id:"osha_16", categoria:"OSHA_PPE", pregunta:"¿Cuál es la función del 'Vacuómetro' (Micron Gauge) desde el punto de vista de la seguridad a largo plazo?", opciones:["Medir la presión de carga", "Asegurar que no queden no-condensables ni humedad que generen ácidos y fallas eléctricas (hermetic burnout)", "Ver si la bomba tiene aceite", "Limpiar las tuberías"], respuesta_correcta:1, explicacion:"Un vacío profundo (500 micrones) elimina el aire y la humedad, previniendo la degradación química del sistema.", en_pregunta:"What is the function of the 'Micron Gauge' from a long-term safety standpoint?", en_opciones:["To measure charging pressure","To ensure no non-condensables or moisture remain that could generate acids and lead to electrical failures (hermetic burnout)","To see if the pump has oil","To clean the lines"], en_explicacion:"A deep vacuum (500 microns) removes air and moisture, preventing chemical degradation of the system." },
  { id:"osha_17", categoria:"OSHA_PPE", pregunta:"El casco de seguridad 'Clase E' (Electrical) está diseñado para soportar hasta:", opciones:["2,000 voltios", "10,000 voltios", "20,000 voltios", "No protege contra electricidad"], respuesta_correcta:2, explicacion:"La clase E está probada para 20,000 voltios, siendo el estándar para electricistas y técnicos HVAC industriales.", en_pregunta:"A Class E (Electrical) hard hat is designed to withstand up to:", en_opciones:["2,000 volts","10,000 volts","20,000 volts","It does not protect against electricity"], en_explicacion:"Class E is tested to 20,000 volts and is the standard for electricians and industrial HVAC technicians." },
  { id:"osha_18", categoria:"OSHA_PPE", pregunta:"Usar un destornillador como palanca o cincel es:", opciones:["Una práctica eficiente", "Una violación de seguridad que puede resultar en la rotura de la herramienta y lesiones oculares", "Permitido si el mango es de goma", "Solo permitido en sistemas residenciales"], respuesta_correcta:1, explicacion:"Las herramientas deben usarse únicamente para el propósito que fueron diseñadas.", en_pregunta:"Using a screwdriver as a pry bar or chisel is:", en_opciones:["An efficient practice","A safety violation that can result in tool breakage and eye injuries","Allowed if the handle is rubber","Only allowed in residential systems"], en_explicacion:"Tools must only be used for the purpose for which they were designed." },
  { id:"osha_19", categoria:"OSHA_PPE", pregunta:"Un sensor de flujo de agua (Flow Switch) en un Chiller es un dispositivo de:", opciones:["Confort", "Seguridad para evitar que el intercambiador se congele y reviente", "Ahorro de energía", "Medición de temperatura"], respuesta_correcta:1, explicacion:"Si el agua deja de fluir y el enfriador sigue operando, el agua estancada se congela y expande, rompiendo los tubos internos.", en_pregunta:"A water flow switch on a chiller is a device used for:", en_opciones:["Comfort","Safety, to prevent the heat exchanger from freezing and rupturing","Energy savings","Temperature measurement"], en_explicacion:"If water stops flowing and the chiller keeps operating, the stagnant water freezes and expands, rupturing the internal tubes." },
  { id:"osha_20", categoria:"OSHA_PPE", pregunta:"Un sistema con una carga de más de 50 lbs de refrigerante tiene una fuga. Según EPA, el límite de tiempo para repararla antes de que sea una violación legal es de:", opciones:["24 horas", "30 días", "6 meses", "No hay límite"], respuesta_correcta:1, explicacion:"Bajo la Sección 608 de la Ley de Aire Limpio, hay plazos estrictos de reparación según el tipo de equipo.", en_pregunta:"A system with a charge of more than 50 lbs of refrigerant has a leak. According to the EPA, the time limit to repair it before it becomes a legal violation is:", en_opciones:["24 hours","30 days","6 months","There is no limit"], en_explicacion:"Under Section 608 of the Clean Air Act, there are strict repair deadlines depending on equipment type." },
  { id:"osha_21", categoria:"OSHA_PPE", pregunta:"¿Cuándo deben usarse tapones para los oídos en una sala de máquinas?", opciones:["Cuando el técnico quiera", "Cuando el nivel de ruido supere los 85-90 dB de promedio ponderado", "Solo si hay música fuerte", "Nunca, si el técnico está acostumbrado"], respuesta_correcta:1, explicacion:"La pérdida auditiva es irreversible y acumulativa.", en_pregunta:"When should hearing protection be worn in a mechanical room?", en_opciones:["Whenever the technician feels like it","When the noise level exceeds 85-90 dB time-weighted average","Only if there is loud music","Never, if the technician is used to it"], en_explicacion:"Hearing loss is irreversible and cumulative." },
  { id:"osha_22", categoria:"OSHA_PPE", pregunta:"Un detector de fugas electrónico pita constantemente en una habitación vacía. Esto se llama 'Falsa alarma' y puede ser causado por:", opciones:["Falta de batería", "Vapores de solventes, alcohol o falta de aire fresco (sensor contaminado)", "Que hay mucho oro cerca", "El campo magnético de la tierra"], respuesta_correcta:1, explicacion:"Los sensores de diodo caliente o corona pueden reaccionar a diversos hidrocarburos, no solo a refrigerantes.", en_pregunta:"An electronic leak detector beeps constantly in an empty room. This is called a 'false alarm' and can be caused by:", en_opciones:["Low battery","Solvent vapors, alcohol, or lack of fresh air (contaminated sensor)","A lot of gold nearby","The Earth's magnetic field"], en_explicacion:"Heated-diode or corona sensors can react to various hydrocarbons, not just refrigerants." },
  { id:"osha_23", categoria:"OSHA_PPE", pregunta:"¿Qué tipo de guantes son obligatorios al manipular baterías de litio de gran escala (ESS)?", opciones:["Guantes de tela", "Guantes aislantes de goma clase 0 con protectores de cuero y resistencia química", "Guantes de soldador", "No se usan guantes para tener mejor tacto"], respuesta_correcta:1, explicacion:"Se requiere protección tanto eléctrica (voltaje de la batería) como química (posibles fugas de electrolito).", en_pregunta:"What type of gloves are mandatory when handling large-scale lithium batteries (ESS)?", en_opciones:["Cloth gloves","Class 0 insulating rubber gloves with leather protectors and chemical resistance","Welding gloves","No gloves, for better tactile feel"], en_explicacion:"Both electrical (battery voltage) and chemical (possible electrolyte leaks) protection are required." },
  { id:"osha_24", categoria:"OSHA_PPE", pregunta:"¿Qué indica el símbolo de un doble cuadrado (un cuadrado dentro de otro) en una herramienta eléctrica?", opciones:["Que es de alta potencia", "Que tiene doble aislamiento y no requiere conexión a tierra (third prong)", "Que es para uso exclusivo en interiores", "Que fue hecha en ACVOLT"], respuesta_correcta:1, explicacion:"El doble aislamiento protege al usuario de fallas internas sin depender de una conexión a tierra externa.", en_pregunta:"What does the double-square symbol (one square inside another) on a power tool indicate?", en_opciones:["That it is high-powered","That it has double insulation and does not require a third-prong ground connection","That it is for indoor use only","That it was made by ACVOLT"], en_explicacion:"Double insulation protects the user from internal faults without relying on an external ground connection." },
  { id:"osha_25", categoria:"OSHA_PPE", pregunta:"¿Qué es el 'Rápido Apagado' (Rapid Shutdown) en sistemas solares según el NEC?", opciones:["Apagar las luces de la casa", "Un sistema que reduce el voltaje de los cables en el techo a niveles seguros (30V o menos) en 30 segundos tras activarse", "Desconectar la batería", "Un extintor automático"], respuesta_correcta:1, explicacion:"Esta función protege a los bomberos y personal de emergencia de electrocutarse al trabajar en el techo durante un incendio.", en_pregunta:"What is 'Rapid Shutdown' in solar systems according to the NEC?", en_opciones:["Turning off the house lights","A system that reduces rooftop conductor voltage to safe levels (30V or less) within 30 seconds of activation","Disconnecting the battery","An automatic fire extinguisher"], en_explicacion:"This function protects firefighters and emergency personnel from electrocution when working on the roof during a fire." },
  { id:"osha_26", categoria:"OSHA_PPE", pregunta:"Un casco de seguridad que ha sufrido un impacto fuerte pero no se ve roto, ¿puede seguir usándose?", opciones:["Sí, si se ve bien", "No, debe ser reemplazado ya que su estructura interna pudo haberse debilitado", "Solo si el jefe lo autoriza", "Solo si es de marca cara"], respuesta_correcta:1, explicacion:"La capacidad de absorción de energía de un casco es de un solo uso crítico.", en_pregunta:"Can a hard hat that has taken a hard impact but does not appear cracked still be used?", en_opciones:["Yes, if it looks fine","No, it must be replaced since its internal structure may have been weakened","Only if the supervisor approves","Only if it is an expensive brand"], en_explicacion:"A hard hat's energy-absorbing capacity is critically single-use." },
  { id:"osha_27", categoria:"OSHA_PPE", pregunta:"Un 'Punto de Anclaje' para un sistema de detención de caídas debe ser capaz de soportar:", opciones:["1,000 lbs por persona", "5,000 lbs por cada persona conectada", "El peso de la escalera", "500 lbs"], respuesta_correcta:1, explicacion:"Debe soportar el impacto de una caída libre, lo cual multiplica el peso del trabajador por la aceleración.", en_pregunta:"An 'Anchor Point' for a fall arrest system must be capable of supporting:", en_opciones:["1,000 lbs per person","5,000 lbs per person connected","The weight of the ladder","500 lbs"], en_explicacion:"It must withstand the impact of a free fall, which multiplies the worker's weight by acceleration." },
  { id:"osha_28", categoria:"OSHA_PPE", pregunta:"Al usar un soplete de Oxiacetileno, ¿por qué nunca se debe usar aceite o grasa en los reguladores de Oxígeno?", opciones:["Porque ensucian las manos", "El oxígeno puro bajo presión reacciona violentamente con hidrocarburos (aceite/grasa) causando una explosión", "Porque el aceite bloquea el gas", "Porque el soplete no prenderá"], respuesta_correcta:1, explicacion:"El oxígeno es un comburente extremadamente potente; la grasa actúa como combustible y la presión genera el calor de ignición.", en_pregunta:"When using an oxy-acetylene torch, why should you never use oil or grease on the oxygen regulators?", en_opciones:["Because it dirties your hands","Pure oxygen under pressure reacts violently with hydrocarbons (oil/grease), causing an explosion","Because the oil blocks the gas","Because the torch won't light"], en_explicacion:"Oxygen is an extremely powerful oxidizer; grease acts as fuel and the pressure generates the heat of ignition." },
  { id:"osha_29", categoria:"OSHA_PPE", pregunta:"Un trabajador de menos de 18 años tiene prohibido por OSHA:", opciones:["Usar un martillo", "Operar la mayoría de la maquinaria pesada, como montacargas o sierras de gran potencia", "Trabajar después de las 5 PM", "Llevar el almuerzo"], respuesta_correcta:1, explicacion:"Existen restricciones de seguridad estrictas para menores en ocupaciones peligrosas de construcción.", en_pregunta:"Workers under 18 are prohibited by OSHA from:", en_opciones:["Using a hammer","Operating most heavy machinery, such as forklifts or high-power saws","Working past 5 PM","Bringing their own lunch"], en_explicacion:"Strict safety restrictions apply to minors in hazardous construction occupations." },
  { id:"osha_30", categoria:"OSHA_PPE", pregunta:"En un evaporador, el 'Superheat' muy bajo (0°F) es un signo de seguridad de:", opciones:["Excelente eficiencia", "Inundación de líquido hacia el compresor (Liquid Slug)", "Falta de refrigerante", "Filtro de aire limpio"], respuesta_correcta:1, explicacion:"0°F de sobrecalentamiento significa que el refrigerante es líquido puro, lo cual destruirá el compresor.", en_pregunta:"In an evaporator, a very low superheat (0 F) is a safety indicator of:", en_opciones:["Excellent efficiency","Liquid flooding back to the compressor (liquid slug)","Low refrigerant","A clean air filter"], en_explicacion:"0 F of superheat means the refrigerant is pure liquid, which will destroy the compressor." },
  { id:"osha_31", categoria:"OSHA_PPE", pregunta:"Al usar una llave ajustable (Crescent wrench), la fuerza debe aplicarse:", opciones:["Hacia la mandíbula fija", "Hacia la mandíbula móvil", "No importa la dirección", "Siempre empujando con la palma"], respuesta_correcta:0, explicacion:"Tirar hacia la mandíbula fija evita que la llave se abra o se resbale, previniendo lesiones en los nudillos.", en_pregunta:"When using an adjustable (crescent) wrench, force should be applied toward:", en_opciones:["The fixed jaw","The movable jaw","Direction does not matter","Always pushing with the palm"], en_explicacion:"Pulling toward the fixed jaw prevents the wrench from opening or slipping, preventing knuckle injuries." },
  { id:"osha_32", categoria:"OSHA_PPE", pregunta:"Antes de entrar a un cuarto de máquinas con Amoníaco tras una alarma, el técnico debe usar:", opciones:["Una toalla mojada", "Un SCBA (Self-Contained Breathing Apparatus) y traje de protección química", "Solo lentes de seguridad", "Correr muy rápido"], respuesta_correcta:1, explicacion:"El amoníaco en altas concentraciones quema los pulmones y la piel húmeda instantáneamente.", en_pregunta:"Before entering a machinery room with ammonia after an alarm, the technician must wear:", en_opciones:["A wet towel","An SCBA (Self-Contained Breathing Apparatus) and a chemical protective suit","Just safety glasses","Run very fast"], en_explicacion:"Ammonia in high concentrations instantly burns the lungs and moist skin." },
  { id:"osha_33", categoria:"OSHA_PPE", pregunta:"¿Qué significa el marcado 'Z87+' en unos lentes de seguridad?", opciones:["Que son para ver de lejos", "Que están certificados para alto impacto", "Que son resistentes al agua", "Que son marca ACVOLT"], respuesta_correcta:1, explicacion:"El signo '+' indica que pasaron la prueba de impacto de alta masa y alta velocidad.", en_pregunta:"What does the 'Z87+' marking on safety glasses mean?", en_opciones:["That they are for distance vision","That they are certified for high impact","That they are water resistant","That they are ACVOLT brand"], en_explicacion:"The '+' sign indicates they passed the high-mass, high-velocity impact test." },
  { id:"osha_34", categoria:"OSHA_PPE", pregunta:"Al trabajar con R-410A, ¿por qué los manómetros de R-22 no son seguros?", opciones:["Porque los colores son distintos", "Porque el R-410A opera a presiones mucho más altas y puede reventar el vidrio o mangueras de un manifold viejo", "Porque el aceite no es compatible", "Porque el R-22 es ilegal"], respuesta_correcta:1, explicacion:"La seguridad física depende de usar herramientas con el rating de presión adecuado (800 psi en el lado de alta para R-410A).", en_pregunta:"When working with R-410A, why are R-22 manifold gauges not safe?", en_opciones:["Because the colors are different","Because R-410A operates at much higher pressures and can burst the glass or hoses of an old manifold","Because the oil is not compatible","Because R-22 is illegal"], en_explicacion:"Physical safety depends on using tools with the proper pressure rating (800 psi on the high side for R-410A)." },
  { id:"osha_35", categoria:"OSHA_PPE", pregunta:"¿Qué es una 'JSA' (Job Safety Analysis)?", opciones:["Un examen médico", "Un proceso de identificar peligros paso a paso antes de iniciar una tarea específica", "Un reporte de ventas", "Una junta de sindicato"], respuesta_correcta:1, explicacion:"La JSA permite al equipo planificar cómo mitigar cada riesgo antes de que ocurra un accidente.", en_pregunta:"What is a JSA (Job Safety Analysis)?", en_opciones:["A medical exam","A step-by-step process to identify hazards before starting a specific task","A sales report","A union meeting"], en_explicacion:"The JSA allows the team to plan how to mitigate each risk before an accident occurs." },
  { id:"osha_36", categoria:"OSHA_PPE", pregunta:"Al cargar refrigerante en fase líquida por la línea de succión, ¿cuál es el peligro?", opciones:["El sistema enfría más rápido", "Golpe de líquido al compresor (slugging) y daño a las válvulas", "Que el refrigerante se congele", "No hay peligro si el tanque está al revés"], respuesta_correcta:1, explicacion:"Cargar líquido por succión debe hacerse con extrema precaución (dosificando) o a través de un dispositivo de expansión para evitar romper el compresor.", en_pregunta:"When charging liquid refrigerant through the suction line, what is the hazard?", en_opciones:["The system cools faster","Liquid slugging the compressor and damaging the valves","That the refrigerant will freeze","There is no hazard if the tank is inverted"], en_explicacion:"Charging liquid through suction must be done with extreme caution (metered) or through an expansion device to avoid breaking the compressor." },
  { id:"osha_37", categoria:"OSHA_PPE", pregunta:"En un sitio de construcción, ¿qué color de cable está prohibido usar para conductores de fase (Hot) según OSHA?", opciones:["Rojo", "Negro", "Verde o Blanco", "Azul"], respuesta_correcta:2, explicacion:"El verde se reserva para tierra (EGC) y el blanco/gris para neutro. Usarlos como fase es una violación grave que causa choques por confusión.", en_pregunta:"On a construction site, which wire color is prohibited by OSHA for use as a phase (hot) conductor?", en_opciones:["Red","Black","Green or white","Blue"], en_explicacion:"Green is reserved for ground (EGC) and white/gray for neutral. Using them as phase is a serious violation that causes shocks from confusion." },
  { id:"osha_38", categoria:"OSHA_PPE", pregunta:"Al usar guantes aislantes de goma, ¿por qué es obligatorio usar el protector de cuero encima?", opciones:["Para que no se ensucien", "Para proteger la goma contra pinchazos, cortes o abrasiones que anularían su capacidad dieléctrica", "Para que el técnico tenga mejor agarre", "Porque OSHA lo dice por estética"], respuesta_correcta:1, explicacion:"Un pinchazo microscópico en la goma permite que miles de voltios pasen directamente a la mano.", en_pregunta:"When wearing insulating rubber gloves, why is the leather protector over them mandatory?", en_opciones:["So they don't get dirty","To protect the rubber against punctures, cuts, or abrasions that would void its dielectric capacity","So the technician gets a better grip","Because OSHA requires it for aesthetics"], en_explicacion:"A microscopic puncture in the rubber allows thousands of volts to pass directly to the hand." },
  { id:"osha_39", categoria:"OSHA_PPE", pregunta:"¿Qué sucede con la ropa de algodón normal (No-FR) durante un evento de Arc Flash?", opciones:["Protege la piel", "Se incendia y continúa ardiendo sobre el cuerpo, agravando severamente las quemaduras", "Se evapora sin dejar rastro", "Se vuelve aislante"], respuesta_correcta:1, explicacion:"La ropa que no es FR (Resistente al Fuego) actúa como combustible en un arco eléctrico.", en_pregunta:"What happens to normal (non-FR) cotton clothing during an Arc Flash event?", en_opciones:["It protects the skin","It ignites and keeps burning on the body, severely worsening burns","It evaporates without a trace","It becomes an insulator"], en_explicacion:"Non-FR (Flame Resistant) clothing acts as fuel during an electrical arc." },
  { id:"osha_40", categoria:"OSHA_PPE", pregunta:"¿Cuál es la jerarquía de controles de OSHA para eliminar peligros (del más efectivo al menos)?", opciones:["EPP, Ingeniería, Eliminación", "Eliminación, Sustitución, Ingeniería, Administrativo, EPP", "Administrativo, EPP, Sustitución", "Eliminación, EPP, Ingeniería"], respuesta_correcta:1, explicacion:"El EPP es siempre la última línea de defensa, no la primera.", en_pregunta:"What is OSHA's hierarchy of controls to eliminate hazards (most to least effective)?", en_opciones:["PPE, Engineering, Elimination","Elimination, Substitution, Engineering, Administrative, PPE","Administrative, PPE, Substitution","Elimination, PPE, Engineering"], en_explicacion:"PPE is always the last line of defense, not the first." },
  { id:"osha_41", categoria:"OSHA_PPE", pregunta:"¿Por qué es peligroso usar un cincel con la cabeza 'hongueada' (espachurrada por golpes)?", opciones:["No corta bien", "Pedazos de metal pueden salir volando como metralla al ser golpeados", "Pesa más", "Se ve mal ante el cliente"], respuesta_correcta:1, explicacion:"El metal fatigado se desprende violentamente bajo el impacto de un martillo.", en_pregunta:"Why is it dangerous to use a chisel with a 'mushroomed' head (flattened from being struck)?", en_opciones:["It doesn't cut well","Pieces of metal can fly off like shrapnel when struck","It weighs more","It looks unprofessional to the client"], en_explicacion:"Fatigued metal breaks off violently under the impact of a hammer." },
  { id:"osha_42", categoria:"OSHA_PPE", pregunta:"Antes de trabajar en la banda de un motor industrial, además de LOTO eléctrico, ¿qué seguridad mecánica es vital?", opciones:["Limpiar la banda", "Bloquear físicamente la rotación (chocking) para evitar que la carga mueva el motor", "Ponerle aceite", "Quitar el motor"], respuesta_correcta:1, explicacion:"La energía mecánica almacenada (como ventiladores movidos por el viento o gravedad) puede causar amputaciones.", en_pregunta:"Before working on the belt of an industrial motor, beyond electrical LOTO, what mechanical safety step is vital?", en_opciones:["Cleaning the belt","Physically blocking the rotation (chocking) to prevent the load from moving the motor","Oiling it","Removing the motor"], en_explicacion:"Stored mechanical energy (such as fans turned by wind or gravity) can cause amputations." },
  { id:"osha_43", categoria:"OSHA_PPE", pregunta:"¿Qué altura mínima de caída requiere protección en la industria general (1910) comparado con construcción (1926)?", opciones:["6 pies en ambas", "4 pies en industria general / 6 pies en construcción", "10 pies en ambas", "2 pies en industria general"], respuesta_correcta:1, explicacion:"OSHA tiene estándares más estrictos para el mantenimiento industrial (4 pies) que para la construcción (6 pies).", en_pregunta:"What minimum fall height requires protection in General Industry (1910) compared to Construction (1926)?", en_opciones:["6 feet in both","4 feet in General Industry / 6 feet in Construction","10 feet in both","2 feet in General Industry"], en_explicacion:"OSHA has stricter standards for industrial maintenance (4 feet) than for construction (6 feet)." },
  { id:"osha_44", categoria:"OSHA_PPE", pregunta:"Un casco clase G (General) protege contra voltajes de hasta:", opciones:["250V", "2,200V", "20,000V", "No protege contra electricidad"], respuesta_correcta:1, explicacion:"Clase G (2,200V); Clase E (20,000V); Clase C (Conductivo, no protege).", en_pregunta:"A Class G (General) hard hat protects against voltages up to:", en_opciones:["250V","2,200V","20,000V","It does not protect against electricity"], en_explicacion:"Class G (2,200V); Class E (20,000V); Class C (Conductive, no protection)." },
  { id:"osha_45", categoria:"OSHA_PPE", pregunta:"¿Quién debe pagar por el EPP (cascos, guantes, lentes) según la ley OSHA?", opciones:["El trabajador", "El sindicato", "El empleador (patrón)", "El cliente"], respuesta_correcta:2, explicacion:"Es obligación legal del empleador proveer el equipo de seguridad necesario sin costo para el empleado (salvo excepciones muy raras).", en_pregunta:"Who must pay for PPE (hard hats, gloves, glasses) under OSHA law?", en_opciones:["The worker","The union","The employer","The client"], en_explicacion:"It is the employer's legal duty to provide necessary safety equipment at no cost to the employee (with very rare exceptions)." },
  { id:"osha_46", categoria:"OSHA_PPE", pregunta:"Una herramienta neumática debe tener qué dispositivo de seguridad en la conexión de la manguera?", opciones:["Cinta", "Un clip o cable de seguridad (Whip check) para evitar que la manguera 'latiguee' si se suelta", "Aceite", "Un silenciador"], respuesta_correcta:1, explicacion:"Evita lesiones graves por el movimiento incontrolado de una manguera bajo presión.", en_pregunta:"A pneumatic tool must have what safety device on the hose connection?", en_opciones:["Tape","A whip check clip or safety cable to prevent the hose from whipping if it disconnects","Oil","A silencer"], en_explicacion:"This prevents serious injuries from the uncontrolled movement of a pressurized hose." },
  { id:"osha_47", categoria:"OSHA_PPE", pregunta:"¿Cuál es el propósito del 'Focus Four' de OSHA?", opciones:["Aprender a usar la cámara", "Identificar las 4 causas principales de muerte: Caídas, Electrocución, Atrapamiento y Golpeado por", "Saber los 4 colores de seguridad", "Las 4 horas de descanso"], respuesta_correcta:1, explicacion:"Estos cuatro peligros causan la gran mayoría de las fatalidades en construcción.", en_pregunta:"What is the purpose of OSHA's 'Focus Four'?", en_opciones:["Learning how to use the camera","To identify the 4 main causes of fatalities: Falls, Electrocution, Caught-Between, and Struck-By","Knowing the 4 safety colors","The 4 hours of break"], en_explicacion:"These four hazards cause the vast majority of construction fatalities." },
  { id:"osha_48", categoria:"OSHA_PPE", pregunta:"¿Cuál es la vida útil promedio de un casco de seguridad de plástico desde su fecha de fabricación?", opciones:["Toda la vida", "2 a 5 años (según el fabricante y exposición)", "20 años", "6 meses"], respuesta_correcta:1, explicacion:"El plástico se degrada con el tiempo y los rayos UV, perdiendo resistencia al impacto.", en_pregunta:"What is the average service life of a plastic hard hat from its date of manufacture?", en_opciones:["A lifetime","2 to 5 years (depending on manufacturer and exposure)","20 years","6 months"], en_explicacion:"Plastic degrades over time and from UV rays, losing impact resistance." },
  { id:"osha_49", categoria:"OSHA_PPE", pregunta:"Un sistema de barandillas debe tener una altura de riel superior de:", opciones:["30 pulgadas", "42 pulgadas (+/- 3 pulgadas)", "60 pulgadas", "24 pulgadas"], respuesta_correcta:1, explicacion:"Es la altura estándar para evitar que el centro de gravedad de una persona pase por encima del riel.", en_pregunta:"A guardrail system must have a top rail height of:", en_opciones:["30 inches","42 inches (+/- 3 inches)","60 inches","24 inches"], en_explicacion:"This is the standard height to prevent a person's center of gravity from going over the rail." },
  { id:"osha_50", categoria:"OSHA_PPE", pregunta:"¿Qué clase de extintor NO debe usarse en un incendio eléctrico?", opciones:["Clase C", "Clase A de agua (Chorro de agua)", "Agente limpio", "CO2"], respuesta_correcta:1, explicacion:"El agua es conductora y puede electrocutar al bombero si el equipo está energizado.", en_pregunta:"Which class of extinguisher should NOT be used on an electrical fire?", en_opciones:["Class C","Class A water (water stream)","Clean agent","CO2"], en_explicacion:"Water is conductive and can electrocute the firefighter if the equipment is energized." },
  { id:"osha_51", categoria:"OSHA_PPE", pregunta:"¿Qué es una 'Violación Willful' (Intencional) de OSHA?", opciones:["Un accidente sin querer", "Cuando el empleador ignora deliberadamente una norma de seguridad sabiendo que hay peligro", "No usar casco un día", "Llegar tarde al trabajo"], respuesta_correcta:1, explicacion:"Son las violaciones con las multas más altas y posibles cargos criminales.", en_pregunta:"What is a 'Willful' OSHA violation?", en_opciones:["An unintentional accident","When the employer deliberately disregards a safety standard knowing there is danger","Not wearing a hard hat one day","Arriving late to work"], en_explicacion:"These violations carry the highest fines and possible criminal charges." },
  { id:"osha_52", categoria:"OSHA_PPE", pregunta:"Un martillo con el mango rajado o suelto es:", opciones:["Fácil de arreglar con pegamento", "Una violación que exige retirar la herramienta de servicio inmediatamente", "Seguro si se usa con cuidado", "Mejor para el balance"], respuesta_correcta:1, explicacion:"La cabeza del martillo puede salir disparada, convirtiéndose en un proyectil letal.", en_pregunta:"A hammer with a cracked or loose handle is:", en_opciones:["Easy to fix with glue","A violation that requires the tool to be removed from service immediately","Safe if used carefully","Better balanced"], en_explicacion:"The hammer head can fly off, becoming a lethal projectile." },
  { id:"osha_53", categoria:"OSHA_PPE", pregunta:"¿Quién es responsable de inspeccionar el EPP antes de cada uso?", opciones:["El supervisor", "El inspector de OSHA", "El usuario (trabajador)", "El fabricante"], respuesta_correcta:2, explicacion:"El trabajador es la última línea de defensa y debe asegurar que su equipo está en condiciones óptimas.", en_pregunta:"Who is responsible for inspecting PPE before each use?", en_opciones:["The supervisor","The OSHA inspector","The user (worker)","The manufacturer"], en_explicacion:"The worker is the last line of defense and must ensure their equipment is in optimal condition." },
  { id:"osha_54", categoria:"OSHA_PPE", pregunta:"¿Cuál es el riesgo de seguridad al apilar materiales de construcción demasiado altos?", opciones:["Que se vean mal", "Inestabilidad y colapso sobre los trabajadores", "Que el cliente no los encuentre", "No hay riesgo"], respuesta_correcta:1, explicacion:"El apilamiento requiere seguir límites de altura y asegurar la base para evitar derrumbes.", en_pregunta:"What is the safety risk of stacking construction materials too high?", en_opciones:["That they look bad","Instability and collapse onto workers","The client can't find them","There is no risk"], en_explicacion:"Stacking requires following height limits and securing the base to prevent collapses." },
  { id:"osha_55", categoria:"OSHA_PPE", pregunta:"¿Cuándo debe usarse protección respiratoria con suministro de aire (SCBA)?", opciones:["En cualquier trabajo", "En atmósferas IDLH (Inmediatamente Peligrosas para la Vida o la Salud) o con deficiencia de oxígeno", "Cuando hay mucho polvo de madera", "Para no oler el solvente"], respuesta_correcta:1, explicacion:"Los respiradores de cartucho no sirven en ambientes sin oxígeno o con altas concentraciones de gases tóxicos.", en_pregunta:"When must supplied-air respiratory protection (SCBA) be used?", en_opciones:["On any job","In IDLH (Immediately Dangerous to Life or Health) atmospheres or in oxygen-deficient environments","When there is a lot of wood dust","To not smell the solvent"], en_explicacion:"Cartridge respirators don't work in oxygen-deficient environments or in high concentrations of toxic gases." },
  { id:"osha_56", categoria:"OSHA_PPE", pregunta:"¿Por qué un técnico debe quitarse los anillos de metal antes de trabajar en un panel eléctrico?", opciones:["Para no rayar el panel", "Para evitar quemaduras severas por contacto accidental o inducción térmica en caso de arco", "Para que no se pierdan", "No es necesario si usa guantes de tela"], respuesta_correcta:1, explicacion:"El metal del anillo puede fundirse con la piel en milisegundos durante un cortocircuito.", en_pregunta:"Why should a technician remove metal rings before working in an electrical panel?", en_opciones:["To not scratch the panel","To avoid severe burns from accidental contact or thermal induction during an arc","So they don't get lost","It isn't necessary if you wear cloth gloves"], en_explicacion:"The metal of a ring can fuse with the skin within milliseconds during a short circuit." },
  { id:"osha_57", categoria:"OSHA_PPE", pregunta:"Se permite usar una sierra circular cuya guarda de seguridad ha sido bloqueada hacia atrás para cortes rápidos:", opciones:["Si el técnico tiene mucha experiencia", "Nunca; es una violación de seguridad extremadamente peligrosa", "Solo en cortes de madera blanda", "Solo si se usa careta"], respuesta_correcta:1, explicacion:"Las guardas retractables están ahí para proteger los dedos tras terminar el corte; bloquearlas causa miles de amputaciones al año.", en_pregunta:"Using a circular saw whose blade guard has been wedged back for faster cuts is allowed:", en_opciones:["If the technician has a lot of experience","Never; it is an extremely dangerous safety violation","Only on soft wood cuts","Only if a face shield is used"], en_explicacion:"Retractable guards exist to protect fingers after the cut is complete; blocking them causes thousands of amputations each year." },
  { id:"osha_58", categoria:"OSHA_PPE", pregunta:"¿Cuándo se deben retirar los escombros y basura inflamable de un sitio de trabajo?", opciones:["Al final del proyecto", "Una vez al mes", "A intervalos regulares y al final de cada turno", "Solo si el inspector viene"], respuesta_correcta:2, explicacion:"La limpieza es fundamental para prevenir caídas e incendios espontáneos.", en_pregunta:"When must flammable debris and trash be removed from a work site?", en_opciones:["At the end of the project","Once a month","At regular intervals and at the end of each shift","Only if the inspector comes"], en_explicacion:"Housekeeping is fundamental to preventing falls and spontaneous fires." },
  { id:"osha_59", categoria:"OSHA_PPE", pregunta:"Un técnico usa un destornillador para probar si una batería tiene carga haciendo un corto entre terminales. Esto es:", opciones:["Una prueba rápida aceptable", "Un acto inseguro que puede causar la explosión de la batería y proyección de ácido", "Permitido en baterías pequeñas", "Una técnica avanzada de ACVOLT"], respuesta_correcta:1, explicacion:"Nunca se debe puentear una batería; la corriente de cortocircuito es inmensa y peligrosa.", en_pregunta:"A technician uses a screwdriver to check if a battery has charge by shorting the terminals. This is:", en_opciones:["An acceptable quick test","An unsafe act that can cause the battery to explode and spray acid","Allowed on small batteries","An advanced ACVOLT technique"], en_explicacion:"You must never short a battery; the short-circuit current is enormous and dangerous." },
  { id:"osha_60", categoria:"OSHA_PPE", pregunta:"Si un casco de seguridad tiene una rajadura pequeña, ¿se puede reparar con resina?", opciones:["Sí, si queda fuerte", "No; cualquier daño estructural anula la certificación y el casco debe ser destruido", "Solo si la rajadura es por fuera", "Sí, con cinta Gorilla"], respuesta_correcta:1, explicacion:"Las reparaciones caseras no están probadas y pueden fallar ante un impacto real.", en_pregunta:"If a hard hat has a small crack, can it be repaired with resin?", en_opciones:["Yes, if it ends up strong","No; any structural damage voids the certification and the helmet must be destroyed","Only if the crack is on the outside","Yes, with Gorilla Tape"], en_explicacion:"Homemade repairs are untested and can fail on a real impact." },
  { id:"osha_61", categoria:"OSHA_PPE", pregunta:"Si un técnico se siente fatigado o enfermo, ¿cuál es su responsabilidad de seguridad?", opciones:["Tomar mucho café y seguir", "Informar al supervisor, ya que la fatiga reduce el tiempo de reacción y aumenta el riesgo de errores fatales", "No decir nada para que no lo manden a casa", "Trabajar más lento"], respuesta_correcta:1, explicacion:"El estado físico y mental es un factor crítico en la prevención de accidentes eléctricos e industriales.", en_pregunta:"If a technician feels fatigued or ill, what is their safety responsibility?", en_opciones:["Drink lots of coffee and keep going","Inform the supervisor, since fatigue reduces reaction time and increases the risk of fatal errors","Say nothing to avoid being sent home","Work more slowly"], en_explicacion:"Physical and mental state is a critical factor in preventing electrical and industrial accidents." },
  { id:"osha_62", categoria:"OSHA_PPE", pregunta:"Al conducir un montacargas cargado en una rampa con pendiente ascendente, ¿hacia dónde debe mirar la carga según OSHA?", opciones:["Hacia abajo de la rampa", "Hacia arriba de la rampa (la carga siempre 'mira' hacia el cerro)", "No importa si vas despacio", "Hacia los lados"], respuesta_correcta:1, explicacion:"Por estabilidad, al subir o bajar rampas con carga, esta debe estar siempre orientada hacia la parte superior de la pendiente.", en_pregunta:"When driving a loaded forklift up a ramp, which direction should the load face according to OSHA?", en_opciones:["Facing down the ramp","Facing up the ramp (the load always 'looks' uphill)","It doesn't matter if you go slow","To the sides"], en_explicacion:"For stability, when going up or down ramps with a load, it must always be oriented toward the top of the slope." },
  { id:"osha_63", categoria:"OSHA_PPE", pregunta:"¿Cuál es el requisito de seguridad para una herramienta de impacto (como un cincel) que presenta una cabeza 'en hongo' (mushroomed)?", opciones:["Usarla con guantes más gruesos", "Esmerilar la cabeza para quitar el exceso de metal y darle forma original", "Ponerle cinta aislante", "No tiene solución, debe tirarse"], respuesta_correcta:1, explicacion:"El metal espachurrado puede desprenderse como proyectil. El mantenimiento preventivo permite corregir la forma antes de que sea peligroso.", en_pregunta:"What is the safety requirement for a struck tool (such as a chisel) that has a mushroomed head?", en_opciones:["Use it with thicker gloves","Grind the head to remove the excess metal and restore its original shape","Wrap it with electrical tape","It can't be fixed; it must be thrown out"], en_explicacion:"Flattened metal can fly off as a projectile. Preventive maintenance allows the shape to be corrected before it becomes dangerous." },
  { id:"osha_64", categoria:"OSHA_PPE", pregunta:"Una guarda de seguridad que ha sido removida para mantenimiento debe ser reinstalada:", opciones:["Al final de la semana", "Antes de que el equipo sea puesto en marcha nuevamente tras el LOTO", "Solo si el inspector de OSHA está presente", "Solo si el operador tiene miedo"], respuesta_correcta:1, explicacion:"Operar maquinaria sin guardas es una violación seria que causa amputaciones inmediatas.", en_pregunta:"A safety guard that was removed for maintenance must be reinstalled:", en_opciones:["At the end of the week","Before the equipment is put back into operation after LOTO","Only if the OSHA inspector is present","Only if the operator is afraid"], en_explicacion:"Operating machinery without guards is a serious violation that causes immediate amputations." },
  { id:"osha_65", categoria:"OSHA_PPE", pregunta:"Si el nivel de ruido en un cuarto de máquinas es de 100 dB, ¿cuánto tiempo puede estar un técnico sin protección según OSHA?", opciones:["8 horas", "2 horas", "15 minutos", "Toda la jornada"], respuesta_correcta:1, explicacion:"A medida que el nivel de ruido sube, el tiempo de exposición permitido baja drásticamente para evitar sordera.", en_pregunta:"If the noise level in a mechanical room is 100 dB, how long can a technician remain without protection according to OSHA?", en_opciones:["8 hours","2 hours","15 minutes","The entire shift"], en_explicacion:"As noise level rises, allowable exposure time drops drastically to prevent hearing loss." },
  { id:"osha_66", categoria:"OSHA_PPE", pregunta:"Al descargar materiales de un camión, la zona debe estar:", opciones:["Abierta a todo el público", "Acordonada y señalizada para evitar que personal no autorizado sea golpeado", "Llena de trabajadores para acabar rápido", "Sin iluminación"], respuesta_correcta:1, explicacion:"La caída de objetos es una de las 4 principales causas de muerte (Focus Four) de OSHA.", en_pregunta:"When unloading materials from a truck, the area must be:", en_opciones:["Open to everyone","Cordoned off and marked to prevent unauthorized personnel from being struck","Full of workers to finish faster","Without lighting"], en_explicacion:"Falling objects are one of the 4 main causes of death (Focus Four) per OSHA." },
  { id:"osha_67", categoria:"OSHA_PPE", pregunta:"Un trabajador usa respirador purificador de aire motorizado (PAPR) con filtros P100. El filtro tiene 6 meses de uso. ¿Cuándo debe cambiarse según OSHA?", opciones:["Cada 3 meses sin excepción.", "Cuando el flujo de aire disminuya o se dañe.", "Cada año calendario.", "Cuando el trabajador sienta olor o sabor."], respuesta_correcta:1, explicacion:"No hay tiempo fijo; se cambia por obstrucción, daño, o según fabricante.", en_pregunta:"A worker uses a powered air-purifying respirator (PAPR) with P100 filters. The filter has been used for 6 months. When must it be changed under OSHA?", en_opciones:["Every 3 months without exception.","When airflow decreases or it becomes damaged.","Every calendar year.","When the worker smells or tastes something."], en_explicacion:"There is no fixed schedule; it is changed due to clogging, damage, or per manufacturer instructions." },
  { id:"osha_68", categoria:"OSHA_PPE", pregunta:"Un trabajador usa gafas de seguridad con recubrimiento anti-rayadura. ¿Qué producto de limpieza destruye este recubrimiento silenciosamente?", opciones:["Agua y jabón suave.", "Limpiador de vidrios con amoníaco.", "Alcohol isopropílico al 70%.", "Paño de microfibra seco."], respuesta_correcta:1, explicacion:"Amoníaco ataca recubrimientos anti-rayadura y anti-empañante.", en_pregunta:"A worker uses safety glasses with anti-scratch coating. Which cleaning product silently destroys this coating?", en_opciones:["Water and mild soap.","Glass cleaner with ammonia.","70% isopropyl alcohol.","Dry microfiber cloth."], en_explicacion:"Ammonia attacks anti-scratch and anti-fog coatings." },
  { id:"osha_69", categoria:"OSHA_PPE", pregunta:"Un trabajador usa protección respiratoria N95 para soldadura de acero inoxidable. ¿Qué peligro específico del acero inoxidable ignora el N95?", opciones:["Humos de níquel y cromo hexavalente (cancerígenos).", "Ozono generado por el arco.", "Partículas ultrafinas (< 0.1 micras).", "Gases de protección (argón)."], respuesta_correcta:0, explicacion:"Cromo hexavalente es cancerígeno; N95 no es suficiente, requiere P100 o suministro de aire.", en_pregunta:"A worker uses N95 respiratory protection while welding stainless steel. What specific hazard of stainless steel does the N95 ignore?", en_opciones:["Nickel and hexavalent chromium fumes (carcinogenic).","Ozone generated by the arc.","Ultrafine particles (< 0.1 microns).","Shielding gases (argon)."], en_explicacion:"Hexavalent chromium is carcinogenic; N95 is not sufficient — P100 or supplied-air respirator is required." },
  { id:"osha_70", categoria:"OSHA_PPE", pregunta:"Un trabajador usa gafas de seguridad con ventilación directa. ¿Qué riesgo de salpicadura química persiste?", opciones:["Líquidos pueden entrar por las ventilaciones superiores.", "Las ventilaciones directas permiten entrada de salpicaduras laterales.", "No hay riesgo, son seguras.", "Solo protegen contra impacto, no químicos."], respuesta_correcta:1, explicacion:"Ventilación directa permite entrada de líquidos; para químicos se requiere ventilación indirecta.", en_pregunta:"A worker uses safety goggles with direct ventilation. What chemical splash risk remains?", en_opciones:["Liquids can enter through the upper vents.","Direct vents allow side splashes to enter.","There is no risk, they are safe.","They only protect against impact, not chemicals."], en_explicacion:"Direct ventilation allows liquids to enter; for chemicals, indirect ventilation is required." },
  { id:"osha_71", categoria:"OSHA_PPE", pregunta:"Un trabajador usa respirador de cara completa con filtros P100. ¿Qué prueba de ajuste es válida para este respirador?", opciones:["Prueba de ajuste cualitativa con sacarina.", "Prueba de ajuste cuantitativa con generador de partículas.", "Prueba de presión negativa manual.", "Ninguna, los respiradores de cara completa no requieren prueba."], respuesta_correcta:1, explicacion:"Respiradores de cara completa requieren prueba cuantitativa (PortaCount o similar).", en_pregunta:"A worker wears a full-face respirator with P100 filters. Which fit test is valid for this respirator?", en_opciones:["Qualitative fit test with saccharin.","Quantitative fit test with a particle generator.","Manual negative-pressure test.","None, full-face respirators don't require fit testing."], en_explicacion:"Full-face respirators require a quantitative fit test (PortaCount or similar)." },
  { id:"osha_72", categoria:"OSHA_PPE", pregunta:"Un trabajador usa protección auditiva tipo copa sobre una gorra de béisbol. ¿Cuál es la reducción efectiva del NRR?", opciones:["La misma, la gorra no afecta.", "Reducción del 50% del NRR por interferencia.", "Aumento del NRR por aislamiento adicional.", "Nula, porque la gorra impide el sello."], respuesta_correcta:3, explicacion:"Gorra impide sello de las copas contra la cabeza, anulando la protección.", en_pregunta:"A worker uses earmuff hearing protection over a baseball cap. What is the effective reduction of the NRR?", en_opciones:["The same, the cap doesn't affect it.","50% reduction of NRR due to interference.","Increased NRR from additional insulation.","None, because the cap breaks the seal."], en_explicacion:"The cap prevents the earmuff seal against the head, nullifying the protection." },
  { id:"osha_73", categoria:"OSHA_PPE", pregunta:"Un trabajador usa guantes de butilo para manipular acetona. Después de 1 hora, los guantes están intactos. ¿Son seguros?", opciones:["Sí, el butilo resiste acetona.", "No, porque la acetona permea el butilo rápidamente.", "Sí, si son de 15 milésimas.", "No, el butilo se disuelve en acetona."], respuesta_correcta:1, explicacion:"Acetona permea butilo en minutos; se requiere Viton o barrera laminada.", en_pregunta:"A worker uses butyl gloves to handle acetone. After 1 hour, the gloves appear intact. Are they safe?", en_opciones:["Yes, butyl resists acetone.","No, because acetone permeates butyl quickly.","Yes, if they are 15 mil thick.","No, butyl dissolves in acetone."], en_explicacion:"Acetone permeates butyl in minutes; Viton or a laminated barrier is required." },
  { id:"osha_74", categoria:"OSHA_PPE", pregunta:"Un trabajador usa respirador de media cara con cartuchos para vapores orgánicos. ¿Cuánto tiempo duran los cartuchos en uso continuo?", opciones:["8 horas de trabajo.", "Depende de la concentración del contaminante.", "30 días calendario.", "Hasta que el trabajador sienta olor."], respuesta_correcta:1, explicacion:"La vida útil depende de concentración, humedad, y tasa de respiración; no hay tiempo fijo.", en_pregunta:"A worker wears a half-face respirator with organic vapor cartridges. How long do the cartridges last in continuous use?", en_opciones:["8 hours of work.","It depends on the contaminant concentration.","30 calendar days.","Until the worker smells odor."], en_explicacion:"Service life depends on concentration, humidity, and breathing rate; there is no fixed schedule." },
  { id:"osha_75", categoria:"OSHA_PPE", pregunta:"Un trabajador usa casco de seguridad tipo II (impacto lateral). ¿Qué ventaja tiene sobre tipo I en caída de herramienta desde altura?", opciones:["Protege contra impacto vertical también.", "Protege contra impacto lateral si la herramienta golpea de lado.", "No hay ventaja, ambos protegen igual.", "Tipo II es más liviano."], respuesta_correcta:1, explicacion:"Tipo I protege solo impacto vertical; Tipo II protege vertical y lateral.", en_pregunta:"A worker uses a Type II hard hat (lateral impact). What advantage does it offer over Type I when a tool falls from height?", en_opciones:["It protects against vertical impact as well.","It protects against lateral impact if the tool strikes from the side.","No advantage, both protect equally.","Type II is lighter."], en_explicacion:"Type I protects only against vertical impact; Type II protects against both vertical and lateral." },
  { id:"osha_76", categoria:"OSHA_PPE", pregunta:"Un trabajador usa gafas de seguridad con lentes de policarbonato. ¿Qué radiación UV bloquea naturalmente el policarbonato?", opciones:["100% UV hasta 380 nm.", "Solo UVB.", "Solo UVA.", "Ninguna, requiere recubrimiento."], respuesta_correcta:0, explicacion:"Policarbonato bloquea 100% UV hasta 380 nm inherentemente, sin recubrimiento.", en_pregunta:"A worker uses safety glasses with polycarbonate lenses. What UV radiation does polycarbonate block naturally?", en_opciones:["100% UV up to 380 nm.","Only UVB.","Only UVA.","None, a coating is required."], en_explicacion:"Polycarbonate inherently blocks 100% UV up to 380 nm without any coating." },
  { id:"osha_77", categoria:"OSHA_PPE", pregunta:"Un trabajador usa respirador purificador de aire motorizado (PAPR) con filtro HE. ¿Qué nivel de protección ofrece?", opciones:["APF 25.", "APF 50.", "APF 1000.", "APF 10."], respuesta_correcta:2, explicacion:"PAPR con filtro HE tiene APF (factor de protección asignado) de 1000 según OSHA.", en_pregunta:"A worker uses a powered air-purifying respirator (PAPR) with an HE filter. What level of protection does it provide?", en_opciones:["APF 25.","APF 50.","APF 1000.","APF 10."], en_explicacion:"A PAPR with an HE filter has an Assigned Protection Factor (APF) of 1000 per OSHA." },
  { id:"osha_78", categoria:"OSHA_PPE", pregunta:"Un trabajador usa protección facial tipo pantalla (face shield) con certificación ANSI Z87.1. ¿Protege contra impacto de alta velocidad?", opciones:["Sí, todas las pantallas certificadas protegen contra impacto.", "No, la certificación puede ser solo para salpicaduras.", "Sí, si tiene marcado 'V' (impacto).", "No, las pantallas no protegen contra impacto."], respuesta_correcta:2, explicacion:"ANSI Z87.1 requiere marcado 'V' para impacto; sin 'V', solo salpicaduras.", en_pregunta:"A worker wears a face shield certified to ANSI Z87.1. Does it protect against high-velocity impact?", en_opciones:["Yes, all certified face shields protect against impact.","No, the certification may be for splash protection only.","Yes, if it carries the 'V' (impact) marking.","No, face shields don't protect against impact."], en_explicacion:"ANSI Z87.1 requires the 'V' marking for impact; without 'V', protection is splash only." },
  { id:"osha_79", categoria:"OSHA_PPE", pregunta:"Un trabajador usa guantes de nitrilo de 8 milésimas para manipular gasolina. ¿Cuánto tiempo de protección tienen?", opciones:["8 horas.", "30 minutos a 1 hora.", "24 horas.", "No protegen contra gasolina."], respuesta_correcta:1, explicacion:"Gasolina permea nitrilo delgado en menos de 1 hora.", en_pregunta:"A worker uses 8 mil nitrile gloves to handle gasoline. How long do they provide protection?", en_opciones:["8 hours.","30 minutes to 1 hour.","24 hours.","They don't protect against gasoline."], en_explicacion:"Gasoline permeates thin nitrile in less than 1 hour." },

  // -- RIESGO ELECTRICO (80-194) --
  { id:"osha_80", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al realizar una medición de amperaje en un motor de 460V con una pinza de 'True RMS', el técnico nota que el cable está vibrando. ¿Cuál es el riesgo de seguridad más probable?", opciones:["Falta de lubricación en los rodamientos", "Armónicos de alta frecuencia que pueden causar fatiga en el aislamiento y falla de arco", "El motor está girando demasiado rápido", "Voltaje de control bajo"], respuesta_correcta:1, explicacion:"Las corrientes armónicas en sistemas industriales causan vibraciones mecánicas en conductores y calor excesivo, aumentando el riesgo de fallas catastróficas del aislamiento.", en_pregunta:"When measuring amperage on a 460V motor with a True RMS clamp meter, the technician notices the cable is vibrating. What is the most likely safety risk?", en_opciones:["Lack of bearing lubrication","High-frequency harmonics that can cause insulation fatigue and arc fault failure","The motor is spinning too fast","Low control voltage"], en_explicacion:"Harmonic currents in industrial systems cause mechanical vibrations in conductors and excessive heat, increasing the risk of catastrophic insulation failures." },
  { id:"osha_81", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la distancia máxima permitida entre un receptáculo de pared y un equipo de HVAC en una azotea comercial según el NEC/OSHA?", opciones:["50 pies", "10 pies", "25 pies", "No hay límite si es GFCI"], respuesta_correcta:2, explicacion:"NEC 210.63 exige un receptáculo de servicio a no más de 25 pies (7.5m) del equipo para evitar el uso de extensiones peligrosas en techos.", en_pregunta:"What is the maximum distance allowed between a wall receptacle and HVAC equipment on a commercial rooftop per NEC/OSHA?", en_opciones:["50 feet","10 feet","25 feet","No limit if GFCI"], en_explicacion:"NEC 210.63 requires a service receptacle within 25 feet (7.5 m) of the equipment to avoid unsafe extension cord use on rooftops." },
  { id:"osha_82", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué OSHA prohíbe usar tuberías de gas metálicas como electrodo de puesta a tierra principal?", opciones:["Porque el gas es aislante", "Riesgo de explosión si ocurre una falla a tierra y la corriente busca camino por la tubería", "Porque el metal es muy delgado", "El NEC lo permite en edificios industriales (Falso)"], respuesta_correcta:1, explicacion:"La seguridad de vida prohíbe usar tuberías de gas para disipar fallas eléctricas por el riesgo obvio de ignición.", en_pregunta:"Why does OSHA prohibit using metal gas piping as a primary grounding electrode?", en_opciones:["Because gas is an insulator","Risk of explosion if a ground fault occurs and current seeks a path through the piping","Because the metal is too thin","The NEC allows it in industrial buildings (false)"], en_explicacion:"Life-safety considerations prohibit using gas piping to dissipate electrical faults due to the obvious risk of ignition." },
  { id:"osha_83", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un transformador de control de 24V se quema repetidamente. El técnico decide poner un fusible de mayor amperaje. ¿Qué riesgo crea?", opciones:["Ninguno, el fusible es más fuerte", "Incendio del cableado del circuito de control al no abrir ante una sobrecarga real", "El transformador enfriará mejor", "El termostato se dañará"], respuesta_correcta:1, explicacion:"Sobredimensionar fusibles elimina la protección térmica, permitiendo que los conductores alcancen temperaturas de ignición.", en_pregunta:"A 24V control transformer burns out repeatedly. The technician decides to install a higher-amperage fuse. What risk does this create?", en_opciones:["None, the fuse is stronger","A fire in the control circuit wiring because it will not open on a real overload","The transformer will cool better","The thermostat will be damaged"], en_explicacion:"Oversizing fuses removes thermal protection, allowing conductors to reach ignition temperatures." },
  { id:"osha_84", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si mides resistencia (Ohms) en un circuito energizado, ¿qué sucede con un multímetro que no tiene protección de sobrecarga?", opciones:["Mide la resistencia correctamente", "El multímetro puede explotar o dañarse internamente de forma permanente", "La batería del multímetro se carga", "Se quema el fusible del motor"], respuesta_correcta:1, explicacion:"Nunca se debe medir resistencia en circuitos vivos; la fuente externa de voltaje destruye el puente de medición del óhmetro.", en_pregunta:"If you measure resistance (ohms) on an energized circuit, what happens to a multimeter without overload protection?", en_opciones:["It measures resistance correctly","The multimeter can explode or be permanently damaged internally","The multimeter's battery charges","The motor fuse burns"], en_explicacion:"You must never measure resistance on live circuits; the external voltage source destroys the ohmmeter's measurement bridge." },
  { id:"osha_85", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un motor de 3 fases, si el desbalance de voltaje entre fases supera el 2%, el técnico debe:", opciones:["Continuar operando", "Desenergizar y corregir, ya que esto causará un aumento drástico en la temperatura del motor", "Cambiar el capacitor de arranque", "Bajar el breaker"], respuesta_correcta:1, explicacion:"Un desbalance de voltaje del 1% puede causar un desbalance de corriente del 6% al 10%, quemando los devanados.", en_pregunta:"In a three-phase motor, if the voltage unbalance between phases exceeds 2%, the technician must:", en_opciones:["Continue operating","De-energize and correct, since this will cause a drastic increase in motor temperature","Replace the start capacitor","Turn off the breaker"], en_explicacion:"A 1% voltage unbalance can cause a 6% to 10% current unbalance, burning the windings." },
  { id:"osha_86", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Usar un probador de voltaje de tipo 'NVC' (sin contacto/lápiz) como única prueba de seguridad es:", opciones:["Recomendado por OSHA", "Peligroso, ya que puede dar falsos negativos en cables blindados o con bajo voltaje", "La forma más rápida y segura", "Obligatorio en niveles comerciales"], respuesta_correcta:1, explicacion:"Los probadores de proximidad fallan ante blindajes metálicos. La verificación final siempre debe hacerse con un multímetro de contacto.", en_pregunta:"Using a non-contact voltage tester (NCV pen) as the sole safety test is:", en_opciones:["Recommended by OSHA","Dangerous, since it can give false negatives on shielded cables or low voltage","The fastest and safest way","Mandatory at commercial voltage levels"], en_explicacion:"Proximity testers fail on metallic shielding. The final verification must always be done with a contact multimeter." },
  { id:"osha_87", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la función del cable verde (EGC) en un equipo de aire acondicionado?", opciones:["Llevar la corriente de retorno", "Proveer un camino de baja impedancia para disparar el breaker ante una falla a chasis", "Aumentar el voltaje del motor", "Reducir el ruido magnético"], respuesta_correcta:1, explicacion:"La tierra no 'tira el voltaje al suelo', su función real es crear un cortocircuito intencional para que la protección abra el circuito rápidamente.", en_pregunta:"What is the function of the green wire (EGC) in an air conditioning unit?", en_opciones:["To carry return current","To provide a low-impedance path to trip the breaker during a fault to chassis","To increase motor voltage","To reduce magnetic noise"], en_explicacion:"Ground does not 'drain voltage to earth'; its real function is to create an intentional short circuit so the protection opens the circuit quickly." },
  { id:"osha_88", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si el neutro y la tierra se unen (bonded) en un panel sub-alimentado (Sub-panel)?", opciones:["Es más seguro", "Corrientes de retorno circularán por las partes metálicas y conductos del edificio", "El voltaje sube a 240V", "Se ahorra energía"], respuesta_correcta:1, explicacion:"La unión neutro-tierra solo debe ocurrir en el servicio principal. En sub-paneles causa corrientes peligrosas en las superficies metálicas.", en_pregunta:"What happens if neutral and ground are bonded in a subpanel?", en_opciones:["It is safer","Return currents will flow through the metal parts and conduits of the building","Voltage rises to 240V","Energy is saved"], en_explicacion:"Neutral-to-ground bonding should occur only at the main service. In subpanels, it causes dangerous currents on metal surfaces." },
  { id:"osha_89", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"El 'Skin Effect' en conductores industriales de gran calibre significa que:", opciones:["El cable se siente como piel", "La corriente fluye principalmente cerca de la superficie del conductor", "El aislamiento es de cuero", "El cable es más flexible"], respuesta_correcta:1, explicacion:"En CA, la corriente tiende a la periferia del cable. Esto afecta los cálculos de resistencia y temperatura en cables gruesos.", en_pregunta:"The 'skin effect' in large-gauge industrial conductors means that:", en_opciones:["The cable feels like skin","Current flows mainly near the surface of the conductor","The insulation is made of leather","The cable is more flexible"], en_explicacion:"In AC, current tends to flow at the cable's periphery. This affects resistance and temperature calculations in large conductors." },
  { id:"osha_90", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué clase de guantes de goma se requieren para trabajar en sistemas de 480V según OSHA?", opciones:["Clase 00 (hasta 500V)", "Clase 0 (hasta 1000V)", "Cualquier guante de cuero", "Guantes de látex quirúrgico"], respuesta_correcta:1, explicacion:"Aunque la Clase 00 llega a 500V, la norma industrial suele preferir Clase 0 por margen de seguridad en sistemas de 480V.", en_pregunta:"What class of rubber gloves is required to work on 480V systems per OSHA?", en_opciones:["Class 00 (up to 500V)","Class 0 (up to 1000V)","Any leather glove","Latex surgical gloves"], en_explicacion:"While Class 00 is rated to 500V, industry practice usually prefers Class 0 for a safety margin on 480V systems." },
  { id:"osha_91", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el riesgo de usar un martillo con mango de madera húmedo cerca de un tablero eléctrico?", opciones:["Que el martillo se pudra", "La madera húmeda se vuelve conductora y puede causar un choque eléctrico", "El martillo pesará más", "No hay riesgo"], respuesta_correcta:1, explicacion:"La humedad elimina las propiedades aislantes de los materiales orgánicos como la madera.", en_pregunta:"What is the risk of using a hammer with a damp wooden handle near an electrical panel?", en_opciones:["That the hammer rots","Damp wood becomes conductive and can cause an electric shock","The hammer will weigh more","There is no risk"], en_explicacion:"Moisture eliminates the insulating properties of organic materials like wood." },
  { id:"osha_92", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si conectas un capacitor de marcha (Run Capacitor) con un voltaje nominal menor al del circuito?", opciones:["Funciona mejor", "El capacitor fallará violentamente y puede explotar debido al estrés del dieléctrico", "El motor consume menos energía", "No pasa nada"], respuesta_correcta:1, explicacion:"El voltaje del capacitor siempre debe ser igual o superior al voltaje máximo que verá en el circuito (considerando el Back-EMF del motor).", en_pregunta:"What happens if you install a run capacitor with a voltage rating lower than the circuit voltage?", en_opciones:["It works better","The capacitor will fail violently and may explode due to dielectric stress","The motor draws less power","Nothing happens"], en_explicacion:"The capacitor voltage must always equal or exceed the maximum voltage it will see in the circuit (accounting for motor back-EMF)." },
  { id:"osha_93", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el propósito de un relé de sobrecarga térmico en un arrancador de motor?", opciones:["Proteger contra cortocircuitos", "Proteger el motor contra sobrecalentamiento por exceso de corriente sostenida", "Encender el motor", "Medir el voltaje"], respuesta_correcta:1, explicacion:"A diferencia del breaker que protege el cable contra cortos, la sobrecarga protege los devanados del motor contra el calor.", en_pregunta:"What is the purpose of a thermal overload relay in a motor starter?", en_opciones:["Protect against short circuits","Protect the motor from overheating due to sustained overcurrent","Start the motor","Measure voltage"], en_explicacion:"Unlike a breaker, which protects the cable against shorts, the overload protects the motor windings from heat." },
  { id:"osha_94", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el riesgo de dejar un conductor neutro 'flotando' (abierto) en un sistema de 120/240V?", opciones:["Las luces brillan más", "Voltajes desbalanceados que pueden destruir equipos y causar incendios", "Ahorro de energía", "El breaker se dispara por seguridad"], respuesta_correcta:1, explicacion:"Un neutro abierto causa que las cargas de 120V se pongan en serie, elevando el voltaje en un lado hasta casi 240V.", en_pregunta:"What is the risk of leaving a neutral conductor 'floating' (open) on a 120/240V system?", en_opciones:["The lights shine brighter","Unbalanced voltages that can destroy equipment and cause fires","Energy savings","The breaker trips for safety"], en_explicacion:"An open neutral causes 120V loads to be placed in series, raising the voltage on one leg to nearly 240V." },
  { id:"osha_95", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa la sigla 'GFCI'?", opciones:["Ground Fault Circuit Interrupter", "General Fault Control Instrument", "Gravity Fall Control Insurance", "Great Fire Control Item"], respuesta_correcta:0, explicacion:"Dispositivo diseñado para detectar fugas de corriente a tierra y cortar el flujo en milisegundos.", en_pregunta:"What does the acronym 'GFCI' mean?", en_opciones:["Ground Fault Circuit Interrupter","General Fault Control Instrument","Gravity Fall Control Insurance","Great Fire Control Item"], en_explicacion:"A device designed to detect ground current leakage and cut the flow in milliseconds." },
  { id:"osha_96", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un técnico encuentra que el voltaje entre Neutro y Tierra es de 50V CA. Esto indica:", opciones:["Un sistema muy limpio", "Una falla grave o un neutro abierto/con alta resistencia", "Que el sistema es de 480V", "Que la tierra es de buena calidad"], respuesta_correcta:1, explicacion:"En un sistema sano, el voltaje N-G debe ser cercano a 0V. 50V indica una condición peligrosa de corriente buscando camino.", en_pregunta:"A technician finds that the voltage between Neutral and Ground is 50V AC. This indicates:", en_opciones:["A very clean system","A serious fault or an open/high-resistance neutral","That the system is 480V","That the ground is high quality"], en_explicacion:"On a healthy system, N-G voltage should be close to 0V. 50V indicates a dangerous condition with current seeking a path." },
  { id:"osha_97", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la función de una 'Puesta a tierra de seguridad' temporal en trabajos de media tensión?", opciones:["Hacer que el trabajo sea más lento", "Proteger al técnico contra una reenergización accidental creando un corto sólido", "Mejorar la señal de radio", "Para que no se roben el cable"], respuesta_correcta:1, explicacion:"Las tierras temporales aseguran que si alguien sube el breaker, el sistema drene la corriente y dispare la protección antes de llegar al técnico.", en_pregunta:"What is the function of temporary protective grounds on medium-voltage work?", en_opciones:["To slow down the work","To protect the technician against accidental re-energization by creating a solid short","To improve radio signal","So the cable doesn't get stolen"], en_explicacion:"Temporary grounds ensure that if someone turns the breaker back on, the system drains the current and trips the protection before it reaches the technician." },
  { id:"osha_98", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es un 'Megóhmetro' (Megger) y para qué se usa en seguridad?", opciones:["Para medir Amperios", "Para probar la integridad del aislamiento de los cables aplicando alto voltaje", "Para ver si hay continuidad en un fusible", "Para medir la humedad del aire"], respuesta_correcta:1, explicacion:"El Megger detecta micro-fisuras en el aislamiento que un multímetro normal de 9V no vería.", en_pregunta:"What is a Megohmmeter (Megger) and what is it used for in safety?", en_opciones:["To measure amperes","To test the integrity of cable insulation by applying high voltage","To check continuity in a fuse","To measure air humidity"], en_explicacion:"The megger detects micro-cracks in insulation that a normal 9V multimeter would not see." },
  { id:"osha_99", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor 'Ground Out' (aterrizado) significa que:", opciones:["Está bien conectado a tierra", "Un devanado interno tocó la carcasa metálica", "El motor es nuevo", "No tiene neutro"], respuesta_correcta:1, explicacion:"Es una falla eléctrica donde el chasis del motor se energiza, representando un peligro de muerte.", en_pregunta:"A motor that is 'grounded out' means that:", en_opciones:["It is properly connected to ground","An internal winding has touched the metal casing","The motor is new","It has no neutral"], en_explicacion:"It is an electrical fault in which the motor chassis becomes energized, representing a deadly hazard." },
  { id:"osha_100", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si usas un multímetro sin fusibles internos?", opciones:["Mide más rápido", "En caso de un pico de voltaje, el multímetro puede explotar en tus manos", "Ahorras dinero en repuestos", "Es igual de seguro"], respuesta_correcta:1, explicacion:"Los fusibles HRC (High Rupture Capacity) en los multímetros de calidad (CAT III/IV) son lo único que evita una explosión de arco dentro del aparato.", en_pregunta:"What happens if you use a multimeter without internal fuses?", en_opciones:["It measures faster","In the event of a voltage spike, the multimeter can explode in your hands","You save money on parts","It is equally safe"], en_explicacion:"HRC (High Rupture Capacity) fuses in quality CAT III/IV multimeters are the only thing preventing an arc explosion inside the device." },
  { id:"osha_101", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué un técnico nunca debe puentear (bypass) un interruptor de alta presión en un sistema comercial de forma permanente?", opciones:["Porque el compresor gasta más luz", "Elimina la única protección mecánica contra la explosión del compresor por sobrepresión", "El termostato dejará de funcionar", "El ventilador del condensador se quemará"], respuesta_correcta:1, explicacion:"Los controles de seguridad protegen la integridad física del equipo y del personal circundante.", en_pregunta:"Why should a technician never permanently bypass a high-pressure switch on a commercial system?", en_opciones:["Because the compressor uses more power","It removes the only mechanical protection against compressor explosion due to overpressure","The thermostat will stop working","The condenser fan will burn out"], en_explicacion:"Safety controls protect the physical integrity of the equipment and surrounding personnel." },
  { id:"osha_102", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un compresor hermético tiene una falla a tierra (short to ground). ¿Qué riesgo existe al tocar la carcasa si el cable de tierra está desconectado?", opciones:["Ninguno, el compresor está aislado por aceite", "Electrocución letal, ya que la carcasa está al mismo potencial que la línea viva", "Solo un pequeño cosquilleo", "El compresor funcionará más lento"], respuesta_correcta:1, explicacion:"Sin una trayectoria de tierra efectiva, el técnico se convierte en el camino de menor resistencia hacia el suelo.", en_pregunta:"A hermetic compressor has a short to ground. What risk exists when touching the casing if the ground wire is disconnected?", en_opciones:["None, the compressor is insulated by oil","Lethal electrocution, since the casing is at the same potential as the live line","Only a small tingle","The compressor will run slower"], en_explicacion:"Without an effective ground path, the technician becomes the path of least resistance to earth." },
  { id:"osha_103", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un sistema trifásico, ¿qué dispositivo de seguridad evita que el motor gire en sentido contrario tras un cambio en la red eléctrica?", opciones:["Un breaker de 20A", "Un monitor de fase (Phase Monitor)", "Un termostato digital", "Un transformador de 24V"], respuesta_correcta:1, explicacion:"El monitor de fase corta el control si detecta pérdida de fase, caída de voltaje o reversión de secuencia, protegiendo compresores scroll.", en_pregunta:"On a three-phase system, what safety device prevents the motor from rotating in reverse after a change in the power grid?", en_opciones:["A 20A breaker","A phase monitor","A digital thermostat","A 24V transformer"], en_explicacion:"The phase monitor cuts the control circuit if it detects phase loss, voltage drop, or reversed sequence, protecting scroll compressors." },
  { id:"osha_104", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un acumulador de succión está cubierto de escarcha. ¿Qué peligro de seguridad mecánica representa para el compresor?", opciones:["Que el compresor se congele por fuera", "Retorno de líquido (slugging), que puede destruir las válvulas y el cigüeñal del compresor", "Que el aceite se vuelva muy ralo", "No hay peligro, el frío es bueno"], respuesta_correcta:1, explicacion:"Los compresores están diseñados para bombear gas, no líquido. El líquido es incompresible y causa fallas mecánicas violentas.", en_pregunta:"A suction accumulator is covered in frost. What mechanical safety hazard does it represent to the compressor?", en_opciones:["That the compressor will freeze from the outside","Liquid slugging, which can destroy the compressor's valves and crankshaft","That the oil will become too thin","No hazard, cold is good"], en_explicacion:"Compressors are designed to pump gas, not liquid. Liquid is incompressible and causes violent mechanical failures." },
  { id:"osha_105", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al revisar un condensador de marcha de 45 microfaradios, el multímetro marca 'OL' en la escala de capacitancia. ¿Qué indica?", opciones:["Que el capacitor está perfecto", "Circuito abierto o falla interna; el capacitor debe ser reemplazado", "Que la batería del multímetro está baja", "Que el motor está apagado"], respuesta_correcta:1, explicacion:"OL (Over Limit) en capacitancia suele indicar que el componente ya no almacena energía.", en_pregunta:"When checking a 45 microfarad run capacitor, the multimeter reads 'OL' on the capacitance scale. What does this indicate?", en_opciones:["That the capacitor is perfect","Open circuit or internal failure; the capacitor must be replaced","That the multimeter battery is low","That the motor is off"], en_explicacion:"OL (Over Limit) on capacitance usually indicates that the component no longer stores energy." },
  { id:"osha_106", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un panel eléctrico comercial, ¿qué indica una etiqueta de color amarillo 'CAUTION'?", opciones:["Peligro de muerte inmediata", "Posibles riesgos de seguridad que podrían resultar en lesiones menores o moderadas", "Punto de reunión", "Ubicación del extintor"], respuesta_correcta:1, explicacion:"Amarillo es precaución; Rojo es peligro/prohibición; Naranja es advertencia de riesgo grave.", en_pregunta:"On a commercial electrical panel, what does a yellow 'CAUTION' label indicate?", en_opciones:["Immediate danger of death","Possible safety hazards that could result in minor or moderate injuries","Assembly point","Extinguisher location"], en_explicacion:"Yellow is caution; Red is danger/prohibition; Orange is warning of serious risk." },
  { id:"osha_107", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si un contactor tiene los puntos 'picados' o carbonizados, ¿qué riesgo eléctrico comercial representa?", opciones:["Aumento de la resistencia, calor excesivo y posible soldadura de los contactos que impide que el equipo apague", "El equipo consumirá menos Amperios", "El motor girará más rápido", "Se quemará el termostato"], respuesta_correcta:0, explicacion:"Los contactos dañados generan calor y pueden quedar 'pegados', causando que el compresor no se detenga, lo que genera riesgos mecánicos.", en_pregunta:"If a contactor has pitted or carbonized contacts, what commercial electrical risk does it represent?", en_opciones:["Increased resistance, excessive heat, and possible welding of contacts that prevents the equipment from shutting off","The equipment will draw fewer amps","The motor will spin faster","The thermostat will burn out"], en_explicacion:"Damaged contacts generate heat and can become 'stuck,' causing the compressor not to stop, which creates mechanical risks." },
  { id:"osha_108", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué componente de seguridad protege a un técnico de recibir una descarga desde el chasis de una manejadora de aire?", opciones:["El filtro de aire", "El puente de unión (Bonding Jumper) y el cable de tierra de seguridad", "El aislamiento de los ductos", "La pintura del equipo"], respuesta_correcta:1, explicacion:"La puesta a tierra asegura que el chasis se mantenga a potencial cero y dispare el breaker si hay una falla.", en_pregunta:"What safety component protects a technician from receiving a shock from the chassis of an air handler?", en_opciones:["The air filter","The bonding jumper and the safety ground wire","The duct insulation","The equipment paint"], en_explicacion:"Grounding ensures the chassis stays at zero potential and trips the breaker if there is a fault." },
  { id:"osha_109", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"La regla de la 'Mano Izquierda' (o trabajar con una sola mano) en paneles energizados busca:", opciones:["Que el técnico se vea más hábil", "Evitar que la corriente pase a través del corazón en caso de una descarga", "No ensuciar el panel", "Tener la otra mano lista para el celular"], respuesta_correcta:1, explicacion:"Al usar una sola mano, se evita cerrar el circuito de brazo a brazo, lo cual es letal.", en_pregunta:"The 'left hand rule' (or one-hand working) on energized panels seeks to:", en_opciones:["Make the technician look more skilled","Prevent current from passing through the heart in the event of a shock","Keep the panel clean","Keep the other hand ready for the phone"], en_explicacion:"Using only one hand avoids closing the circuit arm-to-arm, which is lethal." },
  { id:"osha_110", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa que un motor tenga protección 'Térmica Interna'?", opciones:["Que no necesita breaker", "Que tiene un interruptor sensible al calor dentro de los devanados que abre el circuito si se sobrecalienta", "Que calienta el agua", "Que funciona solo en invierno"], respuesta_correcta:1, explicacion:"Es una defensa de última instancia contra fallas de flujo de aire o sobrecargas mecánicas.", en_pregunta:"What does it mean for a motor to have 'internal thermal' protection?", en_opciones:["That it doesn't need a breaker","That it has a heat-sensitive switch inside the windings that opens the circuit if it overheats","That it heats the water","That it only works in winter"], en_explicacion:"It is a last-line defense against airflow failures or mechanical overloads." },
  { id:"osha_111", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si se instala un fusible de 30A en un circuito diseñado para un máximo de 15A?", opciones:["El equipo funciona mejor", "El cable se incendiará antes de que el fusible se funda ante una sobrecarga de 25A", "Se ahorra dinero en fusibles", "El voltaje sube"], respuesta_correcta:1, explicacion:"El fusible debe ser el eslabón más débil del circuito para proteger el cableado.", en_pregunta:"What happens if a 30A fuse is installed on a circuit designed for a maximum of 15A?", en_opciones:["The equipment runs better","The wire will ignite before the fuse blows under a 25A overload","You save money on fuses","The voltage rises"], en_explicacion:"The fuse must be the weakest link in the circuit to protect the wiring." },
  { id:"osha_112", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el peligro 'invisible' más crítico al trabajar con paneles solares durante el día, incluso si el inversor está apagado?", opciones:["El reflejo del sol", "Los paneles son fuentes de energía activa (Live) que no se pueden 'apagar' mientras haya luz solar", "El peso de los módulos", "La estática del marco"], respuesta_correcta:1, explicacion:"A diferencia de un motor, un arreglo fotovoltaico genera voltaje instantáneamente con la luz. Los cables de DC están energizados y pueden causar arcos mortales.", en_pregunta:"What is the most critical 'invisible' hazard when working with solar panels during the day, even if the inverter is off?", en_opciones:["Glare from the sun","The panels are live energy sources that cannot be 'turned off' as long as there is sunlight","The weight of the modules","Static from the frame"], en_explicacion:"Unlike a motor, a PV array generates voltage instantly with light. The DC conductors are energized and can cause fatal arcs." },
  { id:"osha_113", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un sistema trifásico de 480V, ¿qué sucede si se intercambian dos de los tres cables de alimentación de un compresor Scroll?", opciones:["El compresor se quema instantáneamente", "El compresor girará en reversa, lo que puede causar fallas mecánicas y falta de bombeo", "No sucede nada en sistemas de CA", "El breaker se dispara"], respuesta_correcta:1, explicacion:"Los compresores Scroll son direccionales. La rotación inversa impide la lubricación y compresión, dañando el equipo rápidamente.", en_pregunta:"In a 480V three-phase system, what happens if two of the three supply leads of a Scroll compressor are swapped?", en_opciones:["The compressor burns out instantly","The compressor will run in reverse, which can cause mechanical failures and loss of pumping capacity","Nothing happens on AC systems","The breaker trips"], en_explicacion:"Scroll compressors are directional. Reverse rotation prevents lubrication and compression, damaging the equipment quickly." },
  { id:"osha_114", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué un arco eléctrico en Corriente Continua (DC) es más persistente y peligroso que en CA?", opciones:["Porque la DC tiene más amperios siempre", "Porque la DC no pasa por 'cero' voltios, lo que impide que el arco se extinga naturalmente", "Porque la DC es azul", "Porque los cables son más delgados"], respuesta_correcta:1, explicacion:"En CA, la onda pasa por cero 120 veces por segundo (60Hz), ayudando a romper el arco. En DC, el arco se mantiene hasta que la distancia o un interruptor lo extinga.", en_pregunta:"Why is a DC electrical arc more persistent and dangerous than an AC arc?", en_opciones:["Because DC always has more amperage","Because DC does not cross zero volts, which prevents the arc from extinguishing naturally","Because DC is blue","Because the conductors are thinner"], en_explicacion:"In AC, the waveform crosses zero 120 times per second (60Hz), helping to break the arc. In DC, the arc sustains itself until distance or a breaker extinguishes it." },
  { id:"osha_115", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un sistema de 120V tiene una resistencia a tierra de 25 Ohms. Según la Ley de Ohm, si ocurre un corto a chasis, ¿cuánta corriente fluirá por la tierra?", opciones:["120A", "4.8A", "10A", "0.5A"], respuesta_correcta:1, explicacion:"I = V/R (120/25 = 4.8A). Esto es peligroso porque 4.8A no son suficientes para disparar un breaker de 15A o 20A, dejando el chasis energizado.", en_pregunta:"A 120V system has a ground resistance of 25 Ohms. According to Ohm's Law, if a chassis short occurs, how much current will flow to ground?", en_opciones:["120A","4.8A","10A","0.5A"], en_explicacion:"I = V/R (120/25 = 4.8A). This is dangerous because 4.8A is not enough to trip a 15A or 20A breaker, leaving the chassis energized." },
  { id:"osha_116", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al instalar paneles en un techo con una inclinación de 5:12, ¿qué medida de seguridad es obligatoria?", opciones:["Zapatos con suela de goma solamente", "Sistema de detención de caídas (arnés, línea de vida y punto de anclaje)", "Tener una red abajo", "Solo trabajar cuando no haya viento"], respuesta_correcta:1, explicacion:"Cualquier trabajo en bordes desprotegidos a más de 6 pies requiere protección activa contra caídas.", en_pregunta:"When installing panels on a roof with a 5:12 pitch, what safety measure is mandatory?", en_opciones:["Rubber-soled shoes only","Fall arrest system (harness, lanyard, and anchor point)","Having a net below","Only working when there is no wind"], en_explicacion:"Any work on unprotected edges more than 6 feet up requires active fall protection." },
  { id:"osha_117", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si un técnico toca un cable de 120V con la mano húmeda en lugar de seca, ¿qué sucede con la descarga?", opciones:["Es igual", "La intensidad de la corriente aumenta drásticamente porque la resistencia de la piel baja", "La corriente disminuye", "El voltaje del cable baja"], respuesta_correcta:1, explicacion:"El agua reduce la resistencia óhmica del cuerpo humano, permitiendo que pase más amperaje por el corazón.", en_pregunta:"If a technician touches a 120V conductor with a wet hand instead of a dry hand, what happens to the shock?", en_opciones:["It is the same","Current intensity rises dramatically because skin resistance drops","Current decreases","The conductor voltage drops"], en_explicacion:"Water reduces the ohmic resistance of the human body, allowing more amperage to pass through the heart." },
  { id:"osha_118", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al conectar un aire acondicionado a un sistema solar Off-Grid, ¿por qué es crítico considerar la corriente de 'LRA' (Locked Rotor Amps)?", opciones:["Porque el aire no enfriará", "Porque el pico de arranque puede sobrepasar la capacidad del inversor y causar un apagado de seguridad o daño", "Porque el cable verde se calienta", "No es importante en sistemas solares"], respuesta_correcta:1, explicacion:"Los inversores deben dimensionarse para el pico de arranque del compresor, que puede ser 5-6 veces la corriente nominal.", en_pregunta:"When connecting an air conditioner to an off-grid solar system, why is it critical to consider the Locked Rotor Amps (LRA)?", en_opciones:["Because the AC won't cool","Because the inrush peak can exceed the inverter's capacity and cause a safety shutdown or damage","Because the green wire heats up","It's not important on solar systems"], en_explicacion:"Inverters must be sized for the compressor's starting peak, which can be 5-6 times the rated current." },
  { id:"osha_119", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un banco de baterías de ácido-plomo, ¿qué se debe agregar primero al mezclar electrolito?", opciones:["El ácido al agua", "El agua al ácido", "No importa el orden", "Mezclarlos simultáneamente"], respuesta_correcta:0, explicacion:"Regla: Ácido sobre Agua (A sobre A). Si agregas agua al ácido, la reacción exotérmica puede causar salpicaduras violentas de ácido.", en_pregunta:"In a lead-acid battery bank, what should be added first when mixing electrolyte?", en_opciones:["Acid to water","Water to acid","The order doesn't matter","Mix them simultaneously"], en_explicacion:"Rule: Acid to Water (A to A). Adding water to acid causes a violent exothermic reaction that can splash acid." },
  { id:"osha_120", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es la 'Corriente de Fuga' en un equipo industrial?", opciones:["Corriente que se escapa por la ventana", "Pequeña cantidad de corriente que fluye a través del aislamiento hacia la tierra", "Corriente que no se paga en la factura", "Voltaje de control de 24V"], respuesta_correcta:1, explicacion:"Si la corriente de fuga aumenta, indica que el aislamiento del motor o cable está fallando.", en_pregunta:"What is 'Leakage Current' in industrial equipment?", en_opciones:["Current that escapes through the window","A small amount of current that flows through the insulation to ground","Current that isn't billed on the utility statement","24V control voltage"], en_explicacion:"If leakage current increases, it indicates that motor or cable insulation is failing." },
  { id:"osha_121", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa un breaker de tipo 'AFCI'?", opciones:["Air Flow Circuit Interruptor", "Arc Fault Circuit Interrupter", "Amperage Flow Control Instrument", "All Faults Circuit Inverter"], respuesta_correcta:1, explicacion:"A diferencia del GFCI (falla a tierra), el AFCI detecta arcos eléctricos peligrosos (chispas por cables sueltos) para prevenir incendios.", en_pregunta:"What does an 'AFCI' breaker stand for?", en_opciones:["Air Flow Circuit Interruptor","Arc Fault Circuit Interrupter","Amperage Flow Control Instrument","All Faults Circuit Inverter"], en_explicacion:"Unlike a GFCI (ground fault), the AFCI detects dangerous arc faults (sparks from loose conductors) to prevent fires." },
  { id:"osha_122", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un sistema fotovoltaico, ¿qué componente se encarga de evitar que las baterías se sobrecarguen?", opciones:["El panel", "El Controlador de Carga (Charge Controller)", "El interruptor de pared", "El multímetro"], respuesta_correcta:1, explicacion:"Es un dispositivo de seguridad vital para evitar incendios o explosiones por sobrecarga térmica de las baterías.", en_pregunta:"In a photovoltaic system, which component is responsible for preventing batteries from overcharging?", en_opciones:["The panel","The Charge Controller","The wall switch","The multimeter"], en_explicacion:"It is a vital safety device to prevent fires or explosions from thermal overload of the batteries." },
  { id:"osha_123", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Estás midiendo un circuito de 480V con un multímetro CAT II. ¿Cuál es el error?", opciones:["Ninguno, 480 es menor que 600", "El multímetro CAT II no está diseñado para transitorios de nivel comercial/industrial; puede explotar", "El color del multímetro es incorrecto", "La pantalla se verá borrosa"], respuesta_correcta:1, explicacion:"CAT III o IV es obligatorio para paneles de distribución comercial. CAT II es para tomas residenciales.", en_pregunta:"You are measuring a 480V circuit with a CAT II multimeter. What is the mistake?", en_opciones:["None, 480 is less than 600","A CAT II multimeter is not rated for commercial/industrial transients; it can explode","The color of the multimeter is wrong","The display will look blurry"], en_explicacion:"CAT III or IV is mandatory for commercial distribution panels. CAT II is for residential receptacles." },
  { id:"osha_124", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"El término 'Hot Leg' en un sistema de transformador 'Delta' con toma central (High-leg delta) se identifica con el color:", opciones:["Blanco", "Naranja", "Azul", "Verde"], respuesta_correcta:1, explicacion:"El NEC exige que la fase con el voltaje más alto a tierra (208V en un sistema de 240V) sea naranja.", en_pregunta:"The 'Hot Leg' in a center-tapped Delta transformer system (High-leg delta) is identified by what color?", en_opciones:["White","Orange","Blue","Green"], en_explicacion:"The NEC requires the phase with the highest voltage to ground (208V on a 240V system) to be orange." },
  { id:"osha_125", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué los marcos de aluminio de los paneles solares deben estar conectados a tierra (bonded)?", opciones:["Para que no se oxiden", "Para disipar cargas estáticas, rayos y asegurar que no se ionicen y den choques eléctricos", "Para que pesen menos", "No es necesario si el techo es de madera"], respuesta_correcta:1, explicacion:"El aluminio es excelente conductor; una falla en el aislamiento de un cable de 600V DC energizaría toda la estructura del techo.", en_pregunta:"Why must aluminum frames of solar panels be bonded to ground?", en_opciones:["So they don't rust","To dissipate static charges and lightning and ensure they don't become energized and cause electrical shocks","So they weigh less","It's not necessary if the roof is wood"], en_explicacion:"Aluminum is an excellent conductor; an insulation failure in a 600V DC conductor would energize the entire roof structure." },
  { id:"osha_126", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es un 'Short Circuit Current Rating' (SCCR)?", opciones:["El tamaño del breaker", "La cantidad máxima de corriente de falla que un componente puede soportar sin explotar o incendiarse", "La longitud del cable", "La velocidad del motor"], respuesta_correcta:1, explicacion:"Es vital en paneles industriales para asegurar que el equipo no se convierta en metralla durante una falla masiva.", en_pregunta:"What is a 'Short Circuit Current Rating' (SCCR)?", en_opciones:["The size of the breaker","The maximum fault current a component can withstand without exploding or igniting","The length of the cable","The motor speed"], en_explicacion:"It is vital on industrial panels to ensure equipment does not turn into shrapnel during a massive fault." },
  { id:"osha_127", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un interruptor diferencial (GFCI) protege contra:", opciones:["Sobrecarga de amperaje", "Choque eléctrico por falla a tierra", "Rayos", "Costo alto de electricidad"], respuesta_correcta:1, explicacion:"El GFCI detecta cuando la corriente no regresa por el neutro, asumiendo que está pasando por una persona.", en_pregunta:"A ground fault circuit interrupter (GFCI) protects against:", en_opciones:["Amperage overload","Electric shock from ground fault","Lightning","High electricity cost"], en_explicacion:"The GFCI detects when current is not returning through the neutral, assuming it is passing through a person." },
  { id:"osha_128", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el riesgo de 'Fuga Térmica' (Thermal Runaway) en baterías de Litio-Ion?", opciones:["Que la batería se enfríe", "Una reacción en cadena que genera calor incontrolable, fuego y emisión de gases tóxicos", "Que la batería dure más años", "Que el voltaje baje a 0V"], respuesta_correcta:1, explicacion:"Es el fallo más peligroso de las baterías modernas, difícil de extinguir con agua normal.", en_pregunta:"What is the risk of 'Thermal Runaway' in Lithium-Ion batteries?", en_opciones:["That the battery cools down","A chain reaction that generates uncontrollable heat, fire, and toxic gas emissions","That the battery lasts more years","That the voltage drops to 0V"], en_explicacion:"It is the most dangerous failure of modern batteries, difficult to extinguish with plain water." },
  { id:"osha_129", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"El 'Arco Eléctrico' es principalmente un riesgo de:", opciones:["Envenenamiento", "Quemaduras térmicas severas, presión explosiva y daño auditivo", "Falta de luz", "Radiación nuclear"], respuesta_correcta:1, explicacion:"Es una explosión de plasma que puede proyectar metal fundido y generar ondas de choque.", en_pregunta:"An 'Electrical Arc' is primarily a hazard of:", en_opciones:["Poisoning","Severe thermal burns, explosive pressure, and hearing damage","Lack of light","Nuclear radiation"], en_explicacion:"It is a plasma explosion that can project molten metal and generate shock waves." },
  { id:"osha_130", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un sistema fotovoltaico conectado a la red (Grid-Tied), ¿qué sucede durante un apagón de la ciudad?", opciones:["El sistema sigue funcionando igual", "El inversor debe apagarse (Anti-Islanding) para no inyectar energía a la red y electrocutar a los linieros", "La casa explota", "Los paneles dejan de producir voltaje"], respuesta_correcta:1, explicacion:"Es una función de seguridad obligatoria por ley para proteger a los trabajadores de la compañía eléctrica.", en_pregunta:"In a grid-tied photovoltaic system, what happens during a city-wide power outage?", en_opciones:["The system continues to run normally","The inverter must shut down (Anti-Islanding) to avoid back-feeding the grid and electrocuting line workers","The house explodes","The panels stop producing voltage"], en_explicacion:"It is a safety function required by law to protect utility workers." },
  { id:"osha_131", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si un motor trifásico zumba pero no arranca, lo primero que debe verificar un técnico de ACVOLT es:", opciones:["Si el termostato tiene pilas", "Si falta una de las fases (Single Phasing)", "Si el filtro de aire está sucio", "Si el motor necesita pintura"], respuesta_correcta:1, explicacion:"La pérdida de una fase impide que el motor genere el campo magnético rotativo necesario para el torque de arranque.", en_pregunta:"If a three-phase motor hums but does not start, the first thing an ACVOLT technician should check is:", en_opciones:["Whether the thermostat has batteries","Whether one of the phases is missing (Single Phasing)","Whether the air filter is dirty","Whether the motor needs paint"], en_explicacion:"The loss of a phase prevents the motor from generating the rotating magnetic field needed for starting torque." },
  { id:"osha_132", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la frontera de aproximación limitada para un sistema de 480V según la NFPA 70E?", opciones:["1 pie", "3 pies 6 pulgadas", "10 pies", "25 pies"], respuesta_correcta:1, explicacion:"Es la distancia mínima a la cual personal no calificado puede estar cerca de partes energizadas expuestas.", en_pregunta:"What is the Limited Approach Boundary for a 480V system per NFPA 70E?", en_opciones:["1 foot","3 feet 6 inches","10 feet","25 feet"], en_explicacion:"It is the minimum distance at which unqualified personnel can be near exposed energized parts." },
  { id:"osha_133", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué es peligroso dejar herramientas de metal sobre una batería?", opciones:["Porque se rayan", "Pueden causar un cortocircuito directo entre terminales, generando una explosión de arco o fuego", "Porque el ácido las corroe", "Porque la batería se descarga lento"], respuesta_correcta:1, explicacion:"Las baterías tienen una corriente de cortocircuito altísima; una llave inglesa puede fundirse instantáneamente y causar quemaduras graves.", en_pregunta:"Why is it dangerous to leave metal tools on top of a battery?", en_opciones:["Because they get scratched","They can cause a direct short circuit between terminals, generating an arc explosion or fire","Because the acid corrodes them","Because the battery drains slowly"], en_explicacion:"Batteries have extremely high short-circuit current; a wrench can melt instantly and cause severe burns." },
  { id:"osha_134", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"El 'Efecto Joule' en un conductor eléctrico se refiere a:", opciones:["La luz que emite", "El calor generado por la corriente al pasar por una resistencia", "La fuerza magnética", "La capacidad de almacenar carga"], respuesta_correcta:1, explicacion:"Este calor es el que causa incendios cuando hay conexiones flojas (resistencia alta).", en_pregunta:"The 'Joule Effect' in an electrical conductor refers to:", en_opciones:["The light it emits","The heat generated by current flowing through resistance","Magnetic force","Capacity to store charge"], en_explicacion:"This heat is what causes fires when connections are loose (high resistance)." },
  { id:"osha_135", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué color representa el conductor Neutro en un sistema comercial de 277/480V?", opciones:["Blanco", "Gris", "Verde", "Negro"], respuesta_correcta:1, explicacion:"El NEC permite blanco o gris; en la práctica industrial de 480V, el gris es el estándar para diferenciarlo del sistema de 120V (blanco).", en_pregunta:"What color represents the neutral conductor in a 277/480V commercial system?", en_opciones:["White","Gray","Green","Black"], en_explicacion:"The NEC allows white or gray; in 480V industrial practice, gray is the standard to differentiate it from the 120V system (white)." },
  { id:"osha_136", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la diferencia crítica entre una 'Falla a Tierra' y un 'Arco Eléctrico' en términos de EPP?", opciones:["Son lo mismo", "La falla a tierra requiere guantes aislantes; el arco eléctrico requiere traje con clasificación calórica (Arc Rated)", "Solo se necesita casco para ambos", "El arco eléctrico no requiere protección ocular"], respuesta_correcta:1, explicacion:"La falla a tierra es un choque eléctrico (corriente por el cuerpo); el arco eléctrico es una explosión térmica y de presión.", en_pregunta:"What is the critical difference between a 'Ground Fault' and an 'Arc Flash' in terms of PPE?", en_opciones:["They are the same","A ground fault requires insulating gloves; an arc flash requires an Arc Rated suit","Only a hard hat is needed for both","Arc flash does not require eye protection"], en_explicacion:"A ground fault is an electric shock (current through the body); an arc flash is a thermal and pressure explosion." },
  { id:"osha_137", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Según OSHA, ¿cuál es el voltaje máximo al que se permite trabajar en equipo energizado 'expuesto' sin una barrera física o protección?", opciones:["120V", "50V", "24V", "0V (Nunca se permite)"], respuesta_correcta:1, explicacion:"OSHA 1910.303 exige que las partes energizadas de 50 voltios o más estén protegidas contra contacto accidental.", en_pregunta:"Per OSHA, what is the maximum voltage at which a technician is allowed to work near 'exposed' energized equipment without a physical barrier or protection?", en_opciones:["120V","50V","24V","0V (Never allowed)"], en_explicacion:"OSHA 1910.303 requires live parts of 50 volts or more to be guarded against accidental contact." },
  { id:"osha_138", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el propósito de la 'Trayectoria de Corriente de Falla Efectiva'?", opciones:["Ahorrar cable", "Crear un camino de baja impedancia para que la corriente de falla sea lo suficientemente alta como para disparar el breaker", "Llevar la electricidad a la tierra física", "Evitar el ruido en la radio"], respuesta_correcta:1, explicacion:"Si la resistencia es alta, la corriente de falla será baja y el breaker no se disparará, dejando el equipo energizado.", en_pregunta:"What is the purpose of the 'Effective Ground-Fault Current Path'?", en_opciones:["Saving wire","Creating a low-impedance path so the fault current is high enough to trip the breaker","Carrying electricity to physical earth","Preventing radio interference"], en_explicacion:"If resistance is high, fault current will be low and the breaker will not trip, leaving the equipment energized." },
  { id:"osha_139", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un técnico usa un cable de extensión donde falta la pata de tierra (circular). ¿Qué riesgo corre según OSHA?", opciones:["Ninguno, si el equipo es de plástico", "El chasis metálico del equipo conectado no tiene camino de retorno en falla, causando un choque", "El equipo gastará más luz", "El cable se derretirá"], respuesta_correcta:1, explicacion:"Quitar la pata de tierra anula la protección de seguridad contra fallas a chasis.", en_pregunta:"A technician uses an extension cord that is missing the ground prong (round). What is the OSHA-related risk?", en_opciones:["None, if the equipment is plastic","The metallic chassis of the connected equipment has no return path in a fault, causing a shock","The equipment will use more electricity","The cord will melt"], en_explicacion:"Removing the ground prong defeats the safety protection against chassis faults." },
  { id:"osha_140", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el nivel de corriente (Amperios) que generalmente causa fibrilación ventricular y muerte?", opciones:["10 Amperios", "1 Amperio", "100 a 200 miliamperios (0.1A - 0.2A)", "10 miliamperios"], respuesta_correcta:2, explicacion:"Cantidades extremadamente pequeñas de corriente son suficientes para interrumpir el ritmo eléctrico del corazón.", en_pregunta:"What current level (in amperes) generally causes ventricular fibrillation and death?", en_opciones:["10 Amps","1 Amp","100 to 200 milliamps (0.1A - 0.2A)","10 milliamps"], en_explicacion:"Extremely small amounts of current are enough to disrupt the heart's electrical rhythm." },
  { id:"osha_141", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa 'GFCI de Clase A'?", opciones:["Que es para aviones", "Que se dispara entre 4mA y 6mA", "Que aguanta 1000 Amperios", "Que es de color blanco"], respuesta_correcta:1, explicacion:"Es el estándar para protección de personas. Niveles superiores son para protección de equipos (GFPE).", en_pregunta:"What does 'Class A GFCI' mean?", en_opciones:["That it is for aircraft","That it trips between 4mA and 6mA","That it handles 1000 Amps","That it is white"], en_explicacion:"It is the standard for personnel protection. Higher levels are for equipment protection (GFPE)." },
  { id:"osha_142", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si se usa un probador de voltaje sin clasificación de categoría (No-CAT) en un tablero de 480V?", opciones:["Mide bien el voltaje", "El probador puede explotar debido a un arco interno si hay un pico de tensión (transitorio)", "La batería dura más", "No pasa nada"], respuesta_correcta:1, explicacion:"Los equipos CAT III/IV tienen distancias internas y fusibles especiales para contener explosiones de arco.", en_pregunta:"What happens if a non-CAT rated voltage tester is used on a 480V panel?", en_opciones:["It measures voltage fine","The tester can explode due to an internal arc if there is a voltage transient","The battery lasts longer","Nothing happens"], en_explicacion:"CAT III/IV instruments have internal clearances and special fuses to contain arc explosions." },
  { id:"osha_143", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"La 'Frontera de Arc Flash' es la distancia a la cual un técnico recibiría una quemadura de:", opciones:["Primer grado", "Segundo grado", "Tercer grado", "Muerte instantánea"], respuesta_correcta:1, explicacion:"Se define como 1.2 cal/cm², que es el umbral para una quemadura de segundo grado curable.", en_pregunta:"The 'Arc Flash Boundary' is the distance at which a technician would receive a burn of:", en_opciones:["First degree","Second degree","Third degree","Instant death"], en_explicacion:"It is defined as 1.2 cal/cm², which is the threshold for a curable second-degree burn." },
  { id:"osha_144", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la función del 'System Grounding' (Puesta a tierra del sistema)?", opciones:["Proteger al técnico", "Limitar el voltaje impuesto por rayos o contacto con líneas de alta tensión", "Hacer que el motor sea más eficiente", "Ahorrar energía"], respuesta_correcta:1, explicacion:"El aterrizaje del sistema (ej. neutro a tierra en el transformador) estabiliza el voltaje respecto a la tierra física.", en_pregunta:"What is the function of 'System Grounding'?", en_opciones:["Protecting the technician","Limiting voltage imposed by lightning or contact with high-voltage lines","Making the motor more efficient","Saving energy"], en_explicacion:"System grounding (e.g., neutral to ground at the transformer) stabilizes voltage relative to earth." },
  { id:"osha_145", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Medir voltaje con un multímetro puesto en la escala de Amperios resultará en:", opciones:["Una lectura de 0V", "Un cortocircuito interno y posible explosión del multímetro si no tiene protección HRC", "Que el motor se apague", "Medición correcta de corriente"], respuesta_correcta:1, explicacion:"En escala de Amperios, el multímetro tiene impedancia casi cero. Conectarlo a voltaje es crear un corto directo.", en_pregunta:"Measuring voltage with a multimeter set to the amperage scale will result in:", en_opciones:["A 0V reading","An internal short circuit and possible explosion of the multimeter if it lacks HRC protection","The motor shutting off","Correct current measurement"], en_explicacion:"On the amperage scale, the multimeter has near-zero impedance. Connecting it across voltage is creating a direct short." },
  { id:"osha_146", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es un 'Arco Errante' (Stray Arc)?", opciones:["Un arco que se perdió", "Corriente de soldadura que fluye por caminos no deseados (como rodamientos o tuberías)", "Un rayo", "Electricidad estática en la alfombra"], respuesta_correcta:1, explicacion:"Puede dañar maquinaria costosa o causar incendios en áreas remotas del punto de trabajo.", en_pregunta:"What is a 'Stray Arc'?", en_opciones:["An arc that got lost","Welding current that flows through unintended paths (like bearings or pipes)","A lightning bolt","Static electricity on a carpet"], en_explicacion:"It can damage expensive machinery or cause fires in areas remote from the work point." },
  { id:"osha_147", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un interruptor diferencial (GFCI) protege a una persona contra el choque eléctrico al suelo, pero NO protege contra:", opciones:["Contacto entre fase y neutro (el GFCI cree que es una carga normal)", "Humedad", "Bajo voltaje", "Electricidad estática"], respuesta_correcta:0, explicacion:"Si tocas ambos cables vivos (L y N), la corriente que sale por L regresa por N, y el GFCI no detecta desbalance.", en_pregunta:"A ground fault circuit interrupter (GFCI) protects a person from a shock to ground, but does NOT protect against:", en_opciones:["Line-to-neutral contact (the GFCI sees it as a normal load)","Humidity","Low voltage","Static electricity"], en_explicacion:"If you touch both live conductors (L and N), the current leaving on L returns on N, and the GFCI detects no imbalance." },
  { id:"osha_148", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué prenda de vestir está prohibida para un electricista incluso bajo el traje de Arc Flash?", opciones:["Algodón", "Lana", "Joyas de metal (anillos, relojes)", "Seda"], respuesta_correcta:2, explicacion:"El metal es conductor y puede causar quemaduras por inducción o cortocircuitos accidentales.", en_pregunta:"What article of clothing is prohibited for an electrician even under an Arc Flash suit?", en_opciones:["Cotton","Wool","Metal jewelry (rings, watches)","Silk"], en_explicacion:"Metal is conductive and can cause burns from induction or accidental short circuits." },
  { id:"osha_149", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el riesgo de un cable con aislamiento 'quemado' por el sol (UV damage)?", opciones:["Se ve feo", "Grietas microscópicas que permiten fugas de corriente o cortocircuitos al mojarse", "El cobre se vuelve más resistente", "No hay riesgo"], respuesta_correcta:1, explicacion:"El daño por UV degrada los polímeros del aislamiento, eliminando su capacidad dieléctrica.", en_pregunta:"What is the risk of a cable with UV-damaged insulation?", en_opciones:["It looks ugly","Microscopic cracks that allow current leakage or short circuits when wet","The copper becomes more resistant","There is no risk"], en_explicacion:"UV damage degrades the polymers of the insulation, destroying its dielectric capability." },
  { id:"osha_150", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es la 'Tensión de Paso' (Step Voltage) cerca de un cable de alta tensión caído?", opciones:["El voltaje del zapato", "La diferencia de potencial entre los pies de una persona que camina cerca de la falla", "La velocidad de la corriente", "No existe"], respuesta_correcta:1, explicacion:"La corriente se disipa en círculos; si tus pies están en círculos distintos, la electricidad pasa de un pie a otro a través de tus piernas.", en_pregunta:"What is 'Step Voltage' near a fallen high-voltage line?", en_opciones:["The voltage of the shoe","The difference in potential between the feet of a person walking near the fault","The speed of the current","It does not exist"], en_explicacion:"Current dissipates in circles; if your feet are on different circles, electricity passes from one foot to the other through your legs." },
  { id:"osha_151", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al trabajar en un panel de 600V, ¿cuál es la 'Frontera de Aproximación Restringida'?", opciones:["Evitar el contacto", "1 pie (0.3 metros)", "3.5 pies", "10 pies"], respuesta_correcta:1, explicacion:"Es la distancia donde el riesgo de arco o choque es inminente y requiere EPP completo.", en_pregunta:"When working on a 600V panel, what is the 'Restricted Approach Boundary'?", en_opciones:["Avoid contact","1 foot (0.3 meters)","3.5 feet","10 feet"], en_explicacion:"It is the distance where arc or shock risk is imminent and full PPE is required." },
  { id:"osha_152", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa la sigla 'AHJ' en seguridad y códigos?", opciones:["All Hazards Joined", "Authority Having Jurisdiction (Autoridad Competente/Inspector)", "Always High Junction", "Amperage High Joule"], respuesta_correcta:1, explicacion:"Es la persona o entidad encargada de aprobar instalaciones y asegurar el cumplimiento del código.", en_pregunta:"What does the acronym 'AHJ' mean in safety and codes?", en_opciones:["All Hazards Joined","Authority Having Jurisdiction (Inspector/Competent Authority)","Always High Junction","Amperage High Joule"], en_explicacion:"It is the person or entity responsible for approving installations and ensuring code compliance." },
  { id:"osha_153", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un interruptor automático (breaker) que huele a quemado pero no se ha disparado indica:", opciones:["Que está trabajando bien", "Una conexión floja o falla interna que genera calor extremo (falla inminente)", "Que necesita aire acondicionado", "Que el plástico es de mala calidad"], respuesta_correcta:1, explicacion:"El calor por resistencia es un precursor común de incendios eléctricos.", en_pregunta:"A circuit breaker that smells burnt but has not tripped indicates:", en_opciones:["That it is working well","A loose connection or internal failure generating extreme heat (imminent failure)","That it needs air conditioning","That the plastic is poor quality"], en_explicacion:"Resistive heating is a common precursor to electrical fires." },
  { id:"osha_154", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al trabajar en un panel trifásico, el técnico nota que una barra (bus bar) está decolorada (azulada/oscura). ¿Qué significa?", opciones:["Que es una barra de lujo", "Que ha sufrido un sobrecalentamiento severo por sobrecarga o mala conexión", "Que es de acero", "Que el panel es viejo"], respuesta_correcta:1, explicacion:"La decoloración del metal indica que ha alcanzado temperaturas críticas que afectan su conductividad y seguridad.", en_pregunta:"When working on a three-phase panel, the technician notices a bus bar is discolored (bluish/dark). What does this mean?", en_opciones:["That it is a premium bus bar","That it has suffered severe overheating from overload or a bad connection","That it is steel","That the panel is old"], en_explicacion:"Discoloration of the metal indicates it has reached critical temperatures that affect its conductivity and safety." },
  { id:"osha_155", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué exige OSHA antes de que un técnico pueda trabajar cerca de partes energizadas que no han sido bloqueadas (LOTO)?", opciones:["Solo avisar al supervisor", "Demostrar que desenergizar introduce peligros adicionales o es técnica o operativamente imposible", "Usar guantes de cuero", "Cerrar los ojos"], respuesta_correcta:1, explicacion:"El trabajo energizado es la excepción, no la regla. Debe justificarse por seguridad (ej. sistemas de soporte vital) o imposibilidad técnica.", en_pregunta:"What does OSHA require before a technician can work near energized parts that have not been locked out (LOTO)?", en_opciones:["Just notifying the supervisor","Demonstrating that de-energizing introduces additional hazards or is technically/operationally infeasible","Wearing leather gloves","Closing the eyes"], en_explicacion:"Energized work is the exception, not the rule. It must be justified by safety (e.g., life-support systems) or technical impossibility." },
  { id:"osha_156", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un tablero industrial tiene una etiqueta de Arc Flash que indica 'Energía Incidente de 45 cal/cm²'. ¿Qué significa esto para el técnico?", opciones:["Que puede usar un traje de nivel 4", "Que NO se puede trabajar energizado porque supera el límite de protección del equipo estándar (40 cal/cm²)", "Que el panel está frío", "Que solo necesita careta"], respuesta_correcta:1, explicacion:"Por encima de 40 cal/cm², la presión de la explosión (Arc Blast) es tan fuerte que el EPP no garantiza la supervivencia por trauma físico.", en_pregunta:"An industrial switchboard has an Arc Flash label indicating 'Incident Energy of 45 cal/cm²'. What does this mean for the technician?", en_opciones:["That they can wear a Category 4 suit","That energized work is NOT allowed because it exceeds the standard equipment protection limit (40 cal/cm²)","That the panel is cold","That only a face shield is needed"], en_explicacion:"Above 40 cal/cm², the blast pressure (Arc Blast) is so strong that PPE does not guarantee survival from physical trauma." },
  { id:"osha_157", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué sucede si una canalización metálica (EMT) se interrumpe por una caja de plástico sin un puente de unión (jumper)?", opciones:["El cable fluye mejor", "Se pierde la trayectoria de tierra, dejando la tubería metálica posterior energizada en caso de falla", "Se ahorra dinero", "Mejora el voltaje"], respuesta_correcta:1, explicacion:"La continuidad metálica es vital para que las protecciones eléctricas funcionen correctamente.", en_pregunta:"What happens if a metallic raceway (EMT) is interrupted by a plastic box without a bonding jumper?", en_opciones:["Current flows better","The ground path is lost, leaving the downstream metallic conduit energized in a fault","Money is saved","Voltage is improved"], en_explicacion:"Metallic continuity is vital for electrical protections to operate correctly." },
  { id:"osha_158", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué clase de guantes de goma se requieren para trabajar en un sistema de 13,200V (Media Tensión)?", opciones:["Clase 0", "Clase 1", "Clase 2 (hasta 17,000V)", "Clase 00"], respuesta_correcta:2, explicacion:"La Clase 2 está probada para un voltaje de uso máximo de 17,000V AC.", en_pregunta:"What class of rubber gloves is required to work on a 13,200V (Medium Voltage) system?", en_opciones:["Class 0","Class 1","Class 2 (up to 17,000V)","Class 00"], en_explicacion:"Class 2 is tested for a maximum use voltage of 17,000V AC." },
  { id:"osha_159", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Al trabajar en un techo inclinado con paneles solares, ¿cuál es el peligro de una 'Falla de Arco de Serie' (Series Arc)?", opciones:["Que el sol brille más", "Un incendio en los conectores MC4 que no puede ser detectado por un breaker convencional", "Que los paneles se rompan", "Que el inversor se enfríe"], respuesta_correcta:1, explicacion:"Los arcos de serie ocurren cuando una conexión se afloja; generan calor extremo y fuego sin disparar las protecciones de sobrecorriente.", en_pregunta:"When working on a pitched roof with solar panels, what is the hazard of a 'Series Arc Fault'?", en_opciones:["That the sun shines more","A fire in the MC4 connectors that cannot be detected by a conventional breaker","That the panels break","That the inverter cools down"], en_explicacion:"Series arcs occur when a connection becomes loose; they generate extreme heat and fire without tripping overcurrent protections." },
  { id:"osha_160", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué significa el término 'De-energized' (Desenergizado) según la normativa de seguridad?", opciones:["Apagar el interruptor", "Desconectado de todas las fuentes de energía y verificado mediante prueba de voltaje", "Quitar los cables", "Ponerle cinta al breaker"], respuesta_correcta:1, explicacion:"No está realmente desenergizado hasta que se prueba que no hay voltaje presente.", en_pregunta:"What does 'De-energized' mean according to safety standards?", en_opciones:["Turning off the switch","Disconnected from all energy sources and verified by a voltage test","Removing the conductors","Placing tape on the breaker"], en_explicacion:"It is not truly de-energized until it is tested to confirm no voltage is present." },
  { id:"osha_161", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué OSHA prohíbe el uso de cables de extensión (cords) como sustituto del cableado permanente de un edificio?", opciones:["Porque son muy baratos", "Porque no están diseñados para soportar el calor sostenido y el estrés físico del uso a largo plazo", "Porque los colores son molestos", "No están prohibidos"], respuesta_correcta:1, explicacion:"Las extensiones son para uso temporal solamente; el uso prolongado degrada el aislamiento y causa incendios.", en_pregunta:"Why does OSHA prohibit using extension cords as a substitute for a building's permanent wiring?", en_opciones:["Because they are very cheap","Because they are not designed to withstand the sustained heat and physical stress of long-term use","Because the colors are annoying","They are not prohibited"], en_explicacion:"Extension cords are for temporary use only; prolonged use degrades the insulation and causes fires." },
  { id:"osha_162", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué componente de seguridad protege contra un choque eléctrico si un cable vivo toca la carcasa de un equipo que NO está aterrizado?", opciones:["El breaker", "El fusible", "Ninguno, el chasis queda vivo hasta que alguien lo toca y cierra el circuito a tierra", "El aislante del motor"], respuesta_correcta:2, explicacion:"Sin tierra de seguridad, las protecciones de sobrecorriente (breakers) no 'saben' que hay una falla.", en_pregunta:"Which safety component protects against electric shock if a live conductor touches the enclosure of equipment that is NOT grounded?", en_opciones:["The breaker","The fuse","None; the chassis remains live until someone touches it and completes the circuit to ground","The motor insulation"], en_explicacion:"Without safety ground, overcurrent protections (breakers) do not 'know' there is a fault." },
  { id:"osha_163", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un técnico encuentra que el interruptor principal tiene un candado 'Maestro' que él no puede abrir. ¿Qué debe hacer?", opciones:["Usar su propia llave para intentar abrirlo", "Colocar su propio candado personal en una aldaba (hasp) multi-candado", "Cortar el candado", "Trabajar así"], respuesta_correcta:1, explicacion:"Cada trabajador involucrado debe tener su propio candado personal en el punto de aislamiento.", en_pregunta:"A technician finds that the main disconnect has a 'Master' padlock that he cannot open. What should he do?", en_opciones:["Use his own key to try to open it","Place his own personal padlock on a multi-lock hasp","Cut the padlock","Work anyway"], en_explicacion:"Every worker involved must place their own personal lock on the isolation point." },
  { id:"osha_164", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"En un sistema industrial de 480V, ¿cuál es el peligro de un 'Neutro Flotante'?", opciones:["Que el equipo consuma menos", "Voltajes impredecibles que pueden elevarse hasta 480V en circuitos de 277V, quemando equipos y causando incendios", "Ahorro de energía", "Que el motor gire más rápido"], respuesta_correcta:1, explicacion:"La pérdida del neutro destruye la referencia de voltaje, creando condiciones peligrosas para el personal.", en_pregunta:"In a 480V industrial system, what is the hazard of a 'Floating Neutral'?", en_opciones:["That equipment uses less energy","Unpredictable voltages that can rise up to 480V on 277V circuits, burning out equipment and causing fires","Energy savings","That the motor runs faster"], en_explicacion:"Loss of the neutral destroys the voltage reference, creating dangerous conditions for personnel." },
  { id:"osha_165", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la causa principal de la presión explosiva en un Arc Blast?", opciones:["El aire frío", "La expansión instantánea del metal (cobre) al vaporizarse (hasta 67,000 veces su volumen original)", "El ruido", "La gravedad"], respuesta_correcta:1, explicacion:"El metal sólido se convierte en gas instantáneamente, creando una onda de choque mecánica destructiva.", en_pregunta:"What is the main cause of explosive pressure in an Arc Blast?", en_opciones:["Cold air","The instantaneous expansion of metal (copper) as it vaporizes (up to 67,000 times its original volume)","The noise","Gravity"], en_explicacion:"Solid metal turns to gas instantaneously, creating a destructive mechanical shock wave." },
  { id:"osha_166", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la diferencia entre un 'Grounded Conductor' y un 'Grounding Conductor'?", opciones:["Son lo mismo", "El 'Grounded' es el neutro (blanco); el 'Grounding' es el cable de tierra de seguridad (verde)", "El 'Grounded' es el vivo", "Uno es de plástico y otro de cobre"], respuesta_correcta:1, explicacion:"Es terminología crítica del NEC/OSHA para evitar conexiones erróneas que energicen chasis metálicos.", en_pregunta:"What is the difference between a 'Grounded Conductor' and a 'Grounding Conductor'?", en_opciones:["They are the same","The 'Grounded' is the neutral (white); the 'Grounding' is the safety ground conductor (green)","The 'Grounded' is the hot","One is plastic and the other copper"], en_explicacion:"Critical NEC/OSHA terminology to avoid wiring errors that energize metallic enclosures." },
  { id:"osha_167", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿A qué voltaje se considera que un sistema es 'Alta Tensión' para efectos de entrenamiento especializado?", opciones:["120V", "600V o más", "240V", "480V"], respuesta_correcta:1, explicacion:"Por encima de 600V (o 1000V en normativas nuevas), los riesgos de arco a través del aire y las distancias de seguridad cambian drásticamente.", en_pregunta:"At what voltage is a system considered 'High Voltage' for the purposes of specialized training?", en_opciones:["120V","600V or more","240V","480V"], en_explicacion:"Above 600V (or 1000V under newer standards), the risks of arc-through-air and safety clearances change drastically." },
  { id:"osha_168", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si un cable de alimentación tiene el aislamiento agrietado pero el cobre no se ve, ¿es seguro usarlo?", opciones:["Sí, no hay peligro", "No; OSHA prohíbe el uso de cables dañados, ya que la humedad o el contacto pueden causar una falla", "Solo si se envuelve en cinta de papel", "Solo en interiores"], respuesta_correcta:1, explicacion:"El aislamiento agrietado no garantiza la rigidez dieléctrica necesaria para proteger al técnico.", en_pregunta:"If a supply cable has cracked insulation but the copper is not exposed, is it safe to use?", en_opciones:["Yes, no danger","No; OSHA prohibits the use of damaged cables, as moisture or contact can cause a failure","Only if wrapped in paper tape","Only indoors"], en_explicacion:"Cracked insulation does not guarantee the dielectric strength required to protect the technician." },
  { id:"osha_169", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la función de una careta (Face Shield) con clasificación 'Arc Rated'?", opciones:["Para que no le pegue el sol", "Proteger contra el calor radiante y los desechos de un arco eléctrico", "Sustituir a los lentes de seguridad", "Para que no le vean la cara"], respuesta_correcta:1, explicacion:"Debe usarse junto con lentes de seguridad para proteger la vista y la piel de quemaduras térmicas.", en_pregunta:"What is the function of an Arc Rated face shield?", en_opciones:["So the sun doesn't hit you","Protecting against the radiant heat and debris of an arc flash","Replacing safety glasses","So people can't see your face"], en_explicacion:"It must be used together with safety glasses to protect vision and skin from thermal burns." },
  { id:"osha_170", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Por qué es más peligrosa la Corriente Alterna (60Hz) que la Continua en términos de choque al corazón?", opciones:["Porque tiene más amperios", "Porque la frecuencia de 60Hz interfiere directamente con el ritmo cardíaco (fibrilación)", "Porque la CA es más rápida", "No es más peligrosa"], respuesta_correcta:1, explicacion:"La frecuencia de la red eléctrica comercial es casi idéntica a la frecuencia de los impulsos nerviosos del corazón.", en_pregunta:"Why is Alternating Current (60Hz) more dangerous than Direct Current in terms of shock to the heart?", en_opciones:["Because it has more amperage","Because the 60Hz frequency directly interferes with the cardiac rhythm (fibrillation)","Because AC is faster","It is not more dangerous"], en_explicacion:"The commercial grid frequency is nearly identical to the frequency of the heart's nerve impulses." },
  { id:"osha_171", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un multímetro con la pantalla rota pero que aún mide debe:", opciones:["Usarse con cuidado", "Ser retirado de servicio, ya que la integridad física del aparato es parte de su rating de seguridad", "Pegarse con cinta", "Usarse solo en 24V"], respuesta_correcta:1, explicacion:"Una fisura en la carcasa o pantalla puede permitir que un arco eléctrico entre al aparato y explote en las manos del técnico.", en_pregunta:"A multimeter with a cracked display that still takes readings must:", en_opciones:["Be used with care","Be removed from service, since the physical integrity of the instrument is part of its safety rating","Be taped together","Be used only on 24V"], en_explicacion:"A crack in the case or display can allow an electrical arc to enter the instrument and explode in the technician's hands." },
  { id:"osha_172", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un transformador de 480V tiene un ruido metálico interno (chattering). Antes de abrirlo, ¿qué riesgo de seguridad mecánica existe además del eléctrico?", opciones:["Que el aceite esté frío", "Fuerzas electromagnéticas que pueden causar que las láminas del núcleo salgan proyectadas si fallan los pernos", "Que el transformador se apague solo", "Ninguno"], respuesta_correcta:1, explicacion:"En fallas severas, las fuerzas magnéticas pueden ser tan intensas que destruyen físicamente la estructura del equipo.", en_pregunta:"A 480V transformer has an internal metallic chattering sound. Before opening it, what mechanical safety hazard exists besides the electrical one?", en_opciones:["That the oil is cold","Electromagnetic forces that can project core laminations if the mounting bolts fail","That the transformer shuts itself off","None"], en_explicacion:"In severe faults, magnetic forces can be intense enough to physically destroy the equipment structure." },
  { id:"osha_173", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Si un técnico usa un multímetro para medir voltaje y este 'explota' debido a un arco interno, ¿cuál fue la causa más probable de seguridad?", opciones:["Puntas de prueba mal conectadas o multímetro con categoría (CAT) insuficiente para los transitorios del sistema", "La batería del multímetro era vieja", "El técnico tenía las manos sucias", "El cable era muy largo"], respuesta_correcta:0, explicacion:"Los picos de voltaje (transitorios) pueden saltar entre las pistas del multímetro si no tiene la protección CAT III/IV y fusibles HRC adecuados.", en_pregunta:"If a technician uses a multimeter to measure voltage and it 'explodes' due to an internal arc, what was the most likely safety-related cause?", en_opciones:["Improperly connected test leads or a multimeter with a category (CAT) rating insufficient for the system's transients","The multimeter battery was old","The technician had dirty hands","The cable was too long"], en_explicacion:"Voltage spikes (transients) can jump across the multimeter's PCB traces if it lacks proper CAT III/IV protection and HRC fuses." },
  { id:"osha_174", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué se debe usar para limpiar un panel eléctrico según la norma de seguridad?", opciones:["Agua y jabón", "Aire comprimido a baja presión y solventes aprobados no-conductores (Dielectric cleaners)", "Un trapo húmedo", "Una escoba de metal"], respuesta_correcta:1, explicacion:"Los solventes dieléctricos aseguran que no se creen puentes de conducción accidental entre fases.", en_pregunta:"What should be used to clean an electrical panel per safety standards?", en_opciones:["Water and soap","Low-pressure compressed air and approved non-conductive (dielectric) solvents","A damp rag","A metal broom"], en_explicacion:"Dielectric solvents ensure that accidental conductive paths between phases are not created." },
  { id:"osha_175", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es un 'Grounded Loop' (Lazo de tierra) y por qué es un riesgo de seguridad industrial?", opciones:["Un cable circular", "Conexiones de tierra redundantes que crean corrientes circulantes peligrosas e interfieren con protecciones", "Una buena señal de radio", "No es un riesgo"], respuesta_correcta:1, explicacion:"Los lazos de tierra pueden causar que las superficies metálicas tengan voltajes parásitos peligrosos.", en_pregunta:"What is a 'Ground Loop' and why is it an industrial safety risk?", en_opciones:["A circular cable","Redundant ground connections that create dangerous circulating currents and interfere with protections","A good radio signal","It is not a risk"], en_explicacion:"Ground loops can cause metallic surfaces to carry dangerous stray voltages." },
  { id:"osha_176", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cómo se debe probar un guante aislante de goma antes de empezar el trabajo (Field Test)?", opciones:["Mirándolo a la luz", "Inflándolo con aire (Air test) para buscar fugas microscópicas o pinchazos", "Estirándolo con fuerza", "Sumergiéndolo en aceite"], respuesta_correcta:1, explicacion:"Incluso un pinchazo del tamaño de un alfiler permite que la corriente pase al técnico.", en_pregunta:"How must a rubber insulating glove be field tested before starting work?", en_opciones:["Looking at it against the light","Inflating it with air (Air test) to check for microscopic leaks or punctures","Stretching it forcefully","Submerging it in oil"], en_explicacion:"Even a pinhole allows current to pass to the technician." },
  { id:"osha_177", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es el peligro de la 'Inducción Electromagnética' al trabajar en cables desenergizados que corren paralelos a cables de alta tensión?", opciones:["Que los cables se atraigan como imanes", "El cable 'apagado' puede cargarse con un voltaje letal por inducción del cable energizado cercano", "Que el cable se caliente", "Ninguno"], respuesta_correcta:1, explicacion:"La inducción puede matar a un técnico que cree que el cable es seguro solo porque el breaker está abierto.", en_pregunta:"What is the hazard of 'Electromagnetic Induction' when working on de-energized cables running parallel to high-voltage lines?", en_opciones:["That the cables attract each other like magnets","The 'off' cable can be energized with lethal voltage by induction from the nearby energized line","That the cable heats up","None"], en_explicacion:"Induction can kill a technician who believes the cable is safe just because the breaker is open." },
  { id:"osha_178", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un condensador (capacitor) electrolítico que está 'hinchado' o deformado indica:", opciones:["Que tiene mucha energía acumulada", "Falla interna inminente y riesgo de explosión violenta por acumulación de gas", "Que es de mejor calidad", "Que el motor está frío"], respuesta_correcta:1, explicacion:"La deformación física es señal de que la presión interna ha superado los límites de seguridad.", en_pregunta:"An electrolytic capacitor that is 'swollen' or deformed indicates:", en_opciones:["That it is holding a lot of stored energy","Imminent internal failure and risk of violent explosion from gas buildup","That it is higher quality","That the motor is cold"], en_explicacion:"Physical deformation is a sign that internal pressure has exceeded safety limits." },
  { id:"osha_179", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Cuál es la diferencia entre un cable de tierra de seguridad y el 'Grounded Conductor' (Neutro)?", opciones:["Son el mismo cable", "El neutro lleva corriente en condiciones normales; la tierra solo lleva corriente durante una falla", "La tierra es de color rojo", "El neutro es de cobre desnudo"], respuesta_correcta:1, explicacion:"Confundirlos crea condiciones donde el chasis de los equipos puede quedar energizado permanentemente.", en_pregunta:"What is the difference between a safety ground conductor and the 'Grounded Conductor' (Neutral)?", en_opciones:["They are the same conductor","The neutral carries current under normal conditions; the ground only carries current during a fault","The ground is red","The neutral is bare copper"], en_explicacion:"Confusing them creates conditions where equipment enclosures may be permanently energized." },
  { id:"osha_180", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"¿Qué es un 'Interlock' de seguridad en un panel industrial?", opciones:["Un candado de llave", "Un dispositivo que corta la energía automáticamente si se abre la puerta del gabinete", "Una marca de interruptor", "Un cable más grueso"], respuesta_correcta:1, explicacion:"Los interlocks previenen el acceso accidental a partes energizadas de alto riesgo.", en_pregunta:"What is a safety 'Interlock' on an industrial panel?", en_opciones:["A keyed padlock","A device that automatically cuts power if the enclosure door is opened","A label on a switch","A thicker conductor"], en_explicacion:"Interlocks prevent accidental access to high-risk energized parts." },
  { id:"osha_181", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un técnico calificado debe realizar un 'Análisis de Peligro de Choque' para determinar:", opciones:["Cuánto va a cobrar", "El voltaje del sistema, las fronteras de aproximación y el EPP necesario", "Si el cliente es amable", "La marca del panel"], respuesta_correcta:1, explicacion:"Este análisis es obligatorio antes de realizar cualquier tarea cerca de circuitos energizados.", en_pregunta:"A qualified technician must perform a 'Shock Hazard Analysis' to determine:", en_opciones:["How much to charge","The system voltage, approach boundaries, and required PPE","Whether the customer is friendly","The panel brand"], en_explicacion:"This analysis is mandatory before performing any task near energized circuits." },
  { id:"osha_182", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un cable de media tensión de 15 kV tiene una pantalla semiconductora dañada en un tramo de 10 cm. ¿Qué fenómeno ocurrirá al energizar?", opciones:["Descarga parcial superficial.", "Arco trifásico inmediato.", "Calentamiento resistivo.", "No pasa nada, la pantalla es solo mecánica."], respuesta_correcta:0, explicacion:"Daño en pantalla semiconductora causa concentración de campo eléctrico y descargas parciales.", en_pregunta:"A 15 kV medium-voltage cable has damaged semiconducting screening over a 10 cm section. What phenomenon will occur when energized?", en_opciones:["Surface partial discharge.","Immediate three-phase arc.","Resistive heating.","Nothing happens, the screen is only mechanical."], en_explicacion:"Damage to the semiconducting screen causes electric field concentration and partial discharge." },
  { id:"osha_183", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un banco de capacitores de 13.8 kV tiene reactores de limitación de corriente. ¿Qué falla hace que los reactores sean inútiles?", opciones:["Cortocircuito en los propios reactores.", "Falla a tierra en el neutro.", "Sobretensión por ferroresonancia.", "Saturación magnética por DC offset."], respuesta_correcta:3, explicacion:"Saturación por componente DC elimina la inductancia, anulando la limitación de corriente.", en_pregunta:"A 13.8 kV capacitor bank has current-limiting reactors. What failure makes the reactors useless?", en_opciones:["Short circuit in the reactors themselves.","Ground fault on the neutral.","Overvoltage from ferroresonance.","Magnetic saturation from DC offset."], en_explicacion:"Saturation from a DC component eliminates the inductance, nullifying current limiting." },
  { id:"osha_184", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor de 400 HP tiene una protección de sobrecarga térmica ajustada a 1.15 x In. El motor opera a 1.1 x In continuo. ¿Es seguro?", opciones:["Sí, porque está dentro del factor de servicio.", "No, porque el calentamiento puede dañar el aislamiento a largo plazo.", "Sí, si el motor es clase F.", "No, porque la protección no permite operación continua sobre In."], respuesta_correcta:1, explicacion:"Factor de servicio 1.15 permite sobrecarga ocasional, no continua; reduce vida útil del aislamiento.", en_pregunta:"A 400 HP motor has a thermal overload protection set to 1.15 x In. The motor operates at 1.1 x In continuously. Is this safe?", en_opciones:["Yes, because it is within the service factor.","No, because the heating can damage the insulation long-term.","Yes, if the motor is class F.","No, because the protection does not allow continuous operation above In."], en_explicacion:"A 1.15 service factor allows occasional overload, not continuous; it reduces the useful life of the insulation." },
  { id:"osha_185", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un transformador de 2500 kVA tiene una prueba de relación de vueltas (TTR) que muestra 1% de error. ¿Es aceptable?", opciones:["Sí, 1% está dentro de tolerancia.", "No, la tolerancia máxima es 0.5%.", "Sí, si el transformador es de distribución.", "No, porque puede indicar espiras en corto."], respuesta_correcta:3, explicacion:"1% de error en TTR sugiere espiras en cortocircuito en el devanado.", en_pregunta:"A 2500 kVA transformer has a Turns Ratio Test (TTR) showing 1% error. Is it acceptable?", en_opciones:["Yes, 1% is within tolerance.","No, the maximum tolerance is 0.5%.","Yes, if the transformer is distribution class.","No, because it may indicate shorted turns."], en_explicacion:"1% error in TTR suggests shorted turns in the winding." },
  { id:"osha_186", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor de inducción de 100 HP tiene una corriente de vacío de 30 A. La corriente a plena carga es 120 A. ¿Qué indica una corriente de vacío de 50 A?", opciones:["Rodamientos desgastados.", "Espiras en cortocircuito en el estator.", "Bajo voltaje de alimentación.", "Exceso de entrehierro."], respuesta_correcta:1, explicacion:"Alta corriente de vacío indica espiras en corto o problemas magnéticos en el núcleo.", en_pregunta:"A 100 HP induction motor has a no-load current of 30 A. Full-load current is 120 A. What does a no-load current of 50 A indicate?", en_opciones:["Worn bearings.","Shorted turns in the stator.","Low supply voltage.","Excess air gap."], en_explicacion:"High no-load current indicates shorted turns or magnetic problems in the core." },
  { id:"osha_187", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un interruptor de alta tensión SF6 tiene una presión de gas de 6 bar. El manómetro marca 5.5 bar. ¿Qué indica?", opciones:["Fuga de SF6.", "Temperatura ambiente baja.", "Sobrecarga del interruptor.", "Normal, variación permitida."], respuesta_correcta:0, explicacion:"Caída de presión SF6 indica fuga; riesgo de pérdida de capacidad de extinción de arco.", en_pregunta:"An SF6 high-voltage breaker has a gas pressure of 6 bar. The gauge reads 5.5 bar. What does this indicate?", en_opciones:["SF6 leak.","Low ambient temperature.","Breaker overload.","Normal, allowable variation."], en_explicacion:"A drop in SF6 pressure indicates a leak; there is a risk of losing arc extinguishing capability." },
  { id:"osha_188", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un generador diésel de 1000 kVA tiene una corriente de excitación de 300 A DC. El puente rectificador tiene un diodo abierto. ¿Qué efecto tiene en el voltaje de salida?", opciones:["Caída del 50% del voltaje.", "Ondulación excesiva y posible saturación.", "Aumento del voltaje por compensación.", "No afecta porque el regulador compensa."], respuesta_correcta:1, explicacion:"Diodo abierto causa rectificación de media onda, aumentando ripple y calentamiento del rotor.", en_pregunta:"A 1000 kVA diesel generator has a DC excitation current of 300 A. The rectifier bridge has an open diode. What effect does this have on the output voltage?", en_opciones:["50% drop in voltage.","Excessive ripple and possible saturation.","Voltage increase by compensation.","Does not affect because the regulator compensates."], en_explicacion:"An open diode causes half-wave rectification, increasing ripple and rotor heating." },
  { id:"osha_189", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor de 200 HP tiene una protección diferencial (87) que dispara. ¿Qué falla interna indica?", opciones:["Falla a tierra externa.", "Cortocircuito entre fases en el estator.", "Sobrecarga térmica.", "Pérdida de una fase."], respuesta_correcta:1, explicacion:"Protección diferencial compara corriente de entrada y salida; dispara por falla interna en el motor.", en_pregunta:"A 200 HP motor has a differential protection (87) that trips. What internal fault does it indicate?", en_opciones:["External ground fault.","Phase-to-phase short circuit in the stator.","Thermal overload.","Loss of a phase."], en_explicacion:"Differential protection compares input and output current; it trips on an internal fault in the motor." },
  { id:"osha_190", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un transformador de corriente (TC) tiene su secundario en cortocircuito permanente. ¿Es seguro?", opciones:["Sí, los TC deben operar con secundario en corto.", "No, el corto permanente puede dañar el TC.", "Sí, si la carga es menor a 5 VA.", "No, porque el TC se satura."], respuesta_correcta:0, explicacion:"TC debe operar con secundario en corto (o con carga); secundario abierto es peligroso.", en_pregunta:"A current transformer (CT) has its secondary permanently shorted. Is it safe?", en_opciones:["Yes, CTs must operate with the secondary shorted.","No, the permanent short can damage the CT.","Yes, if the load is less than 5 VA.","No, because the CT saturates."], en_explicacion:"CTs must operate with the secondary shorted (or loaded); an open secondary is dangerous." },
  { id:"osha_191", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor de 500 HP tiene una corriente de arranque de 3000 A. El interruptor general tiene capacidad de 2000 A. ¿Qué ocurre al arrancar?", opciones:["El interruptor dispara por sobrecorriente.", "El motor arranca normalmente.", "El interruptor se daña por arco.", "El motor no arranca."], respuesta_correcta:0, explicacion:"Corriente de arranque (3000 A) excede capacidad del interruptor (2000 A), causando disparo.", en_pregunta:"A 500 HP motor has a starting current of 3000 A. The main breaker is rated for 2000 A. What happens on start-up?", en_opciones:["The breaker trips on overcurrent.","The motor starts normally.","The breaker is damaged by arcing.","The motor does not start."], en_explicacion:"The starting current (3000 A) exceeds the breaker's capacity (2000 A), causing a trip." },
  { id:"osha_192", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un capacitor de potencia de 480V tiene una resistencia de descarga de 100 kΩ. El capacitor es de 100 μF. ¿Cuánto tiempo tarda en descargar a 50V?", opciones:["5 segundos.", "50 segundos.", "115 segundos (5 x R x C = 5 x 100k x 100μF = 50,000 μF? cálculo).", "Depende del voltaje inicial."], respuesta_correcta:2, explicacion:"Tiempo = 5 x R x C = 5 x 100,000 x 0.0001 = 50 segundos.", en_pregunta:"A 480V power capacitor has a discharge resistor of 100 kΩ. The capacitor is 100 μF. How long does it take to discharge to 50V?", en_opciones:["5 seconds.","50 seconds.","115 seconds (5 x R x C = 5 x 100k x 100μF = 50,000 μF? calculation).","Depends on the initial voltage."], en_explicacion:"Time = 5 x R x C = 5 x 100,000 x 0.0001 = 50 seconds." },
  { id:"osha_193", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un motor de inducción de 75 HP tiene un desbalance de corriente entre fases del 8%. ¿Qué acción es necesaria?", opciones:["Ninguna, 8% está dentro de tolerancia.", "Investigar causa; puede indicar falla de aislamiento.", "Reducir la carga a 50%.", "Reemplazar el motor inmediatamente."], respuesta_correcta:1, explicacion:"Desbalance > 5% indica problema en motor o alimentación.", en_pregunta:"A 75 HP induction motor has an 8% current imbalance between phases. What action is required?", en_opciones:["None, 8% is within tolerance.","Investigate cause; may indicate insulation failure.","Reduce load to 50%.","Replace the motor immediately."], en_explicacion:"An imbalance > 5% indicates a problem in the motor or supply." },
  { id:"osha_194", categoria:"OSHA_RIESGO_ELECTRICO", pregunta:"Un transformador de 500 kVA tiene aceite con gas etileno > 500 ppm. ¿Qué indica?", opciones:["Sobrecarga térmica del papel aislante.", "Arco eléctrico interno.", "Oxidación normal del aceite.", "Contaminación por humedad."], respuesta_correcta:0, explicacion:"Etileno indica calentamiento del papel aislante (> 150°C).", en_pregunta:"A 500 kVA transformer has oil with ethylene > 500 ppm. What does this indicate?", en_opciones:["Thermal overload of the insulating paper.","Internal electrical arc.","Normal oil oxidation.","Moisture contamination."], en_explicacion:"Ethylene indicates heating of the insulating paper (> 150°C)." },

  // -- CAIDAS -- Fall Protection (195-239) --
  { id:"osha_195", categoria:"OSHA_CAIDAS", pregunta:"¿Cuál es la fuerza máxima de detención que un arnés de cuerpo completo debe permitir sobre el trabajador según OSHA?", opciones:["900 lbs", "1800 lbs", "3000 lbs", "5000 lbs"], respuesta_correcta:1, explicacion:"OSHA limita la fuerza de impacto a 1800 lbs para minimizar lesiones internas durante la caída.", en_pregunta:"What is the maximum arresting force that a full-body harness must allow on a worker per OSHA?", en_opciones:["900 lbs","1800 lbs","3000 lbs","5000 lbs"], en_explicacion:"OSHA limits the impact force to 1800 lbs to minimize internal injuries during a fall." },
  { id:"osha_196", categoria:"OSHA_CAIDAS", pregunta:"Un andamio debe ser capaz de soportar su propio peso y al menos cuantas veces la carga máxima prevista:", opciones:["2 veces", "4 veces", "6 veces", "10 veces"], respuesta_correcta:1, explicacion:"Regla del factor de seguridad 4:1 de OSHA para plataformas y andamios.", en_pregunta:"A scaffold must be able to support its own weight plus at least how many times the maximum intended load?", en_opciones:["2 times","4 times","6 times","10 times"], en_explicacion:"OSHA's 4:1 safety factor rule for platforms and scaffolds." },
  { id:"osha_197", categoria:"OSHA_CAIDAS", pregunta:"Las barandillas de seguridad deben resistir una fuerza de:", opciones:["50 lbs", "100 lbs", "200 lbs", "500 lbs"], respuesta_correcta:2, explicacion:"OSHA exige que el riel superior soporte 200 libras de fuerza aplicada en cualquier dirección hacia abajo o hacia afuera.", en_pregunta:"Safety guardrails must withstand a force of:", en_opciones:["50 lbs","100 lbs","200 lbs","500 lbs"], en_explicacion:"OSHA requires the top rail to withstand 200 pounds of force applied in any downward or outward direction." },
  { id:"osha_198", categoria:"OSHA_CAIDAS", pregunta:"Las áreas de trabajo deben mantenerse limpias de escombros y clavos para evitar:", opciones:["Que el cliente se enoje", "Punciones, tropiezos e incendios", "Que el inspector cobre más", "Que se pierdan las herramientas"], respuesta_correcta:1, explicacion:"El 'housekeeping' es la base de la prevención de accidentes en construcción.", en_pregunta:"Work areas must be kept clear of debris and nails to prevent:", en_opciones:["Upsetting the customer","Punctures, trips, and fires","Making the inspector charge more","Losing tools"], en_explicacion:"'Housekeeping' is the foundation of accident prevention in construction." },
  { id:"osha_199", categoria:"OSHA_CAIDAS", pregunta:"¿A qué altura debe estar el riel medio (mid-rail) de un andamio?", opciones:["10 pulgadas", "Aproximadamente a la mitad entre la plataforma y el riel superior (21 pulgadas)", "A 42 pulgadas", "No se requiere riel medio"], respuesta_correcta:1, explicacion:"Sirve para evitar que un trabajador se deslice por debajo del riel superior si se cae.", en_pregunta:"At what height should the mid-rail of a scaffold be?", en_opciones:["10 inches","Approximately halfway between the platform and the top rail (21 inches)","At 42 inches","No mid-rail required"], en_explicacion:"It prevents a worker from sliding under the top rail if they fall." },
  { id:"osha_200", categoria:"OSHA_CAIDAS", pregunta:"Se permite el uso de mangueras de manifold que tengan grietas superficiales si:", opciones:["Se envuelven en cinta eléctrica", "No se permite; deben reemplazarse para evitar rupturas bajo alta presión", "Solo se usan en el lado de baja", "Si la fuga es pequeña"], respuesta_correcta:1, explicacion:"Las mangueras de refrigeración soportan cientos de psi; cualquier defecto estructural es un riesgo de proyectil o quemadura.", en_pregunta:"Manifold hoses with surface cracks can be used if:", en_opciones:["They are wrapped in electrical tape","Not permitted; they must be replaced to prevent rupture under high pressure","They are only used on the low side","The leak is small"], en_explicacion:"Refrigeration hoses withstand hundreds of psi; any structural defect is a projectile or burn hazard." },
  { id:"osha_201", categoria:"OSHA_CAIDAS", pregunta:"Al izar un condensador con una grúa, ¿quién tiene la autoridad para dar la señal de parada de emergencia (Stop)?", opciones:["Solo el operador de la grúa", "Solo el supervisor", "Cualquier persona que vea un peligro", "Nadie, una vez que sube no se detiene"], respuesta_correcta:2, explicacion:"Cualquier trabajador en el sitio tiene la autoridad y obligación de detener una maniobra si detecta un riesgo.", en_pregunta:"When hoisting a condensing unit with a crane, who has the authority to give the emergency stop signal?", en_opciones:["Only the crane operator","Only the supervisor","Anyone who sees a hazard","Nobody, once it goes up it doesn't stop"], en_explicacion:"Any worker on site has the authority and obligation to stop a lift if they detect a hazard." },
  { id:"osha_202", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida (Lanyard) con absorbedor de choque debe usarse solo si hay una distancia de caída libre de al menos:", opciones:["6 pies", "18.5 pies (considerando elongación, altura del trabajador y margen de seguridad)", "2 pies", "50 pies"], respuesta_correcta:1, explicacion:"Si la caída es corta, el absorbedor no llegará a desplegarse antes de que el trabajador golpee el suelo.", en_pregunta:"A lanyard with a shock absorber should only be used if there is a free-fall distance of at least:", en_opciones:["6 feet","18.5 feet (considering elongation, worker height, and safety margin)","2 feet","50 feet"], en_explicacion:"If the fall is short, the shock absorber will not fully deploy before the worker hits the ground." },
  { id:"osha_203", categoria:"OSHA_CAIDAS", pregunta:"¿Qué distancia mínima debe haber entre una toma de agua y un panel eléctrico?", opciones:["1 pie", "3 pies", "6 pies", "No hay distancia si el panel es NEMA 3R"], respuesta_correcta:1, explicacion:"Aunque el código varía, 3 pies es la distancia de seguridad estándar para evitar salpicaduras accidentales en equipo vivo.", en_pregunta:"What minimum distance must there be between a water tap and an electrical panel?", en_opciones:["1 foot","3 feet","6 feet","No distance required if the panel is NEMA 3R"], en_explicacion:"Although code varies, 3 feet is the standard safe distance to prevent accidental splashes on live equipment." },
  { id:"osha_204", categoria:"OSHA_CAIDAS", pregunta:"Un grillete (shackle) con el pin sustituido por un tornillo común es:", opciones:["Una reparación ingeniosa", "Extremadamente peligroso y prohibido por OSHA (el tornillo fallará bajo carga)", "Permitido si el tornillo es de acero inoxidable", "Seguro para cargas ligeras"], respuesta_correcta:1, explicacion:"Los componentes de izaje deben estar certificados; un tornillo común no tiene la resistencia al corte necesaria.", en_pregunta:"A shackle with its pin replaced by a common bolt is:", en_opciones:["A clever repair","Extremely dangerous and prohibited by OSHA (the bolt will fail under load)","Allowed if the bolt is stainless steel","Safe for light loads"], en_explicacion:"Rigging components must be rated; a common bolt does not have the shear strength required." },
  { id:"osha_205", categoria:"OSHA_CAIDAS", pregunta:"Al mover un andamio rodante, los trabajadores:", opciones:["Pueden quedarse arriba si se agarran fuerte", "Deben bajar antes de que el andamio sea movido", "Pueden ayudar a empujar desde arriba", "Deben saltar al suelo"], respuesta_correcta:1, explicacion:"Mover un andamio con personas arriba es una de las causas más comunes de vuelcos fatales.", en_pregunta:"When moving a rolling scaffold, workers:", en_opciones:["Can stay on top if they hold on tight","Must dismount before the scaffold is moved","Can help push from above","Must jump to the ground"], en_explicacion:"Moving a scaffold with personnel aboard is one of the most common causes of fatal tip-overs." },
  { id:"osha_206", categoria:"OSHA_CAIDAS", pregunta:"¿Qué componente de un andamio evita que las herramientas caigan y golpeen a alguien abajo?", opciones:["La barandilla", "El rodapié (Toe-board)", "La red de seguridad", "El arnés"], respuesta_correcta:1, explicacion:"Los rodapiés son obligatorios cuando hay personal trabajando o transitando debajo del andamio.", en_pregunta:"What scaffold component prevents tools from falling and striking someone below?", en_opciones:["The guardrail","The toe-board","The safety net","The harness"], en_explicacion:"Toe-boards are mandatory when there is personnel working or passing beneath the scaffold." },
  { id:"osha_207", categoria:"OSHA_CAIDAS", pregunta:"Si hay más de 20 trabajadores en una obra, ¿qué exige OSHA respecto a las escaleras?", opciones:["Que sean de oro", "Que haya escaleras separadas para subir y bajar o doble ancho", "Que cada trabajador tenga su propia escalera", "No hay requisito extra"], respuesta_correcta:1, explicacion:"Busca evitar aglomeraciones y accidentes en puntos de acceso críticos.", en_pregunta:"If there are more than 20 workers on a job site, what does OSHA require regarding ladders?", en_opciones:["That they be gold-plated","That there be separate ladders for up and down, or double-width ladders","That each worker have their own ladder","No extra requirement"], en_explicacion:"It is intended to avoid congestion and accidents at critical access points." },
  { id:"osha_208", categoria:"OSHA_CAIDAS", pregunta:"Durante una maniobra de izaje, ¿qué es un 'Punto de pellizco' (Pinch point)?", opciones:["Donde el técnico se rasca", "Cualquier punto donde una parte del cuerpo puede quedar atrapada entre piezas móviles o fijas", "El gancho de la grúa", "El peso de la carga"], respuesta_correcta:1, explicacion:"Identificar pinch points es clave para evitar aplastamientos y amputaciones.", en_pregunta:"During a lifting operation, what is a 'Pinch Point'?", en_opciones:["Where the technician scratches","Any point where a body part can be caught between moving or fixed parts","The crane hook","The weight of the load"], en_explicacion:"Identifying pinch points is key to preventing crushing injuries and amputations." },
  { id:"osha_209", categoria:"OSHA_CAIDAS", pregunta:"En andamios, ¿qué es un 'Trabajador Calificado'?", opciones:["El que tiene más años de trabajo", "Alguien que por posesión de un título o certificado profesional ha demostrado resolver problemas relacionados con la materia", "El dueño", "El que no tiene miedo"], respuesta_correcta:1, explicacion:"La calificación se basa en conocimiento demostrado y certificaciones.", en_pregunta:"On scaffolds, what is a 'Qualified Person'?", en_opciones:["The one with the most years on the job","Someone who, by possession of a professional degree or certificate, has demonstrated the ability to solve problems related to the matter","The owner","The one who is fearless"], en_explicacion:"Qualification is based on demonstrated knowledge and certifications." },
  { id:"osha_210", categoria:"OSHA_CAIDAS", pregunta:"OSHA exige barandales en escaleras que tengan cuántos elevadores (escalones) o más?", opciones:["2", "4", "10", "15"], respuesta_correcta:1, explicacion:"Escaleras con 4 o más escalones deben tener al menos un pasamanos.", en_pregunta:"OSHA requires handrails on stairways that have how many risers (steps) or more?", en_opciones:["2","4","10","15"], en_explicacion:"Stairways with 4 or more risers must have at least one handrail." },
  { id:"osha_211", categoria:"OSHA_CAIDAS", pregunta:"Al usar un sistema de 'Línea de Advertencia' en un techo plano comercial, ¿a qué distancia del borde debe colocarse la línea según OSHA?", opciones:["2 pies", "6 pies", "10 pies", "15 pies"], respuesta_correcta:1, explicacion:"Para trabajos de techado, la línea de advertencia debe estar a 6 pies del borde desprotegido.", en_pregunta:"When using a 'Warning Line System' on a commercial flat roof, how far from the edge must the line be placed per OSHA?", en_opciones:["2 feet","6 feet","10 feet","15 feet"], en_explicacion:"For roofing work, the warning line must be at least 6 feet from the unprotected edge." },
  { id:"osha_212", categoria:"OSHA_CAIDAS", pregunta:"¿Cuál es la señal manual estándar para indicar 'Parada de Emergencia' a un operador de grúa?", opciones:["Un dedo hacia arriba", "Ambos brazos extendidos horizontalmente moviéndose rápidamente de ida y vuelta", "Cerrar el puño", "Hacer un círculo con la mano"], respuesta_correcta:1, explicacion:"Es una señal universal de seguridad que cualquier trabajador debe conocer para detener una maniobra peligrosa.", en_pregunta:"What is the standard hand signal to indicate 'Emergency Stop' to a crane operator?", en_opciones:["One finger pointed up","Both arms extended horizontally, moving rapidly back and forth","Closing the fist","Making a circle with the hand"], en_explicacion:"It is a universal safety signal that any worker must know in order to stop a dangerous operation." },
  { id:"osha_213", categoria:"OSHA_CAIDAS", pregunta:"¿Quién debe supervisar el montaje, desmontaje o alteración de un andamio según OSHA?", opciones:["Cualquier trabajador", "Una 'Persona Competente' con entrenamiento específico en andamios", "El dueño del edificio", "Un arquitecto"], respuesta_correcta:1, explicacion:"Solo alguien con la autoridad y el conocimiento para identificar peligros puede supervisar estas maniobras.", en_pregunta:"Who must supervise the assembly, disassembly, or alteration of a scaffold per OSHA?", en_opciones:["Any worker","A 'Competent Person' with specific scaffold training","The building owner","An architect"], en_explicacion:"Only someone with the authority and knowledge to identify hazards may supervise these operations." },
  { id:"osha_214", categoria:"OSHA_CAIDAS", pregunta:"En una escalera fija industrial, si la altura de ascenso es mayor a 24 pies, ¿qué exige la nueva normativa de OSHA?", opciones:["Una jaula de protección solamente", "Un sistema de seguridad para escaleras (línea de vida vertical) o un sistema de detención de caídas", "Poner una alfombra", "Que la escalera sea de madera"], respuesta_correcta:1, explicacion:"OSHA está eliminando gradualmente las jaulas (cages) en favor de sistemas activos de detención de caídas en escaleras fijas.", en_pregunta:"On an industrial fixed ladder, if the climb height is greater than 24 feet, what does the new OSHA standard require?", en_opciones:["A protective cage only","A ladder safety system (vertical lifeline) or a fall arrest system","Laying down a mat","That the ladder be made of wood"], en_explicacion:"OSHA is gradually phasing out cages in favor of active fall arrest systems on fixed ladders." },
  { id:"osha_215", categoria:"OSHA_CAIDAS", pregunta:"¿A qué distancia mínima debe mantenerse cualquier maquinaria pesada de una línea eléctrica de 50kV?", opciones:["5 pies", "10 pies", "20 pies", "50 pies"], respuesta_correcta:1, explicacion:"OSHA exige una distancia mínima de 10 pies para voltajes de hasta 50kV para evitar arcos eléctricos al aire.", en_pregunta:"What minimum distance must any heavy machinery maintain from a 50kV power line?", en_opciones:["5 feet","10 feet","20 feet","50 feet"], en_explicacion:"OSHA requires a minimum clearance of 10 feet for voltages up to 50kV to prevent air-gap arcing." },
  { id:"osha_216", categoria:"OSHA_CAIDAS", pregunta:"¿Cuál es el ángulo de inclinación correcto para una escalera de extensión?", opciones:["45 grados", "75.5 grados (relación 4:1)", "90 grados", "30 grados"], respuesta_correcta:1, explicacion:"Por cada 4 pies de altura, la base debe estar a 1 pie de distancia de la pared.", en_pregunta:"What is the correct angle of inclination for an extension ladder?", en_opciones:["45 degrees","75.5 degrees (4:1 ratio)","90 degrees","30 degrees"], en_explicacion:"For every 4 feet of height, the base must be 1 foot out from the wall." },
  { id:"osha_217", categoria:"OSHA_CAIDAS", pregunta:"En el montaje de estructuras de acero, ¿a qué altura deben estar protegidos los trabajadores (excepto conectores)?", opciones:["6 pies", "15 pies", "30 pies", "4 pies"], respuesta_correcta:1, explicacion:"En 'Steel Erection', la regla general de protección contra caídas empieza a los 15 pies.", en_pregunta:"In steel erection, at what height must workers be protected (except connectors)?", en_opciones:["6 feet","15 feet","30 feet","4 feet"], en_explicacion:"In 'Steel Erection', the general fall protection rule starts at 15 feet." },
  { id:"osha_218", categoria:"OSHA_CAIDAS", pregunta:"¿Por qué es obligatorio cubrir las puntas expuestas de las varillas de refuerzo (rebar)?", opciones:["Para que no se oxiden", "Para evitar el empalamiento en caso de una caída", "Para que se vean mejor", "Para marcar el área"], respuesta_correcta:1, explicacion:"Caer sobre una varilla sin protección puede ser fatal; los 'rebar caps' deben estar diseñados para resistir el impacto.", en_pregunta:"Why is it mandatory to cover the exposed ends of rebar?", en_opciones:["To keep them from rusting","To prevent impalement in the event of a fall","To make them look better","To mark the area"], en_explicacion:"Falling onto unprotected rebar can be fatal; rebar caps must be rated to withstand the impact." },
  { id:"osha_219", categoria:"OSHA_CAIDAS", pregunta:"Un agujero en el suelo de una planta industrial de más de 2 pulgadas debe:", opciones:["Ser ignorado", "Estar tapado con una cubierta que soporte el doble del peso esperado y esté marcada como 'HOLE' o 'COVER'", "Pintarse de rojo", "Tener un cono cerca"], respuesta_correcta:1, explicacion:"Cualquier apertura que permita la caída de herramientas o personas debe estar asegurada físicamente.", en_pregunta:"A hole in the floor of an industrial plant larger than 2 inches must:", en_opciones:["Be ignored","Be covered with a cover rated for twice the expected load and marked 'HOLE' or 'COVER'","Be painted red","Have a cone nearby"], en_explicacion:"Any opening that can allow tools or people to fall must be physically secured." },
  { id:"osha_220", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de red de seguridad (safety net) debe probarse dejando caer una bolsa de arena de cuántas libras:", opciones:["100 lbs", "400 lbs", "1000 lbs", "50 lbs"], respuesta_correcta:1, explicacion:"La prueba de impacto asegura que la red y sus anclajes soportarán la caída de un trabajador pesado.", en_pregunta:"A safety net system must be tested by dropping a sandbag of how many pounds?", en_opciones:["100 lbs","400 lbs","1000 lbs","50 lbs"], en_explicacion:"The impact test ensures the net and its anchorages will support the fall of a heavy worker." },
  { id:"osha_221", categoria:"OSHA_CAIDAS", pregunta:"¿Cuánto debe extenderse el tablón (plank) de un andamio más allá de su soporte final si no está asegurado?", opciones:["Al ras", "Mínimo 6 pulgadas y máximo 12 pulgadas", "2 pies", "5 pies"], respuesta_correcta:1, explicacion:"Evita que el tablón se resbale o que haga un 'efecto trampolín' si un trabajador se para en el extremo.", en_pregunta:"How far must a scaffold plank extend beyond its end support if it is not secured?", en_opciones:["Flush","Minimum 6 inches and maximum 12 inches","2 feet","5 feet"], en_explicacion:"Prevents the plank from slipping or creating a 'trampoline effect' if a worker stands on the end." },
  { id:"osha_222", categoria:"OSHA_CAIDAS", pregunta:"El 'Anclaje' de un sistema de posicionamiento debe soportar al menos:", opciones:["5,000 lbs", "3,000 lbs (o el doble de la carga de impacto prevista)", "1,000 lbs", "El peso de la caja de herramientas"], respuesta_correcta:1, explicacion:"Sistemas de posicionamiento tienen requisitos distintos a los de detención de caídas, pero siguen siendo críticos.", en_pregunta:"The anchorage for a positioning device system must support at least:", en_opciones:["5,000 lbs","3,000 lbs (or twice the anticipated impact load)","1,000 lbs","The weight of the tool box"], en_explicacion:"Positioning systems have different requirements than fall arrest systems, but they are still critical." },
  { id:"osha_223", categoria:"OSHA_CAIDAS", pregunta:"¿Cuál es el 'Ángulo Crítico' de una eslinga (sling) donde la tensión aumenta drásticamente y puede causar una falla catastrófica?", opciones:["90 grados", "Menos de 30 grados respecto a la horizontal", "45 grados", "60 grados"], respuesta_correcta:1, explicacion:"A ángulos bajos (horizontales), la tensión en los brazos de la eslinga se multiplica exponencialmente, superando su capacidad nominal.", en_pregunta:"What is the 'critical angle' of a sling where tension increases dramatically and can cause catastrophic failure?", en_opciones:["90 degrees","Less than 30 degrees from horizontal","45 degrees","60 degrees"], en_explicacion:"At low (horizontal) angles, the tension on the sling legs multiplies exponentially, exceeding its rated capacity." },
  { id:"osha_224", categoria:"OSHA_CAIDAS", pregunta:"Al trabajar en una plataforma elevadora (Man-lift / Boom lift), ¿está permitido pararse sobre los rieles de protección para ganar altura?", opciones:["Sí, si el arnés está conectado", "No, los pies deben estar firmemente sobre el piso de la plataforma en todo momento", "Solo si un compañero te sostiene", "Solo en interiores"], respuesta_correcta:1, explicacion:"Subirse a los barandales anula la protección contra caídas y desplaza el centro de gravedad peligrosamente.", en_pregunta:"When working on a man-lift or boom lift, is it permitted to stand on the guardrails to gain height?", en_opciones:["Yes, if the harness is connected","No, feet must remain firmly on the platform floor at all times","Only if a coworker holds you","Only indoors"], en_explicacion:"Climbing on the guardrails defeats fall protection and shifts the center of gravity dangerously." },
  { id:"osha_225", categoria:"OSHA_CAIDAS", pregunta:"En un andamio móvil, las ruedas deben:", opciones:["Estar siempre libres para moverlo rápido", "Tener bloqueos (frenos) puestos mientras los trabajadores están en la plataforma", "Ser de madera", "Ser quitadas al llegar al sitio"], respuesta_correcta:1, explicacion:"El movimiento accidental del andamio mientras hay personal arriba causa caídas fatales.", en_pregunta:"On a mobile scaffold, the wheels must:", en_opciones:["Always be free so it can be moved quickly","Be locked (brakes engaged) while workers are on the platform","Be made of wood","Be removed once on site"], en_explicacion:"Accidental movement of the scaffold while personnel are on top causes fatal falls." },
  { id:"osha_226", categoria:"OSHA_CAIDAS", pregunta:"¿Qué es la 'Carga de Trabajo Segura' (SWL) en un grillete o eslinga?", opciones:["El peso máximo absoluto antes de romperse", "La carga máxima recomendada por el fabricante para uso diario seguro", "El peso del operario", "10,000 lbs siempre"], respuesta_correcta:1, explicacion:"La SWL incluye un factor de seguridad (usualmente 5:1). Nunca se debe exceder la SWL.", en_pregunta:"What is the 'Safe Working Load' (SWL) on a shackle or sling?", en_opciones:["The absolute maximum weight before breaking","The maximum load recommended by the manufacturer for safe daily use","The operator's weight","Always 10,000 lbs"], en_explicacion:"SWL includes a safety factor (usually 5:1). The SWL must never be exceeded." },
  { id:"osha_227", categoria:"OSHA_CAIDAS", pregunta:"Un trabajador usa un arnés con punto de anclaje dorsal. ¿Qué ocurre si se cae de cabeza (invertido) con este punto dorsal?", opciones:["El arnés lo mantiene derecho automáticamente.", "Puede deslizarse fuera del arnés por gravedad.", "El punto dorsal es solo para rescate, no para caídas.", "No hay riesgo, está diseñado para cualquier orientación."], respuesta_correcta:1, explicacion:"Caída invertida con anclaje dorsal puede permitir que el trabajador se deslice fuera del arnés.", en_pregunta:"A worker wears a harness with a dorsal anchor point. What happens if they fall head-down (inverted) with this dorsal attachment?", en_opciones:["The harness automatically keeps him upright.","He can slip out of the harness by gravity.","The dorsal point is for rescue only, not fall arrest.","No risk, it is designed for any orientation."], en_explicacion:"An inverted fall with a dorsal anchor can allow the worker to slip out of the harness." },
  { id:"osha_228", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida horizontal tiene un cable de acero inoxidable. ¿Qué riesgo específico del acero inoxidable es peor que el acero galvanizado?", opciones:["Menor resistencia a la tracción.", "Fragilización por cloruros (corrosión bajo tensión).", "Mayor peso por metro.", "Menor flexibilidad."], respuesta_correcta:1, explicacion:"Acero inoxidable sufre fragilización por cloruros (ambientes marinos o industriales).", en_pregunta:"A horizontal lifeline uses a stainless steel cable. What specific risk is worse for stainless than for galvanized steel?", en_opciones:["Lower tensile strength.","Chloride embrittlement (stress corrosion cracking).","Higher weight per meter.","Lower flexibility."], en_explicacion:"Stainless steel is susceptible to chloride stress corrosion cracking in marine or industrial environments." },
  { id:"osha_229", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de detención de caídas tiene un conector de anclaje tipo argolla soldada. ¿Qué prueba no destructiva es obligatoria periódicamente?", opciones:["Inspección visual con lupa 10x.", "Prueba de tintas penetrantes.", "Prueba de carga al 50% de capacidad.", "Medición de espesor por ultrasonido."], respuesta_correcta:1, explicacion:"Soldaduras requieren inspección por tintas penetrantes o partículas magnéticas para detectar grietas.", en_pregunta:"A fall arrest system has a welded eyebolt anchor connector. Which non-destructive test is required periodically?", en_opciones:["Visual inspection with 10x magnifier.","Dye penetrant test.","Load test at 50% capacity.","Ultrasonic thickness measurement."], en_explicacion:"Welds require dye penetrant or magnetic particle inspection to detect cracks." },
  { id:"osha_230", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida vertical con absorbedor está anclada a 2 metros sobre el punto de operación. ¿Cuál es la distancia de caída total?", opciones:["2 metros + longitud de cuerda.", "2 metros + 1.2 m (absorbedor) + estatura.", "Solo la longitud de la cuerda.", "Depende del peso del trabajador."], respuesta_correcta:1, explicacion:"Caída = distancia anclaje (2 m) + despliegue absorbedor (1.2 m) + altura trabajador (1.75 m).", en_pregunta:"A vertical lifeline with shock absorber is anchored 2 meters above the work point. What is the total fall distance?", en_opciones:["2 meters + rope length.","2 meters + 1.2 m (absorber) + worker height.","Only the rope length.","It depends on worker weight."], en_explicacion:"Fall = anchor distance (2 m) + absorber deployment (1.2 m) + worker height (1.75 m)." },
  { id:"osha_231", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de protección contra caídas tiene un mosquetón de acero. ¿Qué tratamiento de superficie es peligroso para el acero de alta resistencia?", opciones:["Galvanizado en caliente.", "Pintura epóxica.", "Cromado duro.", "Niquelado electrolítico."], respuesta_correcta:2, explicacion:"Cromado duro puede inducir fragilización por hidrógeno en aceros de alta resistencia.", en_pregunta:"A fall protection system uses a steel carabiner. Which surface treatment is dangerous for high-strength steel?", en_opciones:["Hot-dip galvanizing.","Epoxy paint.","Hard chrome plating.","Electrolytic nickel plating."], en_explicacion:"Hard chrome plating can induce hydrogen embrittlement in high-strength steels." },
  { id:"osha_232", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida retráctil (SRL) tiene un indicador de caída desplegado (bandera roja). ¿Puede reutilizarse después de inspección visual?", opciones:["Sí, si no hay daño visible.", "No, el indicador desplegado significa que debe retirarse de servicio.", "Sí, después de recertificación por fabricante.", "No, solo si la caída fue de menos de 1 metro."], respuesta_correcta:1, explicacion:"Indicador de caída desplegado significa que el SRL ha absorbido una caída y debe reemplazarse.", en_pregunta:"A self-retracting lifeline (SRL) shows a deployed fall indicator (red flag). Can it be reused after visual inspection?", en_opciones:["Yes, if no visible damage.","No, a deployed indicator means it must be removed from service.","Yes, after manufacturer recertification.","No, only if the fall was less than 1 meter."], en_explicacion:"A deployed fall indicator means the SRL has arrested a fall and must be replaced." },
  { id:"osha_233", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de protección contra caídas tiene un mosquetón con seguro de tornillo. El trabajador no aprieta el tornillo. ¿Qué riesgo de desenganche existe?", opciones:["El tornillo se afloja más con la vibración.", "El mosquetón puede abrirse por contacto lateral.", "No hay riesgo si el tornillo está al menos a medio apretar.", "El seguro de tornillo no requiere apriete."], respuesta_correcta:1, explicacion:"Mosquetón con seguro sin apretar puede abrirse por fricción contra superficies.", en_pregunta:"A fall protection system uses a screw-gate carabiner. The worker does not tighten the screw. What rollout risk exists?", en_opciones:["The screw loosens more from vibration.","The carabiner can open from side contact.","No risk if the screw is at least half-tightened.","Screw-gate carabiners don't require tightening."], en_explicacion:"An un-tightened screw-gate carabiner can open from friction against surfaces." },
  { id:"osha_234", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida horizontal tiene un cable de acero con un nudo. ¿Es aceptable?", opciones:["Sí, los nudos son comunes en cables.", "No, los nudos reducen la resistencia hasta un 80%.", "Sí, si el nudo está soldado.", "No, pero solo en cables de más de 10 mm."], respuesta_correcta:1, explicacion:"Nudos en cable de acero reducen drásticamente la resistencia a la tracción.", en_pregunta:"A horizontal lifeline uses a steel cable with a knot in it. Is this acceptable?", en_opciones:["Yes, knots are common in cables.","No, knots reduce strength by up to 80%.","Yes, if the knot is welded.","No, but only on cables larger than 10 mm."], en_explicacion:"Knots in steel cable drastically reduce tensile strength." },
  { id:"osha_235", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de detención de caídas tiene un punto de anclaje portátil de 200 kg de peso. ¿Es seguro para un trabajador de 100 kg?", opciones:["Sí, porque 200 kg > 100 kg.", "No, porque la fuerza de caída puede superar 1000 kg.", "Sí, si el anclaje está certificado para 5000 lbs.", "No, porque el peso del anclaje no indica resistencia."], respuesta_correcta:3, explicacion:"El peso del anclaje no es indicador de resistencia; requiere certificación a 5000 lbs (2270 kg).", en_pregunta:"A fall arrest system uses a portable anchor point weighing 200 kg. Is it safe for a 100 kg worker?", en_opciones:["Yes, because 200 kg > 100 kg.","No, because fall forces can exceed 1000 kg.","Yes, if the anchor is certified for 5000 lbs.","No, because anchor weight is not an indicator of strength."], en_explicacion:"Anchor weight does not indicate strength; certification to 5000 lbs (2270 kg) is required." },
  { id:"osha_236", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida vertical tiene un absorbedor de 1.2 metros. ¿Cuál es la distancia libre mínima desde el punto de anclaje al nivel inferior?", opciones:["1.2 metros.", "3.7 metros (1.2 + 1.75 estatura + 0.75 margen).", "2.5 metros.", "Depende del peso del trabajador."], respuesta_correcta:1, explicacion:"Distancia = absorbedor (1.2) + estatura (1.75) + margen seguridad (0.75) = 3.7 m.", en_pregunta:"A vertical lifeline has a 1.2-meter shock absorber. What is the minimum fall clearance from the anchor point to the lower level?", en_opciones:["1.2 meters.","3.7 meters (1.2 + 1.75 worker height + 0.75 safety margin).","2.5 meters.","It depends on the worker's weight."], en_explicacion:"Clearance = absorber (1.2) + worker height (1.75) + safety margin (0.75) = 3.7 m." },
  { id:"osha_237", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida retráctil (SRL) está anclada en el piso. El trabajador sube a una plataforma a 2 metros. ¿Es seguro?", opciones:["Sí, el SRL sigue al trabajador.", "No, porque el cable puede engancharse al subir.", "Sí, si el SRL tiene freno de inercia.", "No, porque el SRL no debe usarse con anclaje inferior."], respuesta_correcta:1, explicacion:"Cable vertical puede engancharse en escalones o bordes.", en_pregunta:"A self-retracting lifeline (SRL) is anchored at floor level. The worker climbs to a platform 2 meters above. Is it safe?", en_opciones:["Yes, the SRL follows the worker.","No, because the cable can snag while climbing.","Yes, if the SRL has an inertial brake.","No, because SRLs should not be used with foot-level anchorage."], en_explicacion:"A vertical cable can snag on steps or edges." },
  { id:"osha_238", categoria:"OSHA_CAIDAS", pregunta:"Un sistema de protección contra caídas tiene un mosquetón de aluminio con desgaste visible en la garganta. ¿Qué riesgo específico existe?", opciones:["El mosquetón puede romperse por fatiga.", "El seguro puede no cerrar correctamente.", "El desgaste reduce el diámetro interior.", "El aluminio se corroe más rápido."], respuesta_correcta:1, explicacion:"Desgaste en garganta puede impedir que el seguro cierre completamente.", en_pregunta:"A fall protection system uses an aluminum carabiner with visible wear on the throat. What specific risk exists?", en_opciones:["The carabiner can fail by fatigue.","The gate may not close properly.","Wear reduces the internal diameter.","Aluminum corrodes faster."], en_explicacion:"Wear on the throat can prevent the gate from fully closing." },
  { id:"osha_239", categoria:"OSHA_CAIDAS", pregunta:"Una línea de vida horizontal tiene una longitud de 30 metros con un solo anclaje intermedio. ¿Cuántos trabajadores pueden conectarse simultáneamente?", opciones:["1 trabajador.", "2 trabajadores.", "Depende de la deflexión del cable.", "4 trabajadores si el cable es de 5/8\"."], respuesta_correcta:0, explicacion:"Línea de vida horizontal sin anclajes intermedios suficientes solo admite un trabajador.", en_pregunta:"A horizontal lifeline is 30 meters long with only one intermediate anchor. How many workers can connect simultaneously?", en_opciones:["1 worker.","2 workers.","Depends on cable deflection.","4 workers if the cable is 5/8\".\""], en_explicacion:"A horizontal lifeline without sufficient intermediate anchors allows only one worker." },

  // -- ESPACIOS CONFINADOS (240-263) --
  { id:"osha_240", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"¿Qué gas es conocido como 'El asesino silencioso' en espacios de calderas o cuartos de máquinas mal ventilados?", opciones:["Nitrógeno", "Monóxido de Carbono (CO)", "Oxígeno", "Dióxido de Carbono"], respuesta_correcta:1, explicacion:"El CO es incoloro e inodoro, y se une a la hemoglobina 200 veces más rápido que el oxígeno.", en_pregunta:"Which gas is known as 'the silent killer' in boiler rooms or poorly ventilated mechanical rooms?", en_opciones:["Nitrogen","Carbon Monoxide (CO)","Oxygen","Carbon Dioxide"], en_explicacion:"CO is colorless and odorless, and binds to hemoglobin 200 times faster than oxygen." },
  { id:"osha_241", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Una escalera para salir de una zanja debe extenderse al menos cuántas pulgadas por encima del borde:", opciones:["12 pulgadas", "24 pulgadas", "36 pulgadas", "No importa"], respuesta_correcta:2, explicacion:"OSHA exige 3 pies (36 pulgadas) para que el trabajador tenga de dónde agarrarse al salir.", en_pregunta:"A ladder used to exit a trench must extend at least how many inches above the edge:", en_opciones:["12 inches","24 inches","36 inches","It doesn't matter"], en_explicacion:"OSHA requires 3 feet (36 inches) so the worker has something to grab when exiting." },
  { id:"osha_242", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"¿Por qué los refrigerantes son peligrosos en un sótano sin ventilación si hay una fuga masiva?", opciones:["Porque huelen mal", "Son más pesados que el aire y desplazan el oxígeno, causando asfixia sin advertencia", "Hacen que el suelo se vuelva resbaladizo", "Aumentan la humedad"], respuesta_correcta:1, explicacion:"La mayoría de los refrigerantes se acumulan en zonas bajas, creando atmósferas deficientes de oxígeno.", en_pregunta:"Why are refrigerants dangerous in an unventilated basement if a massive leak occurs?", en_opciones:["Because they smell bad","They are heavier than air and displace oxygen, causing asphyxiation without warning","They make the floor slippery","They increase humidity"], en_explicacion:"Most refrigerants accumulate in low areas, creating oxygen-deficient atmospheres." },
  { id:"osha_243", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"¿Cuál es la función del 'Permit-Required Confined Space' (Permiso de entrada)?", opciones:["Cobrar más al cliente", "Documentar los peligros, las pruebas de aire, el equipo de rescate y las personas autorizadas", "Saber a qué hora termina el turno", "Es un papel innecesario"], respuesta_correcta:1, explicacion:"El permiso asegura que se hayan tomado todas las medidas preventivas antes de arriesgar una vida.", en_pregunta:"What is the purpose of the Permit-Required Confined Space entry permit?", en_opciones:["To charge the customer more","To document the hazards, air tests, rescue equipment, and authorized personnel","To know what time the shift ends","It is an unnecessary paper"], en_explicacion:"The permit ensures that all preventive measures have been taken before a life is put at risk." },
  { id:"osha_244", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado que contiene un peligro eléctrico expuesto se clasifica automáticamente como:", opciones:["Espacio no-permitido", "Espacio que requiere permiso (Permit-Required Confined Space)", "Espacio abierto", "Zona de confort"], respuesta_correcta:1, explicacion:"Cualquier peligro físico o atmosférico convierte el espacio en uno 'con permiso requerido'.", en_pregunta:"A confined space containing an exposed electrical hazard is automatically classified as:", en_opciones:["Non-permit space","Permit-Required Confined Space","Open space","Comfort zone"], en_explicacion:"Any physical or atmospheric hazard makes the space 'permit-required.'" },
  { id:"osha_245", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"En una excavación de 4 pies de profundidad, ¿qué riesgo 'atmosférico' debe monitorearse según OSHA?", opciones:["Humedad", "Acumulación de gases pesados (como CO2) o deficiencia de oxígeno", "Velocidad del viento", "Temperatura del aire"], respuesta_correcta:1, explicacion:"Las zanjas pueden atrapar gases más pesados que el aire, creando atmósferas letales.", en_pregunta:"In a 4-foot-deep excavation, which atmospheric hazard must be monitored per OSHA?", en_opciones:["Humidity","Accumulation of heavy gases (like CO2) or oxygen deficiency","Wind speed","Air temperature"], en_explicacion:"Trenches can trap gases heavier than air, creating lethal atmospheres." },
  { id:"osha_246", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"¿A qué profundidad de zanja se requiere un diseño de ingeniería profesional para el sistema de protección?", opciones:["5 pies", "10 pies", "20 pies", "No se requiere ingenieros"], respuesta_correcta:2, explicacion:"Zanjas de más de 20 pies de profundidad son extremadamente peligrosas y requieren diseño técnico.", en_pregunta:"At what trench depth is a professional engineer's design required for the protective system?", en_opciones:["5 feet","10 feet","20 feet","Engineers are never required"], en_explicacion:"Trenches deeper than 20 feet are extremely dangerous and require engineered design." },
  { id:"osha_247", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"En una excavación de 6 pies, ¿a qué distancia máxima debe estar una escalera o rampa para que el trabajador pueda salir de forma segura?", opciones:["10 pies", "25 pies de desplazamiento lateral", "50 pies", "No hay límite"], respuesta_correcta:1, explicacion:"OSHA 1926.651(c)(2) exige un medio de salida cada 25 pies de desplazamiento lateral en zanjas de 4 pies o más.", en_pregunta:"In a 6-foot excavation, what is the maximum distance a ladder or ramp must be from a worker so they can exit safely?", en_opciones:["10 feet","25 feet of lateral travel","50 feet","No limit"], en_explicacion:"OSHA 1926.651(c)(2) requires a means of egress within 25 feet of lateral travel in trenches 4 feet or deeper." },
  { id:"osha_248", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"En un espacio confinado, ¿cuál es el orden correcto para probar los gases en la atmósfera?", opciones:["1. Inflamables, 2. Oxígeno, 3. Tóxicos", "1. Oxígeno, 2. Inflamables, 3. Tóxicos", "1. Tóxicos primero", "No importa el orden"], respuesta_correcta:1, explicacion:"Primero se prueba el oxígeno, ya que los sensores de gases inflamables y tóxicos requieren oxígeno para dar lecturas precisas.", en_pregunta:"In a confined space, what is the correct order to test atmospheric gases?", en_opciones:["1. Flammables, 2. Oxygen, 3. Toxics","1. Oxygen, 2. Flammables, 3. Toxics","1. Toxics first","Order doesn't matter"], en_explicacion:"Oxygen is tested first because flammable and toxic gas sensors require oxygen to give accurate readings." },
  { id:"osha_249", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"El suelo Tipo A es el más estable. ¿Cuál es la pendiente de inclinación (sloping) máxima permitida por OSHA para este tipo de suelo?", opciones:["1:1 (45 grados)", "3/4:1 (53 grados)", "1 1/2:1 (34 grados)", "Vertical (90 grados)"], respuesta_correcta:1, explicacion:"Aun siendo suelo estable, OSHA exige una inclinación mínima para evitar derrumbes repentinos.", en_pregunta:"Type A soil is the most stable. What is the maximum sloping angle allowed by OSHA for this soil type?", en_opciones:["1:1 (45 degrees)","3/4:1 (53 degrees)","1 1/2:1 (34 degrees)","Vertical (90 degrees)"], en_explicacion:"Even for stable soil, OSHA requires a minimum slope to prevent sudden collapse." },
  { id:"osha_250", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"¿Qué es un 'Entry Supervisor'?", opciones:["El guardia de la puerta", "La persona responsable de determinar si las condiciones son seguras, autorizar la entrada y cancelar el permiso", "El que entra primero", "El cliente"], respuesta_correcta:1, explicacion:"Es la autoridad legal dentro del protocolo de espacios confinados.", en_pregunta:"What is an 'Entry Supervisor'?", en_opciones:["The gate guard","The person responsible for determining that conditions are safe, authorizing entry, and canceling the permit","The first person to enter","The customer"], en_explicacion:"This is the legal authority within the confined space entry protocol." },
  { id:"osha_251", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 18.5% O2 y 10% LEL de gasolina. ¿Se puede ingresar con respirador de línea de aire?", opciones:["Sí, porque el respirador suministra aire limpio.", "No, porque 10% LEL excede 5% LEL para ingreso.", "Sí, si se usa ropa antiestática.", "No, porque el O2 bajo afecta al rescatista."], respuesta_correcta:1, explicacion:"10% LEL > 5% LEL (límite para ingreso), independientemente del respirador.", en_pregunta:"A confined space has 18.5% O2 and 10% LEL of gasoline. Can entry be made with an airline respirator?", en_opciones:["Yes, because the respirator supplies clean air.","No, because 10% LEL exceeds the 5% LEL entry limit.","Yes, if antistatic clothing is worn.","No, because low O2 affects the rescuer."], en_explicacion:"10% LEL > 5% LEL (entry limit), regardless of the respirator." },
  { id:"osha_252", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 0% LEL, 20.9% O2, pero el monitor PID (fotioinizador) marca 500 ppm. ¿Qué significa?", opciones:["Gas inerte no detectable por LEL.", "Vapores orgánicos tóxicos no inflamables.", "Monóxido de carbono.", "Falso positivo por humedad."], respuesta_correcta:1, explicacion:"PID detecta compuestos orgánicos volátiles que pueden ser tóxicos sin ser inflamables.", en_pregunta:"A confined space reads 0% LEL, 20.9% O2, but the PID (photoionization) monitor reads 500 ppm. What does this mean?", en_opciones:["Inert gas not detectable by LEL.","Toxic non-flammable organic vapors.","Carbon monoxide.","False positive from humidity."], en_explicacion:"A PID detects volatile organic compounds that can be toxic without being flammable." },
  { id:"osha_253", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado tiene 20 ppm de H2S y 0% LEL. ¿Se puede ingresar con respirador de media cara con filtro de H2S?", opciones:["Sí, los filtros para H2S existen.", "No, porque el H2S no tiene filtro efectivo; requiere SCBA.", "Sí, con cartucho tipo H2S color gris.", "No, porque 20 ppm excede el límite de filtros."], respuesta_correcta:1, explicacion:"No existen filtros comerciales efectivos para H2S; solo SCBA o línea de aire.", en_pregunta:"A confined space has 20 ppm of H2S and 0% LEL. Can entry be made with a half-mask respirator using an H2S filter?", en_opciones:["Yes, H2S filters exist.","No, because there is no effective filter for H2S; SCBA is required.","Yes, with a gray H2S cartridge.","No, because 20 ppm exceeds filter limits."], en_explicacion:"No effective commercial filters exist for H2S; only SCBA or airline is acceptable." },
  { id:"osha_254", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado tiene 500 ppm de CO y 18% O2. ¿Qué respirador es adecuado?", opciones:["Media cara con cartucho para CO.", "Máscara completa con línea de aire.", "PAPR con filtro de CO.", "Ninguno, el CO no tiene filtro efectivo."], respuesta_correcta:1, explicacion:"CO requiere SCBA o línea de aire; no hay filtros efectivos.", en_pregunta:"A confined space has 500 ppm of CO and 18% O2. Which respirator is appropriate?", en_opciones:["Half-mask with CO cartridge.","Full-face mask with airline supply.","PAPR with CO filter.","None, CO has no effective filter."], en_explicacion:"CO requires SCBA or airline respirator; no effective filter exists." },
  { id:"osha_255", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 19% O2 y 50 ppm de Cl2 (cloro). ¿Qué respirador es adecuado?", opciones:["Media cara con filtro para gases ácidos.", "Máscara completa con cartucho tipo B (gris).", "PAPR con filtro de cloro.", "SCBA obligatorio por 19% O2."], respuesta_correcta:1, explicacion:"Cloro requiere cartucho tipo B (gases ácidos); máscara completa protege ojos del cloro.", en_pregunta:"A confined space has 19% O2 and 50 ppm of Cl2 (chlorine). Which respirator is appropriate?", en_opciones:["Half-mask with acid gas filter.","Full-face mask with Type B cartridge (gray).","PAPR with chlorine filter.","SCBA required because of 19% O2."], en_explicacion:"Chlorine requires a Type B (acid gas) cartridge; a full-face mask protects the eyes from chlorine." },
  { id:"osha_256", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 15% O2 y 5000 ppm de CO2. ¿Se puede ingresar con respirador de línea de aire?", opciones:["Sí, el respirador suministra aire normal.", "No, porque 5000 ppm CO2 excede límite.", "Sí, si el respirador tiene filtro de CO2.", "No, porque 15% O2 es muy bajo para el rescatista."], respuesta_correcta:0, explicacion:"Respirador de línea suministra aire independiente; CO2 externo no afecta al usuario.", en_pregunta:"A confined space has 15% O2 and 5000 ppm of CO2. Can entry be made with an airline respirator?", en_opciones:["Yes, the respirator supplies normal air.","No, because 5000 ppm CO2 exceeds the limit.","Yes, if the respirator has a CO2 filter.","No, because 15% O2 is too low for the rescuer."], en_explicacion:"An airline respirator supplies independent air; external CO2 does not affect the user." },
  { id:"osha_257", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 17% O2 y 0 ppm de tóxicos. ¿Se puede ingresar sin respirador?", opciones:["Sí, 17% es aceptable si no hay otros peligros.", "No, OSHA requiere mínimo 19.5% O2 para ingreso sin respirador.", "Sí, si se usa monitoreo continuo.", "No, porque el O2 bajo puede no ser detectado por el trabajador."], respuesta_correcta:1, explicacion:"OSHA define atmósfera deficiente de oxígeno como < 19.5%; requiere respirador de suministro de aire.", en_pregunta:"A confined space has 17% O2 and 0 ppm of toxics. Can entry be made without a respirator?", en_opciones:["Yes, 17% is acceptable if there are no other hazards.","No, OSHA requires a minimum of 19.5% O2 for entry without a respirator.","Yes, if continuous monitoring is used.","No, because low O2 may not be detected by the worker."], en_explicacion:"OSHA defines an oxygen-deficient atmosphere as < 19.5%; supplied-air respirator required." },
  { id:"osha_258", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 20.8% O2 y 1000 ppm de acetona. ¿Es inflamable?", opciones:["No, 1000 ppm está bajo LEL de acetona (2.5% = 25000 ppm).", "Sí, porque la acetona es inflamable a cualquier concentración.", "No, porque el O2 es normal.", "Sí, si hay una fuente de ignición."], respuesta_correcta:0, explicacion:"LEL acetona es 2.5% volumen (25000 ppm); 1000 ppm es seguro para ignición.", en_pregunta:"A confined space has 20.8% O2 and 1000 ppm of acetone. Is it flammable?", en_opciones:["No, 1000 ppm is below the LEL of acetone (2.5% = 25000 ppm).","Yes, because acetone is flammable at any concentration.","No, because O2 is normal.","Yes, if there is an ignition source."], en_explicacion:"LEL of acetone is 2.5% by volume (25000 ppm); 1000 ppm is safe from ignition." },
  { id:"osha_259", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 19% O2 y 10% LEL de propano. ¿Se puede ingresar con respirador de línea de aire?", opciones:["Sí, porque el respirador suministra aire limpio.", "No, porque 10% LEL > 5% LEL permitido.", "Sí, si se usa ropa antiestática.", "No, porque el O2 está bajo 19.5%."], respuesta_correcta:1, explicacion:"10% LEL excede 5% LEL (límite para ingreso a espacio confinado).", en_pregunta:"A confined space has 19% O2 and 10% LEL of propane. Can entry be made with an airline respirator?", en_opciones:["Yes, because the respirator supplies clean air.","No, because 10% LEL > 5% LEL allowed.","Yes, if antistatic clothing is worn.","No, because O2 is below 19.5%."], en_explicacion:"10% LEL exceeds 5% LEL (confined space entry limit)." },
  { id:"osha_260", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 19% O2 y 25 ppm de H2S. ¿Qué respirador es adecuado?", opciones:["Media cara con filtro de H2S.", "Máscara completa con línea de aire.", "PAPR con filtro de H2S.", "SCBA obligatorio por 19% O2."], respuesta_correcta:1, explicacion:"H2S requiere SCBA o línea de aire; no hay filtros efectivos.", en_pregunta:"A confined space has 19% O2 and 25 ppm of H2S. Which respirator is appropriate?", en_opciones:["Half-mask with H2S filter.","Full-face mask with airline supply.","PAPR with H2S filter.","SCBA required because of 19% O2."], en_explicacion:"H2S requires SCBA or airline; no effective filter exists." },
  { id:"osha_261", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 18% O2 y 50 ppm de NO2. ¿Qué respirador es adecuado?", opciones:["Media cara con filtro para NO2.", "Máscara completa con línea de aire.", "PAPR con filtro de NO2.", "SCBA obligatorio por 18% O2."], respuesta_correcta:1, explicacion:"NO2 requiere SCBA o línea de aire; 18% O2 también requiere suministro de aire.", en_pregunta:"A confined space has 18% O2 and 50 ppm of NO2. Which respirator is appropriate?", en_opciones:["Half-mask with NO2 filter.","Full-face mask with airline supply.","PAPR with NO2 filter.","SCBA required because of 18% O2."], en_explicacion:"NO2 requires SCBA or airline supply; 18% O2 also requires supplied air." },
  { id:"osha_262", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 16% O2 y 0% LEL. ¿Se puede ingresar con respirador de línea de aire?", opciones:["Sí, porque el respirador suministra aire.", "No, porque 16% O2 es deficiente para el rescatista.", "Sí, si se usa monitoreo continuo.", "No, porque requiere SCBA, no línea de aire."], respuesta_correcta:0, explicacion:"Respirador de línea suministra aire normal; el O2 ambiente no afecta al usuario.", en_pregunta:"A confined space has 16% O2 and 0% LEL. Can entry be made with an airline respirator?", en_opciones:["Yes, because the respirator supplies air.","No, because 16% O2 is deficient for the rescuer.","Yes, if continuous monitoring is used.","No, because SCBA is required, not airline."], en_explicacion:"An airline respirator supplies normal air; ambient O2 does not affect the user." },
  { id:"osha_263", categoria:"OSHA_ESPACIOS_CONFINADOS", pregunta:"Un espacio confinado con 20.8% O2 y 1000 ppm de H2S. ¿Qué respirador es adecuado?", opciones:["Media cara con filtro de H2S.", "Máscara completa con línea de aire.", "PAPR con filtro de H2S.", "SCBA obligatorio."], respuesta_correcta:1, explicacion:"H2S requiere SCBA o línea de aire; no hay filtros efectivos.", en_pregunta:"A confined space has 20.8% O2 and 1000 ppm of H2S. Which respirator is appropriate?", en_opciones:["Half-mask with H2S filter.","Full-face mask with airline supply.","PAPR with H2S filter.","SCBA required."], en_explicacion:"H2S requires SCBA or airline; no effective filter exists." },

  // -- ESCALERAS -- Ladders (264-281) --
  { id:"osha_264", categoria:"OSHA_ESCALERAS", pregunta:"Según OSHA, si una escalera de mano (A-frame) no tiene un separador o dispositivo de bloqueo esparcidor, el técnico debe:", opciones:["Usar una cuerda para amarrar las patas", "Apoyarla cerrada contra la pared", "No usarla y retirarla de servicio inmediatamente", "Tener a un ayudante sosteniendo ambos lados"], respuesta_correcta:2, explicacion:"OSHA 1926.1053(a)(8) exige que las escaleras de tijera tengan un dispositivo de bloqueo de metal para evitar que se cierren durante el uso.", en_pregunta:"Per OSHA, if an A-frame (stepladder) does not have a spreader or spreader-lock device, the technician must:", en_opciones:["Use a rope to tie the legs","Lean it closed against the wall","Not use it and remove it from service immediately","Have a helper hold both sides"], en_explicacion:"OSHA 1926.1053(a)(8) requires stepladders to have a metal spreader or locking device to prevent them from closing during use." },
  { id:"osha_265", categoria:"OSHA_ESCALERAS", pregunta:"Al subir por una escalera de extensión, ¿cuántos puntos de contacto deben mantenerse siempre?", opciones:["Uno", "Dos", "Tres", "Cuatro"], respuesta_correcta:2, explicacion:"La regla de los 3 puntos (dos pies y una mano, o dos manos y un pie) es obligatoria por OSHA para evitar caídas.", en_pregunta:"When climbing an extension ladder, how many points of contact must always be maintained?", en_opciones:["One","Two","Three","Four"], en_explicacion:"The three-points-of-contact rule (two feet and one hand, or two hands and one foot) is required by OSHA to prevent falls." },
  { id:"osha_266", categoria:"OSHA_ESCALERAS", pregunta:"Al trabajar desde una escalera de tijera, ¿cuál es el peldaño más alto en el que puedes pararte?", opciones:["El último (la tapa superior)", "El segundo contando desde arriba", "El tercero contando desde arriba", "Cualquiera si tienes buen equilibrio"], respuesta_correcta:1, explicacion:"OSHA y los fabricantes prohíben pararse en los dos peldaños superiores debido a la inestabilidad extrema.", en_pregunta:"When working from a stepladder, what is the highest rung you are allowed to stand on?", en_opciones:["The top cap","The second rung from the top","The third rung from the top","Any rung if you have good balance"], en_explicacion:"OSHA and manufacturers prohibit standing on the top two rungs due to extreme instability." },
  { id:"osha_267", categoria:"OSHA_ESCALERAS", pregunta:"Las escaleras de mano deben inspeccionarse:", opciones:["Cada año", "Periódicamente por una persona competente y antes de cada uso por el trabajador", "Solo si se caen del camión", "Cuando el técnico se siente inseguro"], respuesta_correcta:1, explicacion:"La inspección pre-uso detecta fallas que causan la mayoría de los accidentes en construcción.", en_pregunta:"Ladders must be inspected:", en_opciones:["Once a year","Periodically by a competent person and before each use by the worker","Only if they fall off the truck","When the technician feels unsafe"], en_explicacion:"Pre-use inspection catches the defects responsible for most construction ladder accidents." },
  { id:"osha_268", categoria:"OSHA_ESCALERAS", pregunta:"Si una escalera está dañada, el técnico debe:", opciones:["Repararla con cinta adhesiva", "Poner una etiqueta de 'No Usar' y destruirla o retirarla del sitio inmediatamente", "Usarla solo en el primer peldaño", "Dejarla ahí para que otro la use"], respuesta_correcta:1, explicacion:"Una escalera defectuosa no tiene reparación permitida que garantice la seguridad original del fabricante.", en_pregunta:"If a ladder is damaged, the technician must:", en_opciones:["Repair it with duct tape","Tag it 'Do Not Use' and destroy it or immediately remove it from the site","Use it only on the first rung","Leave it there for someone else to use"], en_explicacion:"A defective ladder cannot be repaired in a way that guarantees the manufacturer's original safety." },
  { id:"osha_269", categoria:"OSHA_ESCALERAS", pregunta:"¿Cuál es la máxima longitud permitida para una escalera de mano simple (no de extensión)?", opciones:["10 pies", "20 pies", "30 pies", "50 pies"], respuesta_correcta:2, explicacion:"OSHA limita las escaleras simples a 30 pies por razones de estabilidad estructural.", en_pregunta:"What is the maximum allowable length for a single (non-extension) ladder?", en_opciones:["10 feet","20 feet","30 feet","50 feet"], en_explicacion:"OSHA limits single ladders to 30 feet for structural stability reasons." },
  { id:"osha_270", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de madera tiene un peldaño suelto. El trabajador lo clava nuevamente. ¿Es aceptable esta reparación?", opciones:["Sí, los clavos son más fuertes que los originales.", "No, porque los peldaños deben estar ensamblados con mortaja y espiga.", "Sí, si se usa pegamento epóxico también.", "No, pero solo si la escalera es de más de 3 metros."], respuesta_correcta:1, explicacion:"Peldaños de madera deben estar ensamblados (mortaja y espiga); clavarlos no restaura integridad.", en_pregunta:"A wooden ladder has a loose rung. The worker nails it back. Is this repair acceptable?", en_opciones:["Yes, nails are stronger than the original joint.","No, because rungs must be joined with mortise-and-tenon joints.","Yes, if epoxy glue is also used.","No, but only if the ladder is over 3 meters long."], en_explicacion:"Wooden rungs must be joined (mortise and tenon); nailing does not restore integrity." },
  { id:"osha_271", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de tijera está abierta en ángulo de 15 grados (muy cerrada). ¿Qué falla mecánica ocurre primero?", opciones:["Las patas traseras se doblan hacia afuera.", "La bisagra central se sobrecarga.", "Los peldaños se pandean.", "La plataforma superior se separa."], respuesta_correcta:1, explicacion:"Ángulo cerrado aumenta momento en la bisagra central, punto más débil.", en_pregunta:"A stepladder is open at a 15-degree angle (too closed). Which mechanical failure occurs first?", en_opciones:["The rear legs bow outward.","The center hinge becomes overloaded.","The rungs buckle.","The top cap separates."], en_explicacion:"A closed angle increases the moment on the center hinge, its weakest point." },
  { id:"osha_272", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de aluminio tiene los remaches de los peldaños flojos. ¿Se pueden apretar?", opciones:["Sí, apretando con un martillo.", "No, los remaches son de una sola pieza; la holgura indica falla.", "Sí, si se reemplazan por tornillos.", "No, pero solo si la escalera es de menos de 2 metros."], respuesta_correcta:1, explicacion:"Remaches flojos indican desgaste del orificio; no se pueden apretar, la escalera debe retirarse.", en_pregunta:"An aluminum ladder has loose rivets at the rungs. Can they be tightened?", en_opciones:["Yes, hammered tight.","No, rivets are one-piece; looseness indicates failure.","Yes, if replaced with screws.","No, but only if the ladder is shorter than 2 meters."], en_explicacion:"Loose rivets indicate hole wear; they can't be tightened, and the ladder must be removed from service." },
  { id:"osha_273", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de fibra de vidrio tiene una mancha oscura en un larguero. ¿Qué indica?", opciones:["Moho superficial sin importancia.", "Degradación por UV o químicos.", "Humedad atrapada.", "Residuo de grasa."], respuesta_correcta:1, explicacion:"Manchas oscuras en fibra de vidrio pueden indicar degradación de la resina por UV o químicos.", en_pregunta:"A fiberglass ladder shows a dark stain on a rail. What does this indicate?", en_opciones:["Surface mold of no significance.","Degradation from UV or chemicals.","Trapped moisture.","Grease residue."], en_explicacion:"Dark stains on fiberglass can indicate resin degradation from UV or chemicals." },
  { id:"osha_274", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de aluminio está apoyada sobre un piso de concreto mojado con aceite. El coeficiente de fricción estimado es 0.2. ¿Es segura?", opciones:["Sí, 0.2 es suficiente.", "No, se requiere mínimo 0.5 para escaleras.", "Sí, si se usa un segundo trabajador estabilizando.", "No, porque el aluminio es resbaladizo por sí mismo."], respuesta_correcta:1, explicacion:"Coeficiente de fricción mínimo recomendado para escaleras es 0.5 en condiciones secas.", en_pregunta:"An aluminum ladder rests on a wet concrete floor contaminated with oil. Estimated coefficient of friction is 0.2. Is it safe?", en_opciones:["Yes, 0.2 is enough.","No, a minimum of 0.5 is required for ladders.","Yes, if a second worker stabilizes it.","No, because aluminum is slippery itself."], en_explicacion:"Minimum recommended friction coefficient for ladders is 0.5 under dry conditions." },
  { id:"osha_275", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de madera tiene un nudo en un larguero. ¿Qué norma ANSI dice sobre nudos?", opciones:["Los nudos pequeños son aceptables.", "No se permiten nudos en largueros.", "Solo se permiten nudos sanos menores a 2 cm.", "Los nudos deben rellenarse con masilla."], respuesta_correcta:1, explicacion:"ANSI A14.1 prohíbe nudos en largueros de escaleras de madera.", en_pregunta:"A wooden ladder has a knot in a side rail. What does ANSI say about knots?", en_opciones:["Small knots are acceptable.","No knots are allowed in side rails.","Only sound knots smaller than 2 cm are allowed.","Knots must be filled with putty."], en_explicacion:"ANSI A14.1 prohibits knots in the side rails of wooden ladders." },
  { id:"osha_276", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de tijera tiene las patas traseras sin zapatas antideslizantes. ¿Es seguro usarla sobre alfombra?", opciones:["Sí, la alfombra proporciona agarre.", "No, la alfombra puede deslizarse sobre el piso.", "Sí, si la alfombra está fija.", "No, porque las patas traseras perforan la alfombra."], respuesta_correcta:1, explicacion:"Alfombra puede deslizarse como un tapete, llevando la escalera con ella.", en_pregunta:"A stepladder has rear legs without anti-slip feet. Is it safe to use on carpet?", en_opciones:["Yes, carpet provides grip.","No, carpet can slip on the floor.","Yes, if the carpet is fixed down.","No, because the rear legs puncture the carpet."], en_explicacion:"Carpet can slide like a rug, taking the ladder with it." },
  { id:"osha_277", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de aluminio está pintada con esmalte automotriz. ¿Qué peligro introduce la pintura?", opciones:["La pintura puede ocultar corrosión.", "El esmalte es inflamable.", "La pintura conduce electricidad.", "No hay peligro, la pintura protege."], respuesta_correcta:0, explicacion:"Pintura puede ocultar corrosión o grietas en el aluminio.", en_pregunta:"An aluminum ladder has been painted with automotive enamel. What hazard does the paint introduce?", en_opciones:["Paint can hide corrosion.","Enamel is flammable.","Paint conducts electricity.","No hazard, the paint protects."], en_explicacion:"Paint can hide corrosion or cracks in the aluminum." },
  { id:"osha_278", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de fibra de vidrio tiene un olor a quemado. ¿Qué indica?", opciones:["Exposición a calor excesivo que degradó la resina.", "Limpieza reciente con solvente.", "Moho por humedad.", "Normal en escaleras nuevas."], respuesta_correcta:0, explicacion:"Olor a quemado indica que la resina de fibra de vidrio se sobrecalentó, perdiendo resistencia.", en_pregunta:"A fiberglass ladder has a burnt smell. What does this indicate?", en_opciones:["Exposure to excessive heat that degraded the resin.","Recent cleaning with solvent.","Mildew from humidity.","Normal for new ladders."], en_explicacion:"A burnt smell indicates the fiberglass resin overheated and lost strength." },
  { id:"osha_279", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de aluminio tiene una abolladura de 3 mm en un larguero. ¿Es segura?", opciones:["Sí, 3 mm es superficial.", "No, cualquier abolladura en larguero es crítica.", "Sí, si está en la parte inferior.", "No, pero solo si está en la zona media."], respuesta_correcta:1, explicacion:"Abolladura en larguero crea concentración de tensiones; debe retirarse.", en_pregunta:"An aluminum ladder has a 3 mm dent on a side rail. Is it safe?", en_opciones:["Yes, 3 mm is superficial.","No, any dent in the side rail is critical.","Yes, if in the lower section.","No, but only if in the middle section."], en_explicacion:"A dent in the side rail creates stress concentration; the ladder must be removed from service." },
  { id:"osha_280", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de mano de madera tiene una grieta en la unión del peldaño con el larguero. ¿Se puede reparar con pegamento?", opciones:["Sí, con pegamento epóxico estructural.", "No, las uniones de escaleras de madera no son reparables.", "Sí, si se añaden grapas metálicas.", "No, pero solo si la grieta es menor a 1 cm."], respuesta_correcta:1, explicacion:"Uniones escalón-larguero no son reparables; la escalera debe retirarse.", en_pregunta:"A wooden ladder has a crack at the rung-to-rail joint. Can it be repaired with glue?", en_opciones:["Yes, with structural epoxy glue.","No, ladder joints in wood are not repairable.","Yes, if metal staples are added.","No, but only if the crack is less than 1 cm."], en_explicacion:"Rung-to-rail joints are not repairable; the ladder must be retired." },
  { id:"osha_281", categoria:"OSHA_ESCALERAS", pregunta:"Una escalera de tijera tiene una etiqueta ilegible. ¿Qué debe hacerse?", opciones:["Solicitar una etiqueta de reemplazo al fabricante.", "Continuar usándola si se ve en buen estado.", "Retirar la escalera de servicio.", "Escribir una etiqueta manual con marcador."], respuesta_correcta:2, explicacion:"Etiqueta ilegible impide conocer capacidad y certificación; retirar de servicio.", en_pregunta:"A stepladder has an illegible label. What should be done?", en_opciones:["Request a replacement label from the manufacturer.","Keep using it if it looks in good shape.","Remove the ladder from service.","Write a manual label with a marker."], en_explicacion:"An illegible label prevents knowing capacity and certification; take out of service." },

  // -- LOTO -- Lockout/Tagout (282-304) --
  { id:"osha_282", categoria:"OSHA_LOTO", pregunta:"Un técnico aplica LOTO en un chiller. Después de colocar el candado y la etiqueta, ¿cuál es el paso de verificación de 'Energía Cero' más olvidado pero obligatorio?", opciones:["Revisar la fecha de la etiqueta", "Intentar arrancar el equipo localmente (Push Start Button)", "Llamar al supervisor", "Mirar si las luces del panel están apagadas"], respuesta_correcta:1, explicacion:"El paso de 'Verificación' exige intentar encender el equipo tras el bloqueo para asegurar que no existan puentes eléctricos o energía residual.", en_pregunta:"A technician applies LOTO on a chiller. After placing the lock and tag, what is the most commonly forgotten but mandatory 'zero energy' verification step?", en_opciones:["Check the tag date","Try to start the equipment locally (push the start button)","Call the supervisor","Look to see if the panel lights are off"], en_explicacion:"The 'try' verification step requires attempting to start the equipment after lockout to confirm there are no electrical jumpers or residual energy." },
  { id:"osha_283", categoria:"OSHA_LOTO", pregunta:"¿Quién es la única persona autorizada para quitar un candado de bloqueo?", opciones:["El supervisor", "El dueño de la empresa", "La persona que lo colocó", "El cliente"], respuesta_correcta:2, explicacion:"Bajo OSHA 1910.147, solo el trabajador autorizado que aplicó el bloqueo puede retirarlo (salvo procedimientos de emergencia muy específicos).", en_pregunta:"Who is the only person authorized to remove a lockout lock?", en_opciones:["The supervisor","The company owner","The person who placed it","The customer"], en_explicacion:"Under OSHA 1910.147, only the authorized worker who applied the lockout may remove it (except in very specific emergency procedures)." },
  { id:"osha_284", categoria:"OSHA_LOTO", pregunta:"Si un equipo tiene múltiples fuentes de energía (Eléctrica y Neumática), ¿cuántos candados requiere?", opciones:["Uno para la eléctrica solamente", "Dos candados, uno para cada fuente de energía independiente", "Ninguno si el supervisor está mirando", "Un candado compartido"], respuesta_correcta:1, explicacion:"LOTO requiere el aislamiento de TODAS las fuentes de energía peligrosa.", en_pregunta:"If equipment has multiple energy sources (electrical and pneumatic), how many locks are required?", en_opciones:["One, for the electrical only","Two locks, one for each independent energy source","None if the supervisor is watching","One shared lock"], en_explicacion:"LOTO requires the isolation of ALL hazardous energy sources." },
  { id:"osha_285", categoria:"OSHA_LOTO", pregunta:"Un técnico encuentra un candado LOTO de otro compañero en el desconectador. ¿Puede quitarlo si el compañero se fue a almorzar?", opciones:["Sí, para no perder tiempo", "No, está estrictamente prohibido quitar el candado de otra persona", "Solo si el supervisor le da permiso verbal", "Solo si el cliente lo pide"], respuesta_correcta:1, explicacion:"La regla fundamental de LOTO es: 'Tu vida, tu candado'. Nadie más puede retirarlo sin un protocolo de emergencia documentado.", en_pregunta:"A technician finds another coworker's LOTO lock on the disconnect. Can he remove it if the coworker left for lunch?", en_opciones:["Yes, to save time","No, it is strictly prohibited to remove another person's lock","Only with verbal permission from the supervisor","Only if the customer asks"], en_explicacion:"The fundamental LOTO rule is 'Your life, your lock.' No one else may remove it without a documented emergency protocol." },
  { id:"osha_286", categoria:"OSHA_LOTO", pregunta:"Al aplicar LOTO en un Variador de Frecuencia (VFD), ¿cuánto tiempo debe esperar el técnico tras desconectar la energía antes de abrir el panel?", opciones:["Ninguno, es instantáneo", "El tiempo especificado por el fabricante (usualmente 5-20 min) para que los capacitores internos se descarguen", "30 segundos", "24 horas"], respuesta_correcta:1, explicacion:"Los VFD almacenan energía masiva en sus bancos de capacitores de DC (DC Bus) que puede ser letal incluso sin alimentación externa.", en_pregunta:"When applying LOTO on a Variable Frequency Drive (VFD), how long must the technician wait after disconnecting power before opening the panel?", en_opciones:["None, it's instantaneous","The time specified by the manufacturer (usually 5-20 min) for the internal capacitors to discharge","30 seconds","24 hours"], en_explicacion:"VFDs store massive energy in the DC bus capacitor banks, which can be lethal even without external power." },
  { id:"osha_287", categoria:"OSHA_LOTO", pregunta:"¿Qué se debe hacer si el candado de un técnico se queda puesto y él ya se fue a su casa en otra ciudad?", opciones:["Cortarlo con una cizalla de inmediato", "Seguir un protocolo escrito de 'Remoción de candado ausente' que incluye verificar que el técnico no esté en el sitio y autorización gerencial", "Llamar a la policía", "Dejar el equipo apagado hasta que regrese en 3 días"], respuesta_correcta:1, explicacion:"Nunca se corta un candado sin un proceso formal, pues la vida del técnico que lo puso podría estar en riesgo si regresa.", en_pregunta:"What should be done if a technician's lock is left in place and he already went home to another city?", en_opciones:["Cut it off with bolt cutters immediately","Follow a written 'absent lock removal' protocol that includes verifying the technician is not on site and obtaining managerial authorization","Call the police","Leave the equipment off until he returns in 3 days"], en_explicacion:"A lock is never cut without a formal process, because the life of the technician who applied it could be at risk if he returns." },
  { id:"osha_288", categoria:"OSHA_LOTO", pregunta:"Un técnico coloca un candado en un interruptor. ¿Es suficiente para establecer una 'Condición de Trabajo Eléctricamente Segura'?", opciones:["Sí, el candado garantiza seguridad", "No, falta verificar la ausencia de tensión con un voltímetro CAT adecuado", "Solo si la etiqueta es roja", "Sí, si el cliente firmó el permiso"], respuesta_correcta:1, explicacion:"La prueba de ausencia de tensión (Live-Dead-Live) es el único paso que confirma que el circuito no tiene energía residual o retroalimentación.", en_pregunta:"A technician places a lock on a disconnect. Is this enough to establish an 'Electrically Safe Work Condition'?", en_opciones:["Yes, the lock guarantees safety","No, you must verify absence of voltage with an appropriate CAT-rated voltmeter","Only if the tag is red","Yes, if the customer signed the permit"], en_explicacion:"Verification of absence of voltage (Live-Dead-Live test) is the only step that confirms the circuit has no residual energy or backfeed." },
  { id:"osha_289", categoria:"OSHA_LOTO", pregunta:"Si un interruptor no tiene capacidad física para ser bloqueado con candado, ¿qué permite OSHA?", opciones:["No bloquearlo y avisar al jefe", "Usar solo una etiqueta (Tagout) con medidas adicionales de seguridad equivalentes a un bloqueo", "Poner cinta aislante", "Dejar a un compañero vigilando el interruptor"], respuesta_correcta:1, explicacion:"El Tagout solo se permite si el equipo no es 'lockable', pero requiere vigilancia o medidas físicas extra.", en_pregunta:"If a switch physically cannot be locked with a padlock, what does OSHA allow?", en_opciones:["Not locking it and telling the boss","Use only a tag (Tagout) together with additional safety measures equivalent to a lockout","Put electrical tape","Leave a coworker watching the switch"], en_explicacion:"Tagout-only is allowed if the equipment is not lockable, but it requires supervision or additional physical measures." },
  { id:"osha_290", categoria:"OSHA_LOTO", pregunta:"¿Cuál es el 'Peligro de Energía Acumulada' en un resorte industrial comprimido?", opciones:["Ninguno", "Energía mecánica potencial que puede liberarse violentamente durante el desmontaje", "Calor", "Electricidad estática"], respuesta_correcta:1, explicacion:"LOTO incluye bloquear energías mecánicas, hidráulicas y neumáticas, no solo eléctricas.", en_pregunta:"What is the 'stored energy hazard' in a compressed industrial spring?", en_opciones:["None","Potential mechanical energy that can be released violently during disassembly","Heat","Static electricity"], en_explicacion:"LOTO includes isolating mechanical, hydraulic, and pneumatic energies, not just electrical." },
  { id:"osha_291", categoria:"OSHA_LOTO", pregunta:"¿Qué se debe hacer con la energía neumática (aire a presión) durante un LOTO industrial?", opciones:["Nada, el aire es inofensivo", "Purgar la presión residual y bloquear la válvula de suministro en posición cerrada", "Solo apagar el compresor", "Desconectar la manguera y dejarla libre"], respuesta_correcta:1, explicacion:"La presión acumulada en un tanque o manguera puede activar un cilindro y causar un aplastamiento inesperado.", en_pregunta:"What must be done with pneumatic (pressurized air) energy during an industrial LOTO?", en_opciones:["Nothing, air is harmless","Bleed off residual pressure and lock the supply valve in the closed position","Just turn off the compressor","Disconnect the hose and leave it free"], en_explicacion:"Pressure stored in a tank or hose can actuate a cylinder and cause unexpected crush injuries." },
  { id:"osha_292", categoria:"OSHA_LOTO", pregunta:"En un sistema de aire comprimido industrial, ¿qué dispositivo evita que un tanque explote si el interruptor de presión (pressure switch) falla?", opciones:["El manómetro", "La válvula de alivio de seguridad (Pop-off valve)", "La manguera", "El filtro de aire"], respuesta_correcta:1, explicacion:"Es un dispositivo mecánico de seguridad de última instancia que libera la presión excedente.", en_pregunta:"In an industrial compressed-air system, which device prevents a tank from exploding if the pressure switch fails?", en_opciones:["The pressure gauge","The safety relief valve (pop-off valve)","The hose","The air filter"], en_explicacion:"It is a last-resort mechanical safety device that relieves excess pressure." },
  { id:"osha_293", categoria:"OSHA_LOTO", pregunta:"En LOTO de una máquina con dos fuentes de energía (eléctrica y neumática), se bloquea solo la eléctrica. ¿Qué energía neumática peligrosa persiste?", opciones:["Presión residual en cilindros.", "Vacío en líneas de succión.", "Energía de resorte en válvulas.", "Aire comprimido en el compresor remoto."], respuesta_correcta:0, explicacion:"Cilindros neumáticos pueden retener presión atrapada aunque el compresor esté apagado.", en_pregunta:"In LOTO on a machine with two energy sources (electrical and pneumatic), only the electrical is locked out. Which hazardous pneumatic energy remains?", en_opciones:["Residual pressure in cylinders.","Vacuum in suction lines.","Spring energy in valves.","Compressed air at the remote compressor."], en_explicacion:"Pneumatic cylinders can hold trapped pressure even when the compressor is off." },
  { id:"osha_294", categoria:"OSHA_LOTO", pregunta:"En LOTO de un reactor químico, se bloquean todas las líneas de entrada. El reactor está a 150°C. ¿Qué riesgo químico persiste?", opciones:["Polimerización térmica del contenido.", "Generación de gases por descomposición.", "Aumento de presión por expansión térmica.", "Todos los anteriores."], respuesta_correcta:3, explicacion:"Calor residual puede causar múltiples reacciones peligrosas incluso con entradas bloqueadas.", en_pregunta:"During LOTO on a chemical reactor, all inlet lines are locked out. The reactor is at 150°C. What chemical hazard remains?", en_opciones:["Thermal polymerization of the contents.","Gas generation from decomposition.","Pressure increase from thermal expansion.","All of the above."], en_explicacion:"Residual heat can cause multiple dangerous reactions even with inlets locked out." },
  { id:"osha_295", categoria:"OSHA_LOTO", pregunta:"En LOTO de una caldera, se cierra la válvula de gas y se pone candado. ¿Se requiere también purgar la línea de gas?", opciones:["No, con la válvula cerrada es suficiente.", "Sí, porque puede haber gas residual presurizado.", "Solo si la caldera es de alta presión.", "No, el gas se disipa solo."], respuesta_correcta:1, explicacion:"Línea de gas puede retener presión entre válvula de bloqueo y quemador.", en_pregunta:"During LOTO on a boiler, the gas valve is closed and locked. Is it also necessary to purge the gas line?", en_opciones:["No, closing the valve is enough.","Yes, because there may be residual pressurized gas.","Only if the boiler is high pressure.","No, gas dissipates on its own."], en_explicacion:"The gas line can hold pressure between the lockout valve and the burner." },
  { id:"osha_296", categoria:"OSHA_LOTO", pregunta:"En LOTO de una máquina rotativa, se bloquea el motor. El volante sigue girando 2 minutos. ¿Se puede considerar seguro después de que pare?", opciones:["Sí, una vez que para totalmente.", "No, porque la energía potencial del volante puede liberarse al desbloquear.", "Sí, si se usa un freno mecánico.", "No, porque el volante puede tener energía residual invisible."], respuesta_correcta:0, explicacion:"Una vez que todo movimiento cesa, la energía cinética se ha disipado.", en_pregunta:"During LOTO on a rotating machine, the motor is locked out. The flywheel continues to spin for 2 minutes. Can it be considered safe after it stops?", en_opciones:["Yes, once it fully stops.","No, because the flywheel's potential energy can release upon unlock.","Yes, if a mechanical brake is used.","No, because the flywheel may have invisible residual energy."], en_explicacion:"Once all motion has ceased, the kinetic energy has dissipated." },
  { id:"osha_297", categoria:"OSHA_LOTO", pregunta:"En LOTO de un sistema de vacío, se bloquea la bomba y se purga la cámara a presión atmosférica. ¿Es seguro abrir?", opciones:["Sí, presión atmosférica es segura.", "No, porque puede haber vacío residual local.", "Sí, si se usa un manómetro.", "No, porque la purga puede no haber sido completa."], respuesta_correcta:0, explicacion:"Presión atmosférica significa cero diferencial, seguro para abrir.", en_pregunta:"During LOTO on a vacuum system, the pump is locked out and the chamber is vented to atmospheric pressure. Is it safe to open?", en_opciones:["Yes, atmospheric pressure is safe.","No, because residual local vacuum may exist.","Yes, if a pressure gauge is used.","No, because venting may not have been complete."], en_explicacion:"Atmospheric pressure means zero differential pressure, safe to open." },
  { id:"osha_298", categoria:"OSHA_LOTO", pregunta:"En LOTO de una extrusora, se bloquea el motor del tornillo. El barril está a 200°C con plástico fundido. ¿Qué energía peligrosa persiste?", opciones:["Presión del plástico fundido.", "Temperatura del barril.", "Energía química del plástico.", "Todas las anteriores."], respuesta_correcta:3, explicacion:"Plástico fundido tiene presión, temperatura, y puede descomponerse químicamente.", en_pregunta:"During LOTO on an extruder, the screw motor is locked out. The barrel is at 200°C with molten plastic. What hazardous energy remains?", en_opciones:["Pressure of the molten plastic.","Temperature of the barrel.","Chemical energy of the plastic.","All of the above."], en_explicacion:"Molten plastic has pressure, temperature, and can decompose chemically." },
  { id:"osha_299", categoria:"OSHA_LOTO", pregunta:"En LOTO de un sistema neumático, se bloquea el suministro de aire. ¿Se requiere purgar todas las líneas?", opciones:["Sí, para eliminar presión residual.", "No, si se bloquea en la fuente principal.", "Solo las líneas que alimentan actuadores.", "No, el aire no es energía peligrosa."], respuesta_correcta:0, explicacion:"Las líneas pueden retener presión atrapada aunque la fuente esté bloqueada.", en_pregunta:"During LOTO on a pneumatic system, the air supply is locked out. Is it necessary to bleed all lines?", en_opciones:["Yes, to eliminate residual pressure.","No, if the main source is locked out.","Only lines that feed actuators.","No, air is not hazardous energy."], en_explicacion:"Lines can hold trapped pressure even if the source is locked out." },
  { id:"osha_300", categoria:"OSHA_LOTO", pregunta:"En LOTO de una bomba centrífuga, se bloquea el motor. La bomba tiene una válvula de retención. ¿Se requiere bloquear también la válvula de succión?", opciones:["No, la válvula de retención previene flujo inverso.", "Sí, porque la válvula de retención puede fugarse.", "Solo si la bomba está por debajo del nivel del líquido.", "No, si se drena la bomba."], respuesta_correcta:1, explicacion:"Válvulas de retención pueden tener fugas; se requiere bloqueo en succión si hay presión aguas arriba.", en_pregunta:"During LOTO on a centrifugal pump, the motor is locked out. The pump has a check valve. Is it also necessary to lock the suction valve?", en_opciones:["No, the check valve prevents reverse flow.","Yes, because the check valve can leak.","Only if the pump is below liquid level.","No, if the pump is drained."], en_explicacion:"Check valves can leak; suction-side lockout is required if there is upstream pressure." },
  { id:"osha_301", categoria:"OSHA_LOTO", pregunta:"En LOTO de una mezcladora industrial, se bloquea el motor. El agitador tiene impulsores sumergidos en líquido. ¿Qué energía peligrosa persiste?", opciones:["Energía hidráulica por circulación del líquido.", "Energía potencial del líquido en altura.", "Energía química del producto.", "Todas las anteriores."], respuesta_correcta:3, explicacion:"Líquido en movimiento puede seguir girando el agitador por inercia hidráulica.", en_pregunta:"During LOTO on an industrial mixer, the motor is locked out. The agitator has impellers submerged in liquid. What hazardous energy remains?", en_opciones:["Hydraulic energy from liquid circulation.","Potential energy of elevated liquid.","Chemical energy of the product.","All of the above."], en_explicacion:"Moving liquid can continue to turn the agitator by hydraulic inertia." },
  { id:"osha_302", categoria:"OSHA_LOTO", pregunta:"En LOTO de un compresor de aire, se bloquea el motor. El tanque de aire está a 10 bar. ¿Se requiere despresurizar el tanque?", opciones:["No, porque el bloqueo del motor impide que el compresor arranque.", "Sí, porque la presión almacenada es energía independiente.", "Solo si se va a abrir el tanque.", "No, si se usa una válvula de seguridad."], respuesta_correcta:1, explicacion:"Presión de aire en tanque es energía almacenada que debe disiparse.", en_pregunta:"During LOTO on an air compressor, the motor is locked out. The air receiver tank is at 10 bar. Is it necessary to depressurize the tank?", en_opciones:["No, because locking out the motor prevents the compressor from starting.","Yes, because stored pressure is independent energy.","Only if the tank will be opened.","No, if a safety valve is used."], en_explicacion:"Tank air pressure is stored energy that must be dissipated." },
  { id:"osha_303", categoria:"OSHA_LOTO", pregunta:"En LOTO de una caldera de vapor, se cierran válvulas de vapor y alimentación. ¿Se requiere etiquetar la caldera como 'fuera de servicio'?", opciones:["Sí, para advertir a otros trabajadores.", "No, el LOTO es suficiente.", "Solo si la caldera está caliente.", "No, porque las etiquetas no son obligatorias."], respuesta_correcta:0, explicacion:"Etiquetas informan el estado de LOTO a todos los trabajadores.", en_pregunta:"During LOTO on a steam boiler, the steam and feedwater valves are closed. Is it also necessary to tag the boiler 'out of service'?", en_opciones:["Yes, to warn other workers.","No, LOTO is sufficient.","Only if the boiler is hot.","No, because tags are not mandatory."], en_explicacion:"Tags inform all workers of the LOTO status." },
  { id:"osha_304", categoria:"OSHA_LOTO", pregunta:"En LOTO de una máquina con múltiples fuentes de energía, se usa un candado por cada fuente. ¿Es correcto?", opciones:["Sí, cada energía requiere su candado.", "No, un candado puede bloquear todas las fuentes con un hasp.", "Solo si las fuentes están en el mismo panel.", "No, se requiere un candado por trabajador, no por fuente."], respuesta_correcta:1, explicacion:"Un candado puede asegurar múltiples fuentes usando un hasp o dispositivo de bloqueo múltiple.", en_pregunta:"During LOTO on a machine with multiple energy sources, one lock is used per source. Is this correct?", en_opciones:["Yes, each energy source requires its own lock.","No, one lock can secure all sources using a hasp.","Only if the sources are in the same panel.","No, you need one lock per worker, not per source."], en_explicacion:"A single lock can secure multiple sources using a hasp or multi-lockout device." },

  // -- COMUNICACION DE RIESGOS (305-336) --
  { id:"osha_305", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Si un contenedor de químicos no tiene etiqueta original, el técnico debe:", opciones:["Olerlo para identificarlo", "Usarlo con cuidado", "Etiquetarlo inmediatamente si conoce el contenido o tratarlo como residuo peligroso", "Mezclarlo con agua"], respuesta_correcta:2, explicacion:"Bajo HazCom de OSHA, todo contenedor secundario debe estar identificado para prevenir accidentes químicos.", en_pregunta:"If a chemical container has no original label, the technician must:", en_opciones:["Smell it to identify it","Use it carefully","Label it immediately if he knows the contents, or treat it as hazardous waste","Mix it with water"], en_explicacion:"Under OSHA HazCom, every secondary container must be identified to prevent chemical accidents." },
  { id:"osha_306", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"El pictograma de OSHA con una 'Calavera y tibias cruzadas' significa:", opciones:["Inflamable", "Irritante", "Toxicidad aguda (Venero)", "Peligro de explosión"], respuesta_correcta:2, explicacion:"Indica sustancias que pueden causar la muerte con una exposición mínima.", en_pregunta:"The OSHA pictogram with a 'skull and crossbones' means:", en_opciones:["Flammable","Irritant","Acute toxicity (poison)","Explosion hazard"], en_explicacion:"It indicates substances that can cause death from minimal exposure." },
  { id:"osha_307", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Cuál es el riesgo de seguridad de llenar un cilindro de recuperación al 100% de su capacidad volumétrica?", opciones:["El refrigerante se ensucia", "Explosión del cilindro por expansión hidrostática si la temperatura ambiente aumenta", "La bomba de vacío se daña", "El refrigerante no se puede reciclar"], respuesta_correcta:1, explicacion:"Los cilindros nunca deben llenarse más del 80% (regla de oro) para permitir la expansión del líquido con el calor.", en_pregunta:"What is the safety risk of filling a recovery cylinder to 100% of its volumetric capacity?", en_opciones:["The refrigerant gets contaminated","Cylinder explosion from hydrostatic expansion if ambient temperature rises","The vacuum pump gets damaged","The refrigerant can't be recycled"], en_explicacion:"Cylinders must never be filled above 80% (golden rule) to allow the liquid to expand with heat." },
  { id:"osha_308", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Estás presurizando un sistema con Nitrógeno para buscar una fuga. ¿Cuál es el límite de presión de seguridad si el 'Design Pressure' de la placa es de 450 psi?", opciones:["600 psi", "Nunca exceder la presión de diseño indicada en la placa del fabricante", "1000 psi", "Hasta que se escuche el silbido de la fuga"], respuesta_correcta:1, explicacion:"Exceder la presión de diseño puede causar la ruptura de componentes como el evaporador o el acumulador de succión.", en_pregunta:"You are pressurizing a system with nitrogen to find a leak. What is the safe pressure limit if the nameplate 'Design Pressure' is 450 psi?", en_opciones:["600 psi","Never exceed the design pressure shown on the manufacturer's nameplate","1000 psi","Until you hear the leak hissing"], en_explicacion:"Exceeding design pressure can rupture components like the evaporator or the suction accumulator." },
  { id:"osha_309", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Si el refrigerante R-22 se expone a una llama abierta de soldadura, ¿qué gas altamente letal se produce?", opciones:["Oxígeno puro", "Fosgeno (Phosgene)", "Helio", "Vapor de agua"], respuesta_correcta:1, explicacion:"La descomposición térmica de refrigerantes halogenados produce gas fosgeno, un agente químico mortal usado en guerras.", en_pregunta:"If R-22 refrigerant is exposed to an open brazing flame, which highly lethal gas is produced?", en_opciones:["Pure oxygen","Phosgene","Helium","Water vapor"], en_explicacion:"The thermal decomposition of halogenated refrigerants produces phosgene gas, a deadly chemical warfare agent." },
  { id:"osha_310", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Cómo deben almacenarse los cilindros de gas comprimido (Nitrógeno/Acetileno) en un vehículo de ACVOLT?", opciones:["Acostados para que no se caigan", "En posición vertical y asegurados con cadenas o correas", "Debajo de las herramientas pesadas", "No importa la posición si tienen la tapa"], respuesta_correcta:1, explicacion:"El almacenamiento vertical evita que el cilindro se convierta en un proyectil si la válvula se rompe.", en_pregunta:"How should compressed gas cylinders (nitrogen/acetylene) be stored in an ACVOLT service vehicle?", en_opciones:["Lying down so they don't fall over","Upright and secured with chains or straps","Under heavy tools","Position doesn't matter if they have caps"], en_explicacion:"Upright storage prevents the cylinder from becoming a projectile if the valve breaks off." },
  { id:"osha_311", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Al limpiar un serpentín (coil) con ácido, ¿qué sucede si se mezcla accidentalmente con cloro?", opciones:["Limpia mejor", "Se produce gas cloro, que es altamente tóxico y puede ser fatal si se inhala", "La mezcla se vuelve rosa", "No sucede nada"], respuesta_correcta:1, explicacion:"Nunca se deben mezclar productos químicos de limpieza; las reacciones pueden ser letales.", en_pregunta:"When cleaning a coil with acid, what happens if it accidentally mixes with chlorine?", en_opciones:["It cleans better","Chlorine gas is released, which is highly toxic and can be fatal if inhaled","The mixture turns pink","Nothing happens"], en_explicacion:"Cleaning chemicals must never be mixed; the reactions can be lethal." },
  { id:"osha_312", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Qué color de tanque identifica al refrigerante R-410A en el mercado (antes del cambio a gris uniforme)?", opciones:["Verde", "Blanco", "Rosado (Rose)", "Celeste"], respuesta_correcta:2, explicacion:"El R-410A se identifica tradicionalmente con el color rosado.", en_pregunta:"What tank color identifies R-410A refrigerant on the market (before the change to uniform gray)?", en_opciones:["Green","White","Rose (pink)","Light blue"], en_explicacion:"R-410A is traditionally identified by the rose/pink color." },
  { id:"osha_313", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Dónde debe estar disponible la carpeta de Hojas de Datos de Seguridad (SDS) en el sitio de trabajo?", opciones:["En la oficina central a 50 millas", "Accesible para todos los empleados en todo momento durante su turno", "En el camión del dueño bajo llave", "No se necesitan si el técnico sabe lo que hace"], respuesta_correcta:1, explicacion:"OSHA exige acceso inmediato a la información de peligros químicos para todos los trabajadores.", en_pregunta:"Where must the Safety Data Sheet (SDS) binder be available on the job site?", en_opciones:["At the main office 50 miles away","Accessible to all employees at all times during their shift","In the owner's truck under lock","Not needed if the technician knows what he is doing"], en_explicacion:"OSHA requires immediate access to chemical hazard information for all workers." },
  { id:"osha_314", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"En un horno de gas, ¿qué dispositivo de seguridad cierra el gas si no se detecta llama?", opciones:["El termostato", "El sensor de llama (Flame Sensor) o termocupla", "El motor del soplador", "El filtro de aire"], respuesta_correcta:1, explicacion:"Evita la acumulación de gas combustible no quemado, lo cual causaría una explosión al intentar re-encender.", en_pregunta:"In a gas furnace, which safety device shuts off the gas if no flame is detected?", en_opciones:["The thermostat","The flame sensor or thermocouple","The blower motor","The air filter"], en_explicacion:"It prevents the buildup of unburned combustible gas, which would cause an explosion on reignition." },
  { id:"osha_315", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Por qué nunca se debe aplicar calor directo con un soplete a un cilindro de refrigerante para aumentar la presión de carga?", opciones:["El refrigerante se quema", "Riesgo de explosión del cilindro por debilitamiento del metal y presión interna extrema", "La pintura del tanque se arruina", "El refrigerante se vuelve ácido"], respuesta_correcta:1, explicacion:"Se debe usar agua tibia (no más de 110°F) o una manta térmica aprobada, nunca fuego directo.", en_pregunta:"Why should direct torch heat never be applied to a refrigerant cylinder to increase charging pressure?", en_opciones:["The refrigerant burns","Risk of cylinder explosion from metal weakening and extreme internal pressure","The tank paint is ruined","The refrigerant turns acidic"], en_explicacion:"Warm water (no more than 110°F) or an approved heat blanket must be used, never direct flame." },
  { id:"osha_316", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"El tapón fusible (Fusible Plug) en un recibidor de líquido de un Chiller está diseñado para derretirse a una temperatura específica para:", opciones:["Drenar el aceite", "Liberar la presión antes de que el tanque explote en caso de incendio", "Medir la temperatura", "Lubricar las válvulas"], respuesta_correcta:1, explicacion:"Es un dispositivo de alivio de presión por temperatura de un solo uso.", en_pregunta:"The fusible plug on a chiller liquid receiver is designed to melt at a specific temperature to:", en_opciones:["Drain the oil","Relieve pressure before the tank explodes in a fire","Measure temperature","Lubricate the valves"], en_explicacion:"It is a single-use temperature-activated pressure relief device." },
  { id:"osha_317", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Un cilindro de refrigerante que muestra corrosión profunda o abolladuras debe:", opciones:["Pintarse para que no se note", "Vaciarse legalmente y descartarse (no rellenar)", "Usarse solo a media presión", "Envolverse en cinta"], respuesta_correcta:1, explicacion:"La integridad estructural del cilindro es lo único que contiene la presión. Un cilindro dañado es una bomba en potencia.", en_pregunta:"A refrigerant cylinder showing deep corrosion or dents must be:", en_opciones:["Painted so it isn't noticeable","Legally emptied and disposed of (do not refill)","Used only at half pressure","Wrapped in tape"], en_explicacion:"The cylinder's structural integrity is the only thing containing the pressure. A damaged cylinder is a potential bomb." },
  { id:"osha_318", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Cuál es el color de las tuberías de agua refrigerada (Chilled Water) según el estándar industrial?", opciones:["Rojo", "Verde", "Azul claro", "Amarillo"], respuesta_correcta:2, explicacion:"El azul identifica sistemas de agua; el azul claro o con etiquetas específicas indica agua fría para procesos de HVAC.", en_pregunta:"What color identifies chilled water piping under the industrial standard?", en_opciones:["Red","Green","Light blue","Yellow"], en_explicacion:"Blue identifies water systems; light blue or specific labeling indicates chilled water for HVAC processes." },
  { id:"osha_319", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Bajo el sistema GHS de OSHA, ¿qué palabra indica el nivel de peligro más grave en una etiqueta?", opciones:["Caution (Precaución)", "Warning (Advertencia)", "Danger (Peligro)", "Notice (Aviso)"], respuesta_correcta:2, explicacion:"'Danger' se usa para los peligros más severos; 'Warning' para los menos severos.", en_pregunta:"Under OSHA's GHS, which signal word indicates the most severe hazard level on a label?", en_opciones:["Caution","Warning","Danger","Notice"], en_explicacion:"'Danger' is used for the most severe hazards; 'Warning' for less severe ones." },
  { id:"osha_320", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Un letrero de color 'Verde' con letras blancas indica:", opciones:["Peligro", "Información de seguridad (ej. Primeros auxilios, Salidas)", "Precaución", "Radiación"], respuesta_correcta:1, explicacion:"El verde se usa para condiciones seguras, estaciones de lavado de ojos y camillas.", en_pregunta:"A green sign with white letters indicates:", en_opciones:["Danger","Safety information (e.g., first aid, exits)","Caution","Radiation"], en_explicacion:"Green is used for safe conditions, eyewash stations, and stretchers." },
  { id:"osha_321", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"El 'Silicio Cristalino' es un peligro respiratorio común en construcción al cortar concreto. ¿Qué enfermedad causa a largo plazo?", opciones:["Gripe", "Silicosis (cicatrización irreversible de los pulmones)", "Sordera", "Dolor lumbar"], respuesta_correcta:1, explicacion:"La exposición al polvo de sílice es una prioridad de salud ocupacional en OSHA debido a su letalidad.", en_pregunta:"Crystalline silica is a common respiratory hazard in construction when cutting concrete. What long-term disease does it cause?", en_opciones:["Flu","Silicosis (irreversible scarring of the lungs)","Deafness","Lower back pain"], en_explicacion:"Silica dust exposure is an OSHA occupational health priority due to its lethality." },
  { id:"osha_322", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Cuál es el formulario de OSHA donde se registran todas las lesiones y enfermedades laborales anualmente?", opciones:["Form 1040", "Form 300 (Log of Work-Related Injuries and Illnesses)", "W-2", "I-9"], respuesta_correcta:1, explicacion:"El registro Form 300 es obligatorio para empresas con más de 10 empleados y permite rastrear la seguridad de la empresa.", en_pregunta:"Which OSHA form records all workplace injuries and illnesses annually?", en_opciones:["Form 1040","Form 300 (Log of Work-Related Injuries and Illnesses)","W-2","I-9"], en_explicacion:"The Form 300 log is required for companies with more than 10 employees and tracks the company's safety record." },
  { id:"osha_323", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Si un técnico mezcla lejía (cloro) con amoníaco, ¿qué sucede?", opciones:["Limpia el doble", "Se libera gas cloramina, que es altamente irritante y tóxico para los pulmones", "Se vuelve agua pura", "Explota instantáneamente"], respuesta_correcta:1, explicacion:"Es una reacción química clásica en limpieza industrial que causa hospitalizaciones masivas.", en_pregunta:"If a technician mixes bleach (chlorine) with ammonia, what happens?", en_opciones:["It cleans twice as well","Chloramine gas is released, which is highly irritating and toxic to the lungs","It becomes pure water","It explodes instantly"], en_explicacion:"This is a classic industrial cleaning reaction that causes mass hospitalizations." },
  { id:"osha_324", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"¿Qué es el 'PEL' (Permissible Exposure Limit)?", opciones:["El costo de la multa", "El límite máximo de concentración de una sustancia química al que un trabajador puede exponerse legalmente", "El tiempo de descanso", "La velocidad máxima de un montacargas"], respuesta_correcta:1, explicacion:"Es una norma obligatoria de OSHA para proteger contra enfermedades respiratorias y químicas.", en_pregunta:"What is a PEL (Permissible Exposure Limit)?", en_opciones:["The cost of the fine","The maximum concentration of a chemical to which a worker can legally be exposed","Rest time","The maximum speed of a forklift"], en_explicacion:"It is a mandatory OSHA standard to protect against respiratory and chemical illness." },
  { id:"osha_325", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H317: Puede provocar una reacción alérgica en la piel' y 'H334: Puede provocar síntomas de alergia o asma en caso de inhalación'. ¿Qué trabajador no debe manipular este producto?", opciones:["Trabajador con antecedentes de dermatitis atópica.", "Trabajador con asma alérgica.", "Trabajador con diabetes.", "Trabajador con hipertensión."], respuesta_correcta:1, explicacion:"H334 indica sensibilización respiratoria; asmáticos alérgicos tienen alto riesgo de reacción grave.", en_pregunta:"An SDS indicates 'H317: May cause an allergic skin reaction' and 'H334: May cause allergy or asthma symptoms if inhaled.' Which worker should NOT handle this product?", en_opciones:["Worker with a history of atopic dermatitis.","Worker with allergic asthma.","Worker with diabetes.","Worker with hypertension."], en_explicacion:"H334 indicates respiratory sensitization; allergic asthmatics are at high risk of serious reaction." },
  { id:"osha_326", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H226: Líquido y vapores inflamables' y 'H332: Nocivo en caso de inhalación'. ¿Qué distancia de almacenamiento a fuentes de ignición es correcta?", opciones:["3 metros como mínimo.", "Depende de la cantidad, pero mínimo 15 metros.", "No hay distancia fija, debe estar en gabinete inflamable.", "5 metros con ventilación forzada."], respuesta_correcta:2, explicacion:"NFPA requiere almacenamiento en gabinete ignífugo para cantidades > 25 litros.", en_pregunta:"An SDS indicates 'H226: Flammable liquid and vapor' and 'H332: Harmful if inhaled.' What storage distance from ignition sources is correct?", en_opciones:["3 meters minimum.","Depends on quantity, but minimum 15 meters.","No fixed distance, must be in a flammable storage cabinet.","5 meters with forced ventilation."], en_explicacion:"NFPA requires storage in a fire-resistant cabinet for quantities > 25 liters." },
  { id:"osha_327", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H360: Puede perjudicar la fertilidad' y 'H361: Sospechoso de dañar la fertilidad'. ¿Qué diferencia práctica hay entre H360 y H361?", opciones:["H360 tiene evidencia humana; H361 solo animal.", "No hay diferencia, son equivalentes.", "H360 aplica solo a mujeres; H361 a hombres.", "H360 es agudo; H361 es crónico."], respuesta_correcta:0, explicacion:"H360 = evidencia en humanos; H361 = evidencia limitada o solo en animales.", en_pregunta:"An SDS states 'H360: May damage fertility' and 'H361: Suspected of damaging fertility.' What is the practical difference between H360 and H361?", en_opciones:["H360 has human evidence; H361 only animal evidence.","No difference, they are equivalent.","H360 applies only to women; H361 to men.","H360 is acute; H361 is chronic."], en_explicacion:"H360 = evidence in humans; H361 = limited evidence or evidence only in animals." },
  { id:"osha_328", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H351: Sospechoso de provocar cáncer' y 'H352: Puede ser nocivo para los lactantes'. ¿Qué PPE adicional es obligatorio para mujeres embarazadas?", opciones:["Traje de protección química categoría II.", "Respirador con filtro HEPA.", "Guantes de nitrilo doble capa.", "Prohibición de manipulación directa."], respuesta_correcta:3, explicacion:"Mujeres embarazadas o lactantes no deben manipular productos H351 o H352; reasignación laboral.", en_pregunta:"An SDS indicates 'H351: Suspected of causing cancer' and 'H352: May be harmful to breastfed children.' What additional PPE is required for pregnant women?", en_opciones:["Category II chemical protective suit.","Respirator with HEPA filter.","Double-layer nitrile gloves.","Prohibition from direct handling."], en_explicacion:"Pregnant or breastfeeding women should not handle H351 or H352 products; job reassignment is required." },
  { id:"osha_329", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H220: Gas extremadamente inflamable' y 'H280: Contiene gas a presión; puede explotar si se calienta'. ¿Qué cilindro no debe almacenarse junto a este gas?", opciones:["Cilindro de oxígeno.", "Cilindro de nitrógeno.", "Cilindro de argón.", "Cilindro de helio."], respuesta_correcta:0, explicacion:"Gas inflamable + oxígeno = riesgo de explosión; separación mínima 6 metros.", en_pregunta:"An SDS states 'H220: Extremely flammable gas' and 'H280: Contains gas under pressure; may explode if heated.' Which cylinder should NOT be stored next to this gas?", en_opciones:["Oxygen cylinder.","Nitrogen cylinder.","Argon cylinder.","Helium cylinder."], en_explicacion:"Flammable gas + oxygen = explosion risk; minimum separation is 6 meters (20 feet)." },
  { id:"osha_330", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H300: Mortal en caso de ingestión' y 'H310: Mortal en contacto con la piel'. ¿Qué PPE es obligatorio aunque no haya riesgo de salpicadura?", opciones:["Traje encapsulado nivel A.", "Guantes de nitrilo y bata desechable.", "Respirador de cara completa.", "Gafas de seguridad solamente."], respuesta_correcta:0, explicacion:"H300 + H310 indican toxicidad dérmica y oral severa; requiere traje nivel A (encapsulado).", en_pregunta:"An SDS states 'H300: Fatal if swallowed' and 'H310: Fatal in contact with skin.' What PPE is mandatory even if there is no splash risk?", en_opciones:["Level A encapsulated suit.","Nitrile gloves and disposable gown.","Full-face respirator.","Safety glasses only."], en_explicacion:"H300 + H310 indicate severe dermal and oral toxicity; Level A (encapsulated) suit is required." },
  { id:"osha_331", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H400: Muy tóxico para los organismos acuáticos' y 'H411: Tóxico para los organismos acuáticos, con efectos duraderos'. ¿Qué diferencia hay?", opciones:["H400 es más peligroso que H411.", "H411 es menos peligroso pero más persistente.", "No hay diferencia, solo redacción.", "H400 aplica a agua dulce; H411 a marina."], respuesta_correcta:1, explicacion:"H411 = toxicidad crónica con efectos duraderos, pero menor toxicidad aguda que H400.", en_pregunta:"An SDS indicates 'H400: Very toxic to aquatic life' and 'H411: Toxic to aquatic life with long-lasting effects.' What is the difference?", en_opciones:["H400 is more dangerous than H411.","H411 is less dangerous but more persistent.","There is no difference, just wording.","H400 applies to fresh water; H411 to marine water."], en_explicacion:"H411 = chronic toxicity with long-lasting effects, but lower acute toxicity than H400." },
  { id:"osha_332", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H350: Puede provocar cáncer' y 'H340: Puede provocar defectos genéticos'. ¿Qué tipo de guante es insuficiente aunque sea químicamente resistente?", opciones:["Nitrilo de 15 milésimas.", "Neopreno de 20 milésimas.", "Butilo de 10 milésimas.", "Todos son insuficientes; se requiere guante de barrera multilaminado."], respuesta_correcta:3, explicacion:"Carcinógenos y mutágenos requieren guantes con tiempo de penetración > 480 min (barrera laminada).", en_pregunta:"An SDS indicates 'H350: May cause cancer' and 'H340: May cause genetic defects.' What type of glove is insufficient even if chemically resistant?", en_opciones:["15 mil nitrile.","20 mil neoprene.","10 mil butyl.","All are insufficient; a multi-laminate barrier glove is required."], en_explicacion:"Carcinogens and mutagens require gloves with breakthrough time > 480 min (laminated barrier)." },
  { id:"osha_333", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H225: Líquido y vapores muy inflamables' y 'H316: Provoca irritación cutánea leve'. ¿Qué extintor NO debe usarse?", opciones:["CO2.", "Polvo ABC.", "Espuma AFFF.", "Agua pulverizada."], respuesta_correcta:3, explicacion:"Agua no es efectiva en líquidos inflamables (clase B).", en_pregunta:"An SDS indicates 'H225: Highly flammable liquid and vapor' and 'H316: Causes mild skin irritation.' Which extinguisher should NOT be used?", en_opciones:["CO2.","ABC dry chemical.","AFFF foam.","Water spray."], en_explicacion:"Water is not effective on flammable liquids (Class B)." },
  { id:"osha_334", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H330: Mortal en caso de inhalación' y 'H311: Tóxico en contacto con la piel'. ¿Qué nivel de respiración es mínimo?", opciones:["Media cara con filtro P100.", "Máscara completa con suministro de aire (SCBA).", "PAPR con filtro de gases.", "Mascarilla N95."], respuesta_correcta:1, explicacion:"H330 indica toxicidad aguda por inhalación que requiere SCBA.", en_pregunta:"An SDS indicates 'H330: Fatal if inhaled' and 'H311: Toxic in contact with skin.' What is the minimum respiratory protection level?", en_opciones:["Half-face with P100 filter.","Full face mask with supplied air (SCBA).","PAPR with gas filter.","N95 mask."], en_explicacion:"H330 indicates acute inhalation toxicity that requires SCBA." },
  { id:"osha_335", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H224: Líquido y vapores extremadamente inflamables' y 'H304: Puede ser mortal en caso de ingestión y penetración en vías respiratorias'. ¿Qué almacenamiento es incorrecto?", opciones:["Gabinetes inflamables clase I.", "Refrigerador a prueba de explosión.", "Almacenamiento en área con desagüe al alcantarillado.", "Almacenamiento en tambor metálico con respiradero."], respuesta_correcta:2, explicacion:"Desagüe puede llevar líquido inflamable al alcantarillado, riesgo de explosión.", en_pregunta:"An SDS indicates 'H224: Extremely flammable liquid and vapor' and 'H304: May be fatal if swallowed and enters airways.' Which storage is incorrect?", en_opciones:["Class I flammable cabinets.","Explosion-proof refrigerator.","Storage in an area with drain to the sewer.","Storage in a metal drum with vent."], en_explicacion:"A drain can carry flammable liquid into the sewer, creating an explosion risk." },
  { id:"osha_336", categoria:"OSHA_COMUNICACION_RIESGOS", pregunta:"Una SDS indica 'H370: Causa daños a los órganos' (hígado) y 'H372: Provoca daños en los órganos tras exposiciones prolongadas'. ¿Qué prueba médica es obligatoria?", opciones:["Pruebas de función hepática (transaminasas).", "Biopsia hepática.", "Ecografía abdominal.", "Ninguna, solo monitoreo clínico."], respuesta_correcta:0, explicacion:"Daño hepático requiere monitoreo de transaminasas (ALT, AST).", en_pregunta:"An SDS indicates 'H370: Causes damage to organs' (liver) and 'H372: Causes damage to organs through prolonged exposure.' What medical test is mandatory?", en_opciones:["Liver function tests (transaminases).","Liver biopsy.","Abdominal ultrasound.","None, only clinical monitoring."], en_explicacion:"Liver damage requires monitoring of transaminases (ALT, AST)." },

  // -- PRIMEROS AUXILIOS -- First Aid (337-364) --
  { id:"osha_337", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Si un compañero recibe una descarga eléctrica y sigue 'pegado' al cable, lo primero que haces es:", opciones:["Tirarle agua", "Agarrarlo de la mano para jalarlo", "Cortar la energía desde el interruptor principal", "Llamar al 911 antes de hacer nada"], respuesta_correcta:2, explicacion:"Nunca toques a la víctima directamente. Debes aislar la fuente de energía o usar un objeto no conductor (madera seca) para separarlos.", en_pregunta:"If a coworker receives an electric shock and remains 'stuck' to the cable, the first thing you do is:", en_opciones:["Throw water on them","Grab their hand to pull them free","Cut power at the main breaker","Call 911 before doing anything"], en_explicacion:"Never touch the victim directly. You must isolate the power source or use a non-conductive object (dry wood) to separate them." },
  { id:"osha_338", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un extintor debe estar ubicado a no más de cuántos pies de distancia en un área donde se manejen líquidos inflamables:", opciones:["25 pies", "50 pies", "75 pies", "100 pies"], respuesta_correcta:1, explicacion:"OSHA exige una distancia máxima de viaje de 50 pies en estas zonas de alto riesgo.", en_pregunta:"A fire extinguisher must be located no more than how many feet away in an area where flammable liquids are handled:", en_opciones:["25 feet","50 feet","75 feet","100 feet"], en_explicacion:"OSHA requires a maximum travel distance of 50 feet in these high-risk areas." },
  { id:"osha_339", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"El 'Flash Protection Boundary' se calcula basándose en qué nivel de quemadura en la piel:", opciones:["Primer grado", "Segundo grado", "Tercer grado", "Ninguna quemadura"], respuesta_correcta:1, explicacion:"El límite se define como la distancia a la cual una persona sin EPP recibiría una quemadura de segundo grado (1.2 cal/cm2).", en_pregunta:"The 'Flash Protection Boundary' is calculated based on what level of skin burn:", en_opciones:["First degree","Second degree","Third degree","No burn"], en_explicacion:"The boundary is defined as the distance at which a person without PPE would receive a second-degree burn (1.2 cal/cm2)." },
  { id:"osha_340", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Ante una quemadura eléctrica de entrada y salida, ¿qué es lo más peligroso?", opciones:["La mancha en la piel", "El daño interno a órganos y el ritmo cardíaco que no es visible", "El olor a quemado", "Que se rompa la ropa"], respuesta_correcta:1, explicacion:"La electricidad viaja por los nervios y vasos sanguíneos, pudiendo detener el corazón horas después del contacto.", en_pregunta:"With an electrical burn showing entry and exit wounds, what is the most dangerous aspect?", en_opciones:["The skin mark","Internal damage to organs and cardiac rhythm issues that are not visible","The burning smell","Clothing tearing"], en_explicacion:"Electricity travels through nerves and blood vessels, and can stop the heart hours after contact." },
  { id:"osha_341", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Al recuperar refrigerante de un sistema que sufrió una quemadura de compresor (burnout), ¿qué equipo de protección personal adicional es obligatorio por seguridad química?", opciones:["Solo guantes de tela", "Protección ocular y guantes de nitrilo resistentes a ácidos", "Máscara de oxígeno autónoma", "No se requiere nada especial"], respuesta_correcta:1, explicacion:"Un burnout genera ácidos fluorhídricos y clorhídricos en el aceite que pueden causar quemaduras químicas severas en la piel y ojos.", en_pregunta:"When recovering refrigerant from a system that suffered a compressor burnout, what additional personal protective equipment is mandatory for chemical safety?", en_opciones:["Only cloth gloves","Eye protection and acid-resistant nitrile gloves","Self-contained breathing apparatus","Nothing special is required"], en_explicacion:"A burnout produces hydrofluoric and hydrochloric acids in the oil that can cause severe chemical burns to skin and eyes." },
  { id:"osha_342", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Si un técnico sufre una quemadura por frío extremo (frostbite) con refrigerante líquido, el primer paso es:", opciones:["Frotar la zona vigorosamente", "Sumergir en agua caliente a 110°F", "Lavar suavemente con agua tibia y buscar atención médica inmediata", "Poner hielo sobre la quemadura"], respuesta_correcta:2, explicacion:"El agua tibia ayuda a recuperar la temperatura gradualmente; frotar puede destruir los tejidos dañados por los cristales de hielo.", en_pregunta:"If a technician suffers a frostbite injury from liquid refrigerant, the first step is:", en_opciones:["Rub the area vigorously","Immerse in hot water at 110°F","Gently wash with warm water and seek immediate medical attention","Put ice on the burn"], en_explicacion:"Warm water helps restore temperature gradually; rubbing can destroy tissue damaged by ice crystals." },
  { id:"osha_343", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"¿Por qué es peligroso usar un encendedor de cigarrillos para prender un soplete de oxiacetileno?", opciones:["Es de mala educación", "La mano queda demasiado cerca de la ignición y el encendedor puede explotar por el calor", "La llama es muy pequeña", "Se acaba el gas del encendedor"], respuesta_correcta:1, explicacion:"Se debe usar siempre un chispero (striker) diseñado para mantener la mano a una distancia segura.", en_pregunta:"Why is it dangerous to use a cigarette lighter to ignite an oxy-acetylene torch?", en_opciones:["It is rude","The hand is too close to the ignition and the lighter can explode from heat","The flame is too small","The lighter runs out of fuel"], en_explicacion:"Always use a striker designed to keep the hand at a safe distance." },
  { id:"osha_344", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un técnico trabajando en una azotea a 105°F siente mareos, piel seca y caliente, y confusión. ¿Qué debe hacer el compañero?", opciones:["Darle una soda", "Llamar al 911 de inmediato; son síntomas de un golpe de calor (heat stroke)", "Decirle que descanse 5 minutos", "Ponerle más ropa para que no se queme"], respuesta_correcta:1, explicacion:"El golpe de calor es una emergencia médica donde el cuerpo pierde la capacidad de regular su temperatura.", en_pregunta:"A technician working on a 105°F rooftop feels dizzy, has dry hot skin, and is confused. What should the coworker do?", en_opciones:["Give them a soda","Call 911 immediately; these are symptoms of heat stroke","Tell them to rest for 5 minutes","Put more clothing on them so they don't burn"], en_explicacion:"Heat stroke is a medical emergency where the body loses the ability to regulate its temperature." },
  { id:"osha_345", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Para usar un extintor correctamente, se sigue la técnica 'PASS'. ¿Qué significa la primera 'P'?", opciones:["Presionar el gatillo", "Puntar a la base", "Pull (Tirar del pasador de seguridad)", "Pasar el extintor al jefe"], respuesta_correcta:2, explicacion:"Pull (Tirar), Aim (Apuntar), Squeeze (Apretar), Sweep (Barrer).", en_pregunta:"To use a fire extinguisher correctly, the 'PASS' technique is followed. What does the first 'P' stand for?", en_opciones:["Press the trigger","Point at the base","Pull (Pull the safety pin)","Pass the extinguisher to the boss"], en_explicacion:"Pull, Aim, Squeeze, Sweep." },
  { id:"osha_346", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Si un objeto está incrustado en el ojo de un técnico, ¿cuál es el procedimiento?", opciones:["Sacarlo rápidamente con pinzas", "No intentar removerlo, cubrir ambos ojos para evitar movimiento ocular y buscar emergencias", "Lavar con mucha agua a presión", "Poner un parche solo en el ojo herido"], respuesta_correcta:1, explicacion:"Mover el ojo sano hace que el herido también se mueva (movimiento simpático), lo que puede causar más daño con el objeto incrustado.", en_pregunta:"If an object is embedded in a technician's eye, what is the procedure?", en_opciones:["Remove it quickly with tweezers","Do not attempt to remove it, cover both eyes to prevent eye movement and seek emergency care","Flush with plenty of pressurized water","Place a patch only on the injured eye"], en_explicacion:"Moving the healthy eye causes the injured eye to move too (sympathetic movement), which can cause further damage with the embedded object." },
  { id:"osha_347", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"¿Qué tipo de fuego es un incendio de virutas de Magnesio o Titanio?", opciones:["Clase A", "Clase B", "Clase D", "Clase K"], respuesta_correcta:2, explicacion:"Clase D es para metales combustibles. Usar agua en estos fuegos puede causar una explosión de hidrógeno.", en_pregunta:"What class of fire is a magnesium or titanium shavings fire?", en_opciones:["Class A","Class B","Class D","Class K"], en_explicacion:"Class D is for combustible metals. Using water on these fires can cause a hydrogen explosion." },
  { id:"osha_348", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un extintor de Halón o agentes limpios es preferible en cuartos de servidores o paneles eléctricos porque:", opciones:["Es más barato", "No deja residuos conductores ni corrosivos que dañen la electrónica", "Huele mejor", "Es de color verde"], respuesta_correcta:1, explicacion:"El polvo químico seco (ABC) es corrosivo y puede destruir circuitos electrónicos aunque no se hayan quemado.", en_pregunta:"A Halon or clean-agent extinguisher is preferred in server rooms or electrical panels because:", en_opciones:["It is cheaper","It leaves no conductive or corrosive residue that would damage electronics","It smells better","It is green in color"], en_explicacion:"Dry chemical powder (ABC) is corrosive and can destroy electronic circuits even if they weren't burned." },
  { id:"osha_349", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Si un extintor de incendios está marcado como 'No-rechargeable', ¿qué se hace tras usarlo parcialmente?", opciones:["Guardarlo para otra vez", "Descargarlo completamente y desecharlo", "Llenarlo con agua", "Ponerle una etiqueta de 'Lleno'"], respuesta_correcta:1, explicacion:"Los extintores desechables pierden presión tras el primer uso y no son confiables.", en_pregunta:"If a fire extinguisher is marked 'Non-rechargeable,' what do you do after partial use?", en_opciones:["Save it for next time","Fully discharge and dispose of it","Refill it with water","Label it as 'Full'"], en_explicacion:"Disposable extinguishers lose pressure after the first use and are not reliable." },
  { id:"osha_350", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un extintor de incendios debe estar disponible a no más de cuántos pies de un área donde se usa soplete (trabajo en caliente)?", opciones:["10 pies", "30 pies", "100 pies", "No se requiere"], respuesta_correcta:1, explicacion:"En trabajos en caliente, la respuesta inmediata es crítica para evitar incendios fuera de control.", en_pregunta:"A fire extinguisher must be available no more than how many feet from an area where a torch (hot work) is being used?", en_opciones:["10 feet","30 feet","100 feet","Not required"], en_explicacion:"In hot work, immediate response is critical to prevent fires from getting out of control." },
  { id:"osha_351", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"¿Qué tipo de fuego NO debe intentar apagar un técnico con un extintor de agua?", opciones:["Papel", "Madera", "Aceites de cocina o equipos eléctricos", "Basura"], respuesta_correcta:2, explicacion:"El agua conduce la electricidad y esparce el aceite encendido (fuego clase B/C).", en_pregunta:"What type of fire should a technician NOT attempt to extinguish with a water extinguisher?", en_opciones:["Paper","Wood","Cooking oils or electrical equipment","Trash"], en_explicacion:"Water conducts electricity and spreads burning oil (Class B/C fire)." },
  { id:"osha_352", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"¿Qué significa la letra 'K' en un extintor de incendios?", opciones:["Kilo (Pesado)", "Kitchen (Fuegos de aceites vegetales o grasas en cocinas comerciales)", "Krypton", "Killer (Para fuegos grandes)"], respuesta_correcta:1, explicacion:"Los fuegos de grasa reaccionan violentamente al agua y requieren químicos húmedos específicos (Acetato de potasio).", en_pregunta:"What does the letter 'K' mean on a fire extinguisher?", en_opciones:["Kilo (Heavy)","Kitchen (fires of vegetable oils or greases in commercial kitchens)","Krypton","Killer (for large fires)"], en_explicacion:"Grease fires react violently to water and require specific wet chemicals (potassium acetate)." },
  { id:"osha_353", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con herida en el tórax por arma blanca. El cuchillo sigue insertado. ¿Qué posición de transporte es la correcta?", opciones:["Decúbito lateral izquierdo.", "Decúbito supino con el objeto estabilizado.", "Sentado con inclinación hacia la herida.", "Decúbito prono."], respuesta_correcta:1, explicacion:"Supino con objeto estabilizado evita desplazamiento y daño adicional.", en_pregunta:"A victim has a chest wound from a bladed weapon. The knife is still inserted. What is the correct transport position?", en_opciones:["Left lateral decubitus.","Supine with the object stabilized.","Seated and leaning toward the wound.","Prone."], en_explicacion:"Supine with the object stabilized prevents displacement and additional injury." },
  { id:"osha_354", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con quemadura por explosión de polvo de harina tiene partículas incrustadas. ¿Qué acción está contraindicada?", opciones:["Enfriar con agua corriente.", "Retirar partículas grandes con pinzas.", "Cubrir con apósito antiadherente.", "Aplicar pomada antibiótica."], respuesta_correcta:1, explicacion:"No retirar partículas incrustadas; pueden estar en dermis y causar sangrado.", en_pregunta:"A victim has burns from a flour dust explosion with embedded particles. What action is contraindicated?", en_opciones:["Cool with running water.","Remove large particles with tweezers.","Cover with a non-adherent dressing.","Apply antibiotic ointment."], en_explicacion:"Do not remove embedded particles; they may be in the dermis and cause bleeding." },
  { id:"osha_355", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con hipotermia severa (28°C) está en paro cardíaco. ¿Hasta qué temperatura se debe continuar RCP antes de declarar muerte?", opciones:["30 minutos de RCP.", "Hasta que la temperatura corporal supere 32°C.", "Después de 3 dosis de epinefrina.", "Hasta llegar al hospital."], respuesta_correcta:1, explicacion:"En hipotermia, RCP continúa hasta recalentamiento > 32°C, incluso si dura horas.", en_pregunta:"A victim with severe hypothermia (28°C) is in cardiac arrest. Up to what temperature should CPR be continued before declaring death?", en_opciones:["30 minutes of CPR.","Until body temperature exceeds 32°C.","After 3 doses of epinephrine.","Until arriving at the hospital."], en_explicacion:"In hypothermia, CPR continues until rewarming > 32°C, even if it takes hours." },
  { id:"osha_356", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con intoxicación por metanol ha ingerido 100 mL. ¿Qué antídoto específico debe administrarse además de etanol?", opciones:["Naloxona.", "Fomepizol (4-metilpirazol).", "Atropina.", "N-acetilcisteína."], respuesta_correcta:1, explicacion:"Fomepizol inhibe alcohol deshidrogenasa, previniendo formación de ácido fórmico.", en_pregunta:"A victim with methanol poisoning ingested 100 mL. What specific antidote should be administered in addition to ethanol?", en_opciones:["Naloxone.","Fomepizole (4-methylpyrazole).","Atropine.","N-acetylcysteine."], en_explicacion:"Fomepizole inhibits alcohol dehydrogenase, preventing formation of formic acid." },
  { id:"osha_357", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con convulsión por abstinencia alcohólica. ¿Qué medicamento de primeros auxilios puede administrarse por vía oral si está consciente?", opciones:["Diazepam en tabletas.", "Tiamina (vitamina B1).", "Glucosa oral.", "Ninguno, solo atención médica."], respuesta_correcta:1, explicacion:"Tiamina previene encefalopatía de Wernicke; no es anticonvulsivante pero es parte del manejo.", en_pregunta:"A victim is having a seizure from alcohol withdrawal. What first-aid medication can be given orally if the person is conscious?", en_opciones:["Diazepam tablets.","Thiamine (vitamin B1).","Oral glucose.","None, only medical care."], en_explicacion:"Thiamine prevents Wernicke's encephalopathy; it is not an anticonvulsant but is part of the management protocol." },
  { id:"osha_358", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con intoxicación por órgano-fosforados tiene miosis, bradicardia y diarrea. ¿Qué antídoto debe administrarse primero?", opciones:["Atropina intravenosa.", "Pralidoxima (2-PAM).", "Diazepam.", "Naloxona."], respuesta_correcta:0, explicacion:"Atropina revierte efectos muscarínicos (bradicardia, miosis); pralidoxima reactiva colinesterasa.", en_pregunta:"A victim with organophosphate poisoning has miosis, bradycardia, and diarrhea. Which antidote should be administered first?", en_opciones:["Intravenous atropine.","Pralidoxime (2-PAM).","Diazepam.","Naloxone."], en_explicacion:"Atropine reverses muscarinic effects (bradycardia, miosis); pralidoxime reactivates cholinesterase." },
  { id:"osha_359", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con fractura abierta de fémur tiene el hueso expuesto. ¿Qué acción es prioritaria?", opciones:["Limpiar el hueso con solución salina.", "Cubrir con apósito estéril húmedo.", "Reducir la fractura manualmente.", "Aplicar torniquete proximal."], respuesta_correcta:1, explicacion:"Cubrir hueso expuesto con apósito estéril húmedo previene desecación; no limpiar ni reducir.", en_pregunta:"A victim with an open femur fracture has exposed bone. What action is the priority?", en_opciones:["Clean the bone with saline solution.","Cover with a moist sterile dressing.","Manually reduce the fracture.","Apply a proximal tourniquet."], en_explicacion:"Covering exposed bone with a moist sterile dressing prevents desiccation; do not clean or reduce." },
  { id:"osha_360", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con picadura de avispa en la lengua desarrolla estridor. ¿Qué acción es prioritaria?", opciones:["Aplicar hielo en la lengua.", "Administrar antihistamínico oral.", "Preparar para vía aérea avanzada (cricotiroidotomía).", "Colocar en posición de trendelenburg."], respuesta_correcta:2, explicacion:"Estridor indica obstrucción inminente; preparar para vía aérea quirúrgica.", en_pregunta:"A victim with a wasp sting on the tongue develops stridor. What action is the priority?", en_opciones:["Apply ice to the tongue.","Administer an oral antihistamine.","Prepare for advanced airway management (cricothyrotomy).","Place in Trendelenburg position."], en_explicacion:"Stridor indicates imminent airway obstruction; prepare for surgical airway." },
  { id:"osha_361", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con quemadura eléctrica en mano derecha y pie izquierdo. ¿Qué órgano debe monitorearse por 24 horas?", opciones:["Corazón (arritmias).", "Riñones (mioglobinuria).", "Pulmones (edema).", "Hígado (necrosis)."], respuesta_correcta:1, explicacion:"Lesión eléctrica con trayecto muscular puede causar rabdomiólisis y daño renal.", en_pregunta:"A victim has an electrical burn on the right hand and left foot. Which organ must be monitored for 24 hours?", en_opciones:["Heart (arrhythmias).","Kidneys (myoglobinuria).","Lungs (edema).","Liver (necrosis)."], en_explicacion:"Electrical injury with a muscular pathway can cause rhabdomyolysis and kidney damage." },
  { id:"osha_362", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con herida punzante en el pie, clavado por un clavo oxidado. ¿Qué profilaxis es obligatoria además de limpieza?", opciones:["Vacuna antitetánica (refuerzo).", "Antibiótico oral.", "Inmunoglobulina antitetánica.", "Ninguna, el clavo oxidado no es riesgo."], respuesta_correcta:0, explicacion:"Herida punzante con clavo oxidado requiere refuerzo de toxoide tetánico si han pasado > 5 años.", en_pregunta:"A victim has a puncture wound in the foot from a rusty nail. What prophylaxis is mandatory in addition to cleaning?", en_opciones:["Tetanus vaccine (booster).","Oral antibiotic.","Tetanus immunoglobulin.","None, a rusty nail is not a risk."], en_explicacion:"A puncture wound from a rusty nail requires a tetanus toxoid booster if more than 5 years have passed." },
  { id:"osha_363", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con intoxicación por paracetamol (acetaminofén) ingirió 15 gramos. ¿Qué antídoto debe administrarse?", opciones:["N-acetilcisteína (NAC).", "Carbón activado solamente.", "Flumazenil.", "Naloxona."], respuesta_correcta:0, explicacion:"NAC es antídoto específico para intoxicación por paracetamol.", en_pregunta:"A victim with acetaminophen (paracetamol) overdose ingested 15 grams. What antidote should be administered?", en_opciones:["N-acetylcysteine (NAC).","Activated charcoal only.","Flumazenil.","Naloxone."], en_explicacion:"NAC is the specific antidote for acetaminophen poisoning." },
  { id:"osha_364", categoria:"OSHA_PRIMEROS_AUXILIOS", pregunta:"Un auxiliado con hemorragia por herida en el cuello. ¿Qué acción es prioritaria?", opciones:["Aplicar torniquete en el cuello.", "Presión directa con los dedos.", "Aplicar apósito oclusivo.", "Colocar en posición de trendelenburg."], respuesta_correcta:1, explicacion:"Presión directa con dedos (evitando comprimir tráquea) es prioridad; no torniquete en cuello.", en_pregunta:"A victim has bleeding from a neck wound. What action is the priority?", en_opciones:["Apply a tourniquet to the neck.","Direct pressure with the fingers.","Apply an occlusive dressing.","Place in Trendelenburg position."], en_explicacion:"Direct finger pressure (while avoiding compression of the trachea) is the priority; never tourniquet the neck." },

  // -- QUEMADURAS -- Burns (365-404) --
  { id:"osha_365", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué característica define una quemadura de PRIMER grado según la clasificación médica estándar?", opciones:["Destrucción total de la dermis con tejido carbonizado visible","Ampollas grandes con líquido seroso y dolor intenso al tacto","Enrojecimiento superficial de la epidermis sin formación de ampollas","Necrosis del tejido subcutáneo con pérdida de sensibilidad"], respuesta_correcta:2, explicacion:"Las quemaduras de primer grado afectan solo la capa superficial de la epidermis, causando enrojecimiento y dolor pero sin ampollas. Las ampollas indican segundo grado y la destrucción total de dermis indica tercer grado.", en_pregunta:"What characteristic defines a FIRST-degree burn according to the standard medical classification?", en_opciones:["Total destruction of the dermis with visible charred tissue","Large blisters with serous fluid and intense pain on touch","Superficial redness of the epidermis without blister formation","Necrosis of subcutaneous tissue with loss of sensation"], en_explicacion:"First-degree burns affect only the superficial layer of the epidermis, causing redness and pain but no blisters. Blisters indicate second degree and total destruction of the dermis indicates third degree." },
  { id:"osha_366", categoria:"OSHA_QUEMADURAS", pregunta:"Según la 'Regla del 9' para adultos, ¿qué porcentaje de superficie corporal total representa CADA pierna completa?", opciones:["9% de la superficie corporal total por cada extremidad inferior","18% de la superficie corporal total por cada extremidad inferior","14% de la superficie corporal total por cada extremidad inferior","27% de la superficie corporal total por cada extremidad inferior"], respuesta_correcta:1, explicacion:"La Regla del 9 asigna 18% a cada pierna completa (9% anterior + 9% posterior). Cada brazo es 9%, el torso anterior 18%, el torso posterior 18%, la cabeza 9% y el perineo 1%.", en_pregunta:"According to the 'Rule of Nines' for adults, what percentage of total body surface does EACH full leg represent?", en_opciones:["9% of total body surface per lower limb","18% of total body surface per lower limb","14% of total body surface per lower limb","27% of total body surface per lower limb"], en_explicacion:"The Rule of Nines assigns 18% to each full leg (9% anterior + 9% posterior). Each arm is 9%, anterior torso 18%, posterior torso 18%, head 9%, and perineum 1%." },
  { id:"osha_367", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál es la diferencia principal entre una quemadura de segundo grado superficial y una de segundo grado profunda?", opciones:["La superficial destruye toda la dermis mientras la profunda solo la epidermis","La profunda afecta la dermis reticular y puede requerir injerto de piel","La superficial siempre requiere injerto mientras la profunda sana sola","La profunda solo afecta la epidermis y sana en menos de cinco días"], respuesta_correcta:1, explicacion:"La quemadura de segundo grado profunda afecta la dermis reticular (capa profunda), tiene menos dolor por daño nervioso, y frecuentemente requiere injerto. La superficial afecta solo la dermis papilar y generalmente sana sin injerto en 2-3 semanas.", en_pregunta:"What is the main difference between a superficial second-degree burn and a deep second-degree burn?", en_opciones:["The superficial destroys the entire dermis while the deep only affects the epidermis","The deep affects the reticular dermis and may require a skin graft","The superficial always requires a graft while the deep heals on its own","The deep only affects the epidermis and heals in less than five days"], en_explicacion:"A deep second-degree burn affects the reticular dermis (deep layer), has less pain due to nerve damage, and frequently requires a graft. The superficial burn affects only the papillary dermis and generally heals without a graft in 2-3 weeks." },
  { id:"osha_368", categoria:"OSHA_QUEMADURAS", pregunta:"¿A partir de qué porcentaje de superficie corporal quemada se considera una quemadura como CRÍTICA en un adulto según protocolos de emergencia?", opciones:["Cuando supera el 5% de la superficie corporal total del paciente","Cuando supera el 25% de la superficie corporal total del paciente","Cuando supera el 15% de la superficie corporal total del paciente","Cuando supera el 50% de la superficie corporal total del paciente"], respuesta_correcta:1, explicacion:"Quemaduras que cubren más del 25% de la superficie corporal en adultos se consideran críticas y requieren atención en un centro especializado en quemados.", en_pregunta:"At what percentage of burned body surface is a burn considered CRITICAL in an adult according to emergency protocols?", en_opciones:["When it exceeds 5% of the patient's total body surface","When it exceeds 25% of the patient's total body surface","When it exceeds 15% of the patient's total body surface","When it exceeds 50% of the patient's total body surface"], en_explicacion:"Burns covering more than 25% of body surface in adults are considered critical and require care at a specialized burn center." },
  { id:"osha_369", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué característica clínica indica que una quemadura es de TERCER grado y no de segundo grado profunda?", opciones:["El paciente reporta dolor extremo e insoportable en toda el área afectada","El tejido presenta apariencia blanquecina o cerosa con ausencia total de dolor","Se forman ampollas tensas llenas de líquido claro con bordes eritematosos","La piel muestra enrojecimiento intenso que blanquea al aplicar presión digital"], respuesta_correcta:1, explicacion:"Las quemaduras de tercer grado destruyen todas las capas de la piel incluyendo terminaciones nerviosas, por lo que NO hay dolor. La apariencia es cerosa, blanquecina o carbonizada.", en_pregunta:"What clinical feature indicates a burn is third-degree rather than deep second-degree?", en_opciones:["The patient reports extreme, unbearable pain throughout the affected area","The tissue presents a whitish or waxy appearance with total absence of pain","Tense blisters filled with clear fluid with erythematous edges","The skin shows intense redness that blanches with digital pressure"], en_explicacion:"Third-degree burns destroy all layers of skin including nerve endings, so there is NO pain. The appearance is waxy, whitish, or charred." },
  { id:"osha_370", categoria:"OSHA_QUEMADURAS", pregunta:"Al realizar brazing con soplete oxiacetilénico en tuberías de cobre, ¿cuál es la causa MÁS frecuente de quemaduras en técnicos HVAC?", opciones:["Contacto accidental con tuberías recién soldadas que retienen calor residual","Explosión inmediata del tanque de acetileno por sobrecalentamiento ambiental","Derretimiento espontáneo del material de aporte sobre las manos del técnico","Radiación infrarroja directa del soplete que penetra los guantes de cuero"], respuesta_correcta:0, explicacion:"La causa más frecuente de quemaduras durante brazing es tocar tuberías que aún están calientes. El cobre retiene calor y puede superar los 500°F.", en_pregunta:"When brazing copper tubing with an oxy-acetylene torch, what is the MOST frequent cause of burns in HVAC technicians?", en_opciones:["Accidental contact with freshly brazed tubing that retains residual heat","Immediate explosion of the acetylene tank from ambient overheating","Spontaneous melting of filler material onto the technician's hands","Direct infrared radiation from the torch penetrating leather gloves"], en_explicacion:"The most frequent cause of burns during brazing is touching tubing that is still hot. Copper retains heat and can exceed 500°F." },
  { id:"osha_371", categoria:"OSHA_QUEMADURAS", pregunta:"¿A qué temperatura aproximada opera la llama de un soplete oxiacetilénico usado comúnmente para brazing en refrigeración?", opciones:["Alcanza aproximadamente 1,200°F que es suficiente para fundir cobre puro","Alcanza aproximadamente 5,800°F siendo la llama de gas más caliente disponible","Alcanza aproximadamente 3,200°F similar a un soplete de propano estándar","Alcanza aproximadamente 8,500°F superando el punto de fusión del acero inoxidable"], respuesta_correcta:1, explicacion:"La llama oxiacetilénica alcanza aproximadamente 5,800°F (3,200°C), haciéndola la llama de gas combustible más caliente.", en_pregunta:"What approximate temperature does an oxy-acetylene torch flame reach when used for brazing in refrigeration?", en_opciones:["Approximately 1,200°F, enough to melt pure copper","Approximately 5,800°F, the hottest available fuel-gas flame","Approximately 3,200°F, similar to a standard propane torch","Approximately 8,500°F, exceeding the melting point of stainless steel"], en_explicacion:"The oxy-acetylene flame reaches approximately 5,800°F (3,200°C), making it the hottest combustible-gas flame." },
  { id:"osha_372", categoria:"OSHA_QUEMADURAS", pregunta:"Cuando se realiza soldering en líneas de refrigeración, ¿cuál es la distancia mínima de seguridad recomendada para materiales combustibles?", opciones:["Se requiere un mínimo de 18 pulgadas entre la llama y materiales combustibles","Se requiere un mínimo de 6 pulgadas entre la llama y materiales combustibles","Se requiere un mínimo de 36 pulgadas entre la llama y materiales combustibles","Se requiere un mínimo de 48 pulgadas entre la llama y materiales combustibles"], respuesta_correcta:2, explicacion:"OSHA y NFPA 51B requieren un mínimo de 36 pulgadas (3 pies) entre la llama y cualquier material combustible.", en_pregunta:"When soldering refrigeration lines, what is the recommended minimum safe distance to combustible materials?", en_opciones:["A minimum of 18 inches between the flame and combustible materials","A minimum of 6 inches between the flame and combustible materials","A minimum of 36 inches between the flame and combustible materials","A minimum of 48 inches between the flame and combustible materials"], en_explicacion:"OSHA and NFPA 51B require a minimum of 36 inches (3 feet) between the flame and any combustible material." },
  { id:"osha_373", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué es especialmente peligroso usar un soplete cerca de un compresor que ha tenido un burnout eléctrico interno?", opciones:["Porque el compresor frío puede explotar por el cambio brusco de temperatura externa","Porque el aceite descompuesto genera ácido fluorhídrico al exponerse a llama abierta","Porque el metal del compresor se debilita y colapsa bajo el calor del soplete aplicado","Porque el refrigerante residual en estado líquido se expande y congela la llama directa"], respuesta_correcta:1, explicacion:"Cuando un compresor sufre burnout, el aceite y el refrigerante se descomponen. Al aplicar llama abierta, los residuos de refrigerante halogenado generan ácido fluorhídrico (HF) y fosgeno, gases extremadamente tóxicos.", en_pregunta:"Why is it especially dangerous to use a torch near a compressor that has had an internal electrical burnout?", en_opciones:["Because the cold compressor can explode from sudden external temperature change","Because decomposed oil generates hydrofluoric acid when exposed to open flame","Because the compressor metal weakens and collapses under the applied torch heat","Because residual liquid refrigerant expands and freezes the direct flame"], en_explicacion:"When a compressor suffers a burnout, the oil and refrigerant decompose. When open flame is applied, halogenated refrigerant residues generate hydrofluoric acid (HF) and phosgene, extremely toxic gases." },
  { id:"osha_374", categoria:"OSHA_QUEMADURAS", pregunta:"Al soldar tuberías de cobre en un ático con aislamiento de fibra de vidrio, ¿qué precaución es OBLIGATORIA según OSHA?", opciones:["Mojar el aislamiento con agua antes de comenzar para que actúe como barrera térmica","Usar manta cortafuegos y mantener vigilancia contra incendios por 30 minutos después","Retirar completamente todo el aislamiento del ático antes de encender cualquier soplete","Aplicar gel retardante de fuego directamente sobre las tuberías de cobre a soldar"], respuesta_correcta:1, explicacion:"OSHA requiere el uso de manta cortafuegos (fire blanket) y fire watch por mínimo 30 minutos después de completar el trabajo con llama.", en_pregunta:"When soldering copper tubing in an attic with fiberglass insulation, what precaution is REQUIRED by OSHA?", en_opciones:["Wet the insulation with water before starting so it acts as a thermal barrier","Use a fire blanket and maintain a fire watch for 30 minutes afterward","Completely remove all insulation from the attic before lighting any torch","Apply flame-retardant gel directly on the copper tubing to be soldered"], en_explicacion:"OSHA requires the use of a fire blanket and a fire watch for a minimum of 30 minutes after completing hot work." },
  { id:"osha_375", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál es la principal diferencia entre una quemadura eléctrica y una quemadura térmica convencional en términos de evaluación médica?", opciones:["La quemadura eléctrica solo afecta la piel mientras la térmica daña órganos internos","La quemadura eléctrica causa daño interno severo que no es visible externamente","La quemadura térmica requiere monitoreo cardíaco mientras la eléctrica no lo necesita","La quemadura eléctrica sana más rápido porque la corriente cauteriza los vasos sanguíneos"], respuesta_correcta:1, explicacion:"Las quemaduras eléctricas son engañosas: la herida externa puede parecer pequeña pero la corriente viaja por tejidos internos causando daño masivo. Se le llama 'iceberg injury'.", en_pregunta:"What is the main difference between an electrical burn and a conventional thermal burn in terms of medical assessment?", en_opciones:["The electrical burn only affects the skin while the thermal damages internal organs","The electrical burn causes severe internal damage that is not externally visible","The thermal burn requires cardiac monitoring while the electrical does not","The electrical burn heals faster because the current cauterizes blood vessels"], en_explicacion:"Electrical burns are deceptive: the external wound may appear small but the current travels through internal tissues causing massive damage. This is called an 'iceberg injury.'" },
  { id:"osha_376", categoria:"OSHA_QUEMADURAS", pregunta:"En una lesión por arc flash eléctrico, ¿qué temperatura puede alcanzar el arco eléctrico en el punto de falla?", opciones:["Aproximadamente 2,500°F similar a la temperatura de un soplete de propano industrial","Aproximadamente 35,000°F superando la temperatura de la superficie del sol terrestre","Aproximadamente 8,000°F equivalente a la temperatura de un horno de fundición estándar","Aproximadamente 15,000°F comparable a la llama de un cohete de combustible líquido"], respuesta_correcta:1, explicacion:"Un arco eléctrico puede alcanzar temperaturas de hasta 35,000°F (19,400°C), aproximadamente cuatro veces la temperatura de la superficie del sol.", en_pregunta:"In an arc flash injury, what temperature can the electrical arc reach at the fault point?", en_opciones:["Approximately 2,500°F similar to an industrial propane torch","Approximately 35,000°F, exceeding the surface temperature of the sun","Approximately 8,000°F equivalent to a standard foundry furnace","Approximately 15,000°F comparable to a liquid-fuel rocket flame"], en_explicacion:"An electrical arc can reach temperatures of up to 35,000°F (19,400°C), approximately four times the temperature of the sun's surface." },
  { id:"osha_377", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué tipo de monitoreo médico es OBLIGATORIO después de que un técnico sufre una descarga eléctrica significativa, aunque no presente quemaduras visibles?", opciones:["Radiografía de tórax para verificar posibles fracturas costales por espasmo muscular","Monitoreo cardíaco continuo por mínimo 24 horas para detectar arritmias tardías","Análisis de sangre para medir niveles de electrolitos y minerales en el suero","Resonancia magnética cerebral para descartar daño neurológico por la corriente eléctrica"], respuesta_correcta:1, explicacion:"El monitoreo cardíaco por 24 horas es obligatorio porque la corriente puede causar arritmias que se manifiestan horas después del incidente.", en_pregunta:"What medical monitoring is REQUIRED after a technician suffers a significant electrical shock, even without visible burns?", en_opciones:["Chest X-ray to check for possible rib fractures from muscle spasm","Continuous cardiac monitoring for a minimum of 24 hours to detect late arrhythmias","Blood analysis to measure electrolyte and mineral levels in serum","Brain MRI to rule out neurological damage from the electrical current"], en_explicacion:"Cardiac monitoring for 24 hours is mandatory because the current can cause arrhythmias that appear hours after the incident." },
  { id:"osha_378", categoria:"OSHA_QUEMADURAS", pregunta:"Según NFPA 70E, ¿qué nivel mínimo de protección arc-rated debe usar un técnico HVAC al trabajar en un panel eléctrico energizado de 480V?", opciones:["Ropa con clasificación arc rating mínimo de 4 cal/cm² para esta categoría de riesgo","Ropa con clasificación arc rating mínimo de 8 cal/cm² para esta categoría de riesgo","Ropa con clasificación arc rating mínimo de 2 cal/cm² para esta categoría de riesgo","Ropa con clasificación arc rating mínimo de 1 cal/cm² para esta categoría de riesgo"], respuesta_correcta:1, explicacion:"Para paneles de 480V, NFPA 70E clasifica el riesgo como Categoría 2, requiriendo ropa arc-rated de mínimo 8 cal/cm².", en_pregunta:"According to NFPA 70E, what minimum arc-rated protection level must an HVAC technician use when working on an energized 480V electrical panel?", en_opciones:["Clothing with an arc rating of at least 4 cal/cm² for this risk category","Clothing with an arc rating of at least 8 cal/cm² for this risk category","Clothing with an arc rating of at least 2 cal/cm² for this risk category","Clothing with an arc rating of at least 1 cal/cm² for this risk category"], en_explicacion:"For 480V panels, NFPA 70E classifies the risk as Category 2, requiring arc-rated clothing of at least 8 cal/cm²." },
  { id:"osha_379", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué las quemaduras eléctricas frecuentemente presentan una herida de ENTRADA pequeña y una herida de SALIDA más grande y destructiva?", opciones:["Porque la corriente pierde velocidad al salir y se acumula generando más calor concentrado","Porque la electricidad se dispersa al entrar pero se concentra en un punto pequeño al salir","Porque la corriente se concentra al entrar pero al salir rompe tejido buscando el camino a tierra","Porque el cuerpo amplifica el voltaje internamente haciendo que la salida sea más poderosa"], respuesta_correcta:2, explicacion:"La corriente entra por un punto concentrado, viaja por tejidos internos, y al salir rompe tejido para escapar hacia tierra, creando una herida de salida más grande.", en_pregunta:"Why do electrical burns frequently present with a small ENTRY wound and a larger, more destructive EXIT wound?", en_opciones:["Because the current loses speed exiting and accumulates generating more concentrated heat","Because electricity disperses on entry but concentrates at a small point when exiting","Because the current concentrates on entry but on exit it tears tissue seeking the path to ground","Because the body internally amplifies voltage, making the exit more powerful"], en_explicacion:"Current enters at a concentrated point, travels through internal tissues, and on exit tears tissue to escape to ground, creating a larger exit wound." },
  { id:"osha_380", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué tipo de quemadura química es MÁS peligrosa y penetra más profundamente en los tejidos?", opciones:["Las quemaduras por ácidos fuertes porque destruyen proteínas mediante coagulación inmediata","Las quemaduras por álcalis porque licúan los tejidos y continúan penetrando en profundidad","Las quemaduras por solventes orgánicos porque disuelven la grasa subcutánea rápidamente","Las quemaduras por oxidantes porque generan reacción exotérmica con el agua corporal presente"], respuesta_correcta:1, explicacion:"Los álcalis causan necrosis por licuefacción: disuelven los tejidos y siguen penetrando. Los ácidos causan necrosis por coagulación que forma una escara protectora que limita la penetración.", en_pregunta:"What type of chemical burn is MOST dangerous and penetrates most deeply into tissues?", en_opciones:["Strong acid burns because they destroy proteins through immediate coagulation","Alkali burns because they liquefy tissues and continue penetrating deeper","Organic solvent burns because they quickly dissolve subcutaneous fat","Oxidizer burns because they generate an exothermic reaction with body water"], en_explicacion:"Alkalis cause liquefactive necrosis: they dissolve tissues and keep penetrating. Acids cause coagulative necrosis that forms a protective eschar limiting penetration." },
  { id:"osha_381", categoria:"OSHA_QUEMADURAS", pregunta:"Si un técnico HVAC sufre una salpicadura de ácido de batería (ácido sulfúrico) en la piel, ¿cuál es el primer paso correcto?", opciones:["Aplicar bicarbonato de sodio directamente sobre la piel para neutralizar el ácido rápidamente","Lavar con agua corriente abundante durante mínimo 20 minutos sin intentar neutralizar","Secar el área con toallas limpias y cubrir con vendaje estéril absorbente sin mojar la zona","Aplicar vinagre diluido para contrarrestar el pH del ácido antes de enjuagar con agua tibia"], respuesta_correcta:1, explicacion:"SIEMPRE lavar con agua corriente abundante durante mínimo 20 minutos. NUNCA neutralizar un ácido con una base porque la reacción genera calor adicional.", en_pregunta:"If an HVAC technician suffers a battery acid (sulfuric acid) splash on the skin, what is the correct first step?", en_opciones:["Apply sodium bicarbonate directly on the skin to quickly neutralize the acid","Wash with copious running water for at least 20 minutes without trying to neutralize","Dry the area with clean towels and cover with an absorbent sterile bandage","Apply diluted vinegar to counter the acid's pH before rinsing with warm water"], en_explicacion:"ALWAYS wash with copious running water for a minimum of 20 minutes. NEVER neutralize an acid with a base because the reaction generates additional heat." },
  { id:"osha_382", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué componente usado en HVAC durante brazing puede causar quemaduras químicas en la piel y los ojos por contacto?", opciones:["El nitrógeno presurizado usado para purga durante la soldadura de tuberías de cobre","El flux de brazing que contiene compuestos de fluoruro y boro altamente corrosivos","El alambre de aporte de plata que libera partículas metálicas irritantes por contacto","La pasta selladora de roscas que contiene teflon y compuestos de petróleo concentrados"], respuesta_correcta:1, explicacion:"El flux para brazing contiene compuestos de fluoruro y boro que son corrosivos y pueden causar quemaduras químicas en piel y ojos.", en_pregunta:"What HVAC component used during brazing can cause chemical burns to skin and eyes on contact?", en_opciones:["Pressurized nitrogen used for purging during copper tubing brazing","Brazing flux containing highly corrosive fluoride and boron compounds","Silver filler rod that releases irritating metallic particles on contact","Thread sealant containing teflon and concentrated petroleum compounds"], en_explicacion:"Brazing flux contains fluoride and boron compounds that are corrosive and can cause chemical burns to skin and eyes." },
  { id:"osha_383", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué los solventes de limpieza usados para desengrase de serpentines pueden causar quemaduras químicas severas?", opciones:["Porque reaccionan con el aluminio del serpentín creando gas hidrógeno que enciende la piel","Porque contienen ácidos o álcalis concentrados que destruyen la barrera protectora de la piel","Porque elevan la temperatura de la superficie metálica causando quemaduras térmicas indirectas","Porque generan vapores que condensan sobre la piel formando una capa ácida por contacto aéreo"], respuesta_correcta:1, explicacion:"Los limpiadores de serpentines contienen ácidos fuertes (HCl) o álcalis fuertes (NaOH) que causan quemaduras químicas severas.", en_pregunta:"Why can cleaning solvents used for coil degreasing cause severe chemical burns?", en_opciones:["Because they react with the coil's aluminum creating hydrogen gas that ignites the skin","Because they contain concentrated acids or alkalis that destroy the skin's protective barrier","Because they raise the metal surface temperature causing indirect thermal burns","Because they generate vapors that condense on skin forming an acid layer by air contact"], en_explicacion:"Coil cleaners contain strong acids (HCl) or strong alkalis (NaOH) that cause severe chemical burns." },
  { id:"osha_384", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuánto tiempo mínimo debe lavarse con agua una quemadura química por álcali (como hidróxido de sodio)?", opciones:["Lavar durante mínimo 5 minutos con agua fría directamente sobre el área contaminada","Lavar durante mínimo 10 minutos alternando agua fría y caliente sobre la lesión","Lavar durante mínimo 20 minutos con agua corriente continua sin detenerse ni frotar","Lavar durante mínimo 2 minutos con solución salina estéril a temperatura controlada"], respuesta_correcta:2, explicacion:"Las quemaduras por álcali requieren lavado con agua corriente durante mínimo 20 minutos. Los álcalis penetran profundamente y el lavado prolongado es esencial.", en_pregunta:"How long should an alkali (such as sodium hydroxide) chemical burn be washed with water at minimum?", en_opciones:["Wash for at least 5 minutes with cold water directly on the contaminated area","Wash for at least 10 minutes alternating cold and hot water on the injury","Wash for at least 20 minutes with continuous running water without stopping or rubbing","Wash for at least 2 minutes with temperature-controlled sterile saline"], en_explicacion:"Alkali burns require washing with running water for a minimum of 20 minutes. Alkalis penetrate deeply and prolonged washing is essential." },
  { id:"osha_385", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué sucede cuando refrigerante líquido R-410A se libera y hace contacto directo con la piel desnuda de un técnico?", opciones:["Causa irritación leve similar a una picadura de insecto que desaparece en pocos minutos","Produce quemaduras por frío instantáneas ya que el refrigerante hierve a -61°F aproximadamente","Genera una reacción alérgica que produce ampollas térmicas por sensibilidad al compuesto químico","Crea una capa protectora de hielo sobre la piel que previene daño si se remueve inmediatamente"], respuesta_correcta:1, explicacion:"El R-410A tiene punto de ebullición de -61°F (-52°C). Al contacto con la piel se evapora absorbiendo calor, causando frostbite instantáneo.", en_pregunta:"What happens when liquid R-410A refrigerant is released and directly contacts a technician's bare skin?", en_opciones:["Causes mild irritation similar to an insect bite that disappears in minutes","Produces instant frostbite burns since the refrigerant boils at approximately -61°F","Generates an allergic reaction with thermal blisters from compound sensitivity","Creates a protective ice layer on the skin that prevents damage if removed immediately"], en_explicacion:"R-410A has a boiling point of -61°F (-52°C). On skin contact it evaporates absorbing heat, causing instant frostbite." },
  { id:"osha_386", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué es peligroso usar guantes de látex o nitrilo delgados cuando se manipulan cilindros de refrigerante?", opciones:["Porque el látex reacciona químicamente con el refrigerante formando compuestos tóxicos volátiles","Porque la estática del látex puede generar chispas que encienden el refrigerante en estado gaseoso","Porque el refrigerante líquido puede traspasar guantes delgados causando frostbite por contacto","Porque los guantes reducen la sensibilidad impidiendo detectar fugas por vibración de las mangueras"], respuesta_correcta:2, explicacion:"Los guantes delgados NO protegen contra refrigerante líquido. El líquido puede penetrar o congelar el guante contra la piel, causando frostbite severo.", en_pregunta:"Why is it dangerous to use thin latex or nitrile gloves when handling refrigerant cylinders?", en_opciones:["Because latex chemically reacts with refrigerant forming volatile toxic compounds","Because latex static can generate sparks that ignite refrigerant in gaseous state","Because liquid refrigerant can pass through thin gloves causing frostbite on contact","Because gloves reduce sensitivity preventing leak detection by hose vibration"], en_explicacion:"Thin gloves do NOT protect against liquid refrigerant. Liquid can penetrate or freeze the glove against the skin, causing severe frostbite." },
  { id:"osha_387", categoria:"OSHA_QUEMADURAS", pregunta:"Si un técnico sufre frostbite por contacto con refrigerante líquido en los dedos, ¿cuál es el tratamiento correcto?", opciones:["Frotar vigorosamente los dedos para restaurar la circulación sanguínea lo más rápido posible","Sumergir los dedos en agua caliente a 140°F para recalentar el tejido de forma inmediata","Sumergir los dedos en agua tibia entre 100°F y 105°F sin frotar el área congelada afectada","Aplicar hielo adicional sobre el área para reducir la inflamación antes de calentar gradualmente"], respuesta_correcta:2, explicacion:"Sumergir en agua tibia (100-105°F / 38-40°C) sin frotar. Frotar causa daño mecánico al tejido congelado. Agua muy caliente causa quemaduras adicionales.", en_pregunta:"If a technician suffers frostbite from liquid refrigerant contact on the fingers, what is the correct treatment?", en_opciones:["Rub fingers vigorously to restore blood circulation as quickly as possible","Immerse fingers in hot water at 140°F to rewarm tissue immediately","Immerse fingers in warm water between 100°F and 105°F without rubbing the frozen area","Apply additional ice over the area to reduce swelling before gradually warming"], en_explicacion:"Immerse in warm water (100-105°F / 38-40°C) without rubbing. Rubbing causes mechanical damage to frozen tissue. Very hot water causes additional burns." },
  { id:"osha_388", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué riesgo de quemaduras por frío existe al trabajar con nitrógeno líquido durante congelamiento de tuberías en HVAC?", opciones:["El nitrógeno líquido a -321°F puede causar congelamiento instantáneo de tejidos en menos de un segundo","El nitrógeno líquido solo es peligroso si se ingiere ya que sobre la piel se evapora sin causar daño","El nitrógeno líquido causa quemaduras químicas por su acidez natural al contacto con tejido humano","El nitrógeno líquido presenta riesgo solo por inhalación ya que desplaza el oxígeno en áreas cerradas"], respuesta_correcta:0, explicacion:"El nitrógeno líquido hierve a -321°F (-196°C) y puede causar congelamiento instantáneo y destrucción de tejidos en fracciones de segundo.", en_pregunta:"What frostbite risk exists when working with liquid nitrogen during pipe freezing in HVAC?", en_opciones:["Liquid nitrogen at -321°F can cause instant tissue freezing in under a second","Liquid nitrogen is only dangerous if ingested since it evaporates on skin without damage","Liquid nitrogen causes chemical burns from its natural acidity on human tissue contact","Liquid nitrogen presents risk only by inhalation since it displaces oxygen in enclosed areas"], en_explicacion:"Liquid nitrogen boils at -321°F (-196°C) and can cause instant freezing and tissue destruction in fractions of a second." },
  { id:"osha_389", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál es el rango de temperatura del agua recomendado para enfriar una quemadura térmica según protocolos actualizados?", opciones:["Agua helada entre 32°F y 40°F aplicada directamente para máximo efecto de enfriamiento","Agua fría corriente entre 60°F y 77°F aplicada durante 10 a 20 minutos continuos","Agua caliente entre 90°F y 100°F para evitar hipotermia localizada en el tejido dañado","Agua a temperatura ambiente exacta de 72°F aplicada en intervalos de 5 minutos con descanso"], respuesta_correcta:1, explicacion:"Agua fría corriente entre 60°F y 77°F (15-25°C) durante 10-20 minutos. NO usar agua helada ni hielo porque causa vasoconstricción.", en_pregunta:"What is the recommended water temperature range to cool a thermal burn according to updated protocols?", en_opciones:["Ice water between 32°F and 40°F applied directly for maximum cooling effect","Cool running water between 60°F and 77°F applied for 10 to 20 continuous minutes","Warm water between 90°F and 100°F to avoid localized hypothermia in damaged tissue","Room temperature water at exactly 72°F applied in 5-minute intervals with rest"], en_explicacion:"Cool running water between 60°F and 77°F (15-25°C) for 10-20 minutes. Do NOT use ice water or ice because it causes vasoconstriction." },
  { id:"osha_390", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál de las siguientes acciones está CONTRAINDICADA al tratar quemaduras de segundo grado con ampollas?", opciones:["Cubrir la quemadura con un apósito estéril limpio y seco sin apretar contra la herida","Reventar las ampollas para drenar el líquido y aplicar ungüento antibiótico directamente","Enfriar la quemadura con agua fría limpia corriente durante un mínimo de diez minutos","Remover anillos o joyería cercana antes de que se desarrolle inflamación en el área afectada"], respuesta_correcta:1, explicacion:"NUNCA reventar las ampollas. Actúan como barrera natural contra infecciones. Solo personal médico debe manejarlas.", en_pregunta:"Which of the following actions is CONTRAINDICATED when treating second-degree burns with blisters?", en_opciones:["Cover the burn with a clean, dry sterile dressing without pressing against the wound","Pop the blisters to drain the fluid and apply antibiotic ointment directly","Cool the burn with clean running cold water for a minimum of ten minutes","Remove nearby rings or jewelry before swelling develops in the affected area"], en_explicacion:"NEVER pop blisters. They act as a natural barrier against infection. Only medical personnel should manage them." },
  { id:"osha_391", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué NO se debe aplicar hielo directamente sobre una quemadura térmica aunque el técnico sienta dolor intenso?", opciones:["Porque el hielo contamina la herida con bacterias del agua congelada no estéril utilizada","Porque el hielo causa vasoconstricción que reduce flujo sanguíneo y agrava el daño tisular","Porque el hielo eleva la temperatura de la quemadura por efecto rebote térmico al retirarlo","Porque el hielo reacciona con la piel quemada creando una costra que impide la cicatrización"], respuesta_correcta:1, explicacion:"El hielo causa vasoconstricción severa, reduciendo el flujo sanguíneo. También puede causar frostbite adicional en el tejido ya comprometido.", en_pregunta:"Why should ice NOT be applied directly on a thermal burn even though the technician feels intense pain?", en_opciones:["Because the ice contaminates the wound with bacteria from non-sterile frozen water","Because ice causes vasoconstriction that reduces blood flow and worsens tissue damage","Because ice raises the burn's temperature through thermal rebound when removed","Because ice reacts with burned skin creating a scab that prevents healing"], en_explicacion:"Ice causes severe vasoconstriction, reducing blood flow. It can also cause additional frostbite in the already compromised tissue." },
  { id:"osha_392", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué sustancia comúnmente aplicada como remedio casero NUNCA debe usarse en quemaduras?", opciones:["Aloe vera puro aplicado directamente de la planta sobre la quemadura superficial reciente","Mantequilla o aceite porque atrapa el calor dentro del tejido y aumenta el daño térmico","Solución salina estéril al 0.9% para irrigación suave y limpieza del área quemada abierta","Gasa estéril húmeda colocada suavemente sin presión directa sobre la quemadura limpia"], respuesta_correcta:1, explicacion:"La mantequilla, aceite, grasa y pasta de dientes crean una capa aislante que atrapa el calor residual, empeorando la quemadura.", en_pregunta:"What commonly applied home remedy substance should NEVER be used on burns?", en_opciones:["Pure aloe vera applied directly from the plant on a recent superficial burn","Butter or oil because it traps heat inside the tissue and increases thermal damage","0.9% sterile saline solution for gentle irrigation and cleaning of open burned area","Moist sterile gauze placed gently without direct pressure on the clean burn"], en_explicacion:"Butter, oil, grease, and toothpaste create an insulating layer that traps residual heat, worsening the burn." },
  { id:"osha_393", categoria:"OSHA_QUEMADURAS", pregunta:"Al transportar a un técnico con quemaduras extensas, ¿cuál es la principal complicación que debe monitorearse?", opciones:["Reacción alérgica tardía a los materiales del vendaje aplicado en el tratamiento inicial","Shock hipovolémico por pérdida masiva de líquidos a través de la piel dañada expuesta","Infección bacteriana inmediata que se desarrolla en los primeros cinco minutos del incidente","Pérdida auditiva temporal causada por el estrés nervioso del trauma de la quemadura sufrida"], respuesta_correcta:1, explicacion:"Las quemaduras extensas causan pérdida masiva de plasma sanguíneo, llevando a shock hipovolémico.", en_pregunta:"When transporting a technician with extensive burns, what is the main complication that must be monitored?", en_opciones:["Delayed allergic reaction to the bandage materials applied in initial treatment","Hypovolemic shock from massive fluid loss through the exposed damaged skin","Immediate bacterial infection that develops in the first five minutes after the incident","Temporary hearing loss caused by nervous stress from the burn trauma"], en_explicacion:"Extensive burns cause massive plasma loss, leading to hypovolemic shock." },
  { id:"osha_394", categoria:"OSHA_QUEMADURAS", pregunta:"Según OSHA 29 CFR 1910.132, ¿qué debe proporcionar el empleador sin costo al trabajador para prevención de quemaduras?", opciones:["Seguro médico completo que cubra tratamiento de quemaduras en cualquier hospital certificado","Todo el equipo de protección personal necesario para los riesgos identificados en el área","Capacitación universitaria en seguridad contra incendios con certificación NFPA reconocida","Bonificación económica adicional por trabajar en áreas donde existe riesgo de quemaduras"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1910.132 requiere que el empleador proporcione sin costo todo el PPE necesario basado en la evaluación de riesgos.", en_pregunta:"According to OSHA 29 CFR 1910.132, what must the employer provide to the worker at no cost for burn prevention?", en_opciones:["Complete medical insurance covering burn treatment at any certified hospital","All personal protective equipment necessary for identified risks in the area","University training in fire safety with recognized NFPA certification","Extra financial bonus for working in areas with burn risk"], en_explicacion:"OSHA 29 CFR 1910.132 requires the employer to provide all necessary PPE at no cost based on the hazard assessment." },
  { id:"osha_395", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué tipo de guantes debe usar un técnico HVAC al realizar brazing con soplete?", opciones:["Guantes de algodón grueso que permiten buena destreza manual para manipular el soplete","Guantes de cuero resistentes al calor con puño extendido que proteja las muñecas","Guantes de nitrilo reforzado que protegen contra químicos y calor moderado simultáneamente","Guantes de látex doble capa que proporcionan protección básica y sensibilidad táctil"], respuesta_correcta:1, explicacion:"Para brazing se requieren guantes de cuero resistentes al calor con puño extendido para proteger muñecas de salpicaduras de metal fundido.", en_pregunta:"What type of gloves should an HVAC technician use when brazing with a torch?", en_opciones:["Thick cotton gloves that allow good manual dexterity to handle the torch","Heat-resistant leather gloves with extended cuff to protect the wrists","Reinforced nitrile gloves that protect against chemicals and moderate heat simultaneously","Double-layer latex gloves that provide basic protection and tactile sensitivity"], en_explicacion:"Brazing requires heat-resistant leather gloves with an extended cuff to protect wrists from molten metal splatter." },
  { id:"osha_396", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál es el propósito principal de usar ropa FR (Flame Resistant) cerca de riesgos de arc flash eléctrico?", opciones:["Eliminar completamente la posibilidad de sufrir cualquier tipo de quemadura por arco eléctrico","Extinguirse automáticamente al retirar la fuente de ignición limitando la extensión de quemaduras","Reflejar la energía del arco eléctrico de vuelta hacia la fuente neutralizando el peligro térmico","Absorber toda la energía térmica del arco convirtiéndola en calor inofensivo para el trabajador"], respuesta_correcta:1, explicacion:"La ropa FR se autoextingue al retirar la fuente de ignición. La ropa normal puede encenderse y seguir quemando.", en_pregunta:"What is the main purpose of wearing FR (Flame Resistant) clothing near arc flash electrical hazards?", en_opciones:["Completely eliminate the possibility of any burn from an electrical arc","Self-extinguish when the ignition source is removed, limiting burn extension","Reflect the arc's energy back to the source neutralizing the thermal hazard","Absorb all thermal energy from the arc converting it into harmless heat for the worker"], en_explicacion:"FR clothing self-extinguishes when the ignition source is removed. Regular clothing can ignite and keep burning." },
  { id:"osha_397", categoria:"OSHA_QUEMADURAS", pregunta:"Según OSHA, ¿cada cuánto tiempo debe inspeccionarse el equipo de protección personal contra quemaduras?", opciones:["Solo cuando el equipo presenta daño visible a simple vista durante la jornada de trabajo","Antes de cada uso y reemplazarse cuando muestre señales de degradación deterioro o daño","Una vez al año durante la auditoría anual de seguridad requerida por la gerencia de planta","Cada seis meses mediante un laboratorio certificado que emita constancia de calidad del EPP"], respuesta_correcta:1, explicacion:"OSHA requiere inspección del PPE antes de cada uso. El PPE debe reemplazarse inmediatamente cuando muestre degradación.", en_pregunta:"According to OSHA, how often must personal protective equipment for burn protection be inspected?", en_opciones:["Only when the equipment shows obvious damage visible during the work shift","Before each use and replaced when showing signs of degradation, deterioration, or damage","Once a year during the annual safety audit required by plant management","Every six months through a certified laboratory issuing a quality certification"], en_explicacion:"OSHA requires PPE inspection before each use. PPE must be replaced immediately when it shows degradation." },
  { id:"osha_398", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué requisito de OSHA aplica para almacenamiento de cilindros de gas usados en brazing para prevenir incendios?", opciones:["Almacenar todos los cilindros juntos en un área ventilada con temperatura controlada bajo 80°F","Mantener cilindros de oxígeno separados mínimo 20 pies de combustibles o por barrera cortafuegos","Almacenar los cilindros acostados horizontalmente para prevenir caídas y daño a las válvulas","Mantener los cilindros al aire libre expuestos directamente al sol para evitar acumulación de gases"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1910.253 requiere cilindros de oxígeno mínimo 20 pies de gases combustibles o separados por barrera cortafuegos de 5 pies.", en_pregunta:"What OSHA requirement applies to storage of gas cylinders used in brazing to prevent fires?", en_opciones:["Store all cylinders together in a ventilated area with temperature controlled below 80°F","Keep oxygen cylinders at least 20 feet from combustibles or separated by a fire barrier","Store cylinders lying horizontally to prevent falls and damage to valves","Keep cylinders outdoors in direct sunlight to avoid gas buildup"], en_explicacion:"OSHA 29 CFR 1910.253 requires oxygen cylinders to be at least 20 feet from combustible gases or separated by a 5-foot fire barrier." },
  { id:"osha_399", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué tipo de quemadura puede sufrir un técnico al abrir la tapa de un compresor scroll que acaba de fallar con alta presión?", opciones:["Quemadura por radiación ultravioleta reflejada por el aceite caliente dentro del compresor","Quemadura térmica por aceite caliente presurizado que se expulsa violentamente al liberar la tapa","Quemadura química por los ácidos naturales presentes en el aceite mineral del compresor nuevo","Quemadura eléctrica por la carga residual almacenada en los devanados internos del motor"], respuesta_correcta:1, explicacion:"Un compresor puede tener aceite a más de 300°F bajo alta presión. Al abrir sin despresurizar, el aceite caliente se expulsa violentamente.", en_pregunta:"What type of burn can a technician suffer when opening the cover of a scroll compressor that just failed with high pressure?", en_opciones:["UV radiation burn reflected by the hot oil inside the compressor","Thermal burn from pressurized hot oil violently ejected when releasing the cover","Chemical burn from natural acids in the mineral oil of the new compressor","Electrical burn from residual charge stored in the motor's internal windings"], en_explicacion:"A compressor can have oil above 300°F under high pressure. Opening without depressurizing causes hot oil to violently eject." },
  { id:"osha_400", categoria:"OSHA_QUEMADURAS", pregunta:"¿Por qué los técnicos HVAC en azoteas durante verano tienen riesgo elevado de quemaduras solares?", opciones:["Porque el ozono es más concentrado en las azoteas y amplifica los rayos ultravioleta directamente","Porque las superficies metálicas y de membrana reflejan radiación UV aumentando la exposición total","Porque la altitud de las azoteas reduce la protección atmosférica eliminando la capa de ozono","Porque el aire acondicionado de las unidades enfría la piel ocultando el daño solar acumulado"], respuesta_correcta:1, explicacion:"Las azoteas tienen superficies reflectantes que reflejan radiación UV, causando exposición desde arriba y desde abajo simultáneamente.", en_pregunta:"Why do HVAC technicians on rooftops during summer have elevated risk of sunburn?", en_opciones:["Because ozone is more concentrated on rooftops and directly amplifies UV rays","Because metal and membrane surfaces reflect UV radiation increasing total exposure","Because the altitude of rooftops reduces atmospheric protection eliminating the ozone layer","Because the air conditioning of units cools the skin hiding accumulated sun damage"], en_explicacion:"Rooftops have reflective surfaces that reflect UV radiation, causing exposure from above and below simultaneously." },
  { id:"osha_401", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué tipo de quemadura ocurre cuando un técnico contacta accidentalmente una línea de descarga del compresor sin aislamiento?", opciones:["Quemadura por frío porque la línea de descarga transporta refrigerante en estado líquido subenfriado","Quemadura química por los residuos de flux en la superficie exterior de la tubería de cobre","Quemadura térmica porque la línea de descarga puede alcanzar temperaturas superiores a 200°F","Quemadura eléctrica porque la tubería de cobre conduce corriente parásita del compresor al exterior"], respuesta_correcta:2, explicacion:"La línea de descarga transporta gas supercalentado que puede superar 200°F (93°C) y en algunos sistemas 300°F.", en_pregunta:"What type of burn occurs when a technician accidentally contacts an uninsulated discharge line from a compressor?", en_opciones:["Cold burn because the discharge line carries refrigerant in subcooled liquid state","Chemical burn from flux residue on the copper tube's exterior surface","Thermal burn because the discharge line can reach temperatures above 200°F","Electrical burn because the copper tube conducts parasitic current from the compressor"], en_explicacion:"The discharge line carries superheated gas that can exceed 200°F (93°C), and in some systems 300°F." },
  { id:"osha_402", categoria:"OSHA_QUEMADURAS", pregunta:"Al limpiar serpentines con limpiador ácido, ¿qué equipo es MÍNIMO requerido para prevenir quemaduras químicas?", opciones:["Solo guantes de trabajo estándar de cuero ya que el ácido está diluido a concentración segura","Guantes químicos resistentes a ácidos más gafas de protección contra salpicaduras como mínimo","Solo gafas de seguridad ya que el contacto con las manos es breve durante la aplicación","Únicamente una mascarilla N95 porque el riesgo principal es la inhalación no el contacto"], respuesta_correcta:1, explicacion:"OSHA requiere como mínimo guantes resistentes a químicos Y protección ocular al manejar limpiadores ácidos.", en_pregunta:"When cleaning coils with acid cleaner, what is the MINIMUM equipment required to prevent chemical burns?", en_opciones:["Only standard leather work gloves since the acid is diluted to safe concentration","Acid-resistant chemical gloves plus splash protection goggles as a minimum","Only safety glasses since hand contact is brief during application","Only an N95 mask because the main risk is inhalation not contact"], en_explicacion:"OSHA requires as a minimum chemical-resistant gloves AND eye protection when handling acid cleaners." },
  { id:"osha_403", categoria:"OSHA_QUEMADURAS", pregunta:"¿Qué riesgo de quemaduras existe al purgar con nitrógeno un sistema mientras se realiza brazing simultáneamente?", opciones:["El nitrógeno se congela dentro de la tubería creando tapones de hielo que explotan por presión","No existe riesgo de quemaduras ya que el nitrógeno es inerte y esa es precisamente su función","El nitrógeno puede desplazar oxígeno causando desmayo del técnico que cae sobre el soplete encendido","El nitrógeno acelera la combustión haciendo que la llama del soplete crezca de forma incontrolable"], respuesta_correcta:2, explicacion:"En espacios cerrados el nitrógeno desplaza oxígeno. Un técnico puede desmayarse y caer sobre el soplete encendido.", en_pregunta:"What burn risk exists when purging a system with nitrogen while simultaneously brazing?", en_opciones:["Nitrogen freezes inside the tube creating ice plugs that explode from pressure","No burn risk exists since nitrogen is inert and that is precisely its function","Nitrogen can displace oxygen causing the technician to faint and fall on the lit torch","Nitrogen accelerates combustion making the torch flame grow uncontrollably"], en_explicacion:"In enclosed spaces nitrogen displaces oxygen. A technician can faint and fall on the lit torch." },
  { id:"osha_404", categoria:"OSHA_QUEMADURAS", pregunta:"¿Cuál es el procedimiento correcto si la ropa de un técnico se enciende durante trabajo con soplete?", opciones:["Correr hacia la salida más cercana para buscar ayuda inmediata de los compañeros de trabajo","Ejecutar la técnica PARE TÍRESE y RUEDE para sofocar las llamas sobre el piso del área de trabajo","Quitarse la ropa encendida lo más rápido posible sin importar la ubicación o situación presente","Rociar la ropa encendida con el extintor de CO2 más cercano apuntando directamente sobre las llamas"], respuesta_correcta:1, explicacion:"STOP-DROP-ROLL (PARE-TÍRESE-RUEDE): detenerse, tirarse al piso y rodar para sofocar las llamas. Correr aviva el fuego.", en_pregunta:"What is the correct procedure if a technician's clothing ignites during torch work?", en_opciones:["Run toward the nearest exit to seek immediate help from coworkers","Execute the STOP-DROP-ROLL technique to smother the flames on the work area floor","Remove the burning clothing as quickly as possible regardless of location or situation","Spray the burning clothing with the nearest CO2 extinguisher aimed directly at the flames"], en_explicacion:"STOP-DROP-ROLL: stop, drop to the floor, and roll to smother the flames. Running feeds the fire." },

  // -- INTRODUCCIÓN A OSHA -- Derechos del Trabajador (405-434) --
  { id:"osha_405", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es el propósito fundamental de la Cláusula de Deber General (General Duty Clause) de la Ley OSH de 1970?", opciones:["Obligar a los empleados a reportar cualquier incidente menor de forma inmediata","Garantizar un lugar de trabajo libre de peligros reconocidos sin norma específica","Permitir que OSHA imponga multas discrecionales sin necesidad de una inspección","Exigir que todos los técnicos de HVAC tengan una certificación federal vigente"], respuesta_correcta:1, explicacion:"La General Duty Clause (Sección 5(a)(1)) se usa cuando no existe una norma específica para un peligro reconocido que cause o pueda causar la muerte o daño físico.", en_pregunta:"What is the fundamental purpose of the General Duty Clause of the 1970 OSH Act?", en_opciones:["Require employees to immediately report any minor incident","Guarantee a workplace free of recognized hazards with no specific standard","Allow OSHA to impose discretionary fines without the need for an inspection","Require all HVAC technicians to hold a current federal certification"], en_explicacion:"The General Duty Clause (Section 5(a)(1)) is used when no specific standard exists for a recognized hazard that causes or is likely to cause death or physical harm." },
  { id:"osha_406", categoria:"OSHA_INTRODUCCION", pregunta:"Bajo la doctrina de 'Multi-Employer Worksites', ¿qué empleador es responsable de corregir un peligro detectado?", opciones:["El empleador que creó el peligro independientemente de quiénes estén expuestos","Únicamente el contratista general por ser el dueño legal de la póliza de seguro","El empleador cuyos trabajadores están expuestos directamente al riesgo eléctrico","Cualquier empleador con autoridad para corregir el peligro o mando en el sitio"], respuesta_correcta:3, explicacion:"OSHA identifica cuatro tipos de empleadores (creador, expositor, corrector, controlador) y cualquiera con autoridad o responsabilidad puede ser citado.", en_pregunta:"Under the Multi-Employer Worksite doctrine, which employer is responsible for correcting a detected hazard?", en_opciones:["The employer who created the hazard regardless of who is exposed","Only the general contractor as the legal holder of the insurance policy","The employer whose workers are directly exposed to the electrical risk","Any employer with authority to correct the hazard or command on site"], en_explicacion:"OSHA identifies four types of employers (creating, exposing, correcting, controlling), and any with authority or responsibility can be cited." },
  { id:"osha_407", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué tipo de violación de OSHA conlleva la multa más alta debido a la indiferencia intencional del patrono?", opciones:["Violación Seria donde existe probabilidad de muerte por falta de mantenimiento","Violación Repetida tras una inspección previa en un periodo menor a cinco años","Violación Intencional (Willful) por ignorar conscientemente los requisitos legales","Violación de Gravedad Menor que afecta la salud a largo plazo de los empleados"], respuesta_correcta:2, explicacion:"Las violaciones 'Willful' son las más graves y costosas porque demuestran que el empleador conocía la norma y decidió no cumplirla voluntariamente.", en_pregunta:"What type of OSHA violation carries the highest fine due to intentional employer indifference?", en_opciones:["Serious violation where there is probability of death due to lack of maintenance","Repeated violation after a previous inspection within a period of less than five years","Willful violation for consciously ignoring legal requirements","Minor gravity violation that affects the long-term health of employees"], en_explicacion:"Willful violations are the most serious and costly because they demonstrate that the employer knew the standard and deliberately chose not to comply." },
  { id:"osha_408", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuántos días tiene un trabajador para presentar una queja ante OSHA si cree que ha sufrido represalias (Whistleblower)?", opciones:["Tiene un periodo máximo de 60 días calendario tras el incidente de discriminación","Dispone de 30 días exactos desde que ocurrió el acto de represalia por el jefe","Cuenta con 90 días hábiles para someter la documentación legal ante el estado","Debe presentar la queja en menos de 15 días tras ser despedido injustamente"], respuesta_correcta:1, explicacion:"Según la Sección 11(c) de la Ley OSH, los trabajadores tienen 30 días para denunciar discriminación o represalias por ejercer sus derechos de seguridad.", en_pregunta:"How many days does a worker have to file a complaint with OSHA if they believe they have suffered retaliation (Whistleblower)?", en_opciones:["A maximum period of 60 calendar days after the discrimination incident","Exactly 30 days from when the retaliation by the boss occurred","90 working days to submit the legal documentation to the state","Must file the complaint in less than 15 days after being unjustly fired"], en_explicacion:"Under Section 11(c) of the OSH Act, workers have 30 days to report discrimination or retaliation for exercising their safety rights." },
  { id:"osha_409", categoria:"OSHA_INTRODUCCION", pregunta:"En el registro de lesiones OSHA 300, ¿qué evento debe reportarse obligatoriamente dentro de las primeras 8 horas?", opciones:["Cualquier accidente que resulte en la hospitalización de dos o más empleados","Una lesión por electrocución que requiera únicamente tratamiento de primeros auxilios","Todo incidente que resulte en la muerte de un trabajador por causas laborales","Cualquier fractura ósea que impida al técnico realizar sus labores de instalación"], respuesta_correcta:2, explicacion:"Las fatalidades deben reportarse a OSHA en un máximo de 8 horas; las hospitalizaciones, amputaciones o pérdidas de ojo tienen un plazo de 24 horas.", en_pregunta:"On the OSHA 300 injury log, what event must mandatorily be reported within the first 8 hours?", en_opciones:["Any accident that results in the hospitalization of two or more employees","An electrocution injury that requires only first aid treatment","Any incident that results in the death of a worker from work-related causes","Any bone fracture that prevents the technician from performing installation tasks"], en_explicacion:"Fatalities must be reported to OSHA within a maximum of 8 hours; hospitalizations, amputations, or loss of an eye have a 24-hour deadline." },
  { id:"osha_410", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué derecho posee un técnico de refrigeración durante una inspección física realizada por un oficial de OSHA?", opciones:["El derecho a solicitar que la inspección se realice fuera de su horario laboral","El derecho a participar en la inspección y hablar en privado con el inspector","El derecho a exigir una orden judicial antes de permitir el acceso al cuarto mecánico","El derecho a detener la inspección si considera que las preguntas son intrusivas"], respuesta_correcta:1, explicacion:"Los trabajadores tienen el derecho legal de acompañar al inspector y de hablar con él de forma confidencial sin presencia del empleador.", en_pregunta:"What right does a refrigeration technician have during a physical inspection conducted by an OSHA officer?", en_opciones:["The right to request that the inspection be performed outside their work shift","The right to participate in the inspection and speak privately with the inspector","The right to demand a warrant before allowing access to the mechanical room","The right to stop the inspection if they consider the questions intrusive"], en_explicacion:"Workers have the legal right to accompany the inspector and speak with them confidentially without the employer present." },
  { id:"osha_411", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es la función principal del Log OSHA 300A que las empresas deben publicar anualmente?", opciones:["Detallar los nombres de todos los empleados que sufrieron enfermedades laborales","Exhibir un resumen total de lesiones y enfermedades del año previo en el sitio","Enumerar las multas pagadas a la agencia federal por conceptos de seguridad","Registrar las horas de capacitación técnica recibidas por el personal de campo"], respuesta_correcta:1, explicacion:"El OSHA 300A es el resumen anual que debe publicarse del 1 de febrero al 30 de abril en un lugar visible para que los empleados vean las estadísticas.", en_pregunta:"What is the main function of the OSHA 300A Log that companies must post annually?", en_opciones:["Detail the names of all employees who suffered occupational illnesses","Display a total summary of injuries and illnesses from the previous year on site","List the fines paid to the federal agency for safety matters","Record the training hours received by field personnel"], en_explicacion:"The OSHA 300A is the annual summary that must be posted from February 1 to April 30 in a visible place for employees to see the statistics." },
  { id:"osha_412", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué norma de OSHA obliga a los empleadores a informar a los técnicos sobre los peligros químicos en el sitio?", opciones:["Norma de Comunicación de Peligros (HazCom) detallada en 29 CFR 1910.1200","Norma de Equipo de Protección Personal especificada en el código 29 CFR 1926.28","Regulación de Sustancias Tóxicas y Agentes Físicos del estándar 29 CFR 1910.1000","Protocolo de Seguridad para Espacios Confinados bajo el código 29 CFR 1910.146"], respuesta_correcta:0, explicacion:"El estándar de Comunicación de Peligros (Hazard Communication) garantiza el 'Derecho a Saber' de los trabajadores sobre químicos peligrosos.", en_pregunta:"Which OSHA standard requires employers to inform technicians about chemical hazards on site?", en_opciones:["Hazard Communication Standard (HazCom) detailed in 29 CFR 1910.1200","Personal Protective Equipment standard specified in code 29 CFR 1926.28","Toxic and Hazardous Substances regulation in standard 29 CFR 1910.1000","Confined Space Safety Protocol under code 29 CFR 1910.146"], en_explicacion:"The Hazard Communication standard guarantees the workers' 'Right to Know' about hazardous chemicals." },
  { id:"osha_413", categoria:"OSHA_INTRODUCCION", pregunta:"Si un técnico de HVAC nota una condición de 'Peligro Inminente', ¿cuál es su derecho legal más fuerte?", opciones:["Renunciar al empleo con goce de sueldo hasta que se resuelva la situación técnica","Negarse a trabajar si existe una amenaza real de muerte o daño físico grave","Solicitar un aumento salarial por trabajar en condiciones de riesgo extraordinario","Contactar a la policía local para que clausure el edificio de forma inmediata"], respuesta_correcta:1, explicacion:"OSHA protege el derecho a rechazar una tarea si el trabajador cree razonablemente que enfrenta un riesgo inminente de muerte o lesión grave.", en_pregunta:"If an HVAC technician notices an 'Imminent Danger' condition, what is their strongest legal right?", en_opciones:["Resign from employment with full pay until the technical situation is resolved","Refuse to work if there is a real threat of death or serious physical harm","Request a salary increase for working in extraordinary risk conditions","Contact local police to shut down the building immediately"], en_explicacion:"OSHA protects the right to refuse a task if the worker reasonably believes they face imminent risk of death or serious injury." },
  { id:"osha_414", categoria:"OSHA_INTRODUCCION", pregunta:"¿En qué año se firmó la ley que creó OSHA y bajo qué administración presidencial ocurrió?", opciones:["En el año 1968 bajo la dirección de la administración de Lyndon B. Johnson","En el año 1970 tras ser firmada legalmente por el presidente Richard Nixon","En el año 1972 durante el primer término de la presidencia de Gerald Ford","En el año 1975 como respuesta a la crisis industrial del presidente Jimmy Carter"], respuesta_correcta:1, explicacion:"La Occupational Safety and Health Act fue firmada por Richard Nixon el 29 de diciembre de 1970, entrando en vigor en 1971.", en_pregunta:"In what year was the law that created OSHA signed, and under which presidential administration?", en_opciones:["In 1968 under the leadership of the Lyndon B. Johnson administration","In 1970 after being legally signed by President Richard Nixon","In 1972 during the first term of President Gerald Ford","In 1975 as a response to the industrial crisis of President Jimmy Carter"], en_explicacion:"The Occupational Safety and Health Act was signed by Richard Nixon on December 29, 1970, taking effect in 1971." },
  { id:"osha_415", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es la responsabilidad del empleador respecto al costo del Equipo de Protección Personal (PPE)?", opciones:["El empleador debe reembolsar el 50% del costo de cualquier equipo especializado","El trabajador debe comprar su propio equipo para garantizar un ajuste adecuado","El empleador debe proporcionar casi todo el PPE sin costo alguno al trabajador","Solo se requiere que el empleador pague por el PPE si el contrato es de unión"], respuesta_correcta:2, explicacion:"Bajo la norma de OSHA, los empleadores están obligados a pagar por la gran mayoría del PPE necesario para el trabajo (con pocas excepciones).", en_pregunta:"What is the employer's responsibility regarding the cost of Personal Protective Equipment (PPE)?", en_opciones:["The employer must reimburse 50% of the cost of any specialized equipment","The worker must buy their own equipment to ensure proper fit","The employer must provide almost all PPE at no cost to the worker","The employer is only required to pay for PPE if the contract is union"], en_explicacion:"Under the OSHA standard, employers are required to pay for the vast majority of PPE needed for the job (with few exceptions)." },
  { id:"osha_416", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué constituye una violación 'Serious' (Seria) según los criterios de inspección de OSHA?", opciones:["Una falta administrativa que no afecta directamente la salud de los técnicos","Un peligro que el empleador conocía y que probablemente cause muerte o daño","Cualquier violación que se repita más de tres veces en diferentes proyectos","La ausencia de carteles informativos en el área de descanso de los trabajadores"], respuesta_correcta:1, explicacion:"Una violación es seria cuando hay una probabilidad sustancial de que ocurra la muerte o un daño físico serio y el empleador sabía del peligro.", en_pregunta:"What constitutes a Serious violation under OSHA's inspection criteria?", en_opciones:["An administrative fault that does not directly affect the technicians' health","A hazard that the employer knew of and that is likely to cause death or harm","Any violation that is repeated more than three times on different projects","The absence of informational posters in the workers' break area"], en_explicacion:"A violation is serious when there is substantial probability that death or serious physical harm will occur and the employer knew of the hazard." },
  { id:"osha_417", categoria:"OSHA_INTRODUCCION", pregunta:"¿Quién es responsable de garantizar que un contratista HVAC cumpla con las normas OSHA en un sitio federal?", opciones:["El inspector de edificios local que emitió los permisos de construcción iniciales","El dueño de la empresa contratista que emplea directamente a los trabajadores","La agencia estatal de seguridad solo si el estado tiene un plan aprobado por OSHA","El sindicato de trabajadores al que pertenecen los técnicos de refrigeración"], respuesta_correcta:1, explicacion:"La responsabilidad legal primaria de cumplir con OSHA recae siempre en el empleador directo del trabajador en el sitio de trabajo.", en_pregunta:"Who is responsible for ensuring that an HVAC contractor complies with OSHA standards on a federal site?", en_opciones:["The local building inspector who issued the initial construction permits","The owner of the contractor company that directly employs the workers","The state safety agency only if the state has an OSHA-approved plan","The union to which the refrigeration technicians belong"], en_explicacion:"The primary legal responsibility to comply with OSHA always rests with the worker's direct employer at the work site." },
  { id:"osha_418", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es el orden de prioridad de las inspecciones de OSHA (de mayor a menor importancia)?", opciones:["Peligro inminente, fatalidades, quejas de empleados, inspecciones programadas","Quejas de empleados, fatalidades, peligro inminente, inspecciones de rutina","Inspecciones programadas, quejas de empleados, fatalidades, peligro inminente","Fatalidades, peligro inminente, inspecciones de seguimiento, quejas de sindicatos"], respuesta_correcta:0, explicacion:"OSHA prioriza situaciones de peligro inminente, seguidas de fatalidades/hospitalizaciones, quejas de trabajadores y finalmente inspecciones programadas.", en_pregunta:"What is the priority order of OSHA inspections (from highest to lowest importance)?", en_opciones:["Imminent danger, fatalities, employee complaints, programmed inspections","Employee complaints, fatalities, imminent danger, routine inspections","Programmed inspections, employee complaints, fatalities, imminent danger","Fatalities, imminent danger, follow-up inspections, union complaints"], en_explicacion:"OSHA prioritizes imminent danger situations, followed by fatalities/hospitalizations, worker complaints, and finally programmed inspections." },
  { id:"osha_419", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué registro de OSHA se utiliza para anotar los detalles de cada lesión o enfermedad individual?", opciones:["Formulario OSHA 300A (Resumen Anual de incidentes y enfermedades laborales)","Formulario OSHA 301 (Informe de incidente de lesiones y enfermedades graves)","Formulario OSHA 300 (Log de lesiones y enfermedades relacionadas al trabajo)","Formulario OSHA 400 (Reporte de fatalidades y eventos de hospitalización)"], respuesta_correcta:2, explicacion:"El Formulario 300 (Log) es donde se registran los detalles específicos de cada caso asegurable que ocurre durante el año fiscal.", en_pregunta:"Which OSHA record is used to note the details of each individual injury or illness?", en_opciones:["OSHA Form 300A (Annual Summary of incidents and occupational illnesses)","OSHA Form 301 (Injury and Illness Incident Report)","OSHA Form 300 (Log of Work-Related Injuries and Illnesses)","OSHA Form 400 (Fatality and Hospitalization Events Report)"], en_explicacion:"Form 300 (Log) is where the specific details of each recordable case that occurs during the fiscal year are recorded." },
  { id:"osha_420", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es la función del Oficial de Cumplimiento de Seguridad y Salud (CSHO) de OSHA?", opciones:["Asesorar a las empresas sobre cómo evadir impuestos mediante planes de seguridad","Realizar inspecciones en los lugares de trabajo para verificar el cumplimiento","Capacitar gratuitamente a los técnicos de HVAC durante 30 horas certificadas","Diseñar los planos de ingeniería para sistemas de ventilación en edificios públicos"], respuesta_correcta:1, explicacion:"El CSHO es el inspector de campo cuya labor es verificar que se cumplan las normas de OSHA mediante inspecciones físicas y entrevistas.", en_pregunta:"What is the function of the OSHA Compliance Safety and Health Officer (CSHO)?", en_opciones:["Advise companies on how to evade taxes through safety plans","Perform workplace inspections to verify compliance","Provide free training to HVAC technicians during 30 certified hours","Design engineering plans for ventilation systems in public buildings"], en_explicacion:"The CSHO is the field inspector whose job is to verify compliance with OSHA standards through physical inspections and interviews." },
  { id:"osha_421", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué derecho otorga la norma OSHA respecto al acceso a los registros médicos laborales?", opciones:["Los trabajadores pueden ver sus registros médicos solo en presencia de un abogado","Los empleados tienen derecho a examinar y copiar sus propios registros médicos","El acceso a los registros médicos está limitado exclusivamente a la gerencia de RRHH","Solo el médico de la empresa puede revisar los expedientes de exposición química"], respuesta_correcta:1, explicacion:"Los trabajadores tienen el derecho legal de acceder a sus propios registros médicos y de exposición a sustancias tóxicas mantenidos por el empleador.", en_pregunta:"What right does the OSHA standard grant regarding access to occupational medical records?", en_opciones:["Workers can only view their medical records in the presence of a lawyer","Employees have the right to examine and copy their own medical records","Access to medical records is limited exclusively to HR management","Only the company physician can review chemical exposure files"], en_explicacion:"Workers have the legal right to access their own medical records and records of exposure to toxic substances kept by the employer." },
  { id:"osha_422", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué tipo de empleador se define como 'Creating Employer' en una obra de construcción?", opciones:["Aquel que tiene la responsabilidad de seguridad general en todo el proyecto","Aquel que causó el peligro mediante sus acciones o falta de mantenimiento","Aquel cuyos propios trabajadores están en riesgo de sufrir una caída o golpe","Aquel contratado específicamente para reparar las deficiencias de seguridad"], respuesta_correcta:1, explicacion:"El 'Creating Employer' es quien genera la condición peligrosa, incluso si sus propios empleados no están expuestos a dicho riesgo.", en_pregunta:"What type of employer is defined as the 'Creating Employer' on a construction site?", en_opciones:["The one with overall safety responsibility on the entire project","The one who caused the hazard through their actions or lack of maintenance","The one whose own workers are at risk of a fall or impact","The one specifically contracted to repair safety deficiencies"], en_explicacion:"The 'Creating Employer' is the one who generates the hazardous condition, even if their own employees are not exposed to that risk." },
  { id:"osha_423", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué especifica la norma 29 CFR Parte 1926 en el contexto de la seguridad en Estados Unidos?", opciones:["Normas generales de seguridad industrial para plantas de manufactura fija","Estándares de salud y seguridad específicos para la industria de la construcción","Protocolos de seguridad para el transporte de materiales peligrosos por carretera","Regulaciones de protección ambiental para el manejo de gases refrigerantes"], respuesta_correcta:1, explicacion:"La Parte 1926 contiene las regulaciones de seguridad que aplican específicamente a las actividades de construcción, incluyendo HVAC en obras nuevas.", en_pregunta:"What does the 29 CFR Part 1926 standard specify in the context of safety in the United States?", en_opciones:["General industrial safety standards for fixed manufacturing plants","Health and safety standards specific to the construction industry","Safety protocols for the transportation of hazardous materials by road","Environmental protection regulations for handling refrigerant gases"], en_explicacion:"Part 1926 contains safety regulations that apply specifically to construction activities, including HVAC in new builds." },
  { id:"osha_424", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es el requisito para que una queja de un empleado genere una inspección física de OSHA?", opciones:["La queja debe ser presentada de forma anónima para evitar represalias directas","La queja debe estar escrita y firmada por el trabajador o su representante","El empleado debe haber trabajado al menos un año completo en la empresa citada","La queja debe incluir fotos de alta resolución del peligro específico reportado"], respuesta_correcta:1, explicacion:"Aunque OSHA recibe quejas telefónicas, las quejas escritas y firmadas tienen prioridad y es más probable que resulten en una inspección en el sitio.", en_pregunta:"What is the requirement for an employee complaint to trigger a physical OSHA inspection?", en_opciones:["The complaint must be filed anonymously to avoid direct retaliation","The complaint must be in writing and signed by the worker or their representative","The employee must have worked at least one full year at the cited company","The complaint must include high-resolution photos of the specific hazard"], en_explicacion:"Although OSHA receives phone complaints, written and signed complaints have priority and are more likely to result in an on-site inspection." },
  { id:"osha_425", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué sucede si un empleador no publica el resumen OSHA 300A en el tiempo estipulado?", opciones:["Se le revoca automáticamente la licencia de contratista en el estado de operación","Puede recibir una citación y multas administrativas por incumplimiento de registro","El inspector de OSHA cerrará el sitio de trabajo hasta que se publique el cartel","Se le prohíbe participar en licitaciones de proyectos gubernamentales por un año"], respuesta_correcta:1, explicacion:"No publicar el resumen 300A es una violación administrativa de las normas de mantenimiento de registros (recordkeeping) y conlleva multas.", en_pregunta:"What happens if an employer does not post the OSHA 300A summary within the stipulated timeframe?", en_opciones:["Their contractor license is automatically revoked in the state of operation","They may receive a citation and administrative fines for recordkeeping non-compliance","The OSHA inspector will shut down the work site until the poster is put up","They are prohibited from participating in government project bids for one year"], en_explicacion:"Failure to post the 300A summary is an administrative violation of recordkeeping standards and carries fines." },
  { id:"osha_426", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es el límite máximo de empleados que exime a una empresa de mantener registros OSHA 300?", opciones:["Empresas con menos de 25 empleados a tiempo completo durante todo el año fiscal","Empresas con 10 o menos empleados en total durante cualquier punto del año","Pequeños negocios con menos de 5 técnicos operando en camiones de servicio","Contratistas independientes que no tengan ayudantes o aprendices a su cargo"], respuesta_correcta:1, explicacion:"Las empresas con 10 o menos empleados están exentas de mantener los registros OSHA 300, a menos que OSHA o el BLS lo soliciten por escrito.", en_pregunta:"What is the maximum employee count that exempts a company from maintaining OSHA 300 records?", en_opciones:["Companies with fewer than 25 full-time employees throughout the fiscal year","Companies with 10 or fewer employees at any point during the year","Small businesses with fewer than 5 technicians operating in service trucks","Independent contractors who do not have helpers or apprentices under them"], en_explicacion:"Companies with 10 or fewer employees are exempt from maintaining OSHA 300 records, unless OSHA or BLS requests them in writing." },
  { id:"osha_427", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué significa el acrónimo NIOSH en el campo de la seguridad y salud ocupacional?", opciones:["Agencia federal encargada de imponer multas a los contratistas eléctricos","Instituto dedicado a la investigación y recomendación de normas de seguridad","Departamento de justicia encargado de procesar criminalmente a los dueños","Organismo que certifica únicamente las herramientas de mano para construcción"], respuesta_correcta:1, explicacion:"NIOSH es una agencia de investigación (parte del CDC) que desarrolla criterios para OSHA pero no tiene poder para multar directamente.", en_pregunta:"What does the acronym NIOSH mean in the field of occupational safety and health?", en_opciones:["Federal agency in charge of imposing fines on electrical contractors","Institute dedicated to research and recommendation of safety standards","Department of Justice in charge of criminally prosecuting owners","Agency that certifies only hand tools for construction"], en_explicacion:"NIOSH is a research agency (part of the CDC) that develops criteria for OSHA but does not have direct fining authority." },
  { id:"osha_428", categoria:"OSHA_INTRODUCCION", pregunta:"Bajo OSHA, ¿qué se considera un 'peligro reconocido' para aplicar la General Duty Clause?", opciones:["Un riesgo que solo un ingeniero experto podría identificar mediante cálculos","Un peligro que es obvio para cualquier persona sin entrenamiento en seguridad","Un riesgo conocido por la industria o documentado por el propio empleador","Una situación que nunca antes ha causado un accidente en el sector de HVAC"], respuesta_correcta:2, explicacion:"Un peligro es 'reconocido' si la industria lo conoce, si el empleador lo conoce o si es una cuestión de sentido común técnico.", en_pregunta:"Under OSHA, what is considered a 'recognized hazard' for applying the General Duty Clause?", en_opciones:["A risk that only an expert engineer could identify through calculations","A hazard that is obvious to any person without safety training","A risk known by the industry or documented by the employer itself","A situation that has never before caused an accident in the HVAC sector"], en_explicacion:"A hazard is 'recognized' if the industry knows of it, if the employer knows of it, or if it is a matter of technical common sense." },
  { id:"osha_429", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué derecho tienen los técnicos sobre el entrenamiento de seguridad según OSHA?", opciones:["Recibir entrenamiento en un idioma y vocabulario que puedan comprender bien","Tener acceso a cursos de capacitación solo después de seis meses de empleo","Recibir el entrenamiento fuera de horas de trabajo sin compensación salarial","Ser responsables de pagar por sus propios certificados de OSHA 10 u OSHA 30"], respuesta_correcta:0, explicacion:"Los empleadores deben proporcionar capacitación en un lenguaje que el trabajador entienda; si el técnico habla español, el curso debe ser en español.", en_pregunta:"What right do technicians have regarding safety training according to OSHA?", en_opciones:["Receive training in a language and vocabulary they can understand well","Have access to training courses only after six months of employment","Receive training outside of work hours without salary compensation","Be responsible for paying for their own OSHA 10 or OSHA 30 certificates"], en_explicacion:"Employers must provide training in a language the worker understands; if the technician speaks Spanish, the course must be in Spanish." },
  { id:"osha_430", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es el plazo máximo para que un empleador corrija una violación tras recibir una citación?", opciones:["Debe corregirse de inmediato, usualmente antes de que el inspector se retire","El plazo específico (fecha de corrección) se detalla en la citación de OSHA","El empleador tiene 90 días naturales para demostrar que el peligro ya no existe","La corrección debe hacerse solo después de que se agoten todas las apelaciones"], respuesta_correcta:1, explicacion:"Cada citación de OSHA incluye una 'Abatement Date', que es la fecha límite para corregir la condición peligrosa detectada.", en_pregunta:"What is the maximum timeframe for an employer to correct a violation after receiving a citation?", en_opciones:["It must be corrected immediately, usually before the inspector leaves","The specific deadline (abatement date) is detailed in the OSHA citation","The employer has 90 calendar days to demonstrate the hazard no longer exists","Correction should only be made after all appeals are exhausted"], en_explicacion:"Each OSHA citation includes an 'Abatement Date,' which is the deadline for correcting the detected hazardous condition." },
  { id:"osha_431", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué define a un 'Exposing Employer' en un sitio con múltiples empresas trabajando?", opciones:["El empleador que no colocó la señalización de advertencia en el área común","El empleador cuyos propios trabajadores están expuestos a una condición de riesgo","El contratista que supervisa diariamente el cronograma de todas las cuadrillas","La empresa que trajo químicos peligrosos al sitio sin entregar las hojas SDS"], respuesta_correcta:1, explicacion:"El 'Exposing Employer' es aquel cuyo personal está en contacto o riesgo debido a un peligro, sin importar quién creó el peligro.", en_pregunta:"What defines an 'Exposing Employer' on a site with multiple companies working?", en_opciones:["The employer who did not post warning signage in the common area","The employer whose own workers are exposed to a hazardous condition","The contractor who daily supervises the schedule of all crews","The company that brought hazardous chemicals to the site without providing SDS sheets"], en_explicacion:"The 'Exposing Employer' is the one whose personnel is in contact with or at risk from a hazard, regardless of who created it." },
  { id:"osha_432", categoria:"OSHA_INTRODUCCION", pregunta:"¿En qué sección del 29 CFR se encuentran las normas generales para la industria (General Industry)?", opciones:["En la Parte 1910, que aplica a almacenes, tiendas y mantenimiento de HVAC","En la Parte 1926, que rige todas las instalaciones eléctricas de baja tensión","En la Parte 1915, dedicada exclusivamente al sector de construcción naval","En la Parte 1904, que establece las reglas de equipo de protección personal"], respuesta_correcta:0, explicacion:"El 29 CFR 1910 cubre la 'Industria General', que incluye trabajos de mantenimiento y servicio técnico que no son construcción.", en_pregunta:"In which section of 29 CFR are the General Industry standards located?", en_opciones:["In Part 1910, which applies to warehouses, stores, and HVAC maintenance","In Part 1926, which governs all low-voltage electrical installations","In Part 1915, dedicated exclusively to shipbuilding","In Part 1904, which establishes PPE rules"], en_explicacion:"29 CFR 1910 covers 'General Industry,' which includes maintenance and technical service work that is not construction." },
  { id:"osha_433", categoria:"OSHA_INTRODUCCION", pregunta:"¿Qué sucede si un oficial de OSHA llega a un sitio y el empleador le niega la entrada?", opciones:["El oficial puede arrestar al dueño por obstrucción a la justicia federal","OSHA regresará con una orden judicial (warrant) para forzar la inspección","La empresa será multada con un millón de dólares de forma automática","Se asume que la empresa es 100% segura y se cancela la inspección técnica"], respuesta_correcta:1, explicacion:"Si se niega la entrada, OSHA puede obtener una orden de registro legal para ingresar al lugar de trabajo y realizar la inspección obligatoriamente.", en_pregunta:"What happens if an OSHA officer arrives at a site and the employer denies entry?", en_opciones:["The officer can arrest the owner for obstruction of federal justice","OSHA will return with a warrant to force the inspection","The company will be automatically fined one million dollars","The company is assumed to be 100% safe and the technical inspection is canceled"], en_explicacion:"If entry is denied, OSHA can obtain a legal search warrant to enter the workplace and conduct a mandatory inspection." },
  { id:"osha_434", categoria:"OSHA_INTRODUCCION", pregunta:"¿Cuál es la responsabilidad del trabajador (técnico) bajo la Ley OSH de 1970?", opciones:["Diseñar sus propios planes de seguridad si el patrono no proporciona uno","Cumplir con todas las normas de OSHA y reglas de seguridad del empleador","Multar a sus compañeros de trabajo si observa que no usan el casco de seguridad","Inspeccionar el equipo de los demás contratistas antes de iniciar la jornada"], respuesta_correcta:1, explicacion:"Aunque los empleadores son los responsables finales, la sección 5(b) exige que los empleados cumplan con las normas y órdenes de seguridad aplicables.", en_pregunta:"What is the worker's (technician's) responsibility under the 1970 OSH Act?", en_opciones:["Design their own safety plans if the employer does not provide one","Comply with all OSHA standards and employer safety rules","Fine coworkers if they observe them not wearing their safety helmet","Inspect the equipment of other contractors before starting the shift"], en_explicacion:"Although employers are ultimately responsible, Section 5(b) requires employees to comply with applicable safety standards and orders." },

  { id:"osha_435", categoria:"OSHA_RESPIRATORIA", pregunta:"Según 29 CFR 1910.134, ¿cada cuánto tiempo debe actualizarse la evaluación médica de un empleado que usa respirador?", opciones:["Cada 12 meses sin excepción alguna","Cuando cambian condiciones de trabajo","Cada 6 meses según el fabricante","Al inicio de cada proyecto nuevo"], respuesta_correcta:1, explicacion:"La evaluación médica debe actualizarse cuando hay cambios en las condiciones de trabajo, el estado de salud del empleado, o el tipo de respirador utilizado, no en un intervalo fijo automático.", en_pregunta:"According to 29 CFR 1910.134, how often must the medical evaluation of an employee who uses a respirator be updated?", en_opciones:["Every 12 months without exception","When work conditions change","Every 6 months per the manufacturer","At the start of each new project"], en_explicacion:"The medical evaluation must be updated when there are changes in work conditions, the employee's health status, or the type of respirator used, not at a fixed automatic interval." },
  { id:"osha_436", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el Factor de Protección Asignado (APF) de un respirador de media cara con filtros según OSHA?", opciones:["APF de 50 para media cara estándar","APF de 25 para media cara estándar","APF de 10 para media cara estándar","APF de 15 para media cara estándar"], respuesta_correcta:2, explicacion:"OSHA asigna un APF de 10 a los respiradores de media cara (half-facepiece), lo que significa que reducen la concentración del contaminante a 1/10 del nivel ambiental.", en_pregunta:"What is the Assigned Protection Factor (APF) of a half-face respirator with filters per OSHA?", en_opciones:["APF of 50 for a standard half-face","APF of 25 for a standard half-face","APF of 10 for a standard half-face","APF of 15 for a standard half-face"], en_explicacion:"OSHA assigns an APF of 10 to half-facepiece respirators, meaning they reduce contaminant concentration to 1/10 of the ambient level." },
  { id:"osha_437", categoria:"OSHA_RESPIRATORIA", pregunta:"En una atmósfera IDLH, ¿cuál es el respirador mínimo requerido por OSHA para ingresar al área?", opciones:["Respirador de cara completa con P100","Respirador de media cara con cartuchos","SCBA de presión positiva o SAR con escape","Respirador purificador con filtro HEPA"], respuesta_correcta:2, explicacion:"En atmósferas IDLH (Immediately Dangerous to Life or Health), OSHA requiere como mínimo un SCBA de presión positiva o un SAR (Supplied Air Respirator) con botella de escape auxiliar.", en_pregunta:"In an IDLH atmosphere, what is the minimum respirator required by OSHA to enter the area?", en_opciones:["Full-face respirator with P100","Half-face respirator with cartridges","Positive-pressure SCBA or SAR with escape bottle","Purifying respirator with HEPA filter"], en_explicacion:"In IDLH (Immediately Dangerous to Life or Health) atmospheres, OSHA requires at minimum a positive-pressure SCBA or a SAR (Supplied Air Respirator) with an auxiliary escape bottle." },
  { id:"osha_438", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué concentración de oxígeno define una atmósfera como deficiente de oxígeno según OSHA?", opciones:["Menos de 21.5% de oxígeno en el aire","Menos de 20.8% de oxígeno en el aire","Menos de 19.5% de oxígeno en el aire","Menos de 18.0% de oxígeno en el aire"], respuesta_correcta:2, explicacion:"OSHA define una atmósfera deficiente de oxígeno como aquella con menos de 19.5% de oxígeno. El nivel normal es 20.9% y por debajo de 19.5% se requiere suministro de aire.", en_pregunta:"What oxygen concentration defines an atmosphere as oxygen-deficient per OSHA?", en_opciones:["Less than 21.5% oxygen in the air","Less than 20.8% oxygen in the air","Less than 19.5% oxygen in the air","Less than 18.0% oxygen in the air"], en_explicacion:"OSHA defines an oxygen-deficient atmosphere as one with less than 19.5% oxygen. Normal level is 20.9%, and below 19.5% supplied air is required." },
  { id:"osha_439", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el propósito principal de la prueba de ajuste (fit test) cualitativa para respiradores?", opciones:["Medir la concentración de fuga numérica","Verificar el sello usando respuesta sensorial","Calcular el factor de protección del equipo","Determinar la vida útil del cartucho usado"], respuesta_correcta:1, explicacion:"La prueba cualitativa (QLFT) utiliza la respuesta sensorial del usuario (gusto, olor) a un agente de prueba como sacarina o Bitrex para verificar si hay fugas en el sello del respirador.", en_pregunta:"What is the main purpose of a qualitative fit test for respirators?", en_opciones:["Measure the numerical leakage concentration","Verify the seal using sensory response","Calculate the equipment's protection factor","Determine the used cartridge's service life"], en_explicacion:"The qualitative fit test (QLFT) uses the user's sensory response (taste, smell) to a test agent such as saccharin or Bitrex to check for leaks in the respirator's seal." },
  { id:"osha_440", categoria:"OSHA_RESPIRATORIA", pregunta:"Según OSHA, ¿con qué frecuencia mínima debe realizarse la prueba de ajuste (fit test) para respiradores?", opciones:["Cada 6 meses o al cambiar de modelo","Al menos una vez al año como mínimo","Cada 2 años si no hay cambios físicos","Solo al asignar el respirador por vez primera"], respuesta_correcta:1, explicacion:"29 CFR 1910.134 requiere que la prueba de ajuste se realice al menos una vez al año, y también cuando hay cambios en el tipo de respirador o en la condición física del empleado.", en_pregunta:"Per OSHA, what is the minimum frequency at which fit testing must be performed for respirators?", en_opciones:["Every 6 months or when the model changes","At least once a year as a minimum","Every 2 years if there are no physical changes","Only when the respirator is first assigned"], en_explicacion:"29 CFR 1910.134 requires fit testing to be performed at least once a year, and also when there are changes in the type of respirator or in the employee's physical condition." },
  { id:"osha_441", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué tipo de filtro NIOSH protege contra partículas aceitosas y no aceitosas simultáneamente?", opciones:["Serie N que filtra partículas no aceitosas","Serie R que resiste partículas con aceite","Serie P que es prueba contra todo aceite","Serie HE que filtra eficiencia muy alta"], respuesta_correcta:2, explicacion:"La Serie P (oil-Proof) está diseñada para filtrar tanto partículas aceitosas como no aceitosas sin degradación. La Serie N solo filtra no aceitosas y la Serie R resiste aceite pero con tiempo limitado.", en_pregunta:"Which NIOSH filter series protects against both oil and non-oil particulates simultaneously?", en_opciones:["N series, which filters non-oil particulates","R series, which resists oil particulates","P series, which is oil-proof against all oil","HE series, which filters at very high efficiency"], en_explicacion:"The P series (oil-Proof) is designed to filter both oil and non-oil particulates without degradation. The N series only filters non-oil particulates, and the R series resists oil but only for a limited time." },
  { id:"osha_442", categoria:"OSHA_RESPIRATORIA", pregunta:"Un técnico HVAC trabaja con refrigerante R-410A en un cuarto mecánico cerrado. ¿Cuál es el riesgo respiratorio principal?", opciones:["Toxicidad directa por inhalación del gas","Desplazamiento de oxígeno en lugar cerrado","Reacción alérgica al contacto con mucosas","Irritación severa de las vías superiores"], respuesta_correcta:1, explicacion:"El R-410A no es tóxico en concentraciones bajas, pero en un espacio cerrado puede desplazar el oxígeno creando una atmósfera deficiente de oxígeno, que es el riesgo principal para el técnico.", en_pregunta:"An HVAC technician is working with R-410A refrigerant in an enclosed mechanical room. What is the primary respiratory hazard?", en_opciones:["Direct toxicity from inhaling the gas","Oxygen displacement in the enclosed space","Allergic reaction from contact with mucous membranes","Severe irritation of the upper airways"], en_explicacion:"R-410A is not toxic at low concentrations, but in an enclosed space it can displace oxygen and create an oxygen-deficient atmosphere, which is the primary hazard to the technician." },
  { id:"osha_443", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el Factor de Protección Asignado (APF) de un SCBA de presión positiva según la tabla de OSHA?", opciones:["APF de 1,000 para uso en emergencias","APF de 5,000 para atmósferas tóxicas","APF de 10,000 según tabla de factores","APF de 50,000 para máxima protección"], respuesta_correcta:2, explicacion:"OSHA asigna un APF de 10,000 al SCBA (Self-Contained Breathing Apparatus) de presión positiva, el nivel más alto de protección asignado en la tabla de 29 CFR 1910.134.", en_pregunta:"What is the Assigned Protection Factor (APF) of a positive-pressure SCBA according to the OSHA table?", en_opciones:["APF of 1,000 for emergency use","APF of 5,000 for toxic atmospheres","APF of 10,000 per the factor table","APF of 50,000 for maximum protection"], en_explicacion:"OSHA assigns an APF of 10,000 to positive-pressure SCBA (Self-Contained Breathing Apparatus), the highest protection level in the 29 CFR 1910.134 table." },
  { id:"osha_444", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué elemento NO es requerido en un programa escrito de protección respiratoria según 29 CFR 1910.134?", opciones:["Procedimientos para selección del respirador","Evaluación médica previa del trabajador usado","Registro de horas totales de cada respirador","Procedimientos de limpieza y mantenimiento"], respuesta_correcta:2, explicacion:"29 CFR 1910.134 requiere selección, evaluación médica, fit testing, mantenimiento y entrenamiento, pero no exige un registro de horas totales acumuladas por cada respirador individual.", en_pregunta:"Which element is NOT required in a written respiratory protection program under 29 CFR 1910.134?", en_opciones:["Procedures for respirator selection","Prior medical evaluation of the worker","Record of total hours on each respirator","Cleaning and maintenance procedures"], en_explicacion:"29 CFR 1910.134 requires selection, medical evaluation, fit testing, maintenance, and training, but does not require a log of total accumulated hours for each individual respirator." },
  { id:"osha_445", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuándo puede un empleador permitir el uso voluntario de un respirador de filtro sin programa completo?", opciones:["Nunca, siempre se requiere programa completo","Solo si el empleado firma carta de renuncia","Cuando la exposición está bajo el PEL vigente","Solo con autorización médica del especialista"], respuesta_correcta:2, explicacion:"Cuando la exposición está bajo el PEL y el uso es voluntario con respiradores de filtro (no cartuchos químicos), el empleador solo debe proporcionar el Apéndice D y asegurar que el uso no cree peligro.", en_pregunta:"When may an employer permit voluntary use of a filtering respirator without a full written program?", en_opciones:["Never, a full program is always required","Only if the employee signs a waiver","When exposure is below the applicable PEL","Only with authorization from a specialist"], en_explicacion:"When exposure is below the PEL and use is voluntary with filtering facepiece respirators (not chemical cartridges), the employer need only provide Appendix D and ensure that use does not create a hazard." },
  { id:"osha_446", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es la diferencia principal entre una prueba de ajuste cuantitativa y una cualitativa?", opciones:["La cualitativa usa instrumentos de medición","La cuantitativa mide fugas numéricamente","La cualitativa requiere equipo especializado","La cuantitativa se basa en sabor y olfato"], respuesta_correcta:1, explicacion:"La prueba cuantitativa (QNFT) usa instrumentos que miden numéricamente la concentración dentro vs fuera del respirador, mientras que la cualitativa se basa en la respuesta sensorial del usuario.", en_pregunta:"What is the main difference between a quantitative and a qualitative fit test?", en_opciones:["The qualitative test uses measuring instruments","The quantitative test measures leakage numerically","The qualitative test requires specialized equipment","The quantitative test relies on taste and smell"], en_explicacion:"The quantitative fit test (QNFT) uses instruments that numerically measure the concentration inside versus outside the respirator, while the qualitative test relies on the user's sensory response." },
  { id:"osha_447", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué indica la designación '100' en un filtro P100 aprobado por NIOSH?", opciones:["Filtra el 100% de gases y vapores tóxicos","Tiene capacidad para 100 horas de trabajo","Filtra al menos 99.97% de las partículas","Resiste 100 mg de contaminante acumulado"], respuesta_correcta:2, explicacion:"La designación '100' indica que el filtro tiene una eficiencia mínima de 99.97% contra partículas de prueba de 0.3 micrones, el nivel más alto de filtración de partículas según NIOSH.", en_pregunta:"What does the designation '100' indicate on a NIOSH-approved P100 filter?", en_opciones:["It filters 100% of toxic gases and vapors","It has capacity for 100 hours of work","It filters at least 99.97% of particulates","It resists 100 mg of accumulated contaminant"], en_explicacion:"The '100' designation indicates that the filter has a minimum efficiency of 99.97% against 0.3-micron test particulates, the highest level of particulate filtration under NIOSH." },
  { id:"osha_448", categoria:"OSHA_RESPIRATORIA", pregunta:"Un técnico HVAC nota olor a solvente mientras usa un respirador con cartuchos orgánicos. ¿Qué debe hacer?", opciones:["Continuar trabajando si el olor es muy leve","Salir del área y reemplazar los cartuchos","Ajustar las correas para mejorar todo sello","Cambiar a filtros P100 de mayor protección"], respuesta_correcta:1, explicacion:"La detección de olor indica que los cartuchos están saturados (breakthrough). El técnico debe salir inmediatamente del área contaminada y reemplazar los cartuchos antes de continuar.", en_pregunta:"An HVAC technician notices a solvent odor while wearing a respirator with organic vapor cartridges. What should they do?", en_opciones:["Keep working if the odor is very faint","Exit the area and replace the cartridges","Tighten the straps to improve the seal","Switch to P100 filters for greater protection"], en_explicacion:"Detecting odor indicates the cartridges are saturated (breakthrough). The technician must immediately exit the contaminated area and replace the cartridges before continuing." },
  { id:"osha_449", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué tipo de respirador es apropiado para un técnico que suelda con soldadura de plata en HVAC?", opciones:["N95 desechable para polvos de soldadura","Media cara con cartuchos de vapor ácido","Media cara con filtros P100 para partículas","Respirador quirúrgico de grado estándar"], respuesta_correcta:2, explicacion:"La soldadura de plata (brazing) genera humos metálicos que son partículas. Un respirador de media cara con filtros P100 proporciona protección adecuada contra humos de soldadura cuando está bajo el APF.", en_pregunta:"Which respirator is appropriate for an HVAC technician silver-brazing in an HVAC system?", en_opciones:["Disposable N95 for brazing dust","Half-face with acid vapor cartridges","Half-face with P100 particulate filters","Standard-grade surgical respirator"], en_explicacion:"Silver brazing generates metal fumes that are particulates. A half-face respirator with P100 filters provides adequate protection against brazing fumes when exposure is within the APF." },
  { id:"osha_450", categoria:"OSHA_RESPIRATORIA", pregunta:"Según OSHA, ¿quién debe pagar el costo de los respiradores cuando su uso es obligatorio en el trabajo?", opciones:["El costo se divide entre ambas partes","El empleado paga su propio respirador","El empleador paga todos los respiradores","El sindicato cubre el gasto del equipo"], respuesta_correcta:2, explicacion:"Cuando el uso de respiradores es obligatorio, 29 CFR 1910.134 requiere que el empleador proporcione los respiradores sin costo para el empleado, incluyendo filtros y cartuchos de repuesto.", en_pregunta:"According to OSHA, who pays for respirators when their use is required on the job?", en_opciones:["The cost is split between both parties","The employee pays for their own respirator","The employer pays for all respirators","The union covers the equipment cost"], en_explicacion:"When respirator use is required, 29 CFR 1910.134 requires the employer to provide respirators at no cost to the employee, including replacement filters and cartridges." },
  { id:"osha_451", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el contenido principal del Apéndice D de 29 CFR 1910.134 sobre protección respiratoria?", opciones:["Tablas de factores de protección asignados","Protocolos detallados para pruebas de ajuste","Información para uso voluntario del equipo","Cuestionario de evaluación médica completo"], respuesta_correcta:2, explicacion:"El Apéndice D contiene información obligatoria que debe entregarse a empleados que usan respiradores voluntariamente, explicando los riesgos y precauciones del uso voluntario.", en_pregunta:"What is the main content of Appendix D of 29 CFR 1910.134 on respiratory protection?", en_opciones:["Tables of assigned protection factors","Detailed fit-testing protocols","Information for voluntary use of respirators","Complete medical evaluation questionnaire"], en_explicacion:"Appendix D contains mandatory information that must be provided to employees who wear respirators voluntarily, explaining the risks and precautions of voluntary use." },
  { id:"osha_452", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué condición facial impide obtener un sello adecuado en la prueba de ajuste del respirador?", opciones:["Tener la piel ligeramente bronceada por sol","Usar lentes de contacto para la corrección","Tener vello facial donde sella el respirador","Tener cicatrices antiguas lejos del sellado"], respuesta_correcta:2, explicacion:"El vello facial (barba, patillas) en el área donde el respirador sella contra la cara impide un ajuste hermético, lo que compromete la protección y causa fallo en la prueba de ajuste.", en_pregunta:"What facial condition prevents obtaining an adequate seal during a respirator fit test?", en_opciones:["Having slightly sun-tanned skin","Wearing contact lenses for vision correction","Having facial hair where the respirator seals","Having old scars far from the sealing surface"], en_explicacion:"Facial hair (beard, sideburns) in the area where the respirator seals against the face prevents an airtight fit, which compromises protection and causes a fit test failure." },
  { id:"osha_453", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es la concentración de oxígeno en la que una atmósfera se considera IDLH por deficiencia?", opciones:["Menos de 18.0% de oxígeno presente","Menos de 17.5% de oxígeno presente","Menos de 16.0% de oxígeno presente","Menos de 19.5% de oxígeno presente"], respuesta_correcta:2, explicacion:"Una atmósfera con menos de 16% de oxígeno se considera IDLH. Nota: deficiente de oxígeno empieza en 19.5%, pero el nivel IDLH es 16% donde hay peligro inmediato para la vida.", en_pregunta:"At what oxygen concentration is an atmosphere considered IDLH due to oxygen deficiency?", en_opciones:["Less than 18.0% oxygen","Less than 17.5% oxygen","Less than 16.0% oxygen","Less than 19.5% oxygen"], en_explicacion:"An atmosphere with less than 16% oxygen is considered IDLH. Note: oxygen-deficient begins at 19.5%, but the IDLH level is 16%, where there is immediate danger to life." },
  { id:"osha_454", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué tipo de respirador es un SAR (Supplied Air Respirator) y cómo funciona para el usuario?", opciones:["Purifica el aire ambiente con filtros químicos","Suministra aire limpio desde fuente externa","Genera oxígeno puro mediante reacción interna","Recircula el aire exhalado después de filtrarlo"], respuesta_correcta:1, explicacion:"Un SAR (Supplied Air Respirator) suministra aire respirable desde una fuente externa (compresor o cilindros) a través de una manguera, sin depender del aire ambiente contaminado.", en_pregunta:"What type of respirator is a SAR (Supplied Air Respirator) and how does it work for the user?", en_opciones:["It purifies ambient air with chemical filters","It supplies clean air from an external source","It generates pure oxygen via an internal reaction","It recirculates exhaled air after filtering it"], en_explicacion:"A SAR (Supplied Air Respirator) supplies breathable air from an external source (compressor or cylinders) through a hose, without relying on contaminated ambient air." },
  { id:"osha_455", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué factor determina principalmente cuándo se deben cambiar los cartuchos químicos de un respirador?", opciones:["La fecha de manufactura impresa en el equipo","El programa de cambio basado en la exposición","El color del cartucho cuando cambia a oscuro","La cantidad de polvo visible en la superficie"], respuesta_correcta:1, explicacion:"OSHA requiere un programa de cambio de cartuchos basado en datos objetivos: concentración del contaminante, tasa de respiración, humedad, temperatura y capacidad del cartucho según el fabricante.", en_pregunta:"What factor is the primary determinant of when chemical cartridges on a respirator must be changed?", en_opciones:["The manufacture date printed on the equipment","A change-out schedule based on exposure","The color of the cartridge when it darkens","The amount of visible dust on the surface"], en_explicacion:"OSHA requires a cartridge change-out schedule based on objective data: contaminant concentration, breathing rate, humidity, temperature, and manufacturer-rated cartridge capacity." },
  { id:"osha_456", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el Factor de Protección Asignado (APF) de un respirador de cara completa según OSHA?", opciones:["APF de 10 para cara completa tipo básico","APF de 25 para cara completa tipo básico","APF de 50 para cara completa tipo básico","APF de 100 para cara completa tipo básico"], respuesta_correcta:2, explicacion:"OSHA asigna un APF de 50 a los respiradores de cara completa (full-facepiece) con presión negativa, lo que significa que reducen la exposición a 1/50 de la concentración ambiental.", en_pregunta:"What is the Assigned Protection Factor (APF) of a full-facepiece respirator according to OSHA?", en_opciones:["APF of 10 for a basic full facepiece","APF of 25 for a basic full facepiece","APF of 50 for a basic full facepiece","APF of 100 for a basic full facepiece"], en_explicacion:"OSHA assigns an APF of 50 to negative-pressure full-facepiece respirators, meaning they reduce exposure to 1/50 of the ambient concentration." },
  { id:"osha_457", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué debe hacer un empleador ANTES de que un empleado use un respirador por primera vez en el trabajo?", opciones:["Solo entregar el respirador con instrucciones","Proveer evaluación médica al trabajador antes","Realizar únicamente la prueba de ajuste facial","Registrar al empleado en curso de primeros auxilios"], respuesta_correcta:1, explicacion:"29 CFR 1910.134 requiere que el empleador provea una evaluación médica ANTES de la prueba de ajuste y antes de que el empleado use el respirador en el lugar de trabajo.", en_pregunta:"What must an employer do BEFORE an employee first uses a respirator on the job?", en_opciones:["Simply issue the respirator with instructions","Provide a medical evaluation of the worker","Perform only the facial fit test","Enroll the employee in a first-aid course"], en_explicacion:"29 CFR 1910.134 requires the employer to provide a medical evaluation BEFORE fit testing and before the employee wears the respirator in the workplace." },
  { id:"osha_458", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué método de prueba de ajuste cualitativa usa una solución amarga que el usuario puede detectar?", opciones:["Prueba de sacarina con sabor muy dulce","Prueba con acetato de isoamilo y su olor","Prueba de Bitrex con sabor amargo fuerte","Prueba de humo irritante en concentración"], respuesta_correcta:2, explicacion:"La prueba de Bitrex (denatonium benzoate) usa una solución extremadamente amarga. Si el usuario detecta el sabor amargo dentro del respirador, indica que hay fugas en el sello.", en_pregunta:"Which qualitative fit-test method uses a bitter solution that the user can detect?", en_opciones:["Saccharin test with a very sweet taste","Isoamyl acetate test by its banana odor","Bitrex test with a strong bitter taste","Irritant smoke test at high concentration"], en_explicacion:"The Bitrex test (denatonium benzoate) uses an extremely bitter solution. If the user detects the bitter taste inside the respirator, it indicates leakage at the seal." },
  { id:"osha_459", categoria:"OSHA_RESPIRATORIA", pregunta:"¿En qué situación OSHA permite usar un respirador purificador de aire en vez de suministro de aire?", opciones:["Cuando la atmósfera tiene suficiente oxígeno","En cualquier espacio confinado sin ventilación","Cuando el contaminante no tiene olor detectable","En emergencias donde no hay otro equipo cerca"], respuesta_correcta:0, explicacion:"Los respiradores purificadores de aire (APR) solo pueden usarse cuando hay suficiente oxígeno (>19.5%) y la concentración del contaminante está dentro del rango del APF del respirador.", en_pregunta:"In what situation does OSHA allow the use of an air-purifying respirator instead of supplied air?", en_opciones:["When the atmosphere has sufficient oxygen","In any confined space without ventilation","When the contaminant has no detectable odor","In emergencies when no other equipment is nearby"], en_explicacion:"Air-purifying respirators (APRs) may only be used when there is sufficient oxygen (>19.5%) and the contaminant concentration is within the respirator's APF range." },
  { id:"osha_460", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el procedimiento correcto para verificar el sello negativo de un respirador antes de entrar al área?", opciones:["Soplar fuerte y verificar que el aire no sale","Cubrir filtros, inhalar y sentir succión facial","Mover la cabeza de lado a lado rápidamente","Rociar agente de prueba alrededor del equipo"], respuesta_correcta:1, explicacion:"La verificación de sello negativo consiste en cubrir los filtros/cartuchos con las palmas, inhalar suavemente y verificar que la pieza facial se colapsa hacia la cara sin detectar fugas.", en_pregunta:"What is the correct procedure to perform a negative-pressure seal check before entering the work area?", en_opciones:["Exhale forcefully and check that no air escapes","Cover the filters, inhale, and feel the facepiece pull in","Move the head rapidly from side to side","Spray a test agent around the equipment"], en_explicacion:"The negative-pressure seal check involves covering the filters/cartridges with the palms, inhaling gently, and verifying that the facepiece collapses toward the face with no detectable leaks." },
  { id:"osha_461", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuánto tiempo mínimo de aire debe proveer un SCBA para operaciones de entrada en atmósferas IDLH?", opciones:["Al menos 15 minutos de aire como respaldo","Al menos 30 minutos de aire como mínimo","Al menos 45 minutos de aire de suministro","Al menos 60 minutos de aire de suministro"], respuesta_correcta:1, explicacion:"OSHA requiere que un SCBA usado para entrada en atmósferas IDLH tenga al menos 30 minutos de suministro de aire. Los SCBA de 15 minutos son solo para escape, no para entrada.", en_pregunta:"What is the minimum air supply duration required on an SCBA for entry operations into IDLH atmospheres?", en_opciones:["At least 15 minutes of air as backup","At least 30 minutes of air minimum","At least 45 minutes of supplied air","At least 60 minutes of supplied air"], en_explicacion:"OSHA requires an SCBA used for entry into IDLH atmospheres to have at least 30 minutes of air supply. 15-minute SCBAs are for escape only, not for entry." },
  { id:"osha_462", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué información debe incluir el cuestionario médico del Apéndice C de 29 CFR 1910.134?", opciones:["Solo historial de alergias y medicamentos","Historial médico completo y condición actual","Únicamente resultados de espirometría previa","Solo la presión arterial y frecuencia cardíaca"], respuesta_correcta:1, explicacion:"El Apéndice C requiere un cuestionario completo que incluye historial médico, condiciones respiratorias, cardiovasculares, uso previo de respiradores y cualquier condición que afecte su uso.", en_pregunta:"What information must the medical questionnaire in Appendix C of 29 CFR 1910.134 include?", en_opciones:["Only allergy history and medications","Complete medical history and current condition","Only previous spirometry results","Only blood pressure and heart rate"], en_explicacion:"Appendix C requires a comprehensive questionnaire that includes medical history, respiratory and cardiovascular conditions, prior respirator use, and any condition that could affect respirator use." },
  { id:"osha_463", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué color de cartucho indica protección contra vapores orgánicos según el código NIOSH?", opciones:["Cartucho de color amarillo brillante estándar","Cartucho de color negro con franja visible","Cartucho de color blanco con marca lateral","Cartucho de color verde para vapores varios"], respuesta_correcta:1, explicacion:"Según el sistema de código de colores NIOSH, el negro identifica cartuchos para vapores orgánicos. Amarillo es para gases ácidos, verde para amoníaco y blanco para gases ácidos.", en_pregunta:"What cartridge color indicates protection against organic vapors under the NIOSH color code?", en_opciones:["Bright yellow cartridge (standard)","Black cartridge with a visible stripe","White cartridge with a side marking","Green cartridge for various vapors"], en_explicacion:"Under the NIOSH color-coding system, black identifies cartridges for organic vapors. Yellow is for acid gases, green is for ammonia, and white is for acid gases." },
  { id:"osha_464", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué debe hacer el empleador si un médico determina que un empleado no puede usar respiradores?", opciones:["Despedir al empleado de forma inmediata hoy","Reasignar al empleado a área sin respirador","Obligar al empleado a usar otro tipo de equipo","Reducir las horas de exposición a la mitad"], respuesta_correcta:1, explicacion:"Si un empleado no puede usar respiradores por razones médicas, el empleador debe reasignarlo a una posición donde no se requiera protección respiratoria, sin represalias ni reducción de salario.", en_pregunta:"What must an employer do if a physician determines that an employee cannot wear a respirator?", en_opciones:["Terminate the employee immediately","Reassign the employee to a non-respirator area","Require the employee to use different equipment","Reduce exposure hours by half"], en_explicacion:"If an employee cannot wear a respirator for medical reasons, the employer must reassign them to a position where respiratory protection is not required, without retaliation or pay reduction." },
  { id:"osha_465", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Con qué frecuencia deben limpiarse los respiradores de uso personal según las normas de OSHA?", opciones:["Semanalmente o cuando se note suciedad","Después de cada uso diario como mínimo","Mensualmente según calendario del programa","Cada 40 horas acumuladas de uso continuo"], respuesta_correcta:1, explicacion:"Los respiradores de uso personal deben limpiarse y desinfectarse después de cada uso. Los de uso compartido deben limpiarse después de cada usuario para prevenir contaminación cruzada.", en_pregunta:"How often must respirators for personal use be cleaned under OSHA rules?", en_opciones:["Weekly or whenever visibly dirty","After each day of use, at minimum","Monthly, per the program schedule","Every 40 accumulated hours of use"], en_explicacion:"Personal-use respirators must be cleaned and disinfected after each use. Shared respirators must be cleaned after each user to prevent cross-contamination." },
  { id:"osha_466", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué significa que un respirador opera en modo de 'presión negativa' durante la inhalación?", opciones:["La presión dentro es mayor que la del ambiente","La presión dentro es menor que la del ambiente","El respirador genera vacío con bomba eléctrica","El filtro comprime el aire antes de la entrada"], respuesta_correcta:1, explicacion:"En modo presión negativa, al inhalar se crea una presión menor dentro de la pieza facial que la presión atmosférica exterior, lo que podría permitir entrada de contaminantes si hay fugas.", en_pregunta:"What does it mean that a respirator operates in 'negative pressure' mode during inhalation?", en_opciones:["The pressure inside is greater than ambient","The pressure inside is lower than ambient","The respirator creates vacuum with an electric pump","The filter compresses air before entry"], en_explicacion:"In negative-pressure mode, inhalation creates a pressure inside the facepiece lower than outside atmospheric pressure, which could allow contaminants to enter if there is any leakage." },
  { id:"osha_467", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es la ventaja principal de un respirador de presión positiva sobre uno de presión negativa?", opciones:["Es más liviano y más cómodo para el usuario","Mantiene presión interna mayor evitando fugas","Tiene filtros más grandes con mayor capacidad","Permite vello facial sin afectar la protección"], respuesta_correcta:1, explicacion:"Los respiradores de presión positiva mantienen una presión mayor dentro de la pieza facial que la exterior, de modo que si hay alguna fuga, el aire sale en vez de que entre contaminante.", en_pregunta:"What is the main advantage of a positive-pressure respirator over a negative-pressure respirator?", en_opciones:["It is lighter and more comfortable for the user","It maintains higher internal pressure, preventing leaks","It has larger filters with greater capacity","It allows facial hair without affecting protection"], en_explicacion:"Positive-pressure respirators maintain a pressure inside the facepiece higher than outside, so if any leak exists, air flows outward rather than contaminants flowing inward." },
  { id:"osha_468", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué indica la eficiencia del 95% en un filtro N95 aprobado por NIOSH para partículas?", opciones:["Filtra 95% de partículas mayores a 1 micrón","Filtra 95% de partículas de prueba de 0.3 μm","Filtra 95% de gases y vapores simultáneos","Dura 95 horas antes de requerir un reemplazo"], respuesta_correcta:1, explicacion:"N95 filtra al menos el 95% de partículas de prueba de 0.3 micrones de diámetro (el tamaño más penetrante). No protege contra gases ni vapores.", en_pregunta:"What does the 95% efficiency rating indicate on a NIOSH-approved N95 particulate filter?", en_opciones:["Filters 95% of particulates larger than 1 micron","Filters 95% of 0.3 μm test particulates","Filters 95% of gases and vapors","Lasts 95 hours before needing replacement"], en_explicacion:"N95 filters at least 95% of 0.3-micron test particulates (the most-penetrating particle size). It does not protect against gases or vapors." },
  { id:"osha_469", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué acción está PROHIBIDA al almacenar respiradores según las normas de protección respiratoria?", opciones:["Guardarlos en bolsas selladas y muy limpias","Colocarlos donde se deforme la pieza facial","Almacenarlos en casilleros personales secos","Mantenerlos separados de otros equipos de PPE"], respuesta_correcta:1, explicacion:"Los respiradores no deben almacenarse de forma que se deforme la pieza facial o las válvulas, ya que esto compromete el sello y la protección. Deben guardarse protegidos contra deformación.", en_pregunta:"What action is PROHIBITED when storing respirators under respiratory protection rules?", en_opciones:["Storing them in sealed, clean bags","Placing them where the facepiece becomes deformed","Storing them in dry personal lockers","Keeping them separate from other PPE"], en_explicacion:"Respirators must not be stored in a way that deforms the facepiece or valves, as this compromises the seal and protection. They must be stored protected from deformation." },
  { id:"osha_470", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué requisito aplica cuando múltiples empleados comparten el mismo respirador en turnos?", opciones:["Solo necesitan firmar un registro de entrega","Debe limpiarse y desinfectarse entre usuarios","Basta con cambiar los filtros entre cada turno","Solo se requiere inspección visual del estado"], respuesta_correcta:1, explicacion:"Cuando los respiradores son compartidos, OSHA requiere que se limpien y desinfecten completamente entre cada usuario para prevenir transmisión de enfermedades y contaminación cruzada.", en_pregunta:"What requirement applies when multiple employees share the same respirator across shifts?", en_opciones:["They only need to sign an issuance log","It must be cleaned and disinfected between users","It is enough to change filters between shifts","Only a visual inspection is required"], en_explicacion:"When respirators are shared, OSHA requires that they be thoroughly cleaned and disinfected between each user to prevent disease transmission and cross-contamination." },
  { id:"osha_471", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Cuál es el primer paso del entrenamiento obligatorio que OSHA requiere para usuarios de respiradores?", opciones:["Practicar el ajuste correcto del respirador","Explicar por qué se necesita el respirador hoy","Demostrar cómo cambiar filtros y cartuchos","Realizar la prueba de ajuste cuantitativa ya"], respuesta_correcta:1, explicacion:"El entrenamiento debe comenzar explicando por qué es necesario el respirador, los peligros presentes y las consecuencias de uso incorrecto, antes de pasar a aspectos prácticos del equipo.", en_pregunta:"What is the first mandatory OSHA training step for respirator users?", en_opciones:["Practice proper respirator fitting","Explain why the respirator is needed","Demonstrate how to change filters and cartridges","Perform the quantitative fit test immediately"], en_explicacion:"Training must begin by explaining why the respirator is necessary, the hazards present, and the consequences of improper use, before moving on to practical aspects of the equipment." },
  { id:"osha_472", categoria:"OSHA_RESPIRATORIA", pregunta:"Un técnico HVAC recupera refrigerante en un cuarto sin ventilación. ¿Qué tipo de monitoreo es prioritario?", opciones:["Monitor de partículas suspendidas en el aire","Monitor de nivel de oxígeno en la atmósfera","Monitor de compuestos orgánicos tipo volátil","Monitor de temperatura y humedad del espacio"], respuesta_correcta:1, explicacion:"Al recuperar refrigerante en espacios cerrados, la prioridad es monitorear el nivel de oxígeno ya que los refrigerantes desplazan el oxígeno y pueden crear una atmósfera deficiente sin previo aviso.", en_pregunta:"An HVAC technician is recovering refrigerant in an unventilated room. Which monitoring is the priority?", en_opciones:["Airborne particulate monitor","Oxygen level monitor in the atmosphere","Volatile organic compound monitor","Temperature and humidity monitor"], en_explicacion:"When recovering refrigerant in enclosed spaces, the priority is oxygen monitoring because refrigerants displace oxygen and can create an oxygen-deficient atmosphere without warning." },
  { id:"osha_473", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué parte del respirador debe inspeccionarse PRIMERO antes de cada uso según el procedimiento estándar?", opciones:["Los cartuchos para verificar fecha y estado","La pieza facial buscando grietas o desgaste","Las correas para confirmar buena elasticidad","Las válvulas de exhalación buscando residuos"], respuesta_correcta:1, explicacion:"La inspección pre-uso comienza con la pieza facial, verificando que no tenga grietas, rasgaduras, deformación o deterioro que comprometa el sello, ya que es el componente más crítico.", en_pregunta:"Which part of the respirator should be inspected FIRST before each use per standard procedure?", en_opciones:["The cartridges, to verify date and condition","The facepiece, for cracks or wear","The straps, to confirm elasticity","The exhalation valves, for residue"], en_explicacion:"The pre-use inspection begins with the facepiece, checking for cracks, tears, deformation, or deterioration that could compromise the seal, as it is the most critical component." },
  { id:"osha_474", categoria:"OSHA_RESPIRATORIA", pregunta:"¿Qué situación requiere que el empleador actualice inmediatamente el programa de protección respiratoria?", opciones:["Cuando un empleado solicita respirador nuevo","Cuando cambian los contaminantes en el sitio","Cuando se acerca la fecha de auditoría anual","Cuando el proveedor ofrece un modelo diferente"], respuesta_correcta:1, explicacion:"El programa debe actualizarse inmediatamente cuando cambian las condiciones del lugar de trabajo, como nuevos contaminantes, procesos o niveles de exposición que afecten la selección del respirador.", en_pregunta:"What situation requires the employer to immediately update the respiratory protection program?", en_opciones:["When an employee requests a new respirator","When contaminants at the site change","When the annual audit is approaching","When the vendor offers a different model"], en_explicacion:"The program must be updated immediately when workplace conditions change, such as new contaminants, processes, or exposure levels that affect respirator selection." },

  { id:"osha_475", categoria:"OSHA_HERRAMIENTAS", pregunta:"Según OSHA 29 CFR 1926.300, ¿cuándo debe un empleado inspeccionar las herramientas manuales antes de usarlas?", opciones:["Una vez al mes durante la reunión de seguridad del equipo de trabajo","Antes de cada uso para verificar que estén en condiciones seguras de operación","Solamente cuando el supervisor de seguridad lo solicite por escrito al técnico","Después de cada uso para documentar el desgaste en el registro de herramientas"], respuesta_correcta:1, explicacion:"OSHA requiere que las herramientas se inspeccionen antes de cada uso. Las herramientas dañadas o defectuosas deben retirarse de servicio inmediatamente.", en_pregunta:"Under OSHA 29 CFR 1926.300, when must an employee inspect hand tools before using them?", en_opciones:["Once a month during the crew's safety meeting","Before each use, to verify they are in safe operating condition","Only when the safety supervisor requests it in writing","After each use, to document wear in the tool log"], en_explicacion:"OSHA requires that tools be inspected before each use. Damaged or defective tools must be removed from service immediately." },
  { id:"osha_476", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué requisito establece OSHA para las guardas de seguridad en herramientas eléctricas portátiles con partes rotativas expuestas?", opciones:["Deben pintarse de color rojo brillante para ser fácilmente visibles al operador","Deben cubrir las partes rotativas y no pueden ser removidas por el operador","Pueden retirarse si el operador tiene más de cinco años de experiencia laboral","Son opcionales si el técnico usa guantes de cuero de alta resistencia al corte"], respuesta_correcta:1, explicacion:"29 CFR 1926.300(b)(1) exige que las guardas cubran partes expuestas de correas, engranajes, ejes y partes rotativas. Nunca deben removerse durante la operación.", en_pregunta:"What requirement does OSHA set for safety guards on portable power tools with exposed rotating parts?", en_opciones:["They must be painted bright red for easy visibility to the operator","They must cover the rotating parts and cannot be removed by the operator","They may be removed if the operator has more than five years of experience","They are optional if the technician wears high cut-resistance leather gloves"], en_explicacion:"29 CFR 1926.300(b)(1) requires guards to cover exposed belts, gears, shafts, and rotating parts. They must never be removed during operation." },
  { id:"osha_477", categoria:"OSHA_HERRAMIENTAS", pregunta:"Una herramienta eléctrica portátil con el símbolo de doble cuadrado (cuadrado dentro de otro) indica que es:", opciones:["Resistente al agua y apta para uso en ambientes húmedos o bajo lluvia ligera","De doble aislamiento y no requiere una tercera terminal de conexión a tierra","De uso exclusivo en interiores y no apta para trabajos a la intemperie húmeda","De alta potencia y requiere un circuito dedicado de 20 amperios como mínimo"], respuesta_correcta:1, explicacion:"El símbolo de doble cuadrado indica doble aislamiento (Clase II). Estas herramientas no necesitan terminal de tierra porque tienen dos capas independientes de aislamiento eléctrico.", en_pregunta:"A portable power tool marked with the double-square symbol (a square within a square) indicates that it is:", en_opciones:["Water-resistant and suitable for use in humid environments or light rain","Double-insulated and does not require a third grounding terminal","For indoor use only and not suitable for outdoor work in humid conditions","High-power and requires a dedicated 20-amp circuit minimum"], en_explicacion:"The double-square symbol indicates double insulation (Class II). These tools do not need a grounding terminal because they have two independent layers of electrical insulation." },
  { id:"osha_478", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es el requisito de OSHA para herramientas eléctricas portátiles que NO son de doble aislamiento en sitios de construcción?", opciones:["Deben estar conectadas a un circuito protegido con GFCI o programa de cable asegurado","Solo necesitan un fusible de capacidad adecuada instalado en el panel de distribución","Requieren únicamente una extensión de calibre grueso sin necesidad de tierra adicional","Basta con que el operador use guantes aislantes de goma clase 00 durante todo el uso"], respuesta_correcta:0, explicacion:"29 CFR 1926.404(b)(1) requiere que todas las herramientas con conexión a tierra usen protección GFCI o un programa de cable asegurado (Assured Equipment Grounding Conductor Program).", en_pregunta:"What is OSHA's requirement for portable power tools that are NOT double-insulated on construction sites?", en_opciones:["They must be connected to a GFCI-protected circuit or an assured equipment grounding conductor program","They only need a fuse of adequate capacity installed in the distribution panel","They only require a heavy-gauge extension cord without any additional ground","It is enough for the operator to wear Class 00 rubber insulating gloves while using them"], en_explicacion:"29 CFR 1926.404(b)(1) requires all grounded tools to use GFCI protection or an Assured Equipment Grounding Conductor Program." },
  { id:"osha_479", categoria:"OSHA_HERRAMIENTAS", pregunta:"Un técnico HVAC encuentra una herramienta eléctrica cuyo cable tiene el tercer conductor (tierra) cortado. ¿Qué debe hacer?", opciones:["Usarla con cuidado conectándola a un GFCI como medida de protección alternativa","Reemplazar el enchufe él mismo con uno nuevo de tres terminales del almacén","Retirarla inmediatamente de servicio y etiquetarla como defectuosa para reparación","Conectarla a una extensión con tierra para compensar la falta del conductor propio"], respuesta_correcta:2, explicacion:"Una herramienta sin conductor de tierra funcional es una violación seria. Debe retirarse de servicio inmediatamente, etiquetarse y enviarse a reparación por personal calificado.", en_pregunta:"An HVAC technician finds a power tool with the third conductor (ground) cut off the cord. What should they do?", en_opciones:["Use it carefully by plugging it into a GFCI as alternate protection","Replace the plug themselves with a new three-prong plug from stock","Immediately remove it from service and tag it as defective for repair","Connect it to a grounded extension cord to compensate for the missing conductor"], en_explicacion:"A tool without a functional ground conductor is a serious violation. It must be immediately removed from service, tagged, and sent to qualified personnel for repair." },
  { id:"osha_480", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué tipo de interruptor requiere OSHA en herramientas eléctricas manuales como taladros y sierras circulares portátiles?", opciones:["Un interruptor de palanca con posición fija que mantenga encendida la herramienta","Un interruptor de presión constante o de bloqueo según el tipo de herramienta usada","Un interruptor de pie para que el operador tenga ambas manos libres sobre la pieza","Un interruptor remoto inalámbrico que permita apagar desde una distancia de seguridad"], respuesta_correcta:1, explicacion:"OSHA 1926.300(d) requiere interruptores de presión constante (constant-pressure) en herramientas como sierras circulares. Los taladros pueden tener interruptor de bloqueo (lock-on) con liberación de un solo movimiento.", en_pregunta:"What type of switch does OSHA require on hand-held power tools such as drills and portable circular saws?", en_opciones:["A toggle switch with a fixed position that keeps the tool powered on","A constant-pressure or lock-on switch, depending on the tool type","A foot switch so the operator keeps both hands on the workpiece","A wireless remote switch that allows shutoff from a safe distance"], en_explicacion:"OSHA 1926.300(d) requires constant-pressure switches on tools such as circular saws. Drills may have a lock-on switch with single-motion release." },
  { id:"osha_481", categoria:"OSHA_HERRAMIENTAS", pregunta:"Según OSHA, ¿cuál es el riesgo principal de usar un cincel de impacto cuya cabeza tiene forma de hongo (mushroomed)?", opciones:["El cincel pierde capacidad de corte y el trabajo se vuelve más lento e ineficiente","Fragmentos de metal pueden desprenderse como proyectiles al golpear con el martillo","El mango absorbe más vibración y causa síndrome del túnel carpiano a largo plazo","La forma de hongo impide que el martillo haga contacto centrado con la herramienta"], respuesta_correcta:1, explicacion:"La cabeza mushroomed tiene bordes de metal fatigado que se fragmentan violentamente bajo impacto, convirtiéndose en proyectiles que causan lesiones oculares y faciales graves.", en_pregunta:"According to OSHA, what is the primary hazard of using an impact chisel whose head is mushroomed?", en_opciones:["The chisel loses cutting capability and the work becomes slower and less efficient","Metal fragments may break off as projectiles when struck with the hammer","The handle absorbs more vibration and causes carpal tunnel syndrome over time","The mushroomed shape prevents the hammer from making centered contact with the tool"], en_explicacion:"A mushroomed head has edges of fatigued metal that fragment violently under impact, becoming projectiles that can cause serious eye and face injuries." },
  { id:"osha_482", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué exige OSHA sobre las herramientas actuadas por pólvora (powder-actuated tools) en sitios de construcción?", opciones:["Cualquier trabajador puede operarlas si lee las instrucciones del fabricante primero","Solo operadores entrenados y con certificación vigente pueden usar estas herramientas","Solo electricistas con licencia estatal pueden disparar clavos en estructuras de acero","El supervisor de seguridad debe estar presente físicamente durante cada disparo realizado"], respuesta_correcta:1, explicacion:"29 CFR 1926.302(e) requiere que solo operadores entrenados y certificados operen herramientas actuadas por pólvora. Deben portar su tarjeta de certificación en el sitio de trabajo.", en_pregunta:"What does OSHA require for powder-actuated tools on construction sites?", en_opciones:["Any worker may operate them after first reading the manufacturer's instructions","Only trained, currently certified operators may use these tools","Only state-licensed electricians may shoot fasteners into steel structures","The safety supervisor must be physically present for every shot fired"], en_explicacion:"29 CFR 1926.302(e) requires that only trained, certified operators use powder-actuated tools. They must carry their certification card on the job site." },
  { id:"osha_483", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué protección personal mínima exige OSHA al operar una herramienta actuada por pólvora (powder-actuated tool)?", opciones:["Guantes de cuero, protección auditiva y casco con careta facial de policarbonato","Protección ocular adecuada como requisito mínimo obligatorio durante cada disparo","Respirador N95, guantes de nitrilo y protección auditiva de inserción tipo tapón","Traje completo de protección contra fragmentos con chaleco balístico nivel IIIA"], respuesta_correcta:1, explicacion:"29 CFR 1926.302(e)(1) exige como mínimo protección ocular adecuada. Dependiendo de las condiciones, se puede requerir protección auditiva y facial adicional.", en_pregunta:"What minimum personal protection does OSHA require when operating a powder-actuated tool?", en_opciones:["Leather gloves, hearing protection, and a hard hat with a polycarbonate face shield","Adequate eye protection, as the minimum mandatory requirement during each shot","N95 respirator, nitrile gloves, and insert-type hearing protection","Full fragment-protection suit with a Level IIIA ballistic vest"], en_explicacion:"29 CFR 1926.302(e)(1) requires adequate eye protection as a minimum. Depending on conditions, additional hearing and face protection may be required." },
  { id:"osha_484", categoria:"OSHA_HERRAMIENTAS", pregunta:"Una herramienta actuada por pólvora de 'tiro bajo' (low-velocity) se diferencia de una de 'tiro alto' porque:", opciones:["El cartucho de pólvora contiene menos pólvora y genera menos retroceso al disparar","El sujetador nunca sale libre del cañón ya que es atrapado por un pistón cautivo","Utiliza clavos de acero inoxidable en lugar de clavos de acero al carbono común","Puede dispararse con una sola mano sin necesidad de presionar contra la superficie"], respuesta_correcta:1, explicacion:"En herramientas de tiro bajo (low-velocity), un pistón cautivo impulsa el sujetador pero no sale del cañón, eliminando el riesgo de que el clavo atraviese el material y se convierta en proyectil.", en_pregunta:"A low-velocity powder-actuated tool differs from a high-velocity tool because:", en_opciones:["The powder load has less powder and produces less recoil when fired","The fastener never leaves the barrel because it is captured by a captive piston","It uses stainless-steel fasteners instead of common carbon-steel nails","It can be fired with one hand without having to press against the surface"], en_explicacion:"In low-velocity tools, a captive piston drives the fastener but does not leave the barrel, eliminating the risk that the fastener passes through the material and becomes a projectile." },
  { id:"osha_485", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué prueba debe realizarse antes de usar una herramienta actuada por pólvora al inicio de cada jornada de trabajo?", opciones:["Una prueba de disparo contra una superficie de concreto para verificar la penetración","Una prueba de disparo al aire libre en zona despejada para comprobar el funcionamiento","Una prueba de funcionamiento siguiendo las instrucciones del fabricante de la herramienta","Una prueba de presión del cartucho con un manómetro calibrado de alta precisión portátil"], respuesta_correcta:2, explicacion:"29 CFR 1926.302(e)(2) requiere que el operador pruebe la herramienta cada día antes de cargarla, siguiendo las instrucciones del fabricante para verificar que todos los mecanismos de seguridad funcionen.", en_pregunta:"What test must be performed before using a powder-actuated tool at the start of each workday?", en_opciones:["A test shot into a concrete surface to verify penetration","A test shot outdoors in a clear area to check that it functions","A functional test following the tool manufacturer's instructions","A pressure test of the cartridge with a calibrated portable high-precision gauge"], en_explicacion:"29 CFR 1926.302(e)(2) requires the operator to test the tool each day before loading it, following the manufacturer's instructions to verify that all safety mechanisms work." },
  { id:"osha_486", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿A qué distancia mínima debe mantenerse el personal no involucrado cuando se usa una herramienta actuada por pólvora?", opciones:["Al menos 5 pies de distancia del punto de disparo marcado con cinta amarilla","No existe una distancia fija, pero el área debe estar despejada y ser segura según OSHA","Al menos 25 pies de distancia con barrera física de protección contra fragmentos sólidos","Al menos 50 pies de distancia con señalización visible desde todos los accesos del área"], respuesta_correcta:1, explicacion:"OSHA no establece una distancia fija específica, pero requiere que el área de trabajo esté despejada y que se tomen precauciones para proteger a todo el personal cercano de rebotes y fragmentos.", en_pregunta:"What minimum distance must uninvolved personnel be kept when a powder-actuated tool is in use?", en_opciones:["At least 5 feet from the firing point, marked with yellow tape","There is no fixed distance, but the area must be clear and safe per OSHA","At least 25 feet with a physical barrier against fragments","At least 50 feet with signage visible from all access points"], en_explicacion:"OSHA does not set a specific fixed distance, but requires the work area to be clear and that precautions be taken to protect nearby personnel from ricochets and fragments." },
  { id:"osha_487", categoria:"OSHA_HERRAMIENTAS", pregunta:"Al usar una esmeriladora angular (grinder), ¿cuál es el requisito de OSHA respecto a la guarda protectora del disco?", opciones:["La guarda debe cubrir al menos la mitad superior del disco abrasivo en todo momento","Se puede remover si el disco tiene menos de cuatro pulgadas de diámetro total","La guarda es opcional si el técnico usa careta facial completa de policarbonato","Solo se requiere guarda cuando se usa un disco de corte, no con disco de desbaste"], respuesta_correcta:0, explicacion:"29 CFR 1926.303(c) requiere que la guarda cubra el disco expuesto. La guarda protege contra fragmentos si el disco se rompe a alta velocidad rotacional (hasta 12,000 RPM).", en_pregunta:"When using an angle grinder, what is OSHA's requirement regarding the wheel guard?", en_opciones:["The guard must cover at least the upper half of the abrasive wheel at all times","It may be removed if the wheel is under four inches in diameter","The guard is optional if the technician wears a full polycarbonate face shield","A guard is only required with a cutoff wheel, not with a grinding wheel"], en_explicacion:"29 CFR 1926.303(c) requires the guard to cover the exposed wheel. The guard protects against fragments if the wheel shatters at high rotational speed (up to 12,000 RPM)." },
  { id:"osha_488", categoria:"OSHA_HERRAMIENTAS", pregunta:"Antes de montar un disco abrasivo nuevo en una esmeriladora, ¿qué inspección exige OSHA como obligatoria?", opciones:["Medir el diámetro exacto con un calibrador para confirmar compatibilidad con la guarda","Realizar una prueba de sonido (ring test) golpeando suavemente el disco con herramienta","Verificar que la fecha de fabricación del disco no exceda los seis meses de antigüedad","Pesar el disco en una báscula de precisión para descartar defectos internos ocultos"], respuesta_correcta:1, explicacion:"29 CFR 1926.303(c)(7) requiere el ring test: golpear suavemente el disco con un objeto no metálico. Un sonido claro indica integridad; un sonido apagado indica grietas internas y el disco debe descartarse.", en_pregunta:"Before mounting a new abrasive wheel on a grinder, what inspection does OSHA require as mandatory?", en_opciones:["Measure the exact diameter with a caliper to confirm compatibility with the guard","Perform a ring test by tapping the wheel lightly with a non-metallic tool","Verify the wheel's manufacture date does not exceed six months","Weigh the wheel on a precision scale to rule out hidden internal defects"], en_explicacion:"29 CFR 1926.303(c)(7) requires the ring test: tapping the wheel gently with a non-metallic object. A clear tone indicates integrity; a dull tone indicates internal cracks and the wheel must be discarded." },
  { id:"osha_489", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuánto tiempo debe funcionar una esmeriladora de banco en vacío después de montar un disco abrasivo nuevo según OSHA?", opciones:["15 segundos para verificar que no haya vibración excesiva durante el arranque","Al menos un minuto a velocidad máxima para asegurar que el disco esté bien montado","30 segundos con el técnico parado detrás de la guarda lateral de protección total","Cinco minutos a media velocidad aumentando gradualmente hasta la velocidad nominal"], respuesta_correcta:1, explicacion:"29 CFR 1926.303(c)(8) requiere que la esmeriladora funcione al menos un minuto en vacío (sin carga) después de montar un disco nuevo, para verificar que no tenga defectos que causen ruptura.", en_pregunta:"How long must a bench grinder run unloaded after mounting a new abrasive wheel, per OSHA?", en_opciones:["15 seconds to verify there is no excessive vibration during startup","At least one minute at full speed to ensure the wheel is properly mounted","30 seconds with the technician standing behind a full side guard","Five minutes at half speed, ramping up to full rated speed"], en_explicacion:"29 CFR 1926.303(c)(8) requires the grinder to run unloaded for at least one minute after mounting a new wheel to verify it has no defects that could cause it to shatter." },
  { id:"osha_490", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es la holgura máxima permitida entre el apoyo de trabajo (tool rest) y el disco abrasivo en una esmeriladora de banco?", opciones:["Un cuarto de pulgada para evitar que la pieza se atasque entre el disco y el apoyo","Un octavo de pulgada o menos para prevenir que la pieza sea atrapada y lanzada","Media pulgada para permitir espacio de maniobra adecuado al técnico que opera","Una pulgada completa medida desde el borde del apoyo hasta la cara del disco giratorio"], respuesta_correcta:1, explicacion:"29 CFR 1926.303(c)(5) establece que el apoyo de trabajo no debe estar a más de 1/8 de pulgada del disco. Mayor holgura permite que piezas pequeñas se atoren y sean lanzadas violentamente.", en_pregunta:"What is the maximum clearance allowed between the tool rest and the abrasive wheel on a bench grinder?", en_opciones:["One-quarter inch, to keep the workpiece from jamming between wheel and rest","One-eighth inch or less, to prevent the workpiece from being caught and thrown","One-half inch, to give the operating technician adequate maneuvering space","One full inch, measured from the edge of the rest to the face of the spinning wheel"], en_explicacion:"29 CFR 1926.303(c)(5) states the tool rest must be no more than 1/8 inch from the wheel. Greater clearance allows small workpieces to jam and be thrown violently." },
  { id:"osha_491", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué sucede si se monta un disco abrasivo cuya velocidad máxima nominal (RPM) es menor que la velocidad de la esmeriladora?", opciones:["El disco gira más eficientemente y corta materiales más duros sin esfuerzo adicional","El disco puede desintegrarse por la fuerza centrífuga lanzando fragmentos como metralla","La esmeriladora reduce automáticamente sus RPM para igualar la capacidad del disco montado","El motor de la esmeriladora se sobrecalienta y se activa la protección térmica interna"], respuesta_correcta:1, explicacion:"Nunca se debe exceder la velocidad nominal del disco. La fuerza centrífuga aumenta con el cuadrado de la velocidad, causando que el disco explote en fragmentos letales a alta velocidad.", en_pregunta:"What happens if an abrasive wheel with a maximum rated speed (RPM) lower than the grinder's speed is mounted?", en_opciones:["The wheel cuts harder materials more efficiently with no extra effort","The wheel can disintegrate from centrifugal force, throwing fragments like shrapnel","The grinder automatically reduces its RPM to match the mounted wheel's rating","The grinder motor overheats and the internal thermal protection trips"], en_explicacion:"The wheel's rated speed must never be exceeded. Centrifugal force increases with the square of speed, causing the wheel to explode into lethal fragments at high velocity." },
  { id:"osha_492", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué requisito de seguridad aplica OSHA a las mangueras de herramientas neumáticas en sitios de construcción?", opciones:["Deben ser de color rojo para identificarse fácilmente entre las mangueras de otros sistemas","Deben asegurarse con un dispositivo anti-látigo (whip check) en cada conexión de acople","Solo necesitan abrazaderas estándar de metal si la presión es menor a 50 psi de trabajo","Deben enterrarse bajo tierra para evitar tropezones en las áreas de tránsito peatonal"], respuesta_correcta:1, explicacion:"29 CFR 1926.302(b)(1) requiere que las mangueras neumáticas se aseguren con dispositivos anti-látigo (whip checks o safety cables) para prevenir que una manguera suelta bajo presión lesione trabajadores.", en_pregunta:"What safety requirement does OSHA apply to pneumatic tool hoses on construction sites?", en_opciones:["They must be red to be easily identified among hoses of other systems","They must be secured with an anti-whip device (whip check) at each coupling","They only need standard metal clamps if pressure is less than 50 psi","They must be buried underground to prevent trip hazards in pedestrian areas"], en_explicacion:"29 CFR 1926.302(b)(1) requires pneumatic hoses to be secured with anti-whip devices (whip checks or safety cables) to prevent a disconnected pressurized hose from injuring workers." },
  { id:"osha_493", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué tipo de gatillo requiere OSHA en las pistolas de clavos neumáticas (pneumatic nailers) para máxima seguridad?", opciones:["Gatillo de contacto completo que dispara al presionar la punta contra la superficie","Gatillo de disparo secuencial que requiere presionar la punta primero y luego el gatillo","Gatillo automático que dispara continuamente mientras se mantenga presionado sin soltar","Gatillo de doble acción que requiere dos presiones consecutivas rápidas para cada disparo"], respuesta_correcta:1, explicacion:"OSHA recomienda el gatillo secuencial (sequential trigger) como el más seguro. Requiere que la punta toque la superficie ANTES de presionar el gatillo, previniendo disparos accidentales por contacto.", en_pregunta:"What type of trigger does OSHA require on pneumatic nailers for maximum safety?", en_opciones:["Full contact trigger that fires when the tip is pressed against the surface","Sequential trigger that requires pressing the tip first and then the trigger","Automatic trigger that fires continuously while held down","Double-action trigger that requires two rapid successive presses for each shot"], en_explicacion:"OSHA recommends sequential triggers as the safest. They require the tip to contact the surface BEFORE the trigger is pressed, preventing accidental discharges from contact." },
  { id:"osha_494", categoria:"OSHA_HERRAMIENTAS", pregunta:"Al usar una sierra circular portátil, ¿qué protección específica de la guarda inferior exige OSHA durante el corte?", opciones:["La guarda inferior debe retirarse completamente para tener mejor visibilidad del corte","La guarda inferior debe retraerse automáticamente al cortar y cubrir el disco al soltarse","La guarda inferior puede bloquearse en posición abierta si el material es muy grueso","La guarda inferior solo se requiere cuando se cortan materiales metálicos ferrosos pesados"], respuesta_correcta:1, explicacion:"29 CFR 1926.304(d) requiere que la guarda inferior retráctil se abra automáticamente al cortar y regrese por resorte para cubrir el disco completamente cuando se retira del material.", en_pregunta:"When using a portable circular saw, what specific protection of the lower guard does OSHA require during cutting?", en_opciones:["The lower guard must be completely removed for better visibility of the cut","The lower guard must retract automatically during cutting and cover the blade when released","The lower guard may be locked in the open position if the material is very thick","The lower guard is only required when cutting heavy ferrous metals"], en_explicacion:"29 CFR 1926.304(d) requires the retractable lower guard to open automatically while cutting and return via spring to fully cover the blade when removed from the material." },
  { id:"osha_495", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Por qué OSHA prohíbe bloquear la guarda inferior de una sierra circular en posición abierta permanentemente?", opciones:["Porque el polvo del corte se dispersa más cuando la guarda está abierta sin protección","Porque el disco expuesto puede amputar dedos o manos al terminar el corte del material","Porque la sierra pierde precisión de corte cuando la guarda no guía la hoja correctamente","Porque el motor se sobrecalienta al recibir polvo directo sin la deflexión de la guarda"], respuesta_correcta:1, explicacion:"La guarda inferior debe cubrir el disco automáticamente al completar el corte. Bloquearla abierta expone la hoja giratoria, causando miles de amputaciones de dedos y manos anualmente en construcción.", en_pregunta:"Why does OSHA prohibit locking the lower guard of a circular saw permanently open?", en_opciones:["Because cutting dust scatters more when the guard is open without protection","Because the exposed blade can amputate fingers or hands at the end of the cut","Because the saw loses cutting accuracy when the guard does not guide the blade","Because the motor overheats when receiving dust directly without guard deflection"], en_explicacion:"The lower guard must cover the blade automatically when the cut is complete. Locking it open exposes the spinning blade, causing thousands of finger and hand amputations annually in construction." },
  { id:"osha_496", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es el requisito de OSHA para el almacenamiento de herramientas manuales con bordes cortantes como cinceles y formones?", opciones:["Deben almacenarse en un cubo abierto con los filos hacia arriba para facilitar la selección","Deben guardarse con protectores de filo o en compartimientos que protejan los bordes afilados","Pueden dejarse sueltas en la caja de herramientas junto con las demás sin orden específico","Deben envolverse individualmente en papel periódico para absorber la humedad del ambiente"], respuesta_correcta:1, explicacion:"OSHA requiere que las herramientas con bordes cortantes se almacenen con protección en los filos para prevenir cortes accidentales al buscar herramientas en la caja o bolsa de trabajo.", en_pregunta:"What is OSHA's requirement for storing hand tools with cutting edges such as chisels and gouges?", en_opciones:["They must be stored in an open bin with cutting edges up for easy selection","They must be stored with edge guards or in compartments that protect the sharp edges","They may be left loose in the toolbox alongside other tools without any particular order","They must be individually wrapped in newspaper to absorb ambient humidity"], en_explicacion:"OSHA requires tools with cutting edges to be stored with edge protection to prevent accidental cuts when reaching into the toolbox or work pouch." },
  { id:"osha_497", categoria:"OSHA_HERRAMIENTAS", pregunta:"Un técnico usa un destornillador como palanca para abrir una tapa de registro en un equipo HVAC. Según OSHA, esto es:", opciones:["Aceptable si el destornillador es de mango grande y punta plana resistente al torque","Una violación porque las herramientas deben usarse únicamente para su propósito diseñado","Permitido como práctica estándar si no hay una palanca disponible en el momento del trabajo","Correcto si el técnico aplica la fuerza perpendicular al eje para evitar que resbale la punta"], respuesta_correcta:1, explicacion:"29 CFR 1926.301(a) prohíbe usar herramientas para propósitos distintos al diseñado. Un destornillador usado como palanca puede romperse, enviando fragmentos metálicos al rostro del técnico.", en_pregunta:"A technician uses a screwdriver as a pry bar to open an access cover on an HVAC unit. Per OSHA, this is:", en_opciones:["Acceptable if the screwdriver has a large handle and a flat, torque-resistant tip","A violation, because tools must be used only for their intended purpose","Allowed as standard practice when a pry bar is not available at the moment","Correct if the technician applies force perpendicular to the shaft to keep the tip from slipping"], en_explicacion:"29 CFR 1926.301(a) prohibits using tools for purposes other than intended. A screwdriver used as a pry bar can snap, sending metal fragments into the technician's face." },
  { id:"osha_498", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué debe hacer un técnico cuando una broca de taladro se atasca en una pieza de metal durante la perforación?", opciones:["Forzar el taladro en reversa a máxima velocidad para liberar la broca rápidamente","Soltar el gatillo inmediatamente ya que el torque de reacción puede fracturar la muñeca","Sostener el taladro con más fuerza y aumentar la presión hasta que la broca se libere sola","Desconectar el taladro y usar unas pinzas de presión para extraer la broca manualmente"], respuesta_correcta:1, explicacion:"Cuando una broca se atasca, el torque de reacción puede girar violentamente el taladro y fracturar la muñeca o el brazo. Se debe soltar el gatillo inmediatamente y usar el mango auxiliar para control.", en_pregunta:"What must a technician do when a drill bit binds in a piece of metal during drilling?", en_opciones:["Force the drill in reverse at full speed to free the bit quickly","Release the trigger immediately, because reactive torque can break the wrist","Hold the drill more tightly and increase pressure until the bit frees itself","Unplug the drill and use locking pliers to extract the bit manually"], en_explicacion:"When a bit binds, reactive torque can violently spin the drill and break the wrist or arm. Release the trigger immediately and use the auxiliary handle for control." },
  { id:"osha_499", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es el propósito del mango auxiliar (side handle) en un taladro eléctrico de media pulgada o mayor?", opciones:["Sirve como soporte para colgar el taladro del cinturón de herramientas del técnico","Permite al operador controlar el torque de reacción y evitar lesiones en la muñeca","Funciona como punto de conexión para el cable de seguridad anti-caída de la herramienta","Mejora la estética y el balance visual del taladro para presentaciones a los clientes"], respuesta_correcta:1, explicacion:"El mango auxiliar es un dispositivo de seguridad que permite controlar el torque de reacción cuando la broca se atasca, previniendo que el taladro gire violentamente y lesione al operador.", en_pregunta:"What is the purpose of the side handle (auxiliary handle) on a 1/2-inch or larger electric drill?", en_opciones:["It serves as a clip to hang the drill from the technician's tool belt","It lets the operator control reactive torque and avoid wrist injuries","It works as an attachment point for the tool's anti-drop tether","It improves the drill's aesthetics and visual balance for customer presentations"], en_explicacion:"The side handle is a safety device that lets the operator control reactive torque when the bit binds, preventing the drill from spinning violently and injuring the operator." },
  { id:"osha_500", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué verificación de seguridad exige OSHA antes de conectar una herramienta eléctrica portátil a la fuente de energía?", opciones:["Confirmar que el voltaje de la herramienta coincida con el voltaje del circuito disponible","Verificar que el interruptor de la herramienta esté en posición apagado antes de conectarla","Medir la resistencia de aislamiento con un megóhmetro certificado para cada uso individual","Verificar que la herramienta tenga la etiqueta de inspección mensual del departamento de seguridad"], respuesta_correcta:1, explicacion:"OSHA requiere que el interruptor esté en OFF antes de conectar para evitar arranques involuntarios. Un técnico que conecta una herramienta encendida puede perder el control y sufrir lesiones graves.", en_pregunta:"What safety check does OSHA require before connecting a portable power tool to the power source?", en_opciones:["Confirm the tool's voltage matches the available circuit voltage","Verify the tool's switch is in the OFF position before plugging it in","Measure insulation resistance with a certified megohmmeter for each use","Verify the tool has the monthly inspection tag from the safety department"], en_explicacion:"OSHA requires the switch to be OFF before plugging in to prevent unintended starts. A technician who plugs in a running tool can lose control and suffer serious injury." },
  { id:"osha_501", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué requisito establece OSHA para los cables de extensión temporales utilizados con herramientas eléctricas en construcción?", opciones:["Deben ser de color naranja brillante para identificarse como cables de uso temporal","Deben tener conductor de tierra y ser del calibre adecuado para la carga de la herramienta","Solo necesitan ser de tres conductores si la herramienta consume más de diez amperios","Pueden usarse cables de dos conductores si están conectados a un circuito con interruptor GFCI"], respuesta_correcta:1, explicacion:"Los cables de extensión en construcción deben tener conductor de tierra intacto (tres conductores), calibre adecuado para evitar sobrecalentamiento, y estar protegidos con GFCI o programa de cable asegurado.", en_pregunta:"What requirement does OSHA set for temporary extension cords used with power tools in construction?", en_opciones:["They must be bright orange to identify them as temporary-use cords","They must have a ground conductor and be of proper gauge for the tool's load","They only need to be three-conductor if the tool draws more than ten amps","Two-conductor cords may be used if connected to a GFCI-protected circuit"], en_explicacion:"Extension cords in construction must have an intact ground conductor (three-conductor), adequate gauge to prevent overheating, and be protected with GFCI or an assured equipment grounding program." },
  { id:"osha_502", categoria:"OSHA_HERRAMIENTAS", pregunta:"Un cable de extensión pasa por debajo de una puerta y el aislamiento está aplastado y expuesto. Según OSHA, esto es:", opciones:["Aceptable si se cubre con cinta aislante de buena calidad como reparación temporal rápida","Una violación que requiere retirar el cable de servicio y reemplazarlo inmediatamente","Permitido por un máximo de 24 horas mientras se consigue un cable de reemplazo adecuado","Normal en sitios de construcción y solo requiere señalización con cinta de precaución"], respuesta_correcta:1, explicacion:"Un cable con aislamiento dañado es un riesgo de electrocución inmediato. OSHA prohíbe reparaciones con cinta — el cable debe retirarse de servicio y reemplazarse por uno en buenas condiciones.", en_pregunta:"An extension cord runs under a door, and the insulation is crushed and exposed. Per OSHA, this is:", en_opciones:["Acceptable if covered with quality electrical tape as a quick temporary repair","A violation requiring the cord be removed from service and replaced immediately","Allowed for up to 24 hours while an adequate replacement is obtained","Normal on construction sites and only requires caution-tape signage"], en_explicacion:"A cord with damaged insulation is an immediate electrocution hazard. OSHA prohibits tape repairs — the cord must be removed from service and replaced with one in good condition." },
  { id:"osha_503", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Por qué OSHA requiere que las herramientas neumáticas se desconecten de la fuente de aire antes de realizar cualquier ajuste?", opciones:["Para conservar el aire comprimido y reducir costos operativos del compresor portátil","Para evitar que la herramienta se active accidentalmente y cause lesiones durante el ajuste","Para proteger el mecanismo interno de la herramienta contra daños por manipulación incorrecta","Para permitir que la manguera se enfríe antes de ser manipulada por el técnico de servicio"], respuesta_correcta:1, explicacion:"29 CFR 1926.302(b)(4) requiere la desconexión de aire antes de ajustes. Una herramienta neumática conectada puede activarse inesperadamente, disparando sujetadores o girando partes cortantes.", en_pregunta:"Why does OSHA require pneumatic tools to be disconnected from the air source before making any adjustments?", en_opciones:["To conserve compressed air and reduce operating costs on the portable compressor","To prevent the tool from activating accidentally and causing injury during adjustment","To protect the tool's internal mechanism from damage due to improper handling","To allow the hose to cool before being handled by the service technician"], en_explicacion:"29 CFR 1926.302(b)(4) requires disconnecting air before adjustments. A connected pneumatic tool can activate unexpectedly, firing fasteners or spinning cutting parts." },
  { id:"osha_504", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué presión máxima de aire comprimido permite OSHA para la limpieza de viruta o desechos en el área de trabajo?", opciones:["15 psi con boquilla de seguridad y protección ocular para el operador y circundantes","30 psi con boquilla de seguridad y protección ocular para el operador y circundantes","60 psi con boquilla estándar siempre que el operador use careta facial de policarbonato","90 psi con boquilla reductora y el área completamente despejada de personal no esencial"], respuesta_correcta:1, explicacion:"29 CFR 1926.302(b)(4) establece que la presión de aire para limpieza no debe exceder 30 psi en la boquilla, y se debe usar protección ocular. A presiones mayores, la viruta se convierte en proyectil.", en_pregunta:"What maximum compressed-air pressure does OSHA allow for cleaning chips or debris in the work area?", en_opciones:["15 psi with a safety nozzle and eye protection for the operator and bystanders","30 psi with a safety nozzle and eye protection for the operator and bystanders","60 psi with a standard nozzle as long as the operator wears a polycarbonate face shield","90 psi with a reducing nozzle and the area completely cleared of non-essential personnel"], en_explicacion:"29 CFR 1926.302(b)(4) states that air pressure for cleaning must not exceed 30 psi at the nozzle, and eye protection must be used. At higher pressures, chips become projectiles." },
  { id:"osha_505", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es la regulación OSHA que cubre específicamente los requisitos de seguridad para herramientas manuales y eléctricas en construcción?", opciones:["29 CFR 1926 Subpart H que regula almacenamiento y manejo de materiales en sitios","29 CFR 1926 Subpart I que cubre herramientas manuales, eléctricas y actuadas por pólvora","29 CFR 1926 Subpart K que regula las instalaciones eléctricas temporales y permanentes","29 CFR 1926 Subpart P que cubre requisitos de excavaciones y protección de zanjas"], respuesta_correcta:1, explicacion:"29 CFR 1926 Subpart I (Secciones 1926.300-1926.307) cubre todos los requisitos de herramientas: manuales, eléctricas, neumáticas, hidráulicas, actuadas por pólvora y abrasivas.", en_pregunta:"Which OSHA regulation specifically covers safety requirements for hand and power tools in construction?", en_opciones:["29 CFR 1926 Subpart H, which regulates material handling and storage on sites","29 CFR 1926 Subpart I, which covers hand, power, and powder-actuated tools","29 CFR 1926 Subpart K, which regulates temporary and permanent electrical installations","29 CFR 1926 Subpart P, which covers excavation and trench protection requirements"], en_explicacion:"29 CFR 1926 Subpart I (sections 1926.300-1926.307) covers all tool requirements: hand, power, pneumatic, hydraulic, powder-actuated, and abrasive." },
  { id:"osha_506", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué responsabilidad tiene el empleador respecto a herramientas que los trabajadores traen de su casa al sitio de trabajo?", opciones:["No tiene ninguna responsabilidad porque las herramientas personales son propiedad del técnico","Debe asegurar que estén en condiciones seguras, igual que las herramientas proporcionadas por él","Solo necesita verificar que tengan la marca de un fabricante reconocido y certificado nacional","Debe reemplazarlas gratuitamente con herramientas nuevas del inventario de la compañía"], respuesta_correcta:1, explicacion:"29 CFR 1926.301(a) establece que el empleador es responsable de la condición segura de TODAS las herramientas usadas en el sitio, sin importar si son propiedad del trabajador o de la empresa.", en_pregunta:"What responsibility does the employer have regarding tools that workers bring from home to the job site?", en_opciones:["No responsibility, because personal tools are the technician's property","Must ensure they are in safe condition, just as with employer-provided tools","Only needs to verify they have a recognized manufacturer's mark and national certification","Must replace them for free with new tools from the company inventory"], en_explicacion:"29 CFR 1926.301(a) establishes that the employer is responsible for the safe condition of ALL tools used on site, regardless of whether they are worker- or company-owned." },
  { id:"osha_507", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué protección requiere OSHA al usar un martillo neumático (jackhammer) para romper concreto en una instalación HVAC?", opciones:["Solo protección ocular con gafas de seguridad estándar con protección lateral incluida","Protección ocular, auditiva, respiratoria contra sílice, y botas con punta de acero mínimo","Únicamente botas de seguridad con punta de acero y guantes de cuero resistente al corte","Solo un casco de seguridad clase E y chaleco reflectante de alta visibilidad nocturna"], respuesta_correcta:1, explicacion:"Romper concreto genera sílice cristalina respirable (regulada por 1926.1153), niveles de ruido superiores a 100 dBA, y fragmentos a alta velocidad. Se requiere protección múltiple simultánea.", en_pregunta:"What protection does OSHA require when using a jackhammer to break concrete in an HVAC installation?", en_opciones:["Only eye protection with standard safety glasses that include side shields","Eye, hearing, and respiratory protection against silica, plus steel-toed boots","Only steel-toed safety boots and cut-resistant leather gloves","Only a Class E hard hat and a high-visibility reflective vest"], en_explicacion:"Breaking concrete generates respirable crystalline silica (regulated by 1926.1153), noise levels above 100 dBA, and high-velocity fragments. Multiple simultaneous protections are required." },
  { id:"osha_508", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Cuál es el riesgo principal de usar una llave de tubo (pipe wrench) con mordazas desgastadas en tubería de refrigeración?", opciones:["El acabado cromado de la tubería se daña y afecta la presentación estética del trabajo","Las mordazas pueden resbalar súbitamente causando pérdida de equilibrio y golpes severos","La tubería se deforma por presión irregular y genera una fuga difícil de detectar después","El mango de la llave se dobla permanentemente y la herramienta queda fuera de servicio"], respuesta_correcta:1, explicacion:"Mordazas desgastadas no agarran firmemente la tubería. Bajo esfuerzo, la llave resbala súbitamente causando que el técnico pierda el equilibrio, golpeándose contra equipos o cayendo de la escalera.", en_pregunta:"What is the main hazard of using a pipe wrench with worn jaws on refrigeration piping?", en_opciones:["The chrome finish on the pipe is damaged and the work's aesthetic is affected","The jaws can slip suddenly, causing a loss of balance and severe impact","The pipe deforms from uneven pressure and creates a leak that is hard to detect","The wrench handle bends permanently and the tool is removed from service"], en_explicacion:"Worn jaws do not grip the pipe firmly. Under load, the wrench can slip suddenly, causing the technician to lose balance and strike equipment or fall off a ladder." },
  { id:"osha_509", categoria:"OSHA_HERRAMIENTAS", pregunta:"¿Qué debe hacer un técnico si encuentra una herramienta eléctrica que produce hormigueo o cosquilleo al tocar la carcasa metálica?", opciones:["Usar guantes de goma gruesos y continuar trabajando hasta terminar la tarea asignada","Dejar de usar la herramienta inmediatamente porque indica una falla del aislamiento interno","Conectarla a otro tomacorriente para verificar si el problema es del circuito eléctrico","Reportarlo al final del turno en el formulario de mantenimiento preventivo de herramientas"], respuesta_correcta:1, explicacion:"El hormigueo indica una fuga de corriente por falla del aislamiento interno. Continuar usándola puede resultar en electrocución fatal, especialmente en ambientes húmedos comunes en HVAC.", en_pregunta:"What must a technician do when they find a power tool that produces tingling or a faint shock when they touch the metal housing?", en_opciones:["Wear thick rubber gloves and keep working until the assigned task is done","Stop using the tool immediately because it indicates an internal insulation failure","Plug it into another outlet to check whether the problem is with the electrical circuit","Report it at the end of the shift on the preventive maintenance form"], en_explicacion:"Tingling indicates a current leak from internal insulation failure. Continuing to use it can result in fatal electrocution, especially in the humid environments common to HVAC." },

  { id:"osha_510", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la altura mínima requerida por OSHA para la baranda superior (top rail) de un sistema de barandas estándar en industria general?", opciones:["39 pulgadas desde la superficie de trabajo","42 pulgadas desde la superficie de trabajo","44 pulgadas desde la superficie de trabajo","36 pulgadas desde la superficie de trabajo"], respuesta_correcta:1, explicacion:"29 CFR 1910.29(b)(1) requiere que la baranda superior esté a 42 pulgadas (±3 pulgadas) desde la superficie de trabajo. Esta es una de las medidas más confundidas con la de construcción (1926).", en_pregunta:"What is the minimum height required by OSHA for the top rail of a standard guardrail system in general industry?", en_opciones:["39 inches from the working surface","42 inches from the working surface","44 inches from the working surface","36 inches from the working surface"], en_explicacion:"29 CFR 1910.29(b)(1) requires the top rail to be 42 inches (±3 inches) from the working surface. This is one of the measurements most often confused with the construction standard (1926)." },
  { id:"osha_511", categoria:"OSHA_SUPERFICIES", pregunta:"Según OSHA 29 CFR 1910 Subpart D, ¿a partir de qué diámetro un agujero en el piso requiere protección con cubierta o baranda?", opciones:["1 pulgada de diámetro en adelante","2 pulgadas de diámetro en adelante","4 pulgadas de diámetro en adelante","6 pulgadas de diámetro en adelante"], respuesta_correcta:1, explicacion:"Un agujero en el piso de 2 pulgadas o más de diámetro debe estar protegido con cubierta o baranda para prevenir que el pie de un trabajador pase a través. Muchos confunden esto con el tamaño mínimo de 1 pulgada.", en_pregunta:"Under OSHA 29 CFR 1910 Subpart D, at what diameter does a floor hole require protection by a cover or guardrail?", en_opciones:["1 inch in diameter or more","2 inches in diameter or more","4 inches in diameter or more","6 inches in diameter or more"], en_explicacion:"A floor hole 2 inches or more in diameter must be protected with a cover or guardrail to prevent a worker's foot from passing through. Many confuse this with a 1-inch minimum." },
  { id:"osha_512", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la altura mínima requerida para un toeboard (rodapié) instalado en el borde de una plataforma elevada según industria general?", opciones:["2.5 pulgadas desde la superficie del piso","3.5 pulgadas desde la superficie del piso","4.5 pulgadas desde la superficie del piso","5.5 pulgadas desde la superficie del piso"], respuesta_correcta:1, explicacion:"29 CFR 1910.29(k) establece que los toeboards deben tener un mínimo de 3.5 pulgadas de altura desde la superficie del piso. Esto previene que herramientas y materiales caigan al nivel inferior.", en_pregunta:"What is the minimum height required for a toeboard installed at the edge of an elevated platform in general industry?", en_opciones:["2.5 inches from the floor surface","3.5 inches from the floor surface","4.5 inches from the floor surface","5.5 inches from the floor surface"], en_explicacion:"29 CFR 1910.29(k) states toeboards must be a minimum of 3.5 inches in height from the floor surface. This prevents tools and materials from falling to the level below." },
  { id:"osha_513", categoria:"OSHA_SUPERFICIES", pregunta:"En construcción (29 CFR 1926 Subpart M), ¿a partir de qué altura de caída se requiere protección contra caídas para un trabajador?", opciones:["4 pies sobre el nivel inferior","6 pies sobre el nivel inferior","8 pies sobre el nivel inferior","10 pies sobre el nivel inferior"], respuesta_correcta:1, explicacion:"29 CFR 1926.501(b)(1) requiere protección contra caídas a partir de 6 pies en construcción. Muchos lo confunden con los 4 pies de industria general (1910.28) o los 10 pies de acero estructural.", en_pregunta:"In construction (29 CFR 1926 Subpart M), at what fall height is fall protection required for a worker?", en_opciones:["4 feet above the lower level","6 feet above the lower level","8 feet above the lower level","10 feet above the lower level"], en_explicacion:"29 CFR 1926.501(b)(1) requires fall protection at 6 feet in construction. Many confuse this with the 4-foot trigger in general industry (1910.28) or the 10-foot trigger in steel erection." },
  { id:"osha_514", categoria:"OSHA_SUPERFICIES", pregunta:"En industria general (29 CFR 1910.28), ¿a partir de qué altura un borde abierto requiere protección contra caídas?", opciones:["4 pies sobre el nivel inferior","6 pies sobre el nivel inferior","8 pies sobre el nivel inferior","3 pies sobre el nivel inferior"], respuesta_correcta:0, explicacion:"29 CFR 1910.28(b)(1) establece 4 pies como la altura de activación para protección contra caídas en industria general. Esto es diferente a los 6 pies requeridos en construcción (1926 Subpart M).", en_pregunta:"In general industry (29 CFR 1910.28), at what height does an unprotected edge require fall protection?", en_opciones:["4 feet above the lower level","6 feet above the lower level","8 feet above the lower level","3 feet above the lower level"], en_explicacion:"29 CFR 1910.28(b)(1) sets 4 feet as the trigger height for fall protection in general industry. This differs from the 6-foot requirement in construction (1926 Subpart M)." },
  { id:"osha_515", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué debe hacer un técnico HVAC cuando encuentra una cubierta temporal sobre un agujero en el piso que NO está asegurada ni marcada?", opciones:["Caminar sobre ella con cuidado si parece firme","Moverla para inspeccionar el agujero debajo","Asegurarla y marcarla con la palabra HOLE","Reportarla pero seguir trabajando en el área"], respuesta_correcta:2, explicacion:"29 CFR 1910.29(e)(1) y 1926.502(i) requieren que las cubiertas de agujeros estén aseguradas contra desplazamiento y marcadas con la palabra 'HOLE' o 'COVER'. Una cubierta sin asegurar es un peligro inmediato.", en_pregunta:"What must an HVAC technician do when they find a temporary cover over a floor hole that is NOT secured or marked?", en_opciones:["Walk over it carefully if it looks firm","Move it to inspect the hole underneath","Secure it and mark it with the word HOLE","Report it but keep working in the area"], en_explicacion:"29 CFR 1910.29(e)(1) and 1926.502(i) require hole covers to be secured against displacement and marked with the word 'HOLE' or 'COVER.' An unsecured cover is an immediate hazard." },
  { id:"osha_516", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la carga mínima que debe soportar una cubierta de agujero en el piso según los estándares de OSHA?", opciones:["Dos veces el peso máximo esperado sobre ella","Tres veces el peso máximo esperado sobre ella","Cuatro veces el peso máximo esperado sobre ella","Una y media veces el peso máximo sobre ella"], respuesta_correcta:0, explicacion:"Las cubiertas de agujeros deben soportar al menos dos veces la carga máxima anticipada, incluyendo peso de trabajadores, equipos y materiales que puedan transitar sobre ellas durante operaciones normales.", en_pregunta:"What is the minimum load a floor hole cover must support under OSHA standards?", en_opciones:["Two times the maximum expected load over it","Three times the maximum expected load over it","Four times the maximum expected load over it","One and a half times the maximum load over it"], en_explicacion:"Hole covers must support at least twice the maximum anticipated load, including the weight of workers, equipment, and materials that may pass over them during normal operations." },
  { id:"osha_517", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es el ángulo máximo permitido por OSHA para una escalera fija estándar en industria general?", opciones:["50 grados respecto a la horizontal","60 grados respecto a la horizontal","70 grados respecto a la horizontal","80 grados respecto a la horizontal"], respuesta_correcta:0, explicacion:"Las escaleras fijas estándar (stairways) en industria general deben instalarse entre 30° y 50° respecto a la horizontal. Si el ángulo supera los 50°, se considera una escalera de mano fija (fixed ladder) con requisitos diferentes.", en_pregunta:"What is the maximum angle OSHA allows for a standard fixed stairway in general industry?", en_opciones:["50 degrees from horizontal","60 degrees from horizontal","70 degrees from horizontal","80 degrees from horizontal"], en_explicacion:"Standard fixed stairways in general industry must be installed between 30° and 50° from horizontal. Above 50°, it is considered a fixed ladder with different requirements." },
  { id:"osha_518", categoria:"OSHA_SUPERFICIES", pregunta:"Según OSHA, ¿cuál es el ancho mínimo requerido para una escalera fija estándar en un lugar de trabajo de industria general?", opciones:["20 pulgadas de ancho libre","22 pulgadas de ancho libre","24 pulgadas de ancho libre","28 pulgadas de ancho libre"], respuesta_correcta:1, explicacion:"29 CFR 1910.25(b)(3) requiere un ancho mínimo de 22 pulgadas para escaleras fijas estándar. Muchos confunden este requisito con el de plataformas o pasarelas que tienen diferentes medidas mínimas.", en_pregunta:"Under OSHA, what is the minimum width required for a standard fixed stairway in a general-industry workplace?", en_opciones:["20 inches clear width","22 inches clear width","24 inches clear width","28 inches clear width"], en_explicacion:"29 CFR 1910.25(b)(3) requires a minimum width of 22 inches for standard fixed stairways. Many confuse this with platform or walkway minimums, which differ." },
  { id:"osha_519", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué altura máxima puede tener un escalón individual (riser) en una escalera fija de industria general según OSHA?", opciones:["7.0 pulgadas de altura máxima","8.5 pulgadas de altura máxima","9.5 pulgadas de altura máxima","6.5 pulgadas de altura máxima"], respuesta_correcta:2, explicacion:"29 CFR 1910.25(b)(2) permite una altura máxima de escalón (riser) de 9.5 pulgadas. La uniformidad entre escalones es igualmente importante; la variación no debe exceder 3/16 de pulgada entre escalones.", en_pregunta:"What is the maximum individual riser height on a fixed general-industry stairway under OSHA?", en_opciones:["7.0 inches maximum riser height","8.5 inches maximum riser height","9.5 inches maximum riser height","6.5 inches maximum riser height"], en_explicacion:"29 CFR 1910.25(b)(2) allows a maximum riser height of 9.5 inches. Uniformity between steps is equally important; variation must not exceed 3/16 of an inch between steps." },
  { id:"osha_520", categoria:"OSHA_SUPERFICIES", pregunta:"¿Con qué frecuencia mínima exige OSHA realizar inspecciones de housekeeping (orden y limpieza) en superficies de trabajo?", opciones:["Una vez por semana como mínimo obligatorio","Una vez al mes como mínimo obligatorio","Tan frecuente como sea necesario regularmente","Una vez por turno como mínimo obligatorio"], respuesta_correcta:2, explicacion:"29 CFR 1910.22(a) requiere que las superficies de trabajo se mantengan limpias, ordenadas y en condición sanitaria 'tan frecuentemente como sea necesario'. No establece un intervalo fijo sino una obligación continua.", en_pregunta:"How often does OSHA require housekeeping inspections of working surfaces, at minimum?", en_opciones:["Once a week minimum mandatory","Once a month minimum mandatory","As frequently as necessary on an ongoing basis","Once per shift minimum mandatory"], en_explicacion:"29 CFR 1910.22(a) requires working surfaces be kept clean, orderly, and sanitary 'as frequently as necessary.' It does not set a fixed interval, but establishes a continuous obligation." },
  { id:"osha_521", categoria:"OSHA_SUPERFICIES", pregunta:"Cuando un técnico HVAC trabaja en un techo con borde desprotegido a 12 pies de altura, ¿qué sistema de protección es SIEMPRE aceptable?", opciones:["Línea de advertencia a 6 pies del borde","Sistema personal de detención de caídas","Zona de acceso controlado con monitor","Señalización visible en el borde del techo"], respuesta_correcta:1, explicacion:"Un sistema personal de detención de caídas (PFAS) siempre es aceptable. Las líneas de advertencia y zonas de acceso controlado tienen limitaciones específicas según el tipo de trabajo y la altura. La señalización sola nunca es suficiente.", en_pregunta:"When an HVAC technician works on a roof with an unprotected edge 12 feet up, which protection system is ALWAYS acceptable?", en_opciones:["Warning line 6 feet from the edge","Personal fall arrest system","Controlled access zone with a monitor","Signage at the roof edge"], en_explicacion:"A personal fall arrest system (PFAS) is always acceptable. Warning lines and controlled access zones have specific limitations based on the type of work and height. Signage alone is never enough." },
  { id:"osha_522", categoria:"OSHA_SUPERFICIES", pregunta:"¿A qué distancia mínima del borde del techo debe colocarse una línea de advertencia (warning line) según 29 CFR 1926.502(f)?", opciones:["6 pies del borde en todos los lados","10 pies del borde en todos los lados","15 pies del borde en todos los lados","8 pies del borde en todos los lados"], respuesta_correcta:0, explicacion:"29 CFR 1926.502(f)(2) requiere que la línea de advertencia se coloque a no menos de 6 pies del borde del techo. Si se usa equipo mecánico, la distancia aumenta a 6 pies del borde o del equipo mecánico.", en_pregunta:"What is the minimum distance from the roof edge at which a warning line must be placed under 29 CFR 1926.502(f)?", en_opciones:["6 feet from the edge on all sides","10 feet from the edge on all sides","15 feet from the edge on all sides","8 feet from the edge on all sides"], en_explicacion:"29 CFR 1926.502(f)(2) requires the warning line be placed at least 6 feet from the roof edge. If mechanical equipment is used, the distance increases to 6 feet from the edge or from the equipment." },
  { id:"osha_523", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la causa número uno de muertes en la industria de la construcción según las estadísticas de OSHA?", opciones:["Electrocución por contacto con líneas vivas","Golpes por objetos que caen desde altura","Caídas desde alturas a un nivel inferior","Quedar atrapado entre equipos o materiales"], respuesta_correcta:2, explicacion:"Las caídas representan consistentemente la causa #1 de muertes en construcción, siendo parte del 'Fatal Four' de OSHA. Por eso la protección de superficies de trabajo y bordes es tan crítica en la normativa.", en_pregunta:"What is the number-one cause of deaths in the construction industry according to OSHA statistics?", en_opciones:["Electrocution from contact with live lines","Struck-by objects falling from height","Falls from heights to a lower level","Caught-in/between equipment or materials"], en_explicacion:"Falls are consistently the #1 cause of deaths in construction, part of OSHA's 'Fatal Four.' This is why protection of walking-working surfaces and edges is so critical in the regulations." },
  { id:"osha_524", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es el espaciamiento máximo permitido entre balaustres verticales (midrails) de una baranda estándar según industria general?", opciones:["15 pulgadas de separación entre ellos","19 pulgadas de separación entre ellos","21 pulgadas de separación entre ellos","24 pulgadas de separación entre ellos"], respuesta_correcta:1, explicacion:"29 CFR 1910.29(b)(2) requiere que los balaustres intermedios no permitan el paso de una esfera de 19 pulgadas. Esto previene que un trabajador pueda caer o deslizarse entre los componentes de la baranda.", en_pregunta:"What is the maximum permitted spacing between vertical balusters (midrails) of a standard guardrail under general industry?", en_opciones:["15 inches between them","19 inches between them","21 inches between them","24 inches between them"], en_explicacion:"29 CFR 1910.29(b)(2) requires intermediate balusters to not allow a 19-inch sphere to pass. This prevents a worker from falling or slipping between guardrail components." },
  { id:"osha_525", categoria:"OSHA_SUPERFICIES", pregunta:"Un técnico HVAC debe acceder a una azotea usando una escalera de mano portátil. ¿Cuánto debe sobresalir la escalera por encima del punto de llegada?", opciones:["24 pulgadas por encima del punto de apoyo","36 pulgadas por encima del punto de apoyo","42 pulgadas por encima del punto de apoyo","48 pulgadas por encima del punto de apoyo"], respuesta_correcta:1, explicacion:"29 CFR 1926.1053(b)(1) y 1910.23(b)(1) requieren que la escalera se extienda al menos 36 pulgadas (3 pies) por encima del punto de desembarco. Esto permite al trabajador agarrarse al subir y bajar.", en_pregunta:"An HVAC technician needs to access a rooftop using a portable ladder. How far must the ladder extend above the landing?", en_opciones:["24 inches above the landing","36 inches above the landing","42 inches above the landing","48 inches above the landing"], en_explicacion:"29 CFR 1926.1053(b)(1) and 1910.23(b)(1) require the ladder to extend at least 36 inches (3 feet) above the landing. This allows the worker a handhold when stepping on and off." },
  { id:"osha_526", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué tipo de superficie de piso es MÁS probable que cause resbalones en un cuarto mecánico donde se instala equipo HVAC?", opciones:["Concreto sellado con acabado muy liso y pulido","Concreto con textura de escoba sin sellar","Piso con rejilla metálica tipo diamante abierta","Baldosa antideslizante con coeficiente alto"], respuesta_correcta:0, explicacion:"El concreto sellado con acabado liso y pulido tiene el coeficiente de fricción más bajo, especialmente cuando está mojado. Los cuartos mecánicos con condensación o fugas son particularmente peligrosos con este acabado.", en_pregunta:"Which floor surface is MOST likely to cause slips in a mechanical room where HVAC equipment is installed?", en_opciones:["Smooth, polished, sealed concrete","Broom-finished, unsealed concrete","Open diamond-plate metal grating","High-coefficient non-slip tile"], en_explicacion:"Smooth, polished sealed concrete has the lowest coefficient of friction, especially when wet. Mechanical rooms with condensation or leaks are particularly dangerous with this finish." },
  { id:"osha_527", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué acción es la PRIMERA que debe tomar un empleador cuando identifica un peligro de resbalón en una superficie de trabajo?", opciones:["Proveer equipo de protección personal adecuado","Colocar señales de advertencia en el área visible","Eliminar o controlar el peligro en la superficie","Capacitar a los empleados sobre cómo caminar"], respuesta_correcta:2, explicacion:"Según la jerarquía de controles de OSHA, la eliminación del peligro es siempre la primera opción. El PPE es el ÚLTIMO recurso. Primero se elimina el peligro (limpiar derrame, reparar superficie), luego controles administrativos.", en_pregunta:"What is the FIRST action an employer should take upon identifying a slip hazard on a working surface?", en_opciones:["Provide adequate personal protective equipment","Place warning signs in a visible area","Eliminate or control the hazard on the surface","Train employees on how to walk safely"], en_explicacion:"Under OSHA's hierarchy of controls, elimination of the hazard is always the first option. PPE is the LAST resort. First eliminate the hazard (clean spills, repair the surface), then apply administrative controls." },
  { id:"osha_528", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuándo debe un empleador proveer protección contra caídas a un trabajador en un andamio según la norma de construcción?", opciones:["A partir de los 6 pies de altura sobre nivel","A partir de los 8 pies de altura sobre nivel","A partir de los 10 pies de altura sobre nivel","A partir de los 4 pies de altura sobre nivel"], respuesta_correcta:2, explicacion:"29 CFR 1926.451(g)(1) establece 10 pies como la altura de activación para protección contra caídas en andamios. Esto es diferente a los 6 pies generales de construcción y los 4 pies de industria general.", en_pregunta:"When must an employer provide fall protection to a worker on a scaffold under the construction standard?", en_opciones:["At 6 feet above a lower level","At 8 feet above a lower level","At 10 feet above a lower level","At 4 feet above a lower level"], en_explicacion:"29 CFR 1926.451(g)(1) sets 10 feet as the fall-protection trigger on scaffolds. This differs from the general 6-foot construction requirement and the 4-foot general-industry requirement." },
  { id:"osha_529", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué sección del CFR 29 cubre específicamente las superficies para caminar y trabajar en industria general?", opciones:["29 CFR 1910 Subpart C — General Safety","29 CFR 1910 Subpart D — Walking-Working","29 CFR 1910 Subpart E — Exit and Egress","29 CFR 1926 Subpart M — Fall Protection"], respuesta_correcta:1, explicacion:"29 CFR 1910 Subpart D cubre Walking-Working Surfaces en industria general. Subpart M de 1926 cubre protección contra caídas en construcción. Muchos confunden ambas subpartes y sus requisitos específicos.", en_pregunta:"Which section of 29 CFR specifically covers walking-working surfaces in general industry?", en_opciones:["29 CFR 1910 Subpart C — General Safety","29 CFR 1910 Subpart D — Walking-Working Surfaces","29 CFR 1910 Subpart E — Exit and Egress","29 CFR 1926 Subpart M — Fall Protection"], en_explicacion:"29 CFR 1910 Subpart D covers Walking-Working Surfaces in general industry. Subpart M of 1926 covers fall protection in construction. Many confuse the two subparts and their specific requirements." },
  { id:"osha_530", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la carga mínima concentrada que debe soportar una baranda estándar (top rail) aplicada en cualquier dirección?", opciones:["100 libras de fuerza en cualquier dirección","150 libras de fuerza en cualquier dirección","200 libras de fuerza en cualquier dirección","250 libras de fuerza en cualquier dirección"], respuesta_correcta:2, explicacion:"29 CFR 1910.29(b)(3) requiere que la baranda superior resista una fuerza de al menos 200 libras aplicada en cualquier dirección hacia abajo o hacia afuera. Esto asegura que soporte el peso de un trabajador que se recargue.", en_pregunta:"What is the minimum concentrated load a standard top rail must withstand, applied in any direction?", en_opciones:["100 pounds of force in any direction","150 pounds of force in any direction","200 pounds of force in any direction","250 pounds of force in any direction"], en_explicacion:"29 CFR 1910.29(b)(3) requires the top rail to withstand a force of at least 200 pounds applied in any downward or outward direction. This ensures it supports a worker leaning against it." },
  { id:"osha_531", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué condición de una escalera fija requiere que se instale una jaula de protección (cage) o sistema de seguridad según OSHA?", opciones:["Cuando la escalera excede 20 pies de altura","Cuando la escalera excede 24 pies de altura","Cuando la escalera excede 30 pies de altura","Cuando la escalera excede 15 pies de altura"], respuesta_correcta:1, explicacion:"29 CFR 1910.28(b)(9) requiere protección contra caídas en escaleras fijas que excedan 24 pies. Esto puede ser una jaula, un sistema de rieles de seguridad, o un sistema personal de detención de caídas.", en_pregunta:"What condition on a fixed ladder requires the installation of a protective cage or safety system under OSHA?", en_opciones:["When the ladder exceeds 20 feet in height","When the ladder exceeds 24 feet in height","When the ladder exceeds 30 feet in height","When the ladder exceeds 15 feet in height"], en_explicacion:"29 CFR 1910.28(b)(9) requires fall protection on fixed ladders exceeding 24 feet. This may be a cage, a safety rail system, or a personal fall arrest system." },
  { id:"osha_532", categoria:"OSHA_SUPERFICIES", pregunta:"Un técnico HVAC nota que el piso de un cuarto mecánico tiene un cable de extensión cruzándolo. ¿Cuál es la acción correcta según OSHA?", opciones:["Cubrir el cable con cinta adhesiva de colores","Asegurar el cable con una cubierta protectora","Colocar un letrero advirtiendo sobre el cable","Pasar el cable por debajo de una alfombra gruesa"], respuesta_correcta:1, explicacion:"29 CFR 1910.22(a)(3) requiere que los cables y mangueras en superficies de tránsito estén cubiertos, elevados o protegidos para prevenir tropiezos. Las cubiertas protectoras diseñadas para cables son el método aprobado.", en_pregunta:"An HVAC technician notices that a mechanical-room floor has an extension cord running across it. What is the correct action under OSHA?", en_opciones:["Cover the cord with colored tape","Secure the cord with a protective cover","Place a warning sign near the cord","Run the cord under a heavy rug"], en_explicacion:"29 CFR 1910.22(a)(3) requires cords and hoses on walking surfaces to be covered, elevated, or protected to prevent tripping. Purpose-built cord covers are the approved method." },
  { id:"osha_533", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la profundidad mínima (tread depth) requerida para el peldaño de una escalera fija industrial según OSHA?", opciones:["8 pulgadas de profundidad mínima del peldaño","9 pulgadas de profundidad mínima del peldaño","10 pulgadas de profundidad mínima del peldaño","12 pulgadas de profundidad mínima del peldaño"], respuesta_correcta:1, explicacion:"29 CFR 1910.25(b)(4) requiere una profundidad mínima de peldaño de 9.5 pulgadas (redondeado a 9 en la práctica). Esto asegura que el pie del trabajador tenga apoyo suficiente al subir o bajar las escaleras.", en_pregunta:"What is the minimum tread depth required for a step on an industrial fixed stairway under OSHA?", en_opciones:["8 inches minimum tread depth","9 inches minimum tread depth","10 inches minimum tread depth","12 inches minimum tread depth"], en_explicacion:"29 CFR 1910.25(b)(4) requires a minimum tread depth of 9.5 inches (rounded to 9 in practice). This ensures the worker's foot has adequate support going up or down the stairs." },
  { id:"osha_534", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué factor es el MÁS importante para determinar si una superficie de techo puede soportar a un técnico HVAC y su equipo?", opciones:["La antigüedad del material de la cubierta","La capacidad de carga estructural del techo","El tipo de impermeabilizante que fue usado","La pendiente o inclinación total del techo"], respuesta_correcta:1, explicacion:"La capacidad de carga estructural (load rating) es el factor determinante. Un techo puede verse en buenas condiciones pero no soportar el peso concentrado de un trabajador con equipo. OSHA requiere verificar la capacidad antes de acceder.", en_pregunta:"Which factor is MOST important in determining whether a roof surface can support an HVAC technician and their equipment?", en_opciones:["The age of the roof material","The structural load capacity of the roof","The type of waterproofing used","The pitch or overall slope of the roof"], en_explicacion:"Structural load capacity (load rating) is the determining factor. A roof may appear to be in good condition but not support a worker's concentrated load with equipment. OSHA requires verifying capacity before access." },
  { id:"osha_535", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cada cuántos pies de altura debe haber una plataforma de descanso en una escalera fija vertical (fixed ladder) según OSHA?", opciones:["Cada 20 pies debe haber una plataforma","Cada 25 pies debe haber una plataforma","Cada 30 pies debe haber una plataforma","Cada 35 pies debe haber una plataforma"], respuesta_correcta:2, explicacion:"OSHA requiere plataformas de descanso cada 30 pies en escaleras fijas verticales cuando no hay un sistema de seguridad tipo riel. Esto previene la fatiga del trabajador durante ascensos prolongados en escaleras largas.", en_pregunta:"Every how many feet of height must a rest platform be provided on a vertical fixed ladder under OSHA?", en_opciones:["Every 20 feet","Every 25 feet","Every 30 feet","Every 35 feet"], en_explicacion:"OSHA requires rest platforms every 30 feet on vertical fixed ladders when there is no rail-type safety system. This prevents worker fatigue during prolonged climbs on long ladders." },
  { id:"osha_536", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué requisito especial aplica cuando una abertura en el piso es lo suficientemente grande para que una persona caiga a través?", opciones:["Solo se necesita pintar el borde de amarillo","Se requiere cubierta capaz de soportar tráfico","Se requiere baranda estándar con rodapié incluido","Solo colocar conos de tráfico alrededor del área"], respuesta_correcta:2, explicacion:"29 CFR 1910.28(b)(3) requiere baranda estándar completa (top rail, midrail, toeboard) alrededor de aberturas en el piso por las que una persona pueda caer. Una cubierta también es aceptable si cumple requisitos de carga.", en_pregunta:"What special requirement applies when a floor opening is large enough for a person to fall through?", en_opciones:["Only painting the edge yellow is needed","A cover capable of supporting traffic is required","A standard guardrail with toeboard is required","Only place traffic cones around the area"], en_explicacion:"29 CFR 1910.28(b)(3) requires a full standard guardrail (top rail, midrail, toeboard) around floor openings a person could fall through. A cover is also acceptable if it meets load requirements." },
  { id:"osha_537", categoria:"OSHA_SUPERFICIES", pregunta:"¿Qué significa el término 'walking-working surface' según la definición oficial de OSHA en 29 CFR 1910.21?", opciones:["Solo pisos permanentes dentro de edificaciones","Cualquier superficie horizontal o vertical usada","Cualquier superficie donde un empleado camina o trabaja","Solo plataformas elevadas y andamios certificados"], respuesta_correcta:2, explicacion:"29 CFR 1910.21(a) define walking-working surface como cualquier superficie, horizontal o vertical, sobre la cual un empleado camina o trabaja. Incluye pisos, techos, rampas, pasarelas, escaleras y plataformas.", en_pregunta:"What does the term 'walking-working surface' mean under OSHA's official definition in 29 CFR 1910.21?", en_opciones:["Only permanent floors inside buildings","Any horizontal or vertical surface used for work","Any surface on which an employee walks or works","Only elevated platforms and certified scaffolds"], en_explicacion:"29 CFR 1910.21(a) defines walking-working surface as any surface, horizontal or vertical, on which an employee walks or works. It includes floors, roofs, ramps, walkways, stairs, and platforms." },
  { id:"osha_538", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es el ángulo correcto de inclinación para colocar una escalera de mano portátil según la regla de OSHA?", opciones:["Proporción de 1 pie de base por cada 3 pies","Proporción de 1 pie de base por cada 4 pies","Proporción de 1 pie de base por cada 5 pies","Proporción de 1 pie de base por cada 6 pies"], respuesta_correcta:1, explicacion:"La regla de 4 a 1 (75.5 grados) es el estándar de OSHA: por cada 4 pies de altura, la base debe estar a 1 pie de la pared. Esto proporciona el ángulo más seguro y estable para escaleras portátiles rectas.", en_pregunta:"What is the correct set-up angle for a portable straight ladder under OSHA's rule?", en_opciones:["1 foot of base for every 3 feet of height","1 foot of base for every 4 feet of height","1 foot of base for every 5 feet of height","1 foot of base for every 6 feet of height"], en_explicacion:"The 4-to-1 rule (75.5°) is OSHA's standard: for every 4 feet of height, the base should be 1 foot from the wall. This provides the safest and most stable angle for portable straight ladders." },
  { id:"osha_539", categoria:"OSHA_SUPERFICIES", pregunta:"¿Cuál es la acción correcta de OSHA cuando un empleado debe trabajar sobre un tragaluz (skylight) en un techo?", opciones:["Caminar cuidadosamente alrededor del tragaluz","Instalar baranda o cubierta capaz de soportarlo","Cubrir el tragaluz con una lona gruesa visible","Marcar el tragaluz con pintura fluorescente"], respuesta_correcta:1, explicacion:"29 CFR 1926.502(i) y 1910.29(e) requieren que los tragaluces estén protegidos con barandas estándar o cubiertas que soporten al menos dos veces el peso del trabajador y equipo. Los tragaluces son una causa frecuente de caídas fatales.", en_pregunta:"What is the correct OSHA action when an employee must work above a skylight on a roof?", en_opciones:["Carefully walk around the skylight","Install a guardrail or cover capable of supporting the load","Cover the skylight with a visible heavy tarp","Mark the skylight with fluorescent paint"], en_explicacion:"29 CFR 1926.502(i) and 1910.29(e) require skylights to be protected with standard guardrails or covers that support at least twice the weight of the worker and equipment. Skylights are a frequent cause of fatal falls." },

  { id:"osha_540", categoria:"OSHA_MAQUINARIA", pregunta:"Según 29 CFR 1910 Subpart O, ¿cuál es el propósito PRINCIPAL de los resguardos de maquinaria en el lugar de trabajo?", opciones:["Evitar que el operador tenga contacto con las partes móviles de la máquina","Reducir el nivel de ruido que genera la maquinaria industrial pesada","Proteger la máquina contra daños causados por objetos externos sueltos","Facilitar el mantenimiento preventivo programado de los componentes internos"], respuesta_correcta:0, explicacion:"El propósito principal de los resguardos (machine guards) según OSHA Subpart O es prevenir el contacto del trabajador con partes móviles peligrosas de la maquinaria.", en_pregunta:"Under 29 CFR 1910 Subpart O, what is the PRIMARY purpose of machine guards in the workplace?", en_opciones:["Prevent the operator from contacting the moving parts of the machine","Reduce the noise generated by heavy industrial machinery","Protect the machine from damage caused by loose external objects","Facilitate scheduled preventive maintenance of internal components"], en_explicacion:"The primary purpose of machine guards under OSHA Subpart O is to prevent worker contact with hazardous moving parts of the machine." },
  { id:"osha_541", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué tipo de resguardo de máquina está permanentemente fijado a la estructura y NO requiere ajuste por parte del operador?", opciones:["Resguardo fijo que se sujeta con tornillos o se suelda a la estructura","Resguardo ajustable que el operador posiciona según la pieza de trabajo","Resguardo autoajustable que se mueve según el tamaño del material","Resguardo interconectado que desactiva la máquina al ser removido"], respuesta_correcta:0, explicacion:"El resguardo fijo (fixed guard) es una barrera permanente que se atornilla, suelda o fija a la máquina y no permite ajuste ni movimiento por parte del operador.", en_pregunta:"Which type of machine guard is permanently attached to the structure and does NOT require adjustment by the operator?", en_opciones:["Fixed guard, bolted or welded to the structure","Adjustable guard that the operator positions for the workpiece","Self-adjusting guard that moves based on material size","Interlocked guard that shuts off the machine when removed"], en_explicacion:"The fixed guard is a permanent barrier that is bolted, welded, or fastened to the machine and allows no adjustment or movement by the operator." },
  { id:"osha_542", categoria:"OSHA_MAQUINARIA", pregunta:"Un resguardo interconectado (interlocked guard) se diferencia de los demás porque al abrirlo o removerlo automáticamente:", opciones:["Desconecta la fuente de energía o detiene el ciclo operativo de la máquina","Activa una alarma sonora para alertar al supervisor del área de trabajo","Reduce la velocidad de las partes móviles a un nivel seguro de operación","Bloquea la alimentación de material hacia el punto de operación principal"], respuesta_correcta:0, explicacion:"La característica clave del resguardo interconectado es que al abrirlo o removerlo, automáticamente corta la energía o detiene el movimiento de la máquina (trip/shutoff mechanism).", en_pregunta:"An interlocked guard differs from the others because opening or removing it automatically:", en_opciones:["Disconnects the power source or stops the machine's operating cycle","Triggers an audible alarm to alert the area supervisor","Reduces the speed of moving parts to a safe operating level","Blocks material feed into the main point of operation"], en_explicacion:"The key feature of the interlocked guard is that opening or removing it automatically cuts power or stops the machine's motion (trip/shutoff mechanism)." },
  { id:"osha_543", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es la principal ventaja del resguardo autoajustable (self-adjusting guard) en operaciones de maquinaria?", opciones:["Se abre solo lo necesario para que pase el material y luego vuelve a cerrarse","Detecta automáticamente fallas mecánicas y apaga la máquina por completo","Permite al operador cambiar su posición sin necesidad de usar herramientas","Se adapta a diferentes voltajes de alimentación eléctrica de forma automática"], respuesta_correcta:0, explicacion:"El resguardo autoajustable se mueve automáticamente para permitir el paso del material (stock) y regresa a su posición de protección, manteniendo la barrera el mayor tiempo posible.", en_pregunta:"What is the main advantage of a self-adjusting guard in machine operations?", en_opciones:["It opens only enough to let the material pass and then closes again","It automatically detects mechanical failures and shuts the machine down","It lets the operator change position without using tools","It adapts automatically to different supply voltages"], en_explicacion:"The self-adjusting guard moves automatically to allow the stock to pass and returns to its protective position, keeping the barrier in place as much as possible." },
  { id:"osha_544", categoria:"OSHA_MAQUINARIA", pregunta:"En la protección de maquinaria, ¿qué se define como 'punto de operación' (point of operation)?", opciones:["El área donde la máquina realiza el corte, perforado o formado del material","La zona donde el operador acciona los controles de arranque y de parada","El lugar donde se almacena el material antes de ser procesado por la máquina","La sección donde se conecta la fuente principal de energía eléctrica trifásica"], respuesta_correcta:0, explicacion:"El punto de operación es el área específica donde la máquina realiza trabajo sobre el material — cortando, perforando, doblando, formando, etc. Es una de las zonas de mayor peligro.", en_pregunta:"In machine safeguarding, what is defined as the 'point of operation'?", en_opciones:["The area where the machine cuts, punches, or forms the material","The zone where the operator actuates the start and stop controls","The place where material is stored before being processed","The section where the main three-phase electrical source is connected"], en_explicacion:"The point of operation is the specific area where the machine performs work on the material — cutting, punching, bending, forming, etc. It is one of the most hazardous zones." },
  { id:"osha_545", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué es un 'punto de pellizco' (nip point) en el contexto de protección de maquinaria industrial?", opciones:["La zona donde dos partes rotatorias convergen y pueden atrapar extremidades","El área donde el operador coloca las manos para alimentar material a la máquina","El punto donde se ajusta la tensión de las correas de transmisión de potencia","La ubicación donde se instala el interruptor de emergencia de parada rápida"], respuesta_correcta:0, explicacion:"Un nip point (punto de pellizco) se forma donde dos rodillos, engranajes u otras partes rotatorias convergen, creando riesgo de atrapamiento de dedos, manos o ropa.", en_pregunta:"What is a 'nip point' in the context of industrial machine safeguarding?", en_opciones:["The zone where two rotating parts converge and can trap extremities","The area where the operator feeds material into the machine","The point where power-transmission belt tension is adjusted","The location where the emergency stop switch is installed"], en_explicacion:"A nip point forms where two rollers, gears, or other rotating parts converge, creating a risk of entrapment for fingers, hands, or clothing." },
  { id:"osha_546", categoria:"OSHA_MAQUINARIA", pregunta:"Según OSHA, el aparato de transmisión de potencia (power transmission apparatus) incluye TODOS los siguientes componentes EXCEPTO:", opciones:["La cuchilla de corte que da forma directa a la pieza en el punto de operación","Los ejes rotativos y acoplamientos que transfieren movimiento entre componentes","Las poleas y correas que transmiten la fuerza motriz a través del sistema mecánico","Los engranajes y cadenas que conectan el motor con el mecanismo de la máquina"], respuesta_correcta:0, explicacion:"La cuchilla de corte es parte del punto de operación, no del aparato de transmisión de potencia. El power transmission apparatus incluye ejes, poleas, correas, cadenas, engranajes y acoplamientos.", en_pregunta:"Under OSHA, the power transmission apparatus includes ALL of the following EXCEPT:", en_opciones:["The cutting blade that directly shapes the workpiece at the point of operation","The rotating shafts and couplings that transfer motion between components","The pulleys and belts that transmit drive force through the mechanical system","The gears and chains that connect the motor to the machine mechanism"], en_explicacion:"The cutting blade is part of the point of operation, not the power transmission apparatus. The power transmission apparatus includes shafts, pulleys, belts, chains, gears, and couplings." },
  { id:"osha_547", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es el requisito de OSHA para las ruedas abrasivas (abrasive wheels) que se montan en un esmeril de banco (bench grinder)?", opciones:["Deben tener un resguardo que cubra al menos el 75 por ciento de la superficie de la rueda","Deben girar a una velocidad máxima de 1200 revoluciones por minuto sin excepción","Deben reemplazarse cada treinta días de uso independientemente de su estado visible","Deben ser operadas únicamente por trabajadores con certificación especial vigente"], respuesta_correcta:0, explicacion:"OSHA requiere que las ruedas abrasivas en esmeriles de banco tengan guardas de seguridad que expongan no más del 25% de la rueda (cubriendo al menos 75%), según 29 CFR 1910.215.", en_pregunta:"What is OSHA's requirement for abrasive wheels mounted on a bench grinder?", en_opciones:["They must have a guard covering at least 75% of the wheel surface","They must spin at no more than 1200 revolutions per minute, with no exception","They must be replaced every thirty days of use regardless of visible condition","They may be operated only by workers with a current special certification"], en_explicacion:"OSHA requires abrasive wheels on bench grinders to have safety guards that expose no more than 25% of the wheel (covering at least 75%), per 29 CFR 1910.215." },
  { id:"osha_548", categoria:"OSHA_MAQUINARIA", pregunta:"Antes de montar una rueda abrasiva nueva en un esmeril, OSHA requiere que el trabajador realice:", opciones:["Una prueba de anillo (ring test) para verificar que la rueda no tenga grietas internas","Una medición de voltaje para confirmar que el motor soporta la carga de la nueva rueda","Un análisis químico del material abrasivo para determinar su grado de toxicidad exacta","Una calibración del tacómetro digital para asegurar la lectura correcta de velocidad"], respuesta_correcta:0, explicacion:"El ring test consiste en golpear suavemente la rueda y escuchar un sonido claro (sin grietas). Una rueda agrietada produce un sonido sordo y NO debe montarse.", en_pregunta:"Before mounting a new abrasive wheel on a grinder, OSHA requires the worker to perform:", en_opciones:["A ring test to verify the wheel has no internal cracks","A voltage measurement to confirm the motor can handle the new wheel","A chemical analysis of the abrasive material to determine its exact toxicity","A digital tachometer calibration to ensure correct speed readings"], en_explicacion:"The ring test consists of tapping the wheel gently and listening for a clear tone (no cracks). A cracked wheel produces a dull tone and must NOT be mounted." },
  { id:"osha_549", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es la distancia máxima permitida por OSHA entre el descanso de trabajo (tool rest) y la superficie de la rueda abrasiva?", opciones:["Un octavo de pulgada como máximo para evitar que la pieza se atasque en el espacio","Un cuarto de pulgada como máximo para permitir ventilación adecuada del abrasivo","Media pulgada como máximo para que el operador pueda posicionar piezas cómodamente","Una pulgada como máximo para facilitar el cambio rápido entre diferentes tipos de ruedas"], respuesta_correcta:0, explicacion:"OSHA requiere que el tool rest esté ajustado a no más de 1/8 de pulgada (3 mm) de la rueda abrasiva para prevenir que la pieza de trabajo sea jalada hacia el espacio.", en_pregunta:"What is the maximum distance OSHA allows between the tool rest and the surface of the abrasive wheel?", en_opciones:["One-eighth inch maximum, to keep the workpiece from wedging into the gap","One-quarter inch maximum, to allow adequate ventilation of the abrasive","One-half inch maximum, so the operator can position pieces comfortably","One inch maximum, to allow quick changes between different wheel types"], en_explicacion:"OSHA requires the tool rest to be adjusted to no more than 1/8 inch (3 mm) from the abrasive wheel to prevent the workpiece from being pulled into the gap." },
  { id:"osha_550", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es la distancia máxima que OSHA permite entre la lengüeta ajustable (adjustable tongue guard) y la superficie de una rueda abrasiva?", opciones:["Un cuarto de pulgada para minimizar la exposición del trabajador a fragmentos rotos","Un octavo de pulgada para asegurar que las chispas se direccionen correctamente","Media pulgada para permitir que el fluido refrigerante alcance la zona de contacto","Tres cuartos de pulgada para facilitar la visibilidad del punto de esmerilado"], respuesta_correcta:0, explicacion:"La lengüeta ajustable (adjustable tongue guard) debe mantenerse a no más de 1/4 de pulgada de la rueda abrasiva según 29 CFR 1910.215, distinta de la medida del tool rest (1/8 pulg.).", en_pregunta:"What is the maximum distance OSHA allows between the adjustable tongue guard and the surface of an abrasive wheel?", en_opciones:["One-quarter inch, to minimize worker exposure to broken fragments","One-eighth inch, to ensure sparks are directed correctly","One-half inch, to allow coolant to reach the contact zone","Three-quarters inch, to improve visibility of the grinding point"], en_explicacion:"The adjustable tongue guard must be kept no more than 1/4 inch from the abrasive wheel per 29 CFR 1910.215, which differs from the tool rest measurement (1/8 inch)." },
  { id:"osha_551", categoria:"OSHA_MAQUINARIA", pregunta:"En una prensa mecánica de potencia (mechanical power press), ¿qué dispositivo detecta una falla en el mecanismo y detiene el recorrido?", opciones:["El monitor de freno y embrague que supervisa el funcionamiento del ciclo completo","El interruptor de límite de carrera que regula la posición inferior del ariete móvil","El sensor de presencia que detecta cuando el operador ingresa al área restringida","El controlador lógico programable que gestiona la secuencia automática de operación"], respuesta_correcta:0, explicacion:"El brake monitor en prensas mecánicas detecta deterioro en el sistema de freno/embrague y detiene la operación si el tiempo de parada excede los límites normales (29 CFR 1910.217).", en_pregunta:"On a mechanical power press, which device detects a failure in the mechanism and stops the stroke?", en_opciones:["The brake and clutch monitor that supervises full-cycle operation","The stroke limit switch that regulates the bottom position of the moving ram","The presence sensor that detects when the operator enters the restricted area","The programmable logic controller that manages the automatic operating sequence"], en_explicacion:"The brake monitor on mechanical power presses detects deterioration in the brake/clutch system and stops operation if the stopping time exceeds normal limits (29 CFR 1910.217)." },
  { id:"osha_552", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál de los siguientes es un dispositivo de protección (safeguarding device) y NO un resguardo (guard) de máquina?", opciones:["Una cortina de luz infrarroja que detiene la máquina al detectar una obstrucción","Una barrera fija de metal que impide el acceso físico a las partes en movimiento","Una cubierta ajustable de policarbonato que rodea el área del punto de operación","Un encerramiento permanente soldado que cubre completamente la zona de peligro"], respuesta_correcta:0, explicacion:"La cortina de luz (light curtain) es un dispositivo de protección que detecta presencia y detiene la máquina; los demás son resguardos (guards) que actúan como barreras físicas.", en_pregunta:"Which of the following is a safeguarding device and NOT a machine guard?", en_opciones:["An infrared light curtain that stops the machine when it detects an obstruction","A fixed metal barrier that prevents physical access to moving parts","An adjustable polycarbonate cover that surrounds the point-of-operation area","A permanent welded enclosure that completely covers the danger zone"], en_explicacion:"A light curtain is a safeguarding device that detects presence and stops the machine; the others are guards that act as physical barriers." },
  { id:"osha_553", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué tipo de dispositivo de protección utiliza un mecanismo que físicamente retira las manos del operador del punto de operación?", opciones:["Un dispositivo de retirada (pullback device) conectado con correas a las muñecas","Un control a dos manos que requiere presión simultánea para activar el mecanismo","Una cortina de luz que crea una barrera invisible frente al punto de operación","Un tapete sensible a presión que detecta cuando alguien pisa la zona de peligro"], respuesta_correcta:0, explicacion:"El pullback device (dispositivo de retirada) usa cables conectados a las muñecas del operador que jalan las manos fuera del punto de operación cuando la máquina inicia su ciclo.", en_pregunta:"Which type of safeguarding device uses a mechanism that physically pulls the operator's hands away from the point of operation?", en_opciones:["A pullback device connected by straps to the operator's wrists","A two-hand control that requires simultaneous pressure to activate the mechanism","A light curtain that creates an invisible barrier in front of the point of operation","A pressure-sensitive mat that detects when someone steps into the danger zone"], en_explicacion:"The pullback device uses cables connected to the operator's wrists that pull the hands out of the point of operation when the machine begins its cycle." },
  { id:"osha_554", categoria:"OSHA_MAQUINARIA", pregunta:"Un sistema de control a dos manos (two-hand control) protege al operador de una prensa porque:", opciones:["Requiere que ambas manos estén en los botones durante todo el ciclo de operación","Permite que un solo operador maneje dos máquinas al mismo tiempo de forma segura","Duplica la señal eléctrica para garantizar que el motor tenga suficiente par de arranque","Reduce el tiempo del ciclo a la mitad al activar ambos lados del ariete en paralelo"], respuesta_correcta:0, explicacion:"El two-hand control requiere presión simultánea y continua de ambas manos en los botones, asegurando que las manos del operador no estén en el punto de operación durante el ciclo.", en_pregunta:"A two-hand control system protects the press operator because:", en_opciones:["It requires both hands to remain on the buttons throughout the entire operating cycle","It allows a single operator to safely run two machines at the same time","It duplicates the electrical signal to ensure the motor has enough starting torque","It cuts cycle time in half by activating both sides of the ram in parallel"], en_explicacion:"The two-hand control requires simultaneous and continuous pressure from both hands on the buttons, ensuring the operator's hands are not in the point of operation during the cycle." },
  { id:"osha_555", categoria:"OSHA_MAQUINARIA", pregunta:"Según OSHA, ¿cuándo se debe realizar la inspección de las prensas mecánicas de potencia por personal certificado?", opciones:["Al menos una vez cada doce meses según lo requiere la norma federal aplicable","Únicamente cuando el operador reporta una vibración anormal durante la operación","Cada vez que se cambia el troquel independientemente del intervalo transcurrido","Solamente después de que ocurra un accidente o incidente reportable en la prensa"], respuesta_correcta:0, explicacion:"29 CFR 1910.217(e)(1) requiere inspección anual (cada 12 meses) de prensas mecánicas por personal certificado y competente para evaluar frenos, embragues y mecanismos de seguridad.", en_pregunta:"According to OSHA, when must mechanical power presses be inspected by certified personnel?", en_opciones:["At least once every twelve months as required by the applicable federal standard","Only when the operator reports abnormal vibration during operation","Every time the die is changed, regardless of the interval that has passed","Only after a reportable accident or incident occurs on the press"], en_explicacion:"29 CFR 1910.217(e)(1) requires annual (every 12 months) inspection of mechanical presses by certified, competent personnel to evaluate brakes, clutches, and safety mechanisms." },
  { id:"osha_556", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué acción debe realizarse PRIMERO antes de dar servicio o mantenimiento a cualquier máquina con partes móviles peligrosas?", opciones:["Bloquear y etiquetar todas las fuentes de energía siguiendo el procedimiento LOTO","Notificar al supervisor del turno siguiente para que programe un reemplazo temporal","Colocar señalización de advertencia visible en un radio de diez pies alrededor del área","Consultar el manual del fabricante para identificar las partes que necesitan lubricación"], respuesta_correcta:0, explicacion:"Lockout/Tagout (LOTO) según 29 CFR 1910.147 es el PRIMER paso obligatorio antes de cualquier mantenimiento — se deben aislar y bloquear todas las fuentes de energía peligrosa.", en_pregunta:"What action must be performed FIRST before servicing or maintaining any machine with hazardous moving parts?", en_opciones:["Lock out and tag out all energy sources following the LOTO procedure","Notify the next-shift supervisor so a temporary replacement can be scheduled","Post visible warning signage within a ten-foot radius around the area","Consult the manufacturer's manual to identify parts that need lubrication"], en_explicacion:"Lockout/Tagout (LOTO) under 29 CFR 1910.147 is the mandatory FIRST step before any maintenance — all hazardous energy sources must be isolated and locked out." },
  { id:"osha_557", categoria:"OSHA_MAQUINARIA", pregunta:"Un técnico de HVAC trabaja cerca de un ventilador industrial con aspas expuestas. ¿Qué tipo de resguardo es más apropiado?", opciones:["Un resguardo fijo de malla metálica que cubra completamente las aspas rotatorias","Un resguardo autoajustable que se abra cuando el aire necesite mayor flujo libre","Un dispositivo de retirada conectado al brazo del técnico mediante cables flexibles","Un control a dos manos instalado directamente en el panel del ventilador industrial"], respuesta_correcta:0, explicacion:"Para ventiladores industriales con aspas expuestas, el resguardo fijo de malla metálica es el más apropiado — cubre permanentemente las partes rotatorias sin impedir el flujo de aire.", en_pregunta:"An HVAC technician works near an industrial fan with exposed blades. What type of guard is most appropriate?", en_opciones:["A fixed wire-mesh guard that completely covers the rotating blades","A self-adjusting guard that opens when the airflow needs to increase","A pullback device connected to the technician's arm with flexible cables","A two-hand control installed directly on the industrial fan panel"], en_explicacion:"For industrial fans with exposed blades, a fixed wire-mesh guard is most appropriate — it permanently covers the rotating parts without obstructing airflow." },
  { id:"osha_558", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es el peligro principal asociado con los ejes rotativos (rotating shafts) en equipos de transmisión de potencia?", opciones:["El atrapamiento de ropa suelta o cabello largo del trabajador que gira y lo enrolla","La generación de chispas que pueden causar incendios en áreas con material inflamable","La emisión de partículas metálicas calientes que causan quemaduras en la piel expuesta","La vibración excesiva que afloja los pernos de anclaje y desalinea toda la maquinaria"], respuesta_correcta:0, explicacion:"Los ejes rotativos presentan peligro de atrapamiento (entanglement) — ropa suelta, cabello, guantes o joyería pueden quedar atrapados y enrollar al trabajador alrededor del eje.", en_pregunta:"What is the main hazard associated with rotating shafts in power transmission equipment?", en_opciones:["Entanglement of the worker's loose clothing or long hair, which wraps around the shaft","Generation of sparks that can cause fires in areas with flammable material","Emission of hot metallic particles that cause burns on exposed skin","Excessive vibration that loosens the anchor bolts and misaligns the whole machine"], en_explicacion:"Rotating shafts present an entanglement hazard — loose clothing, hair, gloves, or jewelry can get caught and wrap the worker around the shaft." },
  { id:"osha_559", categoria:"OSHA_MAQUINARIA", pregunta:"¿En cuál de estos escenarios OSHA permite operar una máquina sin resguardos de protección en su lugar?", opciones:["En ningún escenario ya que los resguardos deben estar colocados siempre durante la operación","Cuando el operador tiene más de diez años de experiencia documentada con esa máquina exacta","Cuando la velocidad de la máquina se reduce al cincuenta por ciento del valor nominal indicado","Cuando el supervisor de seguridad autoriza verbalmente la operación sin resguardos temporalmente"], respuesta_correcta:0, explicacion:"OSHA NO permite operar maquinaria sin resguardos bajo ninguna circunstancia durante la operación normal. Los resguardos solo se retiran durante mantenimiento con LOTO activo.", en_pregunta:"In which of these scenarios does OSHA allow operating a machine without guards in place?", en_opciones:["In no scenario, since guards must always be in place during operation","When the operator has more than ten years of documented experience on that exact machine","When the machine's speed is reduced to fifty percent of its rated value","When the safety supervisor verbally authorizes operation without guards temporarily"], en_explicacion:"OSHA does NOT allow operating machinery without guards under any circumstances during normal operation. Guards are only removed during maintenance with LOTO active." },
  { id:"osha_560", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué requisito establece OSHA sobre los resguardos de máquina en relación con la creación de nuevos peligros?", opciones:["El resguardo NO debe crear peligros adicionales como bordes cortantes o puntos de pellizco","El resguardo debe ser del mismo color que la máquina para mantener uniformidad en la planta","El resguardo debe poder removerse sin herramientas para facilitar respuestas de emergencia","El resguardo debe ser fabricado exclusivamente por el fabricante original del equipo protegido"], respuesta_correcta:0, explicacion:"Uno de los requisitos mínimos de OSHA para resguardos es que NO deben crear peligros nuevos — no deben tener bordes afilados, puntos de pellizco u otras condiciones que puedan lesionar.", en_pregunta:"What requirement does OSHA establish for machine guards regarding the creation of new hazards?", en_opciones:["The guard must NOT create additional hazards such as sharp edges or pinch points","The guard must be the same color as the machine to maintain uniformity in the plant","The guard must be removable without tools to facilitate emergency responses","The guard must be manufactured exclusively by the original equipment manufacturer"], en_explicacion:"One of OSHA's minimum requirements for guards is that they must NOT create new hazards — they must have no sharp edges, pinch points, or other conditions that could cause injury." },
  { id:"osha_561", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es un requisito de OSHA para los resguardos en cuanto a la capacidad del trabajador para realizar sus tareas?", opciones:["El resguardo no debe impedir que el trabajador realice su trabajo de forma eficiente","El resguardo debe permitir que el trabajador alcance el punto de operación con las manos","El resguardo debe ser transparente para que el trabajador observe las partes internas siempre","El resguardo debe incluir una abertura lateral para la ventilación continua del área protegida"], respuesta_correcta:0, explicacion:"OSHA requiere que los resguardos no interfieran innecesariamente con la productividad del operador — deben proteger sin impedir que el trabajo se realice de manera eficiente.", en_pregunta:"Which is an OSHA requirement for guards regarding the worker's ability to perform their tasks?", en_opciones:["The guard must not prevent the worker from performing the job efficiently","The guard must allow the worker to reach the point of operation by hand","The guard must be transparent so the worker can always view the internal parts","The guard must include a side opening for continuous ventilation of the protected area"], en_explicacion:"OSHA requires that guards not unnecessarily interfere with operator productivity — they must protect without preventing the work from being performed efficiently." },
  { id:"osha_562", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué tipo de movimiento de máquina representa el mayor peligro de amputación en el punto de operación?", opciones:["El movimiento de corte donde una cuchilla o sierra pasa a través del material de trabajo","El movimiento de rotación uniforme de un eje principal sin carga de trabajo aplicada","El movimiento de avance del material hacia la zona de alimentación de entrada a la máquina","El movimiento de vibración lateral que genera el motor durante el arranque inicial del equipo"], respuesta_correcta:0, explicacion:"El movimiento de corte (cutting action) en sierras, cizallas y guillotinas presenta el mayor riesgo de amputación porque involucra cuchillas que pasan a través del material con gran fuerza.", en_pregunta:"Which type of machine motion presents the greatest amputation hazard at the point of operation?", en_opciones:["Cutting action, where a blade or saw passes through the workpiece material","Uniform rotating motion of a main shaft with no applied work load","Feed motion of material into the machine's infeed zone","Lateral vibration motion generated by the motor during initial startup"], en_explicacion:"Cutting action in saws, shears, and guillotines presents the greatest amputation risk because it involves blades passing through the material with great force." },
  { id:"osha_563", categoria:"OSHA_MAQUINARIA", pregunta:"En una sierra de banda (band saw) utilizada en un taller de HVAC, ¿qué parte de la hoja debe estar resguardada?", opciones:["Toda la hoja excepto la porción que realiza el corte entre las guías de la sierra","Solo la mitad superior de la hoja ya que la inferior está protegida por la mesa de trabajo","Únicamente las ruedas superior e inferior donde la hoja cambia de dirección al girar","Solo el segmento que está en contacto directo con la pieza de trabajo siendo cortada"], respuesta_correcta:0, explicacion:"En una sierra de banda, TODA la hoja debe estar resguardada excepto la porción entre las guías que realiza el corte — incluyendo las ruedas y los tramos de retorno de la hoja.", en_pregunta:"On a band saw used in an HVAC shop, which part of the blade must be guarded?", en_opciones:["The entire blade except the portion performing the cut between the saw guides","Only the upper half of the blade, since the lower half is protected by the table","Only the upper and lower wheels where the blade changes direction","Only the segment in direct contact with the workpiece being cut"], en_explicacion:"On a band saw, the ENTIRE blade must be guarded except for the portion between the guides that performs the cut — including the wheels and the blade's return runs." },
  { id:"osha_564", categoria:"OSHA_MAQUINARIA", pregunta:"Un tapete sensible a la presión (pressure-sensitive mat) como dispositivo de protección funciona de la siguiente manera:", opciones:["Detiene la máquina cuando una persona pisa el tapete en la zona de peligro designada","Aumenta la velocidad del ciclo cuando detecta que el operador está en posición correcta","Registra el peso del operador para verificar que sea la persona autorizada en esa estación","Monitorea la temperatura del piso para prevenir el sobrecalentamiento del motor principal"], respuesta_correcta:0, explicacion:"El tapete sensible a presión detecta cuando alguien pisa la zona de peligro y envía una señal para detener la máquina automáticamente, protegiendo al trabajador de las partes móviles.", en_pregunta:"A pressure-sensitive mat as a safeguarding device works as follows:", en_opciones:["It stops the machine when a person steps on the mat in the designated danger zone","It increases cycle speed when it detects the operator is in the correct position","It records the operator's weight to verify they are the authorized person at that station","It monitors floor temperature to prevent overheating of the main motor"], en_explicacion:"The pressure-sensitive mat detects when someone steps into the danger zone and sends a signal to stop the machine automatically, protecting the worker from moving parts." },
  { id:"osha_565", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué medida de seguridad adicional requiere OSHA cuando un resguardo fijo debe removerse para cambio de herramientas o ajustes?", opciones:["El resguardo debe requerir herramientas para su remoción evitando que se quite fácilmente","El resguardo debe tener un color diferente al de la máquina para ser fácilmente identificable","El resguardo debe incluir instrucciones grabadas en su superficie sobre cómo reinstalarlo","El resguardo debe pesar menos de cinco libras para que cualquier operador pueda manejarlo"], respuesta_correcta:0, explicacion:"OSHA requiere que los resguardos fijos no puedan ser removidos fácilmente — deben requerir herramientas para su remoción, asegurando que no se quiten de forma casual o accidental.", en_pregunta:"What additional safety measure does OSHA require when a fixed guard must be removed for tool changes or adjustments?", en_opciones:["The guard must require tools for removal so it cannot be taken off easily","The guard must be a different color from the machine to be easily identifiable","The guard must include instructions engraved on its surface for how to reinstall it","The guard must weigh less than five pounds so any operator can handle it"], en_explicacion:"OSHA requires that fixed guards not be easily removable — they must require tools for removal, ensuring they are not taken off casually or accidentally." },
  { id:"osha_566", categoria:"OSHA_MAQUINARIA", pregunta:"¿Qué estándar de OSHA cubre específicamente los requisitos para resguardos en prensas mecánicas de potencia?", opciones:["29 CFR 1910.217 que establece requisitos específicos de diseño e inspección periódica","29 CFR 1910.147 que regula los procedimientos de bloqueo y etiquetado de energías","29 CFR 1910.134 que define los estándares para protección respiratoria en el trabajo","29 CFR 1910.305 que especifica los métodos de cableado eléctrico en instalaciones"], respuesta_correcta:0, explicacion:"29 CFR 1910.217 es el estándar específico para prensas mecánicas de potencia, cubriendo resguardos del punto de operación, dispositivos de protección, inspecciones y requisitos de frenos.", en_pregunta:"Which OSHA standard specifically covers guarding requirements for mechanical power presses?", en_opciones:["29 CFR 1910.217, which establishes specific design and periodic inspection requirements","29 CFR 1910.147, which regulates lockout/tagout procedures","29 CFR 1910.134, which defines respiratory protection standards in the workplace","29 CFR 1910.305, which specifies wiring methods for electrical installations"], en_explicacion:"29 CFR 1910.217 is the specific standard for mechanical power presses, covering point-of-operation guarding, safeguarding devices, inspections, and brake requirements." },
  { id:"osha_567", categoria:"OSHA_MAQUINARIA", pregunta:"¿Por qué OSHA prohíbe el uso de guantes cuando se opera un taladro de banco (drill press) con broca expuesta?", opciones:["Porque el guante puede ser atrapado por la broca giratoria y jalar la mano del operador","Porque los guantes reducen la sensibilidad táctil necesaria para calibrar la profundidad","Porque el material del guante puede fundirse con el calor de fricción y dañar la broca","Porque los guantes contaminan la pieza de trabajo con fibras que afectan la perforación"], respuesta_correcta:0, explicacion:"Los guantes pueden ser atrapados por la broca giratoria del taladro, enrollando la mano del operador hacia la broca y causando lesiones severas por atrapamiento.", en_pregunta:"Why does OSHA prohibit wearing gloves when operating a drill press with an exposed bit?", en_opciones:["Because the glove can be caught by the rotating bit and pull the operator's hand in","Because gloves reduce the tactile sensitivity needed to calibrate depth","Because the glove material can melt from friction heat and damage the bit","Because gloves contaminate the workpiece with fibers that affect drilling"], en_explicacion:"Gloves can be caught by the rotating drill bit, pulling the operator's hand toward the bit and causing severe entanglement injuries." },
  { id:"osha_568", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es la velocidad mínima de parada que OSHA establece para el mecanismo de freno de una prensa mecánica?", opciones:["El freno debe detener el ariete antes de que el operador pueda alcanzar el punto de operación","El freno debe detener el ariete en exactamente dos segundos desde que se activa la parada","El freno debe reducir la velocidad del ariete a la mitad dentro del primer ciclo de frenado","El freno debe detener completamente el volante de inercia dentro de cinco revoluciones totales"], respuesta_correcta:0, explicacion:"OSHA no establece un tiempo fijo universal, sino que el freno debe detener el ariete (ram/slide) antes de que la mano del operador pueda alcanzar el punto de operación — basado en cálculo de distancia de seguridad.", en_pregunta:"What minimum stopping performance does OSHA require for the brake mechanism on a mechanical press?", en_opciones:["The brake must stop the ram before the operator can reach the point of operation","The brake must stop the ram within exactly two seconds of stop activation","The brake must reduce the ram speed by half within the first braking cycle","The brake must completely stop the flywheel within five total revolutions"], en_explicacion:"OSHA does not set a fixed universal time; the brake must stop the ram (ram/slide) before the operator's hand can reach the point of operation — based on a safety distance calculation." },
  { id:"osha_569", categoria:"OSHA_MAQUINARIA", pregunta:"¿Cuál es la responsabilidad del empleador respecto al entrenamiento en protección de maquinaria según OSHA?", opciones:["Debe entrenar a cada operador sobre los peligros específicos y los resguardos de su máquina","Debe proporcionar un manual impreso general de seguridad al momento de la contratación","Debe publicar las reglas de seguridad en la cartelera principal de la entrada del edificio","Debe asignar un compañero experimentado para que observe al nuevo operador por una hora"], respuesta_correcta:0, explicacion:"OSHA requiere que el empleador proporcione entrenamiento específico a cada operador sobre los peligros de SU máquina, los resguardos instalados, y cómo usarlos correctamente.", en_pregunta:"What is the employer's responsibility for machine guarding training under OSHA?", en_opciones:["Train each operator on the specific hazards and guards of their machine","Provide a general printed safety manual at the time of hire","Post the safety rules on the main bulletin board at the building entrance","Assign an experienced coworker to observe the new operator for one hour"], en_explicacion:"OSHA requires the employer to provide training specific to each operator on the hazards of THEIR machine, the guards installed, and how to use them correctly." },
  { id:"osha_570", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuánto tiempo debe permanecer el vigía de incendios (fire watch) después de completar una operación de soldadura o corte con llama?", opciones:["Un mínimo de 15 minutos para verificar que no haya brasas residuales","Un mínimo de 30 minutos para asegurar que no existan focos de ignición","Un mínimo de 45 minutos para confirmar la ausencia de humo o calor","Un mínimo de 60 minutos para garantizar que el área esté completamente fría"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.352(e) requiere que el fire watch permanezca un mínimo de 30 minutos después de completar operaciones de soldadura o corte para asegurar que no haya focos de ignición.", en_pregunta:"How long must the fire watch remain after completing a welding or flame cutting operation?", en_opciones:["A minimum of 15 minutes to verify there are no residual embers","A minimum of 30 minutes to ensure there are no ignition sources","A minimum of 45 minutes to confirm no smoke or heat is present","A minimum of 60 minutes to ensure the area is completely cool"], en_explicacion:"OSHA 29 CFR 1926.352(e) requires the fire watch to remain for a minimum of 30 minutes after completing welding or cutting operations to ensure no ignition sources remain." },
  { id:"osha_571", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la distancia mínima requerida por OSHA para almacenar cilindros de oxígeno separados de cilindros de gas combustible?", opciones:["10 pies de distancia o una barrera no combustible de 3 pies de altura","15 pies de distancia o una barrera no combustible de 4 pies de altura","20 pies de distancia o una barrera no combustible de 5 pies de altura","25 pies de distancia o una barrera no combustible de 6 pies de altura"], respuesta_correcta:2, explicacion:"OSHA 29 CFR 1926.350(a)(10) requiere que los cilindros de oxígeno se almacenen a un mínimo de 20 pies de cilindros de gas combustible o separados por una barrera no combustible de al menos 5 pies de altura.", en_pregunta:"What is the minimum distance OSHA requires for storing oxygen cylinders separated from fuel-gas cylinders?", en_opciones:["10 feet apart or a 3-foot non-combustible barrier","15 feet apart or a 4-foot non-combustible barrier","20 feet apart or a 5-foot non-combustible barrier","25 feet apart or a 6-foot non-combustible barrier"], en_explicacion:"OSHA 29 CFR 1926.350(a)(10) requires oxygen cylinders to be stored at least 20 feet from fuel-gas cylinders, or separated by a non-combustible barrier at least 5 feet high." },
  { id:"osha_572", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la presión máxima permitida para utilizar acetileno en operaciones de soldadura y corte según las normas de seguridad?", opciones:["No debe exceder 10 psi ya que se vuelve altamente reactivo a presiones mayores","No debe exceder 15 psi ya que se vuelve inestable y puede detonar por sí solo","No debe exceder 20 psi ya que pierde sus propiedades de combustión controlada","No debe exceder 25 psi ya que genera una reacción exotérmica no controlable"], respuesta_correcta:1, explicacion:"El acetileno no debe usarse a presiones superiores a 15 psi (manométrica). Por encima de esta presión, el acetileno se vuelve inestable y puede detonar espontáneamente sin necesidad de una fuente de ignición.", en_pregunta:"What is the maximum working pressure allowed for acetylene in welding and cutting operations per safety standards?", en_opciones:["Must not exceed 10 psi, as it becomes highly reactive at higher pressures","Must not exceed 15 psi, as it becomes unstable and can detonate on its own","Must not exceed 20 psi, as it loses its controlled-combustion properties","Must not exceed 25 psi, as it produces an uncontrollable exothermic reaction"], en_explicacion:"Acetylene must never be used at pressures above 15 psig. Above this pressure, acetylene becomes unstable and can spontaneously detonate without an ignition source." },
  { id:"osha_573", categoria:"OSHA_SOLDADURA", pregunta:"Antes de realizar soldadura o corte en un área no designada, ¿qué documento debe obtenerse obligatoriamente según OSHA?", opciones:["Un certificado de inspección de equipos firmado por el supervisor de mantenimiento","Un permiso de trabajo en caliente autorizado por el responsable de la instalación","Una orden de trabajo especial emitida directamente por el departamento de seguridad","Un formulario de análisis de riesgos completado y aprobado por recursos humanos"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.352 requiere un permiso de trabajo en caliente (hot work permit) antes de realizar soldadura o corte en áreas no designadas. Este debe ser autorizado por el individuo responsable de la instalación.", en_pregunta:"Before performing welding or cutting in a non-designated area, which document must be obtained under OSHA?", en_opciones:["An equipment inspection certificate signed by the maintenance supervisor","A hot work permit authorized by the person responsible for the facility","A special work order issued directly by the safety department","A risk analysis form completed and approved by human resources"], en_explicacion:"OSHA 29 CFR 1926.352 requires a hot work permit before performing welding or cutting in non-designated areas. It must be authorized by the individual responsible for the facility." },
  { id:"osha_574", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué número mínimo de shade (tono de lente) se requiere para soldadura con arco eléctrico SMAW con electrodos de 1/16 a 5/32 pulgadas?", opciones:["Se requiere shade número 8 para proteger adecuadamente contra la radiación ultravioleta","Se requiere shade número 10 para filtrar correctamente la intensidad del arco eléctrico","Se requiere shade número 12 para reducir el riesgo de daño permanente a la retina","Se requiere shade número 14 para bloquear toda la radiación infrarroja del proceso"], respuesta_correcta:1, explicacion:"Para soldadura SMAW con electrodos de 1/16 a 5/32 pulgadas, OSHA recomienda un shade mínimo de #10. El número de shade correcto depende del amperaje y tipo de proceso de soldadura.", en_pregunta:"What minimum shade number is required for SMAW arc welding with 1/16 to 5/32 inch electrodes?", en_opciones:["Shade #8 is required to adequately protect against ultraviolet radiation","Shade #10 is required to properly filter the arc's intensity","Shade #12 is required to reduce the risk of permanent retinal damage","Shade #14 is required to block all infrared radiation from the process"], en_explicacion:"For SMAW welding with 1/16 to 5/32 inch electrodes, OSHA recommends a minimum shade of #10. The correct shade depends on the amperage and welding process." },
  { id:"osha_575", categoria:"OSHA_SOLDADURA", pregunta:"Al realizar soldadura o brazing en sistemas de refrigeración HVAC, ¿cuál es el principal riesgo si no se purga la línea con nitrógeno?", opciones:["La formación de escamas de cobre que obstruyen el sistema de expansión térmico","La generación de óxidos internos que contaminan y bloquean el sistema completo","La cristalización del flux residual que deteriora las juntas de cobre soldadas","La evaporación del aceite lubricante que daña el compresor hermético interno"], respuesta_correcta:1, explicacion:"Al soldar o hacer brazing en tuberías de cobre sin purga de nitrógeno, el calor genera óxidos internos (cascarilla) que contaminan el sistema, bloquean válvulas de expansión, filtros y dañan compresores.", en_pregunta:"When performing welding or brazing on HVAC refrigeration systems, what is the main risk if the line is not purged with nitrogen?", en_opciones:["Formation of copper scale that obstructs the thermal expansion system","Formation of internal oxides that contaminate and block the entire system","Crystallization of residual flux that degrades the brazed copper joints","Evaporation of the lubricant oil that damages the internal hermetic compressor"], en_explicacion:"Brazing or welding copper piping without a nitrogen purge produces internal oxides (scale) that contaminate the system, block expansion valves and filters, and damage compressors." },
  { id:"osha_576", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la función principal de un arrestor de retroceso de llama (flashback arrestor) en un equipo de oxiacetileno?", opciones:["Regular la presión de salida del gas para mantener una llama estable y uniforme","Evitar que la llama retroceda hacia el cilindro y provoque una explosión catastrófica","Filtrar impurezas del gas para que la soldadura sea más limpia y resistente","Controlar el flujo de oxígeno para obtener la mezcla estequiométrica adecuada"], respuesta_correcta:1, explicacion:"El flashback arrestor es un dispositivo de seguridad que impide que una llama de retroceso (flashback) viaje desde el soplete hacia las mangueras y cilindros, previniendo explosiones potencialmente fatales.", en_pregunta:"What is the main function of a flashback arrestor on oxy-acetylene equipment?", en_opciones:["Regulate outlet gas pressure to maintain a stable, uniform flame","Prevent the flame from traveling back to the cylinder and causing a catastrophic explosion","Filter impurities from the gas so the weld is cleaner and stronger","Control oxygen flow to achieve the proper stoichiometric mixture"], en_explicacion:"The flashback arrestor is a safety device that prevents a flashback flame from traveling from the torch into the hoses and cylinders, preventing potentially fatal explosions." },
  { id:"osha_577", categoria:"OSHA_SOLDADURA", pregunta:"¿A qué distancia mínima deben removerse los materiales combustibles del área donde se realizará soldadura o corte con llama?", opciones:["Al menos 25 pies del punto de operación o cubrirse con protecciones ignífugas aprobadas","Al menos 35 pies del punto de operación o cubrirse con protecciones ignífugas aprobadas","Al menos 45 pies del punto de operación o cubrirse con protecciones ignífugas aprobadas","Al menos 55 pies del punto de operación o cubrirse con protecciones ignífugas aprobadas"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.352(a) requiere que los materiales combustibles se muevan al menos 35 pies del área de trabajo. Si no se pueden mover, deben protegerse con cubiertas ignífugas aprobadas.", en_pregunta:"What is the minimum distance combustible materials must be removed from the area where welding or flame cutting will be performed?", en_opciones:["At least 25 feet from the point of operation, or covered with approved fire-resistant protection","At least 35 feet from the point of operation, or covered with approved fire-resistant protection","At least 45 feet from the point of operation, or covered with approved fire-resistant protection","At least 55 feet from the point of operation, or covered with approved fire-resistant protection"], en_explicacion:"OSHA 29 CFR 1926.352(a) requires combustible materials to be moved at least 35 feet from the work area. If they cannot be moved, they must be protected with approved fire-resistant covers." },
  { id:"osha_578", categoria:"OSHA_SOLDADURA", pregunta:"Al soldar en un espacio confinado, ¿qué acción es obligatoria respecto a los cilindros de gas cuando se interrumpe el trabajo?", opciones:["Los cilindros deben colocarse en posición horizontal y asegurar las válvulas con tapones","Los cilindros y las antorchas deben retirarse del espacio confinado inmediatamente","Los cilindros deben purgarse completamente y almacenarse dentro del espacio ventilado","Los cilindros deben cubrirse con mantas ignífugas y dejarse en posición vertical segura"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.353(b)(1) requiere que cuando se interrumpa la soldadura en espacios confinados, los cilindros de gas y las antorchas se retiren del espacio confinado para prevenir acumulación de gases.", en_pregunta:"When welding in a confined space, what action is mandatory regarding gas cylinders when the work is interrupted?", en_opciones:["Cylinders must be placed horizontally and the valves secured with caps","Cylinders and torches must be removed from the confined space immediately","Cylinders must be completely purged and stored inside the ventilated space","Cylinders must be covered with fire blankets and left in a secure upright position"], en_explicacion:"OSHA 29 CFR 1926.353(b)(1) requires that, when welding in confined spaces is interrupted, gas cylinders and torches be removed from the confined space to prevent gas accumulation." },
  { id:"osha_579", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué Subparte del 29 CFR 1926 regula específicamente las operaciones de soldadura y corte en la industria de construcción?", opciones:["La Subparte H que cubre los requisitos de excavaciones y protección contra derrumbes","La Subparte J que establece los estándares de soldadura, corte y trabajo en caliente","La Subparte K que regula los sistemas eléctricos y la protección contra electrocución","La Subparte L que define los requisitos para andamios y plataformas de trabajo elevado"], respuesta_correcta:1, explicacion:"29 CFR 1926 Subpart J — Welding and Cutting cubre todos los requisitos de seguridad para operaciones de soldadura y corte en la industria de la construcción, incluyendo soldadura de gas, arco y brazing.", en_pregunta:"Which Subpart of 29 CFR 1926 specifically regulates welding and cutting operations in the construction industry?", en_opciones:["Subpart H, which covers excavation requirements and protection against cave-ins","Subpart J, which establishes standards for welding, cutting, and hot work","Subpart K, which regulates electrical systems and protection against electrocution","Subpart L, which defines requirements for scaffolds and elevated work platforms"], en_explicacion:"29 CFR 1926 Subpart J — Welding and Cutting covers all safety requirements for welding and cutting operations in the construction industry, including gas welding, arc welding, and brazing." },
  { id:"osha_580", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la ventilación mínima requerida por OSHA para soldadura en espacios interiores sin ventilación mecánica local?", opciones:["Al menos 5,000 pies cúbicos de aire por cada soldador que esté trabajando activamente","Al menos 10,000 pies cúbicos de aire por cada soldador que esté trabajando activamente","Al menos 15,000 pies cúbicos de aire por cada soldador que esté trabajando activamente","Al menos 20,000 pies cúbicos de aire por cada soldador que esté trabajando activamente"], respuesta_correcta:1, explicacion:"OSHA requiere un mínimo de 10,000 pies cúbicos de aire por soldador cuando se realiza soldadura en interiores sin ventilación mecánica local, para asegurar dilución adecuada de humos y gases.", en_pregunta:"What is the minimum ventilation OSHA requires for welding indoors without local mechanical ventilation?", en_opciones:["At least 5,000 cubic feet of air per welder actively working","At least 10,000 cubic feet of air per welder actively working","At least 15,000 cubic feet of air per welder actively working","At least 20,000 cubic feet of air per welder actively working"], en_explicacion:"OSHA requires a minimum of 10,000 cubic feet of air per welder when welding indoors without local mechanical ventilation, to ensure adequate dilution of fumes and gases." },
  { id:"osha_581", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué tipo de extintor debe estar disponible inmediatamente en el área donde se realizan operaciones de soldadura y corte?", opciones:["Extintor tipo A de agua presurizada con capacidad mínima de 5 galones certificados","Extintor tipo ABC con clasificación mínima 2A-10B:C en condiciones operativas listas","Extintor tipo B de espuma mecánica con capacidad mínima de 2.5 galones certificados","Extintor tipo D de polvo especial con clasificación para metales combustibles activos"], respuesta_correcta:1, explicacion:"OSHA requiere que haya extintores tipo ABC disponibles en el área de soldadura y corte. La clasificación 2A-10B:C es el estándar mínimo para cubrir los tipos de fuego más comunes en estas operaciones.", en_pregunta:"What type of fire extinguisher must be immediately available in the area where welding and cutting operations are performed?", en_opciones:["Type A pressurized water extinguisher with a minimum capacity of 5 certified gallons","Type ABC extinguisher with minimum 2A-10B:C rating in ready operating condition","Type B mechanical-foam extinguisher with a minimum of 2.5 certified gallons","Type D special powder extinguisher rated for active combustible metals"], en_explicacion:"OSHA requires Type ABC extinguishers to be available in the welding and cutting area. The 2A-10B:C rating is the minimum standard to cover the most common types of fires in these operations." },
  { id:"osha_582", categoria:"OSHA_SOLDADURA", pregunta:"Al realizar brazing con aleación de plata (silver brazing) en tuberías HVAC, ¿cuál es la principal preocupación de salud ocupacional?", opciones:["La inhalación de partículas de cobre fundido que causa fiebre de los metales pesados","La exposición a vapores de cadmio presentes en algunas aleaciones de plata antiguas","La absorción cutánea del flux ácido que provoca dermatitis química irreversible","La radiación infrarroja del soplete que genera cataratas térmicas ocupacionales"], respuesta_correcta:1, explicacion:"Algunas aleaciones de plata para brazing contienen cadmio, cuyos vapores son extremadamente tóxicos. La exposición a humos de cadmio puede causar daño pulmonar severo y es potencialmente fatal incluso en bajas concentraciones.", en_pregunta:"When performing silver brazing on HVAC piping, what is the main occupational health concern?", en_opciones:["Inhalation of molten copper particles causing heavy-metal fume fever","Exposure to cadmium fumes present in some older silver brazing alloys","Skin absorption of acid flux causing irreversible chemical dermatitis","Infrared radiation from the torch causing occupational thermal cataracts"], en_explicacion:"Some silver brazing alloys contain cadmium, whose fumes are extremely toxic. Cadmium fume exposure can cause severe lung damage and can be fatal even at low concentrations." },
  { id:"osha_583", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la posición correcta para almacenar cilindros de gas comprimido según las normas OSHA de seguridad?", opciones:["En posición horizontal con cuñas de bloqueo y cadenas de seguridad en ambos extremos","En posición vertical asegurados con cadenas o correas para evitar que se caigan","En posición inclinada a 45 grados con el regulador apuntando hacia abajo por seguridad","En posición horizontal solo si están vacíos y vertical únicamente cuando están llenos"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.350(a)(9) requiere que los cilindros se almacenen en posición vertical y asegurados con cadenas, correas o en portacilindros para prevenir caídas que podrían dañar la válvula y causar una proyección peligrosa.", en_pregunta:"What is the correct position for storing compressed-gas cylinders per OSHA safety rules?", en_opciones:["Horizontally with chock blocks and safety chains at both ends","Upright and secured with chains or straps to prevent them from falling","At a 45-degree angle with the regulator pointing downward for safety","Horizontally only when empty and upright only when full"], en_explicacion:"OSHA 29 CFR 1926.350(a)(9) requires cylinders to be stored upright and secured with chains, straps, or in cylinder racks to prevent falls that could damage the valve and cause a dangerous projectile." },
  { id:"osha_584", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué debe verificarse ANTES de encender un soplete de oxiacetileno al inicio de cada turno de trabajo?", opciones:["Que las mangueras tengan el color correcto y que los manómetros marquen presión de trabajo","Que todas las conexiones estén apretadas y no existan fugas verificadas con agua jabonosa","Que los cilindros estén llenos al menos al 50% de su capacidad total de almacenamiento","Que el área tenga ventilación cruzada natural con un mínimo de tres aberturas visibles"], respuesta_correcta:1, explicacion:"Antes de usar un equipo de oxiacetileno, se debe verificar que todas las conexiones estén seguras y hacer prueba de fugas con solución jabonosa. Nunca se debe usar llama para detectar fugas en conexiones de gas.", en_pregunta:"What must be verified BEFORE lighting an oxy-acetylene torch at the start of each work shift?", en_opciones:["That the hoses are the correct color and the gauges read working pressure","That all connections are tight and there are no leaks, verified with soapy water","That the cylinders are filled to at least 50% of their total capacity","That the area has natural cross-ventilation with a minimum of three visible openings"], en_explicacion:"Before using oxy-acetylene equipment, all connections must be verified secure and a leak test performed with soapy solution. A flame must never be used to detect leaks on gas connections." },
  { id:"osha_585", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuándo se requiere obligatoriamente el uso de respirador durante operaciones de soldadura según OSHA?", opciones:["Siempre que se suelde cualquier tipo de material sin importar la ubicación del trabajo","Cuando la ventilación no es suficiente para mantener los humos debajo de los PEL establecidos","Únicamente cuando se trabaja con acero inoxidable o metales que contengan aleaciones de cromo","Solo en espacios confinados donde la concentración de oxígeno es inferior al 21 por ciento"], respuesta_correcta:1, explicacion:"OSHA requiere respirador cuando la ventilación (natural o mecánica) no es suficiente para mantener la exposición a humos de soldadura por debajo de los Límites de Exposición Permisibles (PEL) establecidos para cada sustancia.", en_pregunta:"When is a respirator required during welding operations under OSHA?", en_opciones:["Always when welding any type of material regardless of work location","When ventilation is not sufficient to keep fumes below the established PELs","Only when working with stainless steel or metals containing chromium alloys","Only in confined spaces where the oxygen concentration is below 21 percent"], en_explicacion:"OSHA requires a respirator when ventilation (natural or mechanical) is not sufficient to keep exposure to welding fumes below the Permissible Exposure Limits (PELs) established for each substance." },
  { id:"osha_586", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué color de manguera identifica el suministro de acetileno en un equipo estándar de oxiacetileno en Estados Unidos?", opciones:["La manguera verde identifica el acetileno y tiene conexiones con rosca estándar derecha","La manguera roja identifica el acetileno y tiene conexiones con rosca izquierda especial","La manguera negra identifica el acetileno y tiene conexiones con rosca estándar derecha","La manguera azul identifica el acetileno y tiene conexiones con rosca izquierda especial"], respuesta_correcta:1, explicacion:"En Estados Unidos, la manguera roja es para acetileno (combustible) con conexiones de rosca izquierda, y la manguera verde es para oxígeno con conexiones de rosca derecha. Esta diferencia previene conexiones cruzadas accidentales.", en_pregunta:"Which hose color identifies the acetylene supply on standard oxy-acetylene equipment in the United States?", en_opciones:["The green hose identifies acetylene and has standard right-hand thread connections","The red hose identifies acetylene and has special left-hand thread connections","The black hose identifies acetylene and has standard right-hand thread connections","The blue hose identifies acetylene and has special left-hand thread connections"], en_explicacion:"In the United States, the red hose is for acetylene (fuel) with left-hand thread connections, and the green hose is for oxygen with right-hand thread connections. This difference prevents accidental cross-connections." },
  { id:"osha_587", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es el procedimiento correcto si la válvula de un cilindro de acetileno no se puede abrir con la mano?", opciones:["Usar una llave ajustable estándar de 12 pulgadas para aplicar torque adicional controlado","Devolver el cilindro al proveedor marcándolo como defectuoso sin intentar forzar la válvula","Aplicar aceite penetrante en la rosca de la válvula y esperar 10 minutos antes de reintentar","Calentar levemente la válvula con agua tibia para expandir el metal y facilitar la apertura"], respuesta_correcta:1, explicacion:"Si la válvula de un cilindro no se puede abrir manualmente, NO se debe forzar. Se debe marcar como defectuoso y devolver al proveedor. Nunca aplicar aceite (riesgo de ignición con oxígeno) ni calentar cilindros de gas.", en_pregunta:"What is the correct procedure if an acetylene cylinder valve cannot be opened by hand?", en_opciones:["Use a standard 12-inch adjustable wrench to apply additional controlled torque","Return the cylinder to the supplier marked as defective without forcing the valve","Apply penetrating oil to the valve thread and wait 10 minutes before trying again","Lightly warm the valve with warm water to expand the metal and ease opening"], en_explicacion:"If a cylinder valve cannot be opened by hand, it must NOT be forced. Mark it as defective and return it to the supplier. Never apply oil (ignition risk with oxygen) or heat gas cylinders." },
  { id:"osha_588", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuántas vueltas máximo debe abrirse la válvula de un cilindro de acetileno durante su uso en operaciones normales?", opciones:["Máximo media vuelta para poder cerrarla rápidamente en caso de una emergencia imprevista","Máximo una vuelta y media para permitir flujo adecuado y cierre rápido de seguridad","Máximo dos vueltas completas para asegurar el flujo constante durante toda la operación","Máximo tres vueltas completas ya que el diseño de la válvula limita el flujo naturalmente"], respuesta_correcta:1, explicacion:"La válvula del cilindro de acetileno debe abrirse máximo 1½ vueltas (algunos estándares dicen ¾ a 1½) para permitir un cierre rápido en caso de emergencia. La llave siempre debe permanecer en la válvula durante el uso.", en_pregunta:"How many turns, maximum, should an acetylene cylinder valve be opened during normal use?", en_opciones:["Half a turn maximum so it can be closed quickly in an unforeseen emergency","No more than one and a half turns to allow adequate flow and quick safety shutoff","A maximum of two full turns to ensure constant flow throughout the operation","A maximum of three full turns, since the valve design naturally limits flow"], en_explicacion:"The acetylene cylinder valve should be opened no more than 1½ turns (some standards say ¾ to 1½) to allow rapid closure in an emergency. The wrench must remain on the valve during use." },
  { id:"osha_589", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué condición del área de trabajo requiere obligatoriamente un vigía de incendios (fire watch) durante soldadura?", opciones:["Cuando hay materiales inflamables almacenados a más de 50 pies del punto de soldadura","Cuando existen combustibles a menos de 35 pies que no pueden moverse ni cubrirse totalmente","Cuando la temperatura ambiente supera los 90°F y la humedad relativa está debajo del 30%","Cuando se trabaja en exteriores con velocidad de viento superior a 15 millas por hora"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.352(e) requiere fire watch cuando hay combustibles dentro de 35 pies que no pueden removerse ni protegerse adecuadamente con cubiertas ignífugas. El vigía debe tener extintor disponible.", en_pregunta:"What work-area condition makes a fire watch mandatory during welding?", en_opciones:["When flammable materials are stored more than 50 feet from the welding point","When combustibles are within 35 feet and cannot be moved or fully covered","When the ambient temperature exceeds 90°F and relative humidity is below 30%","When working outdoors with wind speed above 15 miles per hour"], en_explicacion:"OSHA 29 CFR 1926.352(e) requires a fire watch when combustibles are within 35 feet and cannot be removed or adequately covered with fire-resistant protection. The watcher must have an extinguisher available." },
  { id:"osha_590", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué tipo de lesión ocular causa la exposición a radiación ultravioleta del arco de soldadura sin protección adecuada?", opciones:["Glaucoma agudo por el aumento de presión intraocular causado por la radiación directa","Fotoqueratitis conocida como ojo de soldador que inflama la córnea temporalmente dolorosa","Degeneración macular instantánea que destruye permanentemente la visión central del ojo","Desprendimiento de retina causado por la contracción térmica del humor vítreo interno"], respuesta_correcta:1, explicacion:"La exposición a radiación UV del arco de soldadura causa fotoqueratitis (arc eye/welder's flash), una inflamación dolorosa de la córnea. Los síntomas aparecen horas después y generalmente se resuelven en 24-72 horas.", en_pregunta:"What type of eye injury is caused by exposure to ultraviolet radiation from a welding arc without proper protection?", en_opciones:["Acute glaucoma from increased intraocular pressure caused by direct radiation","Photokeratitis (welder's flash/arc eye), a painful temporary inflammation of the cornea","Instant macular degeneration that permanently destroys the eye's central vision","Retinal detachment caused by thermal contraction of the internal vitreous humor"], en_explicacion:"Exposure to UV radiation from the welding arc causes photokeratitis (arc eye/welder's flash), a painful inflammation of the cornea. Symptoms appear hours later and usually resolve within 24-72 hours." },
  { id:"osha_591", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es el riesgo principal de usar oxígeno para ventilar un espacio confinado antes de realizar soldadura?", opciones:["El oxígeno puro desplaza el nitrógeno y causa síntomas de narcosis similares a la embriaguez","El exceso de oxígeno crea una atmósfera enriquecida donde materiales normales arden con violencia","El oxígeno reacciona con el dióxido de carbono residual formando ácido carbónico tóxico irritante","El oxígeno comprimido genera electricidad estática que puede provocar chispas dentro del espacio"], respuesta_correcta:1, explicacion:"NUNCA se debe usar oxígeno para ventilar. Una atmósfera enriquecida con oxígeno (>23.5%) hace que materiales normalmente no combustibles, como ropa y cabello, ardan violentamente. Solo se debe ventilar con aire limpio.", en_pregunta:"What is the main risk of using oxygen to ventilate a confined space before welding?", en_opciones:["Pure oxygen displaces nitrogen and produces narcosis symptoms similar to intoxication","Excess oxygen creates an enriched atmosphere where normal materials burn violently","Oxygen reacts with residual carbon dioxide forming toxic irritant carbonic acid","Compressed oxygen generates static electricity that can spark inside the space"], en_explicacion:"Oxygen must NEVER be used to ventilate. An oxygen-enriched atmosphere (>23.5%) makes normally non-combustible materials, such as clothing and hair, burn violently. Only clean air must be used for ventilation." },
  { id:"osha_592", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué protección personal adicional se requiere cuando se realiza soldadura sobre superficies que contienen pintura con plomo?", opciones:["Guantes de neopreno de doble capa y traje de protección química con sellado hermético total","Respirador con filtros HEPA para partículas y monitoreo de plomo en sangre periódicamente","Gafas con filtro especial para radiación gamma y delantal de plomo como protección adicional","Botas con suela de goma conductiva y pulsera antiestática conectada al sistema de tierra"], respuesta_correcta:1, explicacion:"Al soldar sobre superficies con pintura de plomo, los humos de plomo son altamente tóxicos. Se requiere respirador con filtros HEPA (P100), y OSHA exige monitoreo médico de plomo en sangre para trabajadores expuestos.", en_pregunta:"What additional personal protection is required when welding on surfaces containing lead-based paint?", en_opciones:["Double-layer neoprene gloves and a fully sealed chemical protection suit","Respirator with HEPA particulate filters and periodic blood-lead monitoring","Goggles with a special gamma-radiation filter and a lead apron as extra protection","Boots with conductive rubber soles and an antistatic wrist strap grounded to the system"], en_explicacion:"When welding on surfaces with lead paint, lead fumes are highly toxic. A respirator with HEPA (P100) filters is required, and OSHA requires medical blood-lead monitoring for exposed workers." },
  { id:"osha_593", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué debe hacerse con los tapones protectores de las válvulas de cilindros de gas cuando no están conectados a reguladores?", opciones:["Guardarlos en una caja de herramientas cercana para tenerlos accesibles cuando se necesiten","Mantenerlos siempre colocados y ajustados a mano para proteger la válvula contra daños físicos","Colgarlos de la cadena de seguridad del cilindro para evitar que se pierdan en el área de trabajo","Almacenarlos en el cuarto de herramientas junto con los reguladores y mangueras de repuesto"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.350(a)(1) requiere que los tapones protectores de válvulas estén siempre colocados cuando los cilindros no están en uso o conectados a reguladores. Protegen la válvula de daños que podrían causar liberación violenta de gas.", en_pregunta:"What must be done with the protective caps on gas cylinder valves when they are not connected to regulators?", en_opciones:["Store them in a nearby toolbox so they are accessible when needed","Always keep them in place and hand-tight to protect the valve from physical damage","Hang them from the cylinder's safety chain to prevent losing them in the work area","Store them in the tool room along with spare regulators and hoses"], en_explicacion:"OSHA 29 CFR 1926.350(a)(1) requires valve protection caps to always be in place when cylinders are not in use or connected to regulators. They protect the valve from damage that could cause violent gas release." },
  { id:"osha_594", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es el shade mínimo recomendado para operaciones de corte con oxiacetileno en espesores medianos de acero?", opciones:["Shade número 2 que ofrece protección básica suficiente contra el resplandor del corte térmico","Shade número 4 que filtra adecuadamente la radiación generada durante el corte con oxicombustible","Shade número 6 que proporciona mayor contraste visual manteniendo protección ocular apropiada","Shade número 8 que es el estándar universal obligatorio para cualquier tipo de operación térmica"], respuesta_correcta:1, explicacion:"Para corte con oxiacetileno en espesores medianos, se recomienda shade #4 o #5. El shade requerido para corte es menor que para soldadura por arco porque la intensidad luminosa del corte es significativamente menor.", en_pregunta:"What is the minimum recommended shade for oxy-acetylene cutting operations on medium-thickness steel?", en_opciones:["Shade #2, which provides basic protection sufficient against thermal cutting glare","Shade #4, which adequately filters the radiation generated during oxy-fuel cutting","Shade #6, which provides greater visual contrast while maintaining proper eye protection","Shade #8, which is the universal mandatory standard for any type of thermal operation"], en_explicacion:"For oxy-acetylene cutting on medium thicknesses, shade #4 or #5 is recommended. The required shade for cutting is lower than for arc welding because cutting light intensity is significantly lower." },
  { id:"osha_595", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es el procedimiento correcto para mover un cilindro de gas comprimido dentro del sitio de trabajo?", opciones:["Rodarlo sobre su borde inferior inclinándolo levemente y empujando en la dirección deseada","Transportarlo en posición vertical usando un carro porta-cilindros con cadena de seguridad","Arrastrarlo horizontalmente sobre el piso asegurándose de que la válvula no golpee obstáculos","Cargarlo al hombro si pesa menos de 100 libras y la distancia es menor a 50 pies totales"], respuesta_correcta:1, explicacion:"Los cilindros de gas deben transportarse en posición vertical en un carro porta-cilindros (hand truck) con cadena de seguridad. Nunca deben arrastrarse, rodarse sin control ni cargarse al hombro. Los tapones de válvula deben estar puestos.", en_pregunta:"What is the correct procedure for moving a compressed-gas cylinder within the work site?", en_opciones:["Roll it on its bottom edge by tilting it slightly and pushing in the desired direction","Transport it upright on a cylinder hand truck with a safety chain","Drag it horizontally across the floor, making sure the valve does not strike obstacles","Carry it on the shoulder if it weighs less than 100 pounds and the distance is under 50 feet"], en_explicacion:"Gas cylinders must be transported upright on a cylinder hand truck with a safety chain. They must never be dragged, rolled uncontrolled, or carried on the shoulder. Valve caps must be in place." },
  { id:"osha_596", categoria:"OSHA_SOLDADURA", pregunta:"Al soldar tuberías de refrigeración en HVAC, ¿por qué se debe evacuar el refrigerante antes de aplicar calor con soplete?", opciones:["Porque el refrigerante líquido puede expandirse y crear una explosión hidráulica en la tubería","Porque ciertos refrigerantes al exponerse a llama abierta generan gas fosgeno altamente tóxico","Porque el gas refrigerante impide que la soldadura de plata fluya correctamente por capilaridad","Porque la presión residual del refrigerante puede apagar la llama del soplete repetidamente"], respuesta_correcta:1, explicacion:"Refrigerantes halogenados (como R-22, R-410A) al descomponerse por llama abierta producen gas fosgeno y ácido fluorhídrico, ambos extremadamente tóxicos. Siempre se debe recuperar el refrigerante antes de soldar.", en_pregunta:"When brazing refrigeration piping in HVAC, why must the refrigerant be evacuated before applying heat with a torch?", en_opciones:["Because liquid refrigerant can expand and cause a hydraulic explosion in the tubing","Because certain refrigerants exposed to open flame generate highly toxic phosgene gas","Because refrigerant gas prevents silver brazing alloy from flowing properly by capillarity","Because residual refrigerant pressure can repeatedly blow out the torch flame"], en_explicacion:"Halogenated refrigerants (such as R-22, R-410A) decompose under open flame to produce phosgene gas and hydrofluoric acid, both extremely toxic. Refrigerant must always be recovered before brazing." },
  { id:"osha_597", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué debe verificar un soldador antes de iniciar soldadura por arco eléctrico respecto al equipo y su conexión a tierra?", opciones:["Que el voltaje de circuito abierto no exceda 50 voltios en corriente alterna para mayor seguridad","Que la pinza de tierra esté conectada firmemente a la pieza de trabajo o mesa de soldadura metálica","Que los electrodos estén almacenados en un horno a 250°F durante al menos dos horas completas","Que la máquina de soldar tenga fusibles de respaldo adicionales instalados en el panel eléctrico"], respuesta_correcta:1, explicacion:"La conexión a tierra (work clamp/ground clamp) debe estar firmemente conectada a la pieza de trabajo o a la mesa metálica. Una mala conexión a tierra causa arcos erráticos, daño al equipo y riesgo de electrocución.", en_pregunta:"What must a welder verify before starting arc welding regarding the equipment and its grounding?", en_opciones:["That the open-circuit voltage does not exceed 50 volts AC for added safety","That the work clamp is firmly connected to the workpiece or metal welding table","That the electrodes are stored in an oven at 250°F for at least two full hours","That the welding machine has additional backup fuses installed in the electrical panel"], en_explicacion:"The work clamp/ground clamp must be firmly connected to the workpiece or metal table. A poor ground connection causes erratic arcs, equipment damage, and electrocution risk." },
  { id:"osha_598", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la concentración mínima de oxígeno en la atmósfera de un espacio confinado para permitir operaciones de soldadura?", opciones:["La concentración de oxígeno debe estar entre 18.5% y 21.5% antes de autorizar la entrada","La concentración de oxígeno debe estar entre 19.5% y 23.5% antes de autorizar la entrada","La concentración de oxígeno debe estar entre 20.5% y 24.5% antes de autorizar la entrada","La concentración de oxígeno debe estar entre 21.5% y 25.5% antes de autorizar la entrada"], respuesta_correcta:1, explicacion:"Para entrada y trabajo en espacios confinados, la concentración de oxígeno debe estar entre 19.5% y 23.5%. Menos de 19.5% es deficiente de oxígeno y más de 23.5% es enriquecida, ambas condiciones son peligrosas para soldadura.", en_pregunta:"What is the required oxygen concentration in a confined-space atmosphere to allow welding operations?", en_opciones:["Oxygen concentration must be between 18.5% and 21.5% before entry is authorized","Oxygen concentration must be between 19.5% and 23.5% before entry is authorized","Oxygen concentration must be between 20.5% and 24.5% before entry is authorized","Oxygen concentration must be between 21.5% and 25.5% before entry is authorized"], en_explicacion:"For entry and work in confined spaces, oxygen concentration must be between 19.5% and 23.5%. Below 19.5% is oxygen-deficient and above 23.5% is oxygen-enriched — both conditions are dangerous for welding." },
  { id:"osha_599", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué tipo de guantes son apropiados para operaciones de soldadura con arco eléctrico según los estándares OSHA?", opciones:["Guantes de algodón grueso tratados con retardante de fuego y forro interior absorbente","Guantes de cuero resistentes al calor con aislamiento eléctrico y sin agujeros ni defectos","Guantes de neopreno de alta temperatura con refuerzo de kevlar en palma y los dedos","Guantes de nitrilo industrial de doble capa con protección contra corte nivel A4 mínimo"], respuesta_correcta:1, explicacion:"Para soldadura por arco se requieren guantes de cuero (leather welding gloves) que sean resistentes al calor y proporcionen aislamiento eléctrico. Deben estar en buenas condiciones sin agujeros, grietas o defectos.", en_pregunta:"What type of gloves is appropriate for arc welding operations under OSHA standards?", en_opciones:["Thick cotton gloves treated with flame retardant and an absorbent inner liner","Heat-resistant leather gloves with electrical insulation and no holes or defects","High-temperature neoprene gloves with Kevlar reinforcement on the palm and fingers","Industrial double-layer nitrile gloves with minimum A4 cut protection"], en_explicacion:"Arc welding requires leather welding gloves that are heat-resistant and provide electrical insulation. They must be in good condition with no holes, cracks, or defects." },
  { id:"osha_600", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué precaución especial se debe tomar al soldar o cortar contenedores que hayan almacenado materiales combustibles?", opciones:["Llenar el contenedor con arena seca hasta el nivel de corte para absorber cualquier residuo inflamable","Limpiar con vapor o solución química y verificar con detector de gases antes de soldar o cortar","Perforar múltiples agujeros de ventilación en la parte superior para permitir el escape de vapores","Sumergir completamente el contenedor en agua dejando expuesta solo el área de corte o soldadura"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.352(i) requiere que contenedores que almacenaron combustibles se limpien con vapor o solución química y se verifiquen con detector de gases inflamables antes de soldar o cortar, para prevenir explosiones.", en_pregunta:"What special precaution must be taken when welding or cutting containers that have held combustible materials?", en_opciones:["Fill the container with dry sand up to the cut line to absorb any flammable residue","Clean with steam or chemical solution and verify with a gas detector before welding or cutting","Drill multiple vent holes in the top to allow vapor escape","Completely submerge the container in water, leaving only the cut or weld area exposed"], en_explicacion:"OSHA 29 CFR 1926.352(i) requires containers that held combustibles to be cleaned with steam or chemical solution and checked with a combustible-gas detector before welding or cutting, to prevent explosions." },
  { id:"osha_601", categoria:"OSHA_SOLDADURA", pregunta:"¿Cuál es la distancia mínima que debe haber entre un cilindro de gas y una fuente de calor o llama abierta?", opciones:["Al menos 10 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 20 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 30 pies de distancia de cualquier fuente de calor o llama durante las operaciones","Al menos 40 pies de distancia de cualquier fuente de calor o llama durante las operaciones"], respuesta_correcta:1, explicacion:"Los cilindros de gas deben mantenerse a un mínimo de 20 pies de fuentes de calor o llama abierta para prevenir sobrecalentamiento que podría causar aumento peligroso de presión o falla catastrófica del cilindro.", en_pregunta:"What is the minimum distance between a gas cylinder and a heat source or open flame?", en_opciones:["At least 10 feet from any heat source or flame during operations","At least 20 feet from any heat source or flame during operations","At least 30 feet from any heat source or flame during operations","At least 40 feet from any heat source or flame during operations"], en_explicacion:"Gas cylinders must be kept a minimum of 20 feet from heat sources or open flames to prevent overheating that could cause a dangerous pressure rise or catastrophic cylinder failure." },
  { id:"osha_602", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué indica una llama de oxiacetileno con exceso de acetileno (llama carburante) durante operaciones de soldadura?", opciones:["Una llama azul intensa y corta que produce temperaturas excesivas y quema el metal base rápidamente","Una llama con pluma blanca alargada que agrega carbono al metal y produce soldaduras porosas débiles","Una llama verde oscura con chispas que indica obstrucción parcial de la boquilla del soplete usado","Una llama pulsante intermitente que señala presión insuficiente en el regulador de oxígeno puro"], respuesta_correcta:1, explicacion:"Una llama carburante (con exceso de acetileno) tiene una pluma blanca característica alrededor del cono interno. Esta llama agrega carbono al metal, produciendo soldaduras frágiles, porosas y de baja calidad.", en_pregunta:"What does an oxy-acetylene flame with excess acetylene (carburizing flame) indicate during welding operations?", en_opciones:["An intense, short blue flame producing excessive temperatures and quickly burning the base metal","A flame with an elongated white feather that adds carbon to the metal and produces weak, porous welds","A dark-green flame with sparks indicating a partially clogged torch tip","A pulsing, intermittent flame signaling insufficient pressure on the pure-oxygen regulator"], en_explicacion:"A carburizing flame (with excess acetylene) has a characteristic white feather around the inner cone. This flame adds carbon to the metal, producing brittle, porous, low-quality welds." },
  { id:"osha_603", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué acción inmediata se debe tomar si se detecta una fuga de gas en una manguera de oxiacetileno durante el uso?", opciones:["Aplicar cinta de teflón en el área de la fuga y continuar trabajando si la fuga es pequeña y manejable","Cerrar las válvulas de ambos cilindros inmediatamente y no usar el equipo hasta reparar la manguera","Sumergir la sección de manguera con fuga en un balde con agua para sellar temporalmente la grieta","Aumentar la presión del regulador para compensar la pérdida de gas causada por la fuga detectada"], respuesta_correcta:1, explicacion:"Ante cualquier fuga en mangueras de oxiacetileno, se deben cerrar inmediatamente las válvulas de ambos cilindros. Nunca reparar con cinta ni continuar usando equipo con fugas, ya que hay riesgo de incendio o explosión.", en_pregunta:"What immediate action should be taken if a gas leak is detected on an oxy-acetylene hose during use?", en_opciones:["Apply Teflon tape to the leak area and keep working if the leak is small and manageable","Immediately close both cylinder valves and stop using the equipment until the hose is repaired","Submerge the leaking hose section in a bucket of water to temporarily seal the crack","Increase the regulator pressure to compensate for the gas loss caused by the leak"], en_explicacion:"On any leak in an oxy-acetylene hose, both cylinder valves must be closed immediately. Never repair with tape or continue using leaking equipment due to fire or explosion risk." },
  { id:"osha_604", categoria:"OSHA_SOLDADURA", pregunta:"¿Qué requisito especial aplica OSHA para soldadura en pisos elevados o plataformas donde pueden caer chispas y escoria?", opciones:["Instalar sistemas de rociadores automáticos directamente debajo del área de soldadura en pisos elevados","Colocar protecciones ignífugas debajo del área de trabajo y asignar fire watch en el nivel inferior","Restringir todo el acceso al edificio durante operaciones de soldadura en cualquier nivel superior","Aplicar pintura intumescente en todas las superficies de madera dentro de un radio de cien pies"], respuesta_correcta:1, explicacion:"OSHA requiere que se coloquen cubiertas ignífugas debajo del área de soldadura en pisos elevados para atrapar chispas y escoria, además de asignar un vigía de incendios (fire watch) en los niveles inferiores expuestos.", en_pregunta:"What special OSHA requirement applies to welding on elevated floors or platforms where sparks and slag may fall?", en_opciones:["Install automatic sprinkler systems directly below the welding area on elevated floors","Place fire-resistant protection below the work area and assign a fire watch on the lower level","Restrict all access to the building during welding operations on any upper level","Apply intumescent paint on all wood surfaces within a 100-foot radius"], en_explicacion:"OSHA requires fire-resistant covers to be placed below the welding area on elevated floors to catch sparks and slag, and a fire watch must be assigned on exposed lower levels." },

  { id:"osha_605", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA 29 CFR 1926 Subpart P, a partir de que profundidad se requiere un sistema de proteccion en una excavacion?", opciones:["A partir de los 4 pies de profundidad","A partir de los 5 pies de profundidad","A partir de los 6 pies de profundidad","A partir de los 8 pies de profundidad"], respuesta_correcta:1, explicacion:"OSHA requiere sistemas de proteccion (sloping, shoring o shielding) cuando la excavacion alcanza 5 pies (1.52 m) de profundidad o mas, a menos que la excavacion este hecha completamente en roca estable.", en_pregunta:"Per OSHA 29 CFR 1926 Subpart P, at what depth is a protective system required in an excavation?", en_opciones:["Starting at 4 feet deep","Starting at 5 feet deep","Starting at 6 feet deep","Starting at 8 feet deep"], en_explicacion:"OSHA requires protective systems (sloping, shoring, or shielding) when an excavation reaches 5 feet (1.52 m) deep or more, unless the excavation is made entirely in stable rock." },
  { id:"osha_606", categoria:"OSHA_EXCAVACIONES", pregunta:"Cual es la clasificacion de suelo MAS estable segun el sistema de clasificacion de OSHA para excavaciones?", opciones:["El suelo Tipo B es el mas estable de todos","El suelo Tipo C es el mas estable de todos","El suelo Tipo A es el mas estable de todos","La roca estable y el Tipo B son iguales"], respuesta_correcta:2, explicacion:"La clasificacion de OSHA va de mas estable a menos estable: Roca Estable, Tipo A, Tipo B y Tipo C. El Tipo A (arcilla dura, por ejemplo) es el suelo mas estable, excluyendo la roca estable que es una categoria separada.", en_pregunta:"Which is the MOST stable soil classification under OSHA's excavation classification system?", en_opciones:["Type B is the most stable of all","Type C is the most stable of all","Type A is the most stable of all","Stable rock and Type B are equal"], en_explicacion:"OSHA's classification ranges from most to least stable: Stable Rock, Type A, Type B, and Type C. Type A (for example, hard clay) is the most stable soil, excluding stable rock which is a separate category." },
  { id:"osha_607", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, cual es el angulo maximo de inclinacion (sloping) permitido para una excavacion en suelo Tipo C?", opciones:["No mas de 1:1 que equivale a 45 grados","No mas de 1.5:1 equivalente a 34 grados","No mas de 1.5:1 equivalente a 53 grados","No mas de 0.75:1 equivale a 53 grados"], respuesta_correcta:1, explicacion:"Para suelo Tipo C, OSHA requiere un angulo de inclinacion no mas empinado que 1.5H:1V (1.5 horizontal por cada 1 vertical), lo que equivale a aproximadamente 34 grados respecto a la horizontal.", en_pregunta:"According to OSHA, what is the maximum sloping angle allowed for an excavation in Type C soil?", en_opciones:["No more than 1:1, which equals 45 degrees","No more than 1.5:1, equivalent to 34 degrees","No more than 1.5:1, equivalent to 53 degrees","No more than 0.75:1, equivalent to 53 degrees"], en_explicacion:"For Type C soil, OSHA requires a slope no steeper than 1.5H:1V (1.5 horizontal per 1 vertical), which equals approximately 34 degrees from horizontal." },
  { id:"osha_608", categoria:"OSHA_EXCAVACIONES", pregunta:"A que distancia maxima debe haber un medio de acceso o salida (escalera, rampa) en una zanja para que los trabajadores puedan evacuar?", opciones:["No mas de 50 pies de distancia lateral","No mas de 30 pies de distancia lateral","No mas de 25 pies de distancia lateral","No mas de 20 pies de distancia lateral"], respuesta_correcta:2, explicacion:"OSHA 1926.651(c)(2) requiere que en zanjas de 4 pies o mas de profundidad, los medios de salida (escaleras, rampas o escalones) no esten a mas de 25 pies de distancia lateral de cualquier trabajador.", en_pregunta:"What is the maximum lateral distance to a means of access or egress (ladder, ramp) in a trench so workers can evacuate?", en_opciones:["No more than 50 feet laterally","No more than 30 feet laterally","No more than 25 feet laterally","No more than 20 feet laterally"], en_explicacion:"OSHA 1926.651(c)(2) requires that in trenches 4 feet deep or more, means of egress (ladders, ramps, or steps) must not be more than 25 feet laterally from any worker." },
  { id:"osha_609", categoria:"OSHA_EXCAVACIONES", pregunta:"Quien es responsable de clasificar el tipo de suelo y determinar las medidas de proteccion necesarias en una excavacion segun OSHA?", opciones:["El supervisor general de la obra completa","La persona competente designada por el empleador","El ingeniero de seguridad del estado vigente","El inspector de OSHA asignado al proyecto"], respuesta_correcta:1, explicacion:"OSHA 1926.650 y 1926.651 requieren que una 'persona competente' (competent person) designada por el empleador clasifique el suelo, inspeccione la excavacion y determine las medidas de proteccion adecuadas.", en_pregunta:"Who is responsible for classifying the soil type and determining the necessary protective measures in an excavation under OSHA?", en_opciones:["The general site supervisor","The competent person designated by the employer","The state safety engineer on duty","The OSHA inspector assigned to the project"], en_explicacion:"OSHA 1926.650 and 1926.651 require a 'competent person' designated by the employer to classify the soil, inspect the excavation, and determine the appropriate protective measures." },
  { id:"osha_610", categoria:"OSHA_EXCAVACIONES", pregunta:"Con que frecuencia debe la persona competente inspeccionar una excavacion segun los requisitos de OSHA Subpart P?", opciones:["Semanalmente y despues de cada tormenta fuerte","Cada 48 horas y al inicio de cada turno nuevo","Diariamente y despues de eventos como lluvias","Mensualmente y cuando cambian las condiciones"], respuesta_correcta:2, explicacion:"OSHA 1926.651(k)(1) requiere que la persona competente inspeccione las excavaciones diariamente antes de cada turno, y ademas despues de lluvias, tormentas, u otros eventos que puedan aumentar el riesgo de derrumbe.", en_pregunta:"How often must the competent person inspect an excavation per OSHA Subpart P?", en_opciones:["Weekly and after every major storm","Every 48 hours and at the start of each new shift","Daily and after events such as rainfall","Monthly and when conditions change"], en_explicacion:"OSHA 1926.651(k)(1) requires the competent person to inspect excavations daily before each shift, and also after rainstorms or other events that may increase the risk of a cave-in." },
  { id:"osha_611", categoria:"OSHA_EXCAVACIONES", pregunta:"Que tipo de suelo tiene una resistencia a la compresion no confinada de 1.5 tsf (toneladas por pie cuadrado) o mayor segun OSHA?", opciones:["Suelo clasificado como Tipo B estable","Suelo clasificado como Tipo A estable","Suelo clasificado como Tipo C estable","Suelo clasificado como roca blanda"], respuesta_correcta:1, explicacion:"El suelo Tipo A tiene una resistencia a la compresion no confinada de 1.5 tsf (toneladas por pie cuadrado) o mayor. Ejemplos incluyen arcilla dura, arcilla silty y arcilla arenosa cementada.", en_pregunta:"Which soil type has an unconfined compressive strength of 1.5 tsf (tons per square foot) or greater under OSHA?", en_opciones:["Soil classified as stable Type B","Soil classified as stable Type A","Soil classified as stable Type C","Soil classified as soft rock"], en_explicacion:"Type A soil has an unconfined compressive strength of 1.5 tsf or greater. Examples include hard clay, silty clay, and cemented sandy clay." },
  { id:"osha_612", categoria:"OSHA_EXCAVACIONES", pregunta:"Cual es el angulo de inclinacion (sloping) permitido por OSHA para excavaciones en suelo Tipo A?", opciones:["No mas de 1:1 que equivale a 45 grados","No mas de 1.5:1 equivalente a 34 grados","No mas de 0.75:1 equivale a 53 grados","No mas de 2:1 que equivale a 27 grados"], respuesta_correcta:2, explicacion:"Para suelo Tipo A, OSHA permite un angulo de inclinacion de 0.75H:1V (3/4 horizontal por cada 1 vertical), equivalente a aproximadamente 53 grados. Es el angulo mas empinado permitido porque el Tipo A es el suelo mas estable.", en_pregunta:"What is the OSHA-permitted sloping angle for excavations in Type A soil?", en_opciones:["No more than 1:1, which equals 45 degrees","No more than 1.5:1, equivalent to 34 degrees","No more than 0.75:1, equivalent to 53 degrees","No more than 2:1, equivalent to 27 degrees"], en_explicacion:"For Type A soil, OSHA allows a sloping angle of 0.75H:1V (3/4 horizontal per 1 vertical), equivalent to about 53 degrees. It is the steepest angle permitted because Type A is the most stable soil." },
  { id:"osha_613", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, a que distancia minima del borde de una excavacion se debe colocar el material excavado (spoil pile)?", opciones:["A un minimo de 3 pies del borde superior","A un minimo de 2 pies del borde superior","A un minimo de 4 pies del borde superior","A un minimo de 5 pies del borde superior"], respuesta_correcta:1, explicacion:"OSHA 1926.651(j)(2) requiere que el material excavado (spoil) se mantenga a un minimo de 2 pies del borde de la excavacion para evitar que el peso adicional cause un derrumbe o que el material caiga sobre los trabajadores.", en_pregunta:"Per OSHA, what is the minimum distance from the excavation edge at which excavated material (spoil pile) must be placed?", en_opciones:["A minimum of 3 feet from the upper edge","A minimum of 2 feet from the upper edge","A minimum of 4 feet from the upper edge","A minimum of 5 feet from the upper edge"], en_explicacion:"OSHA 1926.651(j)(2) requires the excavated material (spoil) to be kept at least 2 feet from the excavation edge to prevent the added weight from causing a cave-in or material from falling on workers." },
  { id:"osha_614", categoria:"OSHA_EXCAVACIONES", pregunta:"Que debe hacerse ANTES de iniciar cualquier excavacion con respecto a las instalaciones subterraneas (utilities) segun OSHA?", opciones:["Excavar con cuidado los primeros tres pies","Contactar a las companias de servicios publicos","Usar solo maquinaria liviana al comenzar a excavar","Colocar senales de advertencia en toda el area"], respuesta_correcta:1, explicacion:"OSHA 1926.651(b) requiere que ANTES de abrir una excavacion, se contacten las companias de servicios publicos (gas, electricidad, agua, telecomunicaciones) para localizar y marcar todas las instalaciones subterraneas en el area.", en_pregunta:"What must be done BEFORE starting any excavation regarding underground utilities under OSHA?", en_opciones:["Carefully excavate the first three feet","Contact the utility companies","Use only light equipment when starting to dig","Place warning signs throughout the area"], en_explicacion:"OSHA 1926.651(b) requires that BEFORE opening an excavation, utility companies (gas, electric, water, telecom) be contacted to locate and mark all underground installations in the area." },
  { id:"osha_615", categoria:"OSHA_EXCAVACIONES", pregunta:"Que es una 'trench box' (caja de zanja) y cual es su funcion principal en una excavacion segun OSHA?", opciones:["Es un contenedor para guardar herramientas dentro de zanjas","Es una estructura que protege contra derrumbes laterales","Es una barrera para desviar el agua fuera de la excavacion","Es un sistema de ventilacion para zanjas profundas cerradas"], respuesta_correcta:1, explicacion:"Una trench box (trench shield) es una estructura prefabricada de acero o aluminio que se coloca dentro de la zanja para proteger a los trabajadores contra derrumbes de las paredes laterales. Es un metodo de 'shielding' segun OSHA.", en_pregunta:"What is a 'trench box' and what is its main function in an excavation under OSHA?", en_opciones:["A container for storing tools inside trenches","A structure that protects against lateral cave-ins","A barrier to divert water away from the excavation","A ventilation system for deep closed trenches"], en_explicacion:"A trench box (trench shield) is a prefabricated steel or aluminum structure placed inside the trench to protect workers from sidewall cave-ins. It is a 'shielding' method per OSHA." },
  { id:"osha_616", categoria:"OSHA_EXCAVACIONES", pregunta:"A partir de que profundidad OSHA requiere que un ingeniero profesional registrado disene el sistema de proteccion de una excavacion?", opciones:["Cuando la excavacion supera los 15 pies","Cuando la excavacion supera los 25 pies","Cuando la excavacion supera los 20 pies","Cuando la excavacion supera los 10 pies"], respuesta_correcta:2, explicacion:"OSHA 1926.652 requiere que cuando una excavacion excede los 20 pies de profundidad, el sistema de proteccion debe ser disenado por un ingeniero profesional registrado (registered professional engineer).", en_pregunta:"At what depth does OSHA require a registered professional engineer to design the protective system for an excavation?", en_opciones:["When the excavation exceeds 15 feet","When the excavation exceeds 25 feet","When the excavation exceeds 20 feet","When the excavation exceeds 10 feet"], en_explicacion:"OSHA 1926.652 requires that when an excavation exceeds 20 feet deep, the protective system must be designed by a registered professional engineer." },
  { id:"osha_617", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, que se debe hacer cuando hay acumulacion de agua dentro de una excavacion donde trabajan empleados?", opciones:["Continuar el trabajo si el agua no supera 6 pulgadas","Usar precauciones especiales controladas por persona competente","Detener todo trabajo hasta que el agua se evapore sola","Bombear el agua solo al final de la jornada laboral"], respuesta_correcta:1, explicacion:"OSHA 1926.651(h) requiere que se tomen precauciones especiales cuando hay acumulacion de agua, incluyendo: monitoreo por la persona competente, uso de bombeo, y equipos de proteccion especiales para los trabajadores.", en_pregunta:"Per OSHA, what must be done when water accumulates inside an excavation where employees are working?", en_opciones:["Continue work if the water does not exceed 6 inches","Use special precautions controlled by the competent person","Stop all work until the water evaporates on its own","Pump the water out only at the end of the workday"], en_explicacion:"OSHA 1926.651(h) requires special precautions when water accumulates, including: monitoring by the competent person, use of pumping, and special protective equipment for workers." },
  { id:"osha_618", categoria:"OSHA_EXCAVACIONES", pregunta:"Cual de las siguientes opciones describe correctamente el suelo Tipo B segun la clasificacion de OSHA?", opciones:["Arcilla dura con resistencia mayor a 1.5 tsf total","Suelo granular cohesivo con 0.5 a 1.5 tsf de fuerza","Grava suelta y arena seca sin ninguna cohesion natural","Roca fracturada con resistencia menor a 0.5 tsf fija"], respuesta_correcta:1, explicacion:"El suelo Tipo B tiene una resistencia a la compresion no confinada entre 0.5 y 1.5 tsf. Incluye suelos granulares cohesivos como limo, arcilla media, y suelos previamente perturbados que no califican como Tipo A.", en_pregunta:"Which of the following correctly describes Type B soil under OSHA's classification?", en_opciones:["Hard clay with strength greater than 1.5 tsf total","Cohesive granular soil with 0.5 to 1.5 tsf of strength","Loose gravel and dry sand with no natural cohesion","Fractured rock with strength less than 0.5 tsf fixed"], en_explicacion:"Type B soil has an unconfined compressive strength between 0.5 and 1.5 tsf. It includes cohesive granular soils such as silt, medium clay, and previously disturbed soils that do not qualify as Type A." },
  { id:"osha_619", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, cual de estas condiciones automaticamente DEGRADA un suelo Tipo A a una clasificacion inferior?", opciones:["Si la temperatura ambiente supera los 95 grados F","Si el suelo esta sujeto a vibracion de trafico pesado","Si la excavacion tiene menos de cuatro pies de profundidad","Si no hay presencia de agua subterranea en el area"], respuesta_correcta:1, explicacion:"OSHA establece que el suelo Tipo A se degrada si esta sujeto a vibraciones (trafico pesado, maquinaria), si ha sido previamente perturbado, si esta sumergido, o si hay filtraciones de agua. Cualquiera de estas condiciones lo reclasifica.", en_pregunta:"Under OSHA, which of these conditions automatically DOWNGRADES Type A soil to a lower classification?", en_opciones:["If the ambient temperature exceeds 95 degrees F","If the soil is subject to vibration from heavy traffic","If the excavation is less than four feet deep","If there is no groundwater present in the area"], en_explicacion:"OSHA states that Type A soil is downgraded if it is subject to vibration (heavy traffic, machinery), has been previously disturbed, is submerged, or has water seepage. Any of these conditions reclassify it." },
  { id:"osha_620", categoria:"OSHA_EXCAVACIONES", pregunta:"Cual es el angulo de inclinacion (sloping) permitido por OSHA para excavaciones en suelo clasificado como Tipo B?", opciones:["No mas de 0.75:1 equivalente a 53 grados exactos","No mas de 1.5:1 que equivale a 34 grados exactos","No mas de 1:1 que equivale a 45 grados exactamente","No mas de 2:1 que equivale a 27 grados exactamente"], respuesta_correcta:2, explicacion:"Para suelo Tipo B, OSHA requiere un angulo de inclinacion no mas empinado que 1H:1V (1 horizontal por cada 1 vertical), equivalente a 45 grados. Esto es menos empinado que el Tipo A (53 grados) pero mas que el Tipo C (34 grados).", en_pregunta:"What sloping angle does OSHA allow for excavations in soil classified as Type B?", en_opciones:["No more than 0.75:1, equivalent to exactly 53 degrees","No more than 1.5:1, equivalent to exactly 34 degrees","No more than 1:1, which equals exactly 45 degrees","No more than 2:1, which equals exactly 27 degrees"], en_explicacion:"For Type B soil, OSHA requires a slope no steeper than 1H:1V (1 horizontal per 1 vertical), equivalent to 45 degrees. This is less steep than Type A (53 degrees) but steeper than Type C (34 degrees)." },
  { id:"osha_621", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, donde deben colocarse las escaleras en una zanja para garantizar una salida segura de los trabajadores?", opciones:["Las escaleras deben sobresalir 2 pies sobre el borde superior","Las escaleras deben sobresalir 3 pies sobre el borde superior","Las escaleras deben quedar al nivel exacto del borde de zanja","Las escaleras deben sobresalir 4 pies sobre el borde superior"], respuesta_correcta:1, explicacion:"OSHA 1926.651(c)(2) requiere que las escaleras utilizadas como medio de salida en zanjas se extiendan al menos 3 pies por encima del borde superior de la excavacion para permitir un agarre seguro al subir.", en_pregunta:"Per OSHA, where must ladders be placed in a trench to ensure safe worker egress?", en_opciones:["Ladders must extend 2 feet above the upper edge","Ladders must extend 3 feet above the upper edge","Ladders must be flush with the trench edge","Ladders must extend 4 feet above the upper edge"], en_explicacion:"OSHA 1926.651(c)(2) requires ladders used as a means of egress from trenches to extend at least 3 feet above the upper edge of the excavation to provide a safe handhold while climbing out." },
  { id:"osha_622", categoria:"OSHA_EXCAVACIONES", pregunta:"Que metodo de prueba se usa comunmente en el campo para determinar la clasificacion de un suelo en excavaciones segun OSHA?", opciones:["La prueba de compactacion Proctor estandar","La prueba de penetrometro de bolsillo en campo","La prueba de permeabilidad en laboratorio certificado","La prueba de consolidacion unidimensional rapida"], respuesta_correcta:1, explicacion:"La prueba de penetrometro de bolsillo (pocket penetrometer) es uno de los metodos comunes de campo que OSHA reconoce para determinar la resistencia a la compresion no confinada del suelo y asi clasificarlo como Tipo A, B o C.", en_pregunta:"Which test method is commonly used in the field to determine the soil classification for excavations under OSHA?", en_opciones:["The standard Proctor compaction test","The field pocket penetrometer test","The certified laboratory permeability test","The rapid one-dimensional consolidation test"], en_explicacion:"The pocket penetrometer test is one of the common field methods OSHA recognizes for determining unconfined compressive strength of soil, and classifying it as Type A, B, or C." },
  { id:"osha_623", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, cuando se debe monitorear la atmosfera dentro de una excavacion para detectar condiciones peligrosas?", opciones:["Solo si la excavacion supera los 20 pies de profundidad total","Cuando exista posibilidad razonable de atmosfera peligrosa","Unicamente si hay tuberias de gas rotas visibles en la zona","Solo cuando los trabajadores reportan mareos o dificultad al respirar"], respuesta_correcta:1, explicacion:"OSHA 1926.651(g) requiere pruebas atmosfericas cuando existe una posibilidad razonable de deficiencia de oxigeno, gases combustibles, u otros contaminantes en la excavacion, sin importar la profundidad especifica.", en_pregunta:"Per OSHA, when must the atmosphere inside an excavation be monitored for hazardous conditions?", en_opciones:["Only if the excavation exceeds 20 feet in total depth","When there is a reasonable possibility of a hazardous atmosphere","Only if there are visibly broken gas pipes in the area","Only when workers report dizziness or breathing difficulty"], en_explicacion:"OSHA 1926.651(g) requires atmospheric testing when there is a reasonable possibility of oxygen deficiency, combustible gases, or other contaminants in the excavation, regardless of a specific depth." },
  { id:"osha_624", categoria:"OSHA_EXCAVACIONES", pregunta:"Que debe hacer la persona competente si detecta evidencia de una posible falla o derrumbe en las paredes de la excavacion?", opciones:["Documentar la evidencia y continuar monitoreando por 24 horas","Retirar a los trabajadores hasta eliminar el peligro detectado","Reforzar las paredes con material excavado disponible en sitio","Reducir el numero de trabajadores dentro de la zanja a la mitad"], respuesta_correcta:1, explicacion:"OSHA 1926.651(k)(2) requiere que la persona competente retire inmediatamente a todos los trabajadores expuestos de la excavacion cuando encuentre evidencia de posible derrumbe, acumulacion de agua peligrosa, o falla del sistema de proteccion.", en_pregunta:"What must the competent person do if they detect evidence of a possible failure or cave-in in the excavation walls?", en_opciones:["Document the evidence and continue monitoring for 24 hours","Remove workers until the hazard is eliminated","Reinforce the walls with excavated material available on site","Cut the number of workers in the trench in half"], en_explicacion:"OSHA 1926.651(k)(2) requires the competent person to immediately remove all exposed workers from the excavation when they find evidence of a possible cave-in, dangerous water accumulation, or failure of the protective system." },
  { id:"osha_625", categoria:"OSHA_EXCAVACIONES", pregunta:"Cual es la caracteristica principal del suelo Tipo C segun la clasificacion de OSHA para excavaciones?", opciones:["Es arcilla firme con resistencia mayor a 1.0 tsf total","Es suelo cohesivo con resistencia de 0.5 a 1.5 tsf exacto","Es suelo con resistencia menor a 0.5 tsf o granular libre","Es roca parcialmente estable con fracturas menores visibles"], respuesta_correcta:2, explicacion:"El suelo Tipo C tiene una resistencia a la compresion no confinada de 0.5 tsf o menos. Incluye suelo granular (grava, arena, suelo sumergido), suelo del cual se filtra agua, y roca sumergida que no es estable.", en_pregunta:"What is the main characteristic of Type C soil under OSHA's classification for excavations?", en_opciones:["Firm clay with strength greater than 1.0 tsf total","Cohesive soil with strength from 0.5 to 1.5 tsf exact","Soil with strength less than 0.5 tsf or free-running granular","Partially stable rock with minor visible fractures"], en_explicacion:"Type C soil has an unconfined compressive strength of 0.5 tsf or less. It includes granular soil (gravel, sand, submerged soil), soil from which water is seeping, and submerged rock that is not stable." },
  { id:"osha_626", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, que tipo de proteccion NO es aceptable como sistema de proteccion aprobado para excavaciones y zanjas?", opciones:["Sloping o corte inclinado de las paredes de la excavacion","Shoring con sistemas hidraulicos de soporte de aluminio","Shielding con cajas de zanja prefabricadas de acero pesado","Colocar madera suelta contra la pared sin un diseno formal"], respuesta_correcta:3, explicacion:"OSHA acepta tres metodos: sloping/benching, shoring (sistemas diseñados de soporte), y shielding (trench boxes). Colocar madera suelta sin un diseno de ingenieria no cumple con ningun metodo aprobado de 1926.652.", en_pregunta:"Per OSHA, which is NOT an acceptable, approved protective system for excavations and trenches?", en_opciones:["Sloping or inclined cutting of excavation walls","Shoring with hydraulic aluminum support systems","Shielding with heavy-duty prefabricated steel trench boxes","Placing loose lumber against the wall without a formal design"], en_explicacion:"OSHA accepts three methods: sloping/benching, shoring (engineered support systems), and shielding (trench boxes). Placing loose lumber without an engineering design meets none of the approved methods under 1926.652." },
  { id:"osha_627", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, que es 'benching' como metodo de proteccion en una excavacion y en que tipo de suelo NO se permite?", opciones:["Cortar escalones en la pared; prohibido en suelo Tipo A estable","Cortar escalones en la pared; prohibido en suelo Tipo C suelto","Inclinar toda la pared; prohibido en suelo Tipo B intermedio","Colocar tablones horizontales; prohibido en roca fracturada"], respuesta_correcta:1, explicacion:"Benching consiste en cortar escalones (bench) en las paredes de la excavacion. OSHA prohibe el benching en suelo Tipo C porque es demasiado inestable para mantener la forma de los escalones cortados.", en_pregunta:"Per OSHA, what is 'benching' as an excavation protective method, and in which soil type is it NOT allowed?", en_opciones:["Cutting steps in the wall; prohibited in stable Type A soil","Cutting steps in the wall; prohibited in loose Type C soil","Sloping the entire wall; prohibited in intermediate Type B soil","Placing horizontal planks; prohibited in fractured rock"], en_explicacion:"Benching consists of cutting steps (benches) into the excavation walls. OSHA prohibits benching in Type C soil because it is too unstable to hold the shape of the cut steps." },
  { id:"osha_628", categoria:"OSHA_EXCAVACIONES", pregunta:"Cuando se trabaja cerca de una excavacion abierta, a que distancia minima se deben colocar las barreras de proteccion para vehiculos?", opciones:["Las barreras deben estar al menos a 4 pies del borde visible","Las barreras se deben colocar a un minimo de 6 pies del borde","No hay distancia fija pero deben soportar impacto del vehiculo","Las barreras deben estar a un minimo de 10 pies del borde fijo"], respuesta_correcta:2, explicacion:"OSHA 1926.651(f) requiere barreras o barricadas adecuadas cuando el trafico vehicular es un peligro. No especifica una distancia fija exacta, pero las barreras deben ser capaces de detener vehiculos antes de que caigan a la excavacion.", en_pregunta:"When working near an open excavation, what minimum distance must vehicle protection barriers be placed?", en_opciones:["Barriers must be at least 4 feet from the visible edge","Barriers must be placed a minimum of 6 feet from the edge","No fixed distance, but they must withstand vehicle impact","Barriers must be a minimum of 10 feet from the edge fixed"], en_explicacion:"OSHA 1926.651(f) requires adequate barriers or barricades when vehicular traffic is a hazard. It does not specify an exact fixed distance, but barriers must be capable of stopping vehicles before they fall into the excavation." },
  { id:"osha_629", categoria:"OSHA_EXCAVACIONES", pregunta:"Segun OSHA, que requisito aplica a los trabajadores que deben cruzar sobre una excavacion o zanja en el sitio de trabajo?", opciones:["Pueden saltar si la zanja tiene menos de 4 pies de ancho","Se requiere un puente con barandas si tiene 6 pies o mas","Se requiere un puente con barandas para zanjas de mas de 6 pies de profundidad","No se permite cruzar sobre excavaciones bajo ninguna condicion vigente"], respuesta_correcta:1, explicacion:"OSHA 1926.651(l) requiere que las pasarelas o puentes utilizados para cruzar sobre zanjas de 6 pies o mas de profundidad tengan barandas estandar (guardrails) para proteger a los trabajadores de caidas.", en_pregunta:"Per OSHA, what requirement applies to workers who must cross over an excavation or trench at the work site?", en_opciones:["They can jump if the trench is less than 4 feet wide","A bridge with handrails is required if it is 6 feet or more","A bridge with handrails is required for trenches more than 6 feet deep","Crossing over excavations is not permitted under any condition"], en_explicacion:"OSHA 1926.651(l) requires walkways or bridges used to cross over trenches 6 feet or more deep to have standard guardrails to protect workers from falls." },
{ id:"osha_630", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es la capacidad mínima de carga que debe soportar un andamio según OSHA?", opciones:["El doble del peso máximo previsto incluyendo trabajadores y materiales","Cuatro veces la carga máxima prevista incluyendo trabajadores y materiales","Tres veces el peso combinado de trabajadores y herramientas sobre él","Seis veces la carga muerta del andamio sin contar a los trabajadores"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1926.451(a)(1) requiere que los andamios soporten 4 veces la carga máxima prevista (4:1 ratio de seguridad).", en_pregunta:"What is the minimum load capacity a scaffold must support under OSHA?", en_opciones:["Twice the maximum anticipated load, including workers and materials","Four times the maximum anticipated load, including workers and materials","Three times the combined weight of workers and tools on it","Six times the scaffold's dead load, not counting workers"], en_explicacion:"OSHA 29 CFR 1926.451(a)(1) requires scaffolds to support 4 times the maximum anticipated load (4:1 safety ratio)." },
{ id:"osha_631", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es la altura mínima requerida para la baranda superior (top rail) de un andamio?", opciones:["36 pulgadas medidas desde la superficie de trabajo del andamio","38 pulgadas medidas desde la superficie de trabajo del andamio","42 pulgadas medidas desde la superficie de trabajo del andamio","48 pulgadas medidas desde la superficie de trabajo del andamio"], respuesta_correcta:1, explicacion:"OSHA 1926.451(g)(4)(ii) especifica que la baranda superior debe estar entre 38 y 45 pulgadas sobre la superficie de trabajo.", en_pregunta:"What is the required minimum height for the top rail of a scaffold?", en_opciones:["36 inches measured from the scaffold work surface","38 inches measured from the scaffold work surface","42 inches measured from the scaffold work surface","48 inches measured from the scaffold work surface"], en_explicacion:"OSHA 1926.451(g)(4)(ii) specifies that the top rail must be between 38 and 45 inches above the working surface." },
{ id:"osha_632", categoria:"OSHA_ANDAMIOS", pregunta:"¿A partir de qué altura se requiere protección contra caídas en andamios?", opciones:["6 pies sobre el nivel inferior para andamios de cualquier tipo usado","8 pies sobre el nivel inferior para andamios de cualquier tipo usado","10 pies sobre el nivel inferior para andamios de cualquier tipo","12 pies sobre el nivel inferior para andamios de cualquier tipo"], respuesta_correcta:2, explicacion:"OSHA 1926.451(g)(1) requiere protección contra caídas cuando la superficie de trabajo está a 10 pies o más sobre el nivel inferior.", en_pregunta:"At what height is fall protection required on scaffolds?", en_opciones:["6 feet above the lower level for scaffolds of any type in use","8 feet above the lower level for scaffolds of any type in use","10 feet above the lower level for scaffolds of any type","12 feet above the lower level for scaffolds of any type"], en_explicacion:"OSHA 1926.451(g)(1) requires fall protection when the working surface is 10 feet or more above the lower level." },
{ id:"osha_633", categoria:"OSHA_ANDAMIOS", pregunta:"¿Quién debe inspeccionar un andamio antes de cada turno de trabajo según OSHA?", opciones:["Un ingeniero estructural certificado por el estado donde se encuentra la obra","Una persona competente designada por el empleador con experiencia comprobada","El supervisor general de la obra con mínimo cinco años de experiencia total","Un inspector certificado de OSHA asignado específicamente al proyecto en curso"], respuesta_correcta:1, explicacion:"OSHA 1926.451(f)(7) requiere que una persona competente inspeccione el andamio antes de cada turno y después de cualquier evento que afecte su integridad.", en_pregunta:"Who must inspect a scaffold before each work shift under OSHA?", en_opciones:["A structural engineer certified by the state where the site is located","A competent person designated by the employer with demonstrated experience","The general site supervisor with a minimum of five years of total experience","An OSHA-certified inspector specifically assigned to the project"], en_explicacion:"OSHA 1926.451(f)(7) requires a competent person to inspect the scaffold before each shift and after any event that may affect its structural integrity." },
{ id:"osha_634", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el ancho mínimo de las tablas de plataforma (planking) en un andamio?", opciones:["El ancho debe ser de al menos 16 pulgadas para plataformas de trabajo estándar","El ancho debe ser de al menos 18 pulgadas para plataformas de trabajo estándar","El ancho debe ser de al menos 20 pulgadas para plataformas de trabajo estándar","El ancho debe ser de al menos 24 pulgadas para plataformas de trabajo estándar"], respuesta_correcta:2, explicacion:"OSHA 1926.451(b)(2) requiere que las plataformas tengan al menos 20 pulgadas de ancho (nominalmente) para trabajo general.", en_pregunta:"What is the minimum plank width for platform planking on a scaffold?", en_opciones:["The width must be at least 16 inches for standard working platforms","The width must be at least 18 inches for standard working platforms","The width must be at least 20 inches for standard working platforms","The width must be at least 24 inches for standard working platforms"], en_explicacion:"OSHA 1926.451(b)(2) requires platforms to be at least 20 inches wide (nominal) for general work." },
{ id:"osha_635", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es la distancia máxima permitida entre la plataforma del andamio y la cara del edificio?", opciones:["10 pulgadas máximo entre la plataforma y la estructura de trabajo cercana","14 pulgadas máximo entre la plataforma y la estructura de trabajo cercana","18 pulgadas máximo entre la plataforma y la estructura de trabajo cercana","20 pulgadas máximo entre la plataforma y la estructura de trabajo cercana"], respuesta_correcta:1, explicacion:"OSHA 1926.451(b)(1) permite un máximo de 14 pulgadas entre la plataforma y la cara de la estructura, excepto en ciertas condiciones específicas.", en_pregunta:"What is the maximum distance allowed between the scaffold platform and the face of the building?", en_opciones:["10 inches maximum between the platform and the adjacent structure","14 inches maximum between the platform and the adjacent structure","18 inches maximum between the platform and the adjacent structure","20 inches maximum between the platform and the adjacent structure"], en_explicacion:"OSHA 1926.451(b)(1) allows a maximum of 14 inches between the platform and the face of the structure, except under certain specific conditions." },
{ id:"osha_636", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué tipo de andamio se sostiene desde arriba mediante cuerdas o cables de acero?", opciones:["Andamio soportado que se fija mediante cables tensados a la estructura superior","Andamio suspendido que cuelga de soportes en el techo o estructura superior","Andamio móvil que se eleva con cables conectados a grúas en la azotea","Andamio aéreo que se ancla con cuerdas atadas a postes estructurales fijos"], respuesta_correcta:1, explicacion:"Un andamio suspendido (suspended scaffold) se sostiene desde arriba mediante cuerdas o cables de acero conectados a soportes superiores, a diferencia del andamio soportado que descansa sobre el suelo.", en_pregunta:"Which type of scaffold is supported from above by ropes or wire cables?", en_opciones:["A supported scaffold, anchored by cables tensioned to the upper structure","A suspended scaffold, which hangs from supports on the roof or upper structure","A mobile scaffold, raised by cables connected to cranes on the roof","An aerial scaffold, anchored by ropes tied to fixed structural posts"], en_explicacion:"A suspended scaffold is supported from above by ropes or wire cables connected to overhead supports, unlike a supported scaffold, which rests on the ground." },
{ id:"osha_637", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuántos puntos de acceso se requieren cuando un andamio tiene más de un nivel de trabajo?", opciones:["Un punto de acceso por cada nivel de trabajo con escalera interna o externa aprobada","Un punto de acceso por cada dos niveles que puede ser escalera o rampa segura","Acceso directo a cada nivel mediante escaleras integradas o medios equivalentes","Dos puntos de acceso en cada nivel para permitir evacuación de emergencia rápida"], respuesta_correcta:2, explicacion:"OSHA 1926.451(e)(1) requiere acceso directo a cada nivel del andamio mediante escaleras portátiles, escaleras integradas, rampas u otros medios equivalentes seguros.", en_pregunta:"How many access points are required when a scaffold has more than one working level?", en_opciones:["One access point per working level with an approved internal or external ladder","One access point for every two levels, which may be a ladder or safe ramp","Direct access to each level by built-in ladders or equivalent means","Two access points on each level to allow rapid emergency evacuation"], en_explicacion:"OSHA 1926.451(e)(1) requires direct access to each scaffold level by portable ladders, integral ladders, ramps, or other equivalent safe means." },
{ id:"osha_638", categoria:"OSHA_ANDAMIOS", pregunta:"¿A qué distancia mínima debe mantenerse un andamio de líneas eléctricas energizadas de menos de 300 voltios?", opciones:["Al menos 3 pies de distancia de las líneas eléctricas energizadas de bajo voltaje","Al menos 5 pies de distancia de las líneas eléctricas energizadas de bajo voltaje","Al menos 8 pies de distancia de las líneas eléctricas energizadas de bajo voltaje","Mínimo 10 pies de distancia de líneas eléctricas energizadas de bajo voltaje"], respuesta_correcta:0, explicacion:"OSHA 1926.451(f)(6) requiere una distancia mínima de 3 pies para líneas de menos de 300 voltios. Para líneas de 300V a 50kV la distancia mínima es 10 pies.", en_pregunta:"What is the minimum distance a scaffold must be kept from energized electrical lines under 300 volts?", en_opciones:["At least 3 feet from energized low-voltage electrical lines","At least 5 feet from energized low-voltage electrical lines","At least 8 feet from energized low-voltage electrical lines","At least 10 feet from energized low-voltage electrical lines"], en_explicacion:"OSHA 1926.451(f)(6) requires a minimum distance of 3 feet for lines under 300 volts. For lines from 300V to 50kV, the minimum distance is 10 feet." },
{ id:"osha_639", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el requisito para la baranda intermedia (mid-rail) en un sistema de barandas de andamio?", opciones:["Debe instalarse a la mitad de la altura entre la plataforma y la baranda superior","Debe instalarse a 21 pulgadas fijas desde la superficie de trabajo del andamio","Debe instalarse a 24 pulgadas exactas medidas desde la baranda superior hacia abajo","Debe instalarse a un tercio de la altura entre la plataforma y baranda superior"], respuesta_correcta:0, explicacion:"OSHA 1926.451(g)(4)(iii) requiere que la baranda intermedia se instale aproximadamente a la mitad de la distancia entre la plataforma y la baranda superior.", en_pregunta:"What is the requirement for the mid-rail in a scaffold guardrail system?", en_opciones:["Must be installed at mid-height between the platform and the top rail","Must be installed at a fixed 21 inches from the scaffold working surface","Must be installed exactly 24 inches below the top rail","Must be installed at one-third of the distance between the platform and top rail"], en_explicacion:"OSHA 1926.451(g)(4)(iii) requires the mid-rail to be installed approximately at the midpoint between the platform and the top rail." },
{ id:"osha_640", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué componente del andamio previene que herramientas y materiales caigan sobre trabajadores abajo?", opciones:["La baranda superior instalada a 38-45 pulgadas de la plataforma de trabajo","La baranda intermedia colocada a media altura entre plataforma y baranda","El rodapié (toeboard) de al menos 3.5 pulgadas de altura en cada borde","La malla de protección de nylon tensada entre las barandas del andamio"], respuesta_correcta:2, explicacion:"OSHA 1926.451(h)(1) requiere rodapiés (toeboards) de al menos 3.5 pulgadas de altura para prevenir que objetos caigan de la plataforma sobre trabajadores debajo.", en_pregunta:"Which scaffold component prevents tools and materials from falling onto workers below?", en_opciones:["The top rail installed 38-45 inches above the working platform","The mid-rail placed at half-height between the platform and top rail","The toeboard at least 3.5 inches tall on each edge","The nylon protective mesh tensioned between the scaffold rails"], en_explicacion:"OSHA 1926.451(h)(1) requires toeboards at least 3.5 inches high to prevent objects from falling off the platform onto workers below." },
{ id:"osha_641", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es la proporción máxima de altura a base para un andamio móvil (rolling scaffold)?", opciones:["La altura no debe exceder dos veces la dimensión menor de la base del andamio","La altura no debe exceder tres veces la dimensión menor de la base del andamio","La altura no debe exceder cuatro veces la dimensión menor de la base del andamio","La altura no debe exceder cinco veces la dimensión menor de la base del andamio"], respuesta_correcta:2, explicacion:"OSHA 1926.452(w)(6) establece que la altura de un andamio móvil no debe exceder 4 veces la dimensión mínima de la base, a menos que se usen estabilizadores.", en_pregunta:"What is the maximum height-to-base ratio for a rolling scaffold?", en_opciones:["Height must not exceed two times the smaller base dimension of the scaffold","Height must not exceed three times the smaller base dimension of the scaffold","Height must not exceed four times the smaller base dimension of the scaffold","Height must not exceed five times the smaller base dimension of the scaffold"], en_explicacion:"OSHA 1926.452(w)(6) states that the height of a rolling scaffold must not exceed 4 times the minimum base dimension unless stabilizers are used." },
{ id:"osha_642", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué se debe hacer con las ruedas de un andamio móvil cuando hay trabajadores en la plataforma?", opciones:["Las ruedas deben estar giradas hacia adentro y aseguradas con cadenas de acero","Las ruedas deben estar bloqueadas con frenos y los trabajadores deben sujetarse","Las ruedas deben retirarse y sustituirse por placas de base fijas y niveladas","Las ruedas deben estar desinfladas parcialmente para aumentar fricción en el suelo"], respuesta_correcta:1, explicacion:"OSHA 1926.452(w)(2) requiere que las ruedas estén bloqueadas con frenos cuando hay trabajadores en la plataforma para prevenir movimiento involuntario del andamio.", en_pregunta:"What must be done with the wheels of a rolling scaffold when workers are on the platform?", en_opciones:["The wheels must be turned inward and secured with steel chains","The wheels must be locked with brakes and the workers must hold on","The wheels must be removed and replaced with fixed, level base plates","The wheels must be partially deflated to increase friction with the floor"], en_explicacion:"OSHA 1926.452(w)(2) requires the wheels to be locked with brakes when workers are on the platform to prevent unintended movement of the scaffold." },
{ id:"osha_643", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el requisito de sobreposición (overlap) para tablas de plataforma en un andamio?", opciones:["Las tablas deben superponerse al menos 6 pulgadas sobre los soportes del andamio","Las tablas deben superponerse mínimo 12 pulgadas sobre los soportes del andamio","Las tablas deben superponerse al menos 18 pulgadas sobre soportes del andamio","Las tablas deben superponerse al menos 24 pulgadas sobre soportes del andamio"], respuesta_correcta:1, explicacion:"OSHA 1926.451(b)(4) requiere que las tablas de plataforma se superpongan al menos 12 pulgadas sobre los soportes, a menos que estén clavadas o aseguradas contra movimiento.", en_pregunta:"What is the overlap requirement for scaffold platform planks?", en_opciones:["Planks must overlap at least 6 inches over the scaffold supports","Planks must overlap a minimum of 12 inches over the scaffold supports","Planks must overlap at least 18 inches over the scaffold supports","Planks must overlap at least 24 inches over the scaffold supports"], en_explicacion:"OSHA 1926.451(b)(4) requires platform planks to overlap the supports by at least 12 inches unless they are nailed or otherwise secured against movement." },
{ id:"osha_644", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuándo debe un andamio suspendido utilizar líneas de vida independientes para los trabajadores?", opciones:["Solo cuando el andamio suspendido está a más de 50 pies sobre el nivel del suelo","Solo cuando el andamio suspendido opera cerca de líneas de alta tensión eléctricas","Siempre que los trabajadores estén en un andamio suspendido de dos puntos o más","Solo cuando las condiciones climáticas presentan vientos superiores a 25 millas/hora"], respuesta_correcta:2, explicacion:"OSHA 1926.451(g)(3)(iii) requiere que cada trabajador en un andamio suspendido de dos puntos use un arnés con línea de vida independiente como protección contra caídas en todo momento.", en_pregunta:"When must workers on a suspended scaffold use independent lifelines?", en_opciones:["Only when the suspended scaffold is more than 50 feet above ground level","Only when the suspended scaffold operates near high-voltage electrical lines","Always when workers are on a two-point or greater suspended scaffold","Only when weather conditions bring winds above 25 miles per hour"], en_explicacion:"OSHA 1926.451(g)(3)(iii) requires each worker on a two-point suspended scaffold to use a harness with an independent lifeline as fall protection at all times." },
{ id:"osha_645", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué acción debe tomarse si se encuentra un defecto en un componente del andamio durante inspección?", opciones:["Documentar el defecto y programar reparación dentro de las siguientes 72 horas","Marcar el componente con pintura roja y notificar al supervisor de seguridad","Retirar inmediatamente de servicio y no usar hasta que sea reparado o reemplazado","Reducir la carga del andamio a la mitad hasta que se complete la reparación total"], respuesta_correcta:2, explicacion:"OSHA 1926.451(f)(7) requiere que cualquier componente defectuoso sea retirado inmediatamente de servicio y no se use hasta que sea reparado o reemplazado por una persona competente.", en_pregunta:"What action must be taken if a defect is found on a scaffold component during inspection?", en_opciones:["Document the defect and schedule repair within the next 72 hours","Mark the component with red paint and notify the safety supervisor","Immediately remove it from service and do not use it until repaired or replaced","Reduce the scaffold's load by half until the repair is complete"], en_explicacion:"OSHA 1926.451(f)(7) requires any defective component to be immediately removed from service and not used until it is repaired or replaced by a competent person." },
{ id:"osha_646", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es la norma específica de OSHA que regula la seguridad en andamios de construcción?", opciones:["La norma 29 CFR 1926 Subpart K que cubre equipos eléctricos en construcción","La norma 29 CFR 1926 Subpart L que cubre andamios en la industria de construcción","La norma 29 CFR 1926 Subpart M que cubre protección contra caídas en general","La norma 29 CFR 1926 Subpart N que cubre grúas y equipos de elevación pesados"], respuesta_correcta:1, explicacion:"29 CFR 1926 Subpart L es la norma específica de OSHA que regula todos los requisitos de seguridad para andamios en la industria de la construcción.", en_pregunta:"Which specific OSHA standard regulates construction scaffold safety?", en_opciones:["29 CFR 1926 Subpart K, which covers electrical equipment in construction","29 CFR 1926 Subpart L, which covers scaffolds in the construction industry","29 CFR 1926 Subpart M, which covers fall protection in general","29 CFR 1926 Subpart N, which covers heavy cranes and lifting equipment"], en_explicacion:"29 CFR 1926 Subpart L is the specific OSHA standard that regulates all safety requirements for scaffolds in the construction industry." },
{ id:"osha_647", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el requisito para trabajar en andamios durante tormentas eléctricas o vientos fuertes?", opciones:["Se permite trabajar con vientos de hasta 35 mph si se usan arneses de seguridad","Se permite trabajar si la persona competente evalúa que el riesgo es aceptable","No se debe trabajar en andamios durante tormentas eléctricas o vientos fuertes","Se permite si el andamio tiene protección de viento instalada correctamente fija"], respuesta_correcta:2, explicacion:"OSHA 1926.451(f)(12) prohíbe el trabajo en andamios durante tormentas eléctricas, vientos fuertes u otras condiciones climáticas adversas que pongan en peligro a los trabajadores.", en_pregunta:"What is the requirement for working on scaffolds during thunderstorms or high winds?", en_opciones:["Work is allowed in winds up to 35 mph if safety harnesses are used","Work is allowed if the competent person evaluates the risk as acceptable","Work on scaffolds during thunderstorms or high winds is not allowed","Work is allowed if the scaffold has wind protection properly installed"], en_explicacion:"OSHA 1926.451(f)(12) prohibits work on scaffolds during thunderstorms, high winds, or other adverse weather conditions that would endanger workers." },
{ id:"osha_648", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué tipo de protección contra caídas se requiere en andamios soportados sobre 10 pies?", opciones:["Sistema de línea de vida horizontal con arnés de cuerpo completo certificado","Sistema de barandas completo o sistema personal de detención de caídas válido","Red de seguridad instalada debajo de la plataforma de trabajo del andamio usado","Cuerda de restricción atada al marco del andamio con mosquetón autocierre total"], respuesta_correcta:1, explicacion:"OSHA 1926.451(g)(1)(vii) requiere un sistema de barandas o un sistema personal de detención de caídas para trabajadores en andamios soportados a más de 10 pies sobre el nivel inferior.", en_pregunta:"What type of fall protection is required on supported scaffolds above 10 feet?", en_opciones:["A horizontal lifeline system with a certified full-body harness","A complete guardrail system or a valid personal fall arrest system","A safety net installed below the scaffold's work platform","A restraint line tied to the scaffold frame with a self-locking carabiner"], en_explicacion:"OSHA 1926.451(g)(1)(vii) requires a guardrail system or a personal fall arrest system for workers on supported scaffolds more than 10 feet above the lower level." },
{ id:"osha_649", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el peso mínimo que debe soportar la baranda superior de un andamio según OSHA?", opciones:["100 libras de fuerza aplicada en cualquier dirección hacia abajo o hacia afuera","150 libras de fuerza aplicada en cualquier dirección hacia abajo o hacia afuera","200 libras de fuerza aplicada en cualquier dirección hacia abajo o hacia afuera","250 libras de fuerza aplicada en cualquier dirección hacia abajo o hacia afuera"], respuesta_correcta:2, explicacion:"OSHA 1926.451(g)(4)(vii) requiere que la baranda superior soporte al menos 200 libras de fuerza aplicada en cualquier dirección descendente o hacia afuera en cualquier punto.", en_pregunta:"What minimum force must the top rail of a scaffold support per OSHA?", en_opciones:["100 pounds of force applied in any downward or outward direction","150 pounds of force applied in any downward or outward direction","200 pounds of force applied in any downward or outward direction","250 pounds of force applied in any downward or outward direction"], en_explicacion:"OSHA 1926.451(g)(4)(vii) requires the top rail to withstand at least 200 pounds of force applied in any downward or outward direction at any point." },
{ id:"osha_650", categoria:"OSHA_ANDAMIOS", pregunta:"¿Quién puede diseñar un andamio que exceda las especificaciones estándar de OSHA para construcción?", opciones:["La persona competente designada por el empleador con experiencia en andamios","Un ingeniero profesional registrado con conocimientos en diseño de andamios","El fabricante del andamio a través de sus manuales técnicos de especificaciones","El supervisor de seguridad de la obra con certificación OSHA 30 horas vigente"], respuesta_correcta:1, explicacion:"OSHA 1926.452 requiere que andamios que excedan las especificaciones estándar sean diseñados por un ingeniero profesional registrado (registered professional engineer).", en_pregunta:"Who may design a scaffold that exceeds OSHA's standard construction specifications?", en_opciones:["The competent person designated by the employer with scaffold experience","A registered professional engineer with scaffold design expertise","The scaffold manufacturer through its technical specification manuals","The site safety supervisor with a current OSHA 30-hour certification"], en_explicacion:"OSHA 1926.452 requires scaffolds that exceed standard specifications to be designed by a registered professional engineer." },
{ id:"osha_651", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuál es el requisito para las bases de un andamio soportado respecto al terreno donde se instala?", opciones:["Las bases deben colocarse sobre terreno firme, nivelado y con placas base adecuadas","Las bases deben clavarse al suelo con estacas de metal de al menos doce pulgadas","Las bases pueden colocarse sobre cualquier superficie si se usan estabilizadores fijos","Las bases requieren cimentación de concreto de mínimo cuatro pulgadas de espesor"], respuesta_correcta:0, explicacion:"OSHA 1926.451(c)(2) requiere que los andamios soportados se coloquen sobre bases adecuadas (mudsills, placas base) en terreno firme y nivelado para garantizar estabilidad.", en_pregunta:"What is the requirement for the base of a supported scaffold regarding the terrain where it is installed?", en_opciones:["Bases must be placed on firm, level ground with adequate base plates","Bases must be anchored to the ground with at least twelve-inch metal stakes","Bases can be placed on any surface if fixed stabilizers are used","Bases require a concrete footing of at least four inches thick"], en_explicacion:"OSHA 1926.451(c)(2) requires supported scaffolds to be placed on adequate bases (mudsills, base plates) on firm, level ground to ensure stability." },
{ id:"osha_652", categoria:"OSHA_ANDAMIOS", pregunta:"¿Cuándo se requiere que los trabajadores reciban capacitación sobre seguridad en andamios?", opciones:["Anualmente como parte del programa de capacitación general de seguridad laboral","Cada seis meses con actualización semestral documentada en el expediente laboral","Antes de trabajar en andamios y cuando cambien condiciones o se identifiquen riesgos","Solo al inicio del empleo como parte de la orientación general para nuevos empleados"], respuesta_correcta:2, explicacion:"OSHA 1926.454(a) requiere capacitación antes de trabajar en andamios, y recapacitación cuando cambien las condiciones del lugar de trabajo, los tipos de andamio, o se identifiquen deficiencias.", en_pregunta:"When must workers receive scaffold safety training?", en_opciones:["Annually as part of the general workplace safety training program","Every six months with semiannual updates documented in the employee file","Before working on scaffolds and when conditions change or hazards are identified","Only at hire as part of general orientation for new employees"], en_explicacion:"OSHA 1926.454(a) requires training before working on scaffolds, and retraining when workplace conditions, scaffold types change, or deficiencies are identified." },
{ id:"osha_653", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué distancia máxima debe haber entre el borde de la plataforma y los soportes verticales del andamio?", opciones:["No más de 1 pulgada entre la plataforma y los montantes verticales del andamio","No más de 3 pulgadas entre la plataforma y los montantes verticales del andamio","No más de 6 pulgadas entre la plataforma y los montantes verticales del andamio","No más de 8 pulgadas entre la plataforma y los montantes verticales del andamio"], respuesta_correcta:0, explicacion:"OSHA 1926.451(b)(1)(i) establece que no debe haber más de 1 pulgada de espacio entre las tablas de plataforma y los montantes verticales del andamio para prevenir caídas de objetos.", en_pregunta:"What is the maximum distance allowed between the edge of the scaffold platform and the vertical supports?", en_opciones:["No more than 1 inch between the platform and the vertical uprights","No more than 3 inches between the platform and the vertical uprights","No more than 6 inches between the platform and the vertical uprights","No more than 8 inches between the platform and the vertical uprights"], en_explicacion:"OSHA 1926.451(b)(1)(i) states that there must be no more than 1 inch of space between the platform planks and the vertical scaffold uprights to prevent objects from falling through." },
{ id:"osha_654", categoria:"OSHA_ANDAMIOS", pregunta:"¿Qué se requiere cuando un andamio se erige cerca de líneas eléctricas de 50kV o más?", opciones:["Distancia mínima de 10 pies más 0.4 pulgadas por cada kV adicional sobre 50kV","Distancia mínima de 15 pies más 0.5 pulgadas por cada kV adicional sobre 50kV","Distancia mínima de 20 pies más 0.4 pulgadas por cada kV adicional sobre 50kV","Distancia mínima de 25 pies más 0.5 pulgadas por cada kV adicional sobre 50kV"], respuesta_correcta:2, explicacion:"OSHA 1926.451(f)(6) requiere una distancia mínima de 20 pies más 0.4 pulgadas por cada kV adicional sobre 50kV para andamios cerca de líneas eléctricas de alto voltaje.", en_pregunta:"What is required when a scaffold is erected near electrical lines of 50kV or more?", en_opciones:["Minimum distance of 10 feet plus 0.4 inches for each kV over 50kV","Minimum distance of 15 feet plus 0.5 inches for each kV over 50kV","Minimum distance of 20 feet plus 0.4 inches for each kV over 50kV","Minimum distance of 25 feet plus 0.5 inches for each kV over 50kV"], en_explicacion:"OSHA 1926.451(f)(6) requires a minimum distance of 20 feet plus 0.4 inches per additional kV above 50kV for scaffolds near high-voltage electrical lines." },
{ id:"osha_655", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la señal manual estándar para indicar al operador de grúa que detenga toda operación inmediatamente?", opciones:["Ambas manos extendidas al frente con las palmas hacia abajo moviéndolas lateralmente","Un brazo extendido con la palma hacia abajo moviéndolo horizontalmente de lado a lado","Ambos puños cerrados al frente del cuerpo golpeándolos uno contra el otro repetidamente","Ambas manos abiertas al frente con las palmas hacia abajo sin ningún tipo de movimiento"], respuesta_correcta:1, explicacion:"La señal de parada de emergencia (Emergency Stop) es un brazo extendido con la palma hacia abajo, moviéndolo horizontalmente de lado a lado según ASME B30.5.", en_pregunta:"What is the standard hand signal to tell a crane operator to immediately stop all operation?", en_opciones:["Both hands extended forward with palms down, moving laterally","One arm extended with palm down, moved horizontally side to side","Both fists closed in front of the body, striking one against the other repeatedly","Both hands open in front with palms down and no movement"], en_explicacion:"The Emergency Stop signal is one arm extended with palm down, moved horizontally side to side, per ASME B30.5." },
{ id:"osha_656", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el ángulo mínimo recomendado para eslingas medido desde la horizontal al levantar una carga?", opciones:["30 grados desde la horizontal para minimizar la tensión excesiva en las eslingas","45 grados desde la horizontal para minimizar la tensión excesiva en las eslingas","60 grados desde la horizontal para minimizar la tensión excesiva en las eslingas","75 grados desde la horizontal para minimizar la tensión excesiva en las eslingas"], respuesta_correcta:2, explicacion:"El ángulo mínimo recomendado para eslingas es 60 grados desde la horizontal. A menor ángulo, mayor es la tensión en cada ramal de la eslinga, aumentando el riesgo de falla.", en_pregunta:"What is the minimum recommended sling angle measured from horizontal when lifting a load?", en_opciones:["30 degrees from horizontal to minimize excessive tension in the slings","45 degrees from horizontal to minimize excessive tension in the slings","60 degrees from horizontal to minimize excessive tension in the slings","75 degrees from horizontal to minimize excessive tension in the slings"], en_explicacion:"The minimum recommended sling angle is 60 degrees from horizontal. The smaller the angle, the greater the tension in each sling leg, increasing the risk of failure." },
{ id:"osha_657", categoria:"OSHA_MATERIALES", pregunta:"¿Quién está autorizado para operar un montacargas (forklift) en el lugar de trabajo según OSHA?", opciones:["Cualquier empleado mayor de 21 años que tenga licencia de conducir vigente válida","Solo empleados que hayan completado capacitación y evaluación práctica certificada","Cualquier empleado con experiencia previa en operación de maquinaria pesada industrial","Solo empleados con certificación estatal de operador de equipo pesado actualizada"], respuesta_correcta:1, explicacion:"OSHA 1910.178(l) requiere que solo operadores que hayan completado capacitación formal y evaluación práctica por parte del empleador estén autorizados para operar montacargas.", en_pregunta:"Who is authorized to operate a forklift in the workplace per OSHA?", en_opciones:["Any employee over 21 with a valid driver's license","Only employees who have completed training and certified practical evaluation","Any employee with prior heavy industrial equipment experience","Only employees with a current state heavy-equipment operator certification"], en_explicacion:"OSHA 1910.178(l) requires that only operators who have completed formal training and a practical evaluation by the employer be authorized to operate forklifts." },
{ id:"osha_658", categoria:"OSHA_MATERIALES", pregunta:"¿Con qué frecuencia debe un operador inspeccionar un montacargas según las normas de OSHA?", opciones:["Semanalmente con documentación escrita firmada por el supervisor de seguridad","Mensualmente como parte del programa de mantenimiento preventivo del equipo","Al inicio de cada turno de trabajo antes de poner el montacargas en operación","Cada 200 horas de operación según las recomendaciones del fabricante del equipo"], respuesta_correcta:2, explicacion:"OSHA 1910.178(q)(7) requiere que los montacargas sean inspeccionados al inicio de cada turno. Si se encuentran defectos, el equipo debe retirarse de servicio hasta ser reparado.", en_pregunta:"How often must an operator inspect a forklift under OSHA?", en_opciones:["Weekly with written documentation signed by the safety supervisor","Monthly as part of the equipment's preventive maintenance program","At the start of each shift before putting the forklift into operation","Every 200 hours of operation per the manufacturer's recommendations"], en_explicacion:"OSHA 1910.178(q)(7) requires forklifts to be inspected at the start of each shift. If defects are found, the equipment must be removed from service until repaired." },
{ id:"osha_659", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la señal manual estándar para indicar al operador de grúa que suba la carga lentamente?", opciones:["Un brazo extendido hacia arriba con el dedo índice apuntando hacia arriba haciendo círculos","Ambos brazos extendidos hacia arriba con las palmas abiertas moviéndose hacia el cielo","Un puño cerrado frente al pecho con el pulgar apuntando hacia arriba de forma estática","Una mano a nivel del pecho con el pulgar arriba y los dedos abriendo y cerrando despacio"], respuesta_correcta:3, explicacion:"La señal de subir lentamente (Hoist Slowly) es una mano a nivel del pecho con el pulgar apuntando hacia arriba y los dedos abriendo y cerrando, indicando movimiento lento controlado.", en_pregunta:"What is the standard hand signal to tell a crane operator to hoist the load slowly?", en_opciones:["One arm extended up with index finger pointing up, making circles","Both arms extended up with palms open, moving skyward","One closed fist in front of the chest with thumb pointing up, held static","One hand at chest level with thumb up and fingers opening and closing slowly"], en_explicacion:"The Hoist Slowly signal is one hand at chest level with the thumb pointing up and fingers opening and closing, indicating slow, controlled movement." },
{ id:"osha_660", categoria:"OSHA_MATERIALES", pregunta:"¿Cuándo se debe retirar de servicio una eslinga de cable de acero según los criterios de inspección?", opciones:["Cuando presenta tres o más alambres rotos en un mismo torón dentro de un paso del cable","Cuando presenta seis o más alambres rotos en un paso del cable o tres en un solo torón","Cuando presenta diez o más alambres rotos distribuidos aleatoriamente en todo su largo","Cuando presenta dos o más alambres rotos en cualquier sección visible del cable de acero"], respuesta_correcta:1, explicacion:"OSHA 1926.251(c)(4)(ii) establece que una eslinga de cable debe retirarse cuando tiene 6 o más alambres rotos en un paso del cable, o 3 o más en un solo torón.", en_pregunta:"When must a wire-rope sling be removed from service based on inspection criteria?", en_opciones:["When it shows three or more broken wires in a single strand within one rope lay","When it shows six or more broken wires in one rope lay, or three in a single strand","When it shows ten or more broken wires randomly distributed across its full length","When it shows two or more broken wires in any visible section of the wire rope"], en_explicacion:"OSHA 1926.251(c)(4)(ii) states that a wire-rope sling must be removed from service when it has 6 or more broken wires in one rope lay, or 3 or more in a single strand." },
{ id:"osha_661", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la altura máxima para apilar materiales manualmente sin usar equipo mecánico de elevación?", opciones:["Los materiales apilados manualmente no deben exceder los 12 pies de altura máxima","Los materiales apilados manualmente no deben exceder los 16 pies de altura máxima","Los materiales apilados manualmente no deben exceder los 20 pies de altura máxima","No hay límite fijo si el apilamiento es estable y supervisado por persona competente"], respuesta_correcta:2, explicacion:"OSHA 1926.250(b)(1) establece que los materiales apilados manualmente no deben exceder 20 pies de altura como regla general para mantener la estabilidad del apilamiento.", en_pregunta:"What is the maximum height for manually stacking materials without using mechanical lifting equipment?", en_opciones:["Manually stacked materials must not exceed 12 feet in maximum height","Manually stacked materials must not exceed 16 feet in maximum height","Manually stacked materials must not exceed 20 feet in maximum height","There is no fixed limit as long as the stack is stable and supervised by a competent person"], en_explicacion:"OSHA 1926.250(b)(1) establishes that manually stacked materials must not exceed 20 feet in height as a general rule to maintain stack stability." },
{ id:"osha_662", categoria:"OSHA_MATERIALES", pregunta:"¿Qué porcentaje de la capacidad nominal de carga de una grúa nunca debe excederse durante operación?", opciones:["No debe excederse el 75% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 80% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 85% de la capacidad nominal indicada en la tabla de cargas","No debe excederse el 100% de la capacidad indicada en la tabla de cargas vigente"], respuesta_correcta:3, explicacion:"OSHA prohíbe exceder el 100% de la capacidad nominal de la tabla de cargas del fabricante. Las tablas ya incluyen factores de seguridad; el operador nunca debe sobrepasar la capacidad indicada.", en_pregunta:"What percentage of a crane's rated load capacity should never be exceeded during operation?", en_opciones:["75% of the rated capacity shown in the load chart should not be exceeded","80% of the rated capacity shown in the load chart should not be exceeded","85% of the rated capacity shown in the load chart should not be exceeded","100% of the capacity shown in the current load chart should not be exceeded"], en_explicacion:"OSHA prohibits exceeding 100% of the manufacturer's rated load chart capacity. The charts already include safety factors; the operator must never exceed the indicated capacity." },
{ id:"osha_663", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el peso máximo recomendado por NIOSH para levantamiento manual bajo condiciones ideales?", opciones:["35 libras como límite máximo recomendado para levantamiento manual seguro repetitivo","41 libras como límite máximo recomendado para levantamiento manual seguro repetitivo","51 libras como límite máximo recomendado para levantamiento manual seguro repetitivo","65 libras como límite máximo recomendado para levantamiento manual seguro repetitivo"], respuesta_correcta:2, explicacion:"La ecuación de levantamiento revisada de NIOSH establece 51 libras (23 kg) como el límite de peso recomendado bajo condiciones ideales de levantamiento manual.", en_pregunta:"What is the maximum weight recommended by NIOSH for manual lifting under ideal conditions?", en_opciones:["35 pounds as the maximum recommended limit for safe repetitive manual lifting","41 pounds as the maximum recommended limit for safe repetitive manual lifting","51 pounds as the maximum recommended limit for safe repetitive manual lifting","65 pounds as the maximum recommended limit for safe repetitive manual lifting"], en_explicacion:"The NIOSH revised lifting equation establishes 51 pounds (23 kg) as the Recommended Weight Limit under ideal manual lifting conditions." },
{ id:"osha_664", categoria:"OSHA_MATERIALES", pregunta:"¿Qué debe verificarse PRIMERO antes de realizar cualquier operación de levantamiento con grúa?", opciones:["Verificar que todos los trabajadores tengan sus equipos de protección personal puestos","Verificar las condiciones del terreno y confirmar la capacidad de carga del equipo usado","Verificar que el operador de la grúa tenga su certificación actualizada y documentada","Verificar que el señalero designado esté en posición visible para el operador de la grúa"], respuesta_correcta:1, explicacion:"Antes de cualquier levantamiento, se debe verificar las condiciones del terreno (estabilidad, nivelación) y confirmar que la carga no exceda la capacidad del equipo según la tabla de cargas.", en_pregunta:"What must be verified FIRST before performing any crane lifting operation?", en_opciones:["Verify that all workers are wearing their personal protective equipment","Verify ground conditions and confirm the load capacity of the equipment being used","Verify that the crane operator has a current, documented certification","Verify that the designated signal person is in a position visible to the crane operator"], en_explicacion:"Before any lift, you must verify ground conditions (stability, level) and confirm that the load does not exceed the equipment's capacity according to the load chart." },
{ id:"osha_665", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la norma de OSHA que regula el manejo y almacenamiento de materiales en construcción?", opciones:["La norma 29 CFR 1926 Subpart G que cubre señalización y protección del público","La norma 29 CFR 1926 Subpart H que cubre manejo y almacenamiento de materiales","La norma 29 CFR 1926 Subpart I que cubre herramientas manuales y de poder usadas","La norma 29 CFR 1926 Subpart J que cubre soldadura y corte en áreas de construcción"], respuesta_correcta:1, explicacion:"29 CFR 1926 Subpart H es la norma específica de OSHA que regula el manejo, almacenamiento, uso y disposición de materiales en la industria de la construcción.", en_pregunta:"Which OSHA standard regulates material handling and storage in construction?", en_opciones:["29 CFR 1926 Subpart G, which covers signaling and protection of the public","29 CFR 1926 Subpart H, which covers materials handling, storage, use and disposal","29 CFR 1926 Subpart I, which covers hand and power tools used on site","29 CFR 1926 Subpart J, which covers welding and cutting in construction areas"], en_explicacion:"29 CFR 1926 Subpart H is the specific OSHA standard that regulates the handling, storage, use and disposal of materials in the construction industry." },
{ id:"osha_666", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la técnica correcta de levantamiento manual para prevenir lesiones de espalda baja?", opciones:["Doblar la cintura manteniendo las piernas rectas y levantar con la fuerza de los brazos","Doblar las rodillas manteniendo la espalda recta y levantar con la fuerza de las piernas","Girar el torso mientras levanta para distribuir el peso entre ambos lados del cuerpo","Extender los brazos lejos del cuerpo para crear mejor palanca al levantar objetos pesados"], respuesta_correcta:1, explicacion:"La técnica correcta es doblar las rodillas, mantener la espalda recta, acercar la carga al cuerpo y levantar con la fuerza de las piernas para minimizar la tensión en la espalda baja.", en_pregunta:"What is the correct manual lifting technique to prevent lower back injuries?", en_opciones:["Bend at the waist keeping legs straight and lift using arm strength","Bend at the knees keeping the back straight and lift using leg strength","Twist your torso while lifting to distribute the weight across both sides of the body","Extend arms away from the body to create better leverage when lifting heavy objects"], en_explicacion:"The correct technique is to bend at the knees, keep the back straight, hold the load close to the body, and lift with the strength of the legs to minimize strain on the lower back." },
{ id:"osha_667", categoria:"OSHA_MATERIALES", pregunta:"¿Qué factor reduce MÁS la capacidad de carga de una eslinga cuando se usa en configuración angular?", opciones:["La temperatura ambiente del entorno donde se está realizando la operación de izaje","El ángulo de la eslinga respecto a la vertical cuando se conecta al gancho de la grúa","El material de fabricación de la eslinga ya sea nylon poliéster o cable de acero usado","La velocidad con la que se eleva la carga durante la operación de izaje con la grúa"], respuesta_correcta:1, explicacion:"El ángulo de la eslinga es el factor que más afecta su capacidad. A menor ángulo respecto a la vertical (más abierta), mayor tensión en cada ramal y menor capacidad efectiva de carga.", en_pregunta:"Which factor MOST reduces the load capacity of a sling when used at an angle?", en_opciones:["The ambient temperature of the environment where the lift is being performed","The sling angle relative to vertical when connected to the crane hook","The sling's material of construction, whether nylon, polyester or wire rope","The speed at which the load is hoisted during the crane lift operation"], en_explicacion:"The sling angle is the factor that most affects its capacity. The lower the angle relative to vertical (more open/horizontal), the greater the tension in each leg and the lower the effective load capacity." },
{ id:"osha_668", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el requisito para almacenar cilindros de gas comprimido en el área de trabajo según OSHA?", opciones:["Almacenarlos acostados horizontalmente asegurados con cuñas para que no se muevan","Almacenarlos en posición vertical asegurados con cadenas o soportes contra volcamiento","Almacenarlos en cualquier posición siempre que estén dentro de un gabinete ventilado fijo","Almacenarlos en grupos de máximo seis cilindros separados por tipo con señalización clara"], respuesta_correcta:1, explicacion:"OSHA 1926.350(a)(9) requiere que los cilindros de gas comprimido se almacenen en posición vertical y se aseguren con cadenas o soportes para prevenir que se volteen o caigan.", en_pregunta:"What is the OSHA requirement for storing compressed gas cylinders in the work area?", en_opciones:["Store them lying horizontally secured with wedges so they cannot move","Store them upright, secured with chains or supports to prevent tipping over","Store them in any position as long as they are inside a fixed ventilated cabinet","Store them in groups of no more than six cylinders separated by type with clear signage"], en_explicacion:"OSHA 1926.350(a)(9) requires compressed gas cylinders to be stored upright and secured with chains or supports to prevent them from tipping or falling." },
{ id:"osha_669", categoria:"OSHA_MATERIALES", pregunta:"¿Qué significa la señal manual de un brazo extendido horizontalmente con el dedo índice apuntando al suelo haciendo círculos?", opciones:["Significa que el operador debe girar la pluma de la grúa hacia la derecha lentamente","Significa que el operador debe bajar la carga hacia el punto indicado por el señalero","Significa que el operador debe mover el carro del puente grúa en dirección al señalero","Significa que el operador debe recoger el cable auxiliar de la grúa de forma inmediata"], respuesta_correcta:1, explicacion:"Un brazo extendido con el dedo índice apuntando hacia abajo haciendo círculos es la señal estándar de 'bajar' (Lower) la carga, según las señales manuales de ASME B30.5.", en_pregunta:"What does the hand signal of an extended arm horizontally with the index finger pointing down making circles mean?", en_opciones:["It means the operator must slowly swing the crane boom to the right","It means the operator must lower the load to the point indicated by the signal person","It means the operator must move the bridge crane trolley in the direction of the signal person","It means the operator must immediately retract the crane's auxiliary cable"], en_explicacion:"An extended arm with the index finger pointing downward making circles is the standard 'Lower' signal for the load, per ASME B30.5 standard hand signals." },
{ id:"osha_670", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el requisito de OSHA para las áreas de almacenamiento de materiales en sitios de construcción?", opciones:["Deben estar cercadas con malla metálica de al menos 6 pies de altura con acceso controlado","Deben mantenerse libres de vegetación excesiva y desechos acumulados que obstruyan acceso","Deben tener iluminación artificial de al menos 50 lux en todas las áreas de almacenamiento","Deben estar pavimentadas con concreto o asfalto para prevenir hundimiento de materiales"], respuesta_correcta:1, explicacion:"OSHA 1926.250(a)(1) requiere que las áreas de almacenamiento se mantengan libres de acumulación de materiales de desecho, vegetación excesiva y otros obstáculos que creen peligros.", en_pregunta:"What is OSHA's requirement for material storage areas on construction sites?", en_opciones:["They must be fenced with chain-link at least 6 feet high with controlled access","They must be kept free of excessive vegetation and accumulated debris that obstruct access","They must have artificial lighting of at least 50 lux throughout the storage areas","They must be paved with concrete or asphalt to prevent materials from sinking"], en_explicacion:"OSHA 1926.250(a)(1) requires that storage areas be kept free of accumulated waste materials, excessive vegetation, and other obstructions that create hazards." },
{ id:"osha_671", categoria:"OSHA_MATERIALES", pregunta:"¿Con qué frecuencia deben inspeccionarse las eslingas según OSHA antes de ser utilizadas?", opciones:["Las eslingas deben inspeccionarse una vez por semana por una persona calificada designada","Las eslingas deben inspeccionarse antes de cada uso por una persona competente designada","Las eslingas deben inspeccionarse mensualmente y documentar los resultados por cada eslinga","Las eslingas deben inspeccionarse cada 90 días con registro escrito firmado y archivado"], respuesta_correcta:1, explicacion:"OSHA 1926.251(a)(1) requiere que las eslingas sean inspeccionadas antes de cada uso por una persona competente para detectar daños, deformaciones o deterioro que comprometan su integridad.", en_pregunta:"How often must slings be inspected per OSHA before being used?", en_opciones:["Slings must be inspected once a week by a designated qualified person","Slings must be inspected before each use by a designated competent person","Slings must be inspected monthly with documented results for each sling","Slings must be inspected every 90 days with a signed, filed written record"], en_explicacion:"OSHA 1926.251(a)(1) requires slings to be inspected before each use by a competent person to detect damage, deformation, or deterioration that would compromise their integrity." },
{ id:"osha_672", categoria:"OSHA_MATERIALES", pregunta:"¿Qué acción debe tomarse si un montacargas necesita ser dejado desatendido según las normas de OSHA?", opciones:["Apagar el motor y colocar un cono de seguridad naranja frente al equipo estacionado","Bajar las horquillas al suelo, poner freno de mano, apagar motor y retirar la llave","Bajar las horquillas al suelo y activar las luces intermitentes de advertencia del equipo","Colocar cuñas en las ruedas traseras y dejar el motor encendido en ralentí con freno puesto"], respuesta_correcta:1, explicacion:"OSHA 1910.178(m)(5) requiere que al dejar un montacargas desatendido se bajen las horquillas al piso, se aplique el freno de estacionamiento, se apague el motor y se retire la llave.", en_pregunta:"What action must be taken if a forklift needs to be left unattended per OSHA rules?", en_opciones:["Shut off the engine and place an orange safety cone in front of the parked equipment","Lower the forks to the floor, set the parking brake, shut off the engine, and remove the key","Lower the forks to the floor and activate the equipment's flashing warning lights","Place wheel chocks on the rear tires and leave the engine idling with the brake set"], en_explicacion:"OSHA 1910.178(m)(5) requires that when leaving a forklift unattended, the forks be lowered to the floor, the parking brake be applied, the engine be shut off, and the key be removed." },
{ id:"osha_673", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la distancia mínima segura que debe mantenerse de una carga suspendida por una grúa?", opciones:["Al menos 5 pies de distancia de cualquier carga suspendida durante operaciones de izaje","Al menos 10 pies de distancia de cualquier carga suspendida durante operaciones de izaje","Nadie debe estar debajo ni en la zona de giro de una carga suspendida en ningún momento","Al menos 20 pies de distancia de cualquier carga suspendida durante operaciones de izaje"], respuesta_correcta:2, explicacion:"OSHA 1926.1425(c) prohíbe que cualquier persona se posicione debajo de una carga suspendida o dentro de la zona de giro. No es solo distancia, es prohibición absoluta de estar bajo la carga.", en_pregunta:"What is the minimum safe distance that must be maintained from a load suspended by a crane?", en_opciones:["At least 5 feet from any suspended load during hoisting operations","At least 10 feet from any suspended load during hoisting operations","No one should be under or in the swing zone of a suspended load at any time","At least 20 feet from any suspended load during hoisting operations"], en_explicacion:"OSHA 1926.1425(c) prohibits any person from being positioned under a suspended load or within the swing radius. It is not just a distance requirement — it is an absolute prohibition on being under the load." },
{ id:"osha_674", categoria:"OSHA_MATERIALES", pregunta:"¿Qué tipo de eslinga NO debe usarse para levantar cargas con bordes afilados sin protección adicional?", opciones:["Eslingas de cable de acero porque los bordes afilados cortan los alambres del cable rápido","Eslingas de cadena de aleación porque los bordes afilados debilitan los eslabones de acero","Eslingas sintéticas de nylon o poliéster porque se cortan fácilmente con bordes afilados","Eslingas de malla metálica porque los bordes afilados deforman la trama del tejido metálico"], respuesta_correcta:2, explicacion:"Las eslingas sintéticas de nylon o poliéster son las más vulnerables a bordes afilados y se cortan fácilmente. OSHA 1926.251(b)(4) requiere protección de bordes cuando se usan con cargas cortantes.", en_pregunta:"Which type of sling should NOT be used to lift loads with sharp edges without additional protection?", en_opciones:["Wire rope slings, because sharp edges quickly cut the wire strands","Alloy chain slings, because sharp edges weaken the steel links","Synthetic nylon or polyester slings, because sharp edges cut them easily","Metal mesh slings, because sharp edges deform the metal weave"], en_explicacion:"Synthetic nylon or polyester slings are the most vulnerable to sharp edges and cut easily. OSHA 1926.251(b)(4) requires edge protection when used with cutting loads." },
{ id:"osha_675", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el requisito para la placa de capacidad (data plate) en un montacargas según OSHA?", opciones:["La placa debe estar visible pero puede cubrirse parcialmente si no interfiere con el trabajo","La placa debe estar legible y visible en todo momento en la ubicación original del fabricante","La placa puede reemplazarse con una etiqueta adhesiva equivalente con la misma información","La placa solo es necesaria en montacargas con capacidad superior a las 5000 libras totales"], respuesta_correcta:1, explicacion:"OSHA 1910.178(a)(7) requiere que la placa de datos del fabricante con la capacidad nominal esté legible y visible en todo momento. Operar sin placa o con placa ilegible es una violación.", en_pregunta:"What is the requirement for the capacity data plate on a forklift per OSHA?", en_opciones:["The plate must be visible but may be partially covered if it does not interfere with the work","The plate must be legible and visible at all times in the manufacturer's original location","The plate may be replaced with an equivalent adhesive label containing the same information","The plate is only required on forklifts with a capacity greater than 5,000 pounds"], en_explicacion:"OSHA 1910.178(a)(7) requires the manufacturer's data plate with the rated capacity to be legible and visible at all times. Operating without a plate or with an illegible plate is a violation." },
{ id:"osha_676", categoria:"OSHA_MATERIALES", pregunta:"¿Qué debe hacerse cuando se descubre una eslinga de cadena con eslabones deformados o estirados?", opciones:["Reparar los eslabones dañados mediante soldadura certificada y volver a poner en servicio","Retirar inmediatamente de servicio y no reutilizar hasta que sea inspeccionada y recertificada","Reducir la capacidad nominal de la eslinga en un 50% y continuar usándola con precaución","Marcar los eslabones dañados con pintura y limitar el uso a cargas menores de 500 libras"], respuesta_correcta:1, explicacion:"OSHA 1926.251(b)(2) requiere que eslingas de cadena con eslabones deformados, estirados o agrietados sean retiradas inmediatamente de servicio. No se permite reparación por soldadura en campo.", en_pregunta:"What must be done when a chain sling is found with deformed or stretched links?", en_opciones:["Repair the damaged links by certified welding and return to service","Remove it from service immediately and do not reuse until inspected and recertified","Derate the sling's rated capacity by 50% and continue using it with caution","Mark the damaged links with paint and limit use to loads under 500 pounds"], en_explicacion:"OSHA 1926.251(b)(2) requires chain slings with deformed, stretched or cracked links to be removed from service immediately. Field welding repairs are not permitted." },
{ id:"osha_677", categoria:"OSHA_MATERIALES", pregunta:"¿Cuántas señales manuales debe conocer un señalero (signal person) calificado como mínimo?", opciones:["Debe conocer al menos las 8 señales básicas estandarizadas por ASME para grúas de obra","Debe conocer todas las señales estándar aplicables al tipo de grúa que se está operando","Debe conocer al menos 12 señales que incluyen emergencia y movimientos multidireccionales","Debe conocer las 5 señales fundamentales de subir, bajar, parar, girar y avanzar la grúa"], respuesta_correcta:1, explicacion:"OSHA 1926.1428 requiere que el señalero calificado conozca TODAS las señales manuales estándar aplicables al equipo en uso, no un número mínimo fijo. Debe demostrar competencia completa.", en_pregunta:"How many hand signals must a qualified signal person know at minimum?", en_opciones:["At least the 8 basic signals standardized by ASME for construction cranes","All standard signals applicable to the type of crane being operated","At least 12 signals including emergency and multi-directional movements","The 5 fundamental signals of hoist, lower, stop, swing and move the crane"], en_explicacion:"OSHA 1926.1428 requires a qualified signal person to know ALL standard hand signals applicable to the equipment in use — not a fixed minimum. The signal person must demonstrate full competence." },
{ id:"osha_678", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la norma de OSHA para industria general que regula montacargas industriales motorizados?", opciones:["La norma 29 CFR 1910 Subpart M que cubre superficies para caminar y trabajar en planta","La norma 29 CFR 1910 Subpart N que cubre manejo de materiales y almacenamiento general","La norma 29 CFR 1910 Subpart O que cubre maquinaria y protección de máquinas en planta","La norma 29 CFR 1910 Subpart P que cubre herramientas manuales y portátiles de poder"], respuesta_correcta:1, explicacion:"29 CFR 1910 Subpart N cubre el manejo de materiales y almacenamiento, incluyendo 1910.178 que es la norma específica para montacargas industriales motorizados (powered industrial trucks).", en_pregunta:"Which general industry OSHA standard regulates powered industrial trucks?", en_opciones:["29 CFR 1910 Subpart M, which covers walking-working surfaces","29 CFR 1910 Subpart N, which covers materials handling and storage","29 CFR 1910 Subpart O, which covers machinery and machine guarding","29 CFR 1910 Subpart P, which covers hand and portable power tools"], en_explicacion:"29 CFR 1910 Subpart N covers materials handling and storage, including 1910.178, which is the specific standard for powered industrial trucks (forklifts)." },
{ id:"osha_679", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es la velocidad máxima permitida para un montacargas dentro de un edificio o almacén cerrado?", opciones:["No más de 5 millas por hora dentro de edificios y áreas de trabajo interiores cerrados","No hay velocidad fija establecida, debe ser segura para las condiciones del área de trabajo","No más de 10 millas por hora dentro de edificios y áreas de trabajo interiores cerrados","No más de 15 millas por hora dentro de edificios y áreas de trabajo interiores cerrados"], respuesta_correcta:1, explicacion:"OSHA no establece una velocidad máxima fija para montacargas. 1910.178(n)(1) requiere que se mantenga una velocidad segura según las condiciones del área, incluyendo visibilidad, tráfico y superficie.", en_pregunta:"What is the maximum allowed speed for a forklift inside a building or enclosed warehouse?", en_opciones:["No more than 5 miles per hour inside buildings and enclosed interior work areas","There is no fixed speed — it must be safe for the conditions of the work area","No more than 10 miles per hour inside buildings and enclosed interior work areas","No more than 15 miles per hour inside buildings and enclosed interior work areas"], en_explicacion:"OSHA does not establish a fixed maximum speed for forklifts. 1910.178(n)(1) requires a safe speed appropriate to the area conditions, including visibility, traffic and surface." },
{ id:"osha_680", categoria:"OSHA_MATERIALES", pregunta:"¿Qué se debe hacer con los materiales almacenados en pilas para prevenir deslizamientos o colapsos?", opciones:["Cubrir las pilas con lonas impermeables aseguradas con cuerdas para dar estabilidad total","Apilar en forma de pirámide escalonada y asegurar con cuñas de madera entre cada nivel","Asegurar que las pilas estén apiladas ordenadamente con trabas cruzadas o medios seguros","Rodear cada pila con barreras metálicas de contención de al menos tres pies de altura fija"], respuesta_correcta:2, explicacion:"OSHA 1926.250(a)(1) requiere que los materiales apilados estén ordenados, con trabas cruzadas (cross-tied) donde sea aplicable, y asegurados para prevenir deslizamientos o colapsos.", en_pregunta:"What must be done with materials stored in piles to prevent sliding or collapse?", en_opciones:["Cover the piles with waterproof tarps secured with ropes for full stability","Stack in a stepped pyramid and secure with wooden wedges between each level","Ensure piles are stacked in an orderly manner with cross-tying or other secure means","Surround each pile with metal containment barriers at least three feet high"], en_explicacion:"OSHA 1926.250(a)(1) requires stacked materials to be orderly, cross-tied where applicable, and secured to prevent sliding or collapse." },
{ id:"osha_681", categoria:"OSHA_MATERIALES", pregunta:"¿Qué indica una reducción del diámetro del cable de acero de una eslinga de más de un tercio del diámetro original?", opciones:["Indica desgaste moderado y la eslinga puede seguir en uso con capacidad reducida al 75%","Indica que la eslinga necesita lubricación inmediata para restaurar su diámetro original","Indica deterioro severo y la eslinga debe ser retirada de servicio inmediatamente por seguridad","Indica que los alambres internos se acomodaron y es normal durante el período de asentamiento"], respuesta_correcta:2, explicacion:"Una reducción del diámetro de más de 1/3 del original en un cable de acero indica deterioro severo (desgaste, corrosión interna o rotura de alambres). La eslinga debe retirarse inmediatamente de servicio.", en_pregunta:"What does a reduction in wire rope sling diameter of more than one-third of the original diameter indicate?", en_opciones:["It indicates moderate wear and the sling can remain in service at 75% reduced capacity","It indicates the sling needs immediate lubrication to restore its original diameter","It indicates severe deterioration and the sling must be removed from service immediately","It indicates that the internal wires have settled, which is normal during break-in"], en_explicacion:"A diameter reduction of more than 1/3 of the original in a wire rope indicates severe deterioration (wear, internal corrosion or broken wires). The sling must be removed from service immediately." },
{ id:"osha_682", categoria:"OSHA_MATERIALES", pregunta:"¿Está permitido que un trabajador viaje como pasajero en las horquillas de un montacargas en uso?", opciones:["Sí, si el trabajador usa arnés de seguridad atado al mástil del montacargas correctamente","Sí, si la velocidad del montacargas no excede 3 millas por hora durante el desplazamiento","No, nunca se permite que personas viajen en las horquillas de un montacargas bajo ningún caso","Sí, solo si se instala una plataforma de trabajo aprobada y diseñada para montacargas usado"], respuesta_correcta:2, explicacion:"OSHA 1910.178(m)(13) prohíbe absolutamente que cualquier persona viaje sobre las horquillas de un montacargas. Para elevar personas, se requiere una plataforma de trabajo aprobada y asegurada.", en_pregunta:"Is a worker allowed to ride as a passenger on the forks of a forklift in use?", en_opciones:["Yes, if the worker wears a safety harness correctly tied off to the forklift mast","Yes, if the forklift's travel speed does not exceed 3 miles per hour","No — people are never allowed to ride on the forks of a forklift under any circumstances","Yes, only if an approved work platform designed for forklift use is installed"], en_explicacion:"OSHA 1910.178(m)(13) absolutely prohibits any person from riding on the forks of a forklift. To elevate people, an approved, secured work platform is required." },
{ id:"osha_683", categoria:"OSHA_MATERIALES", pregunta:"¿Cada cuánto tiempo debe recertificarse la capacitación de un operador de montacargas según OSHA?", opciones:["La recertificación del operador de montacargas debe hacerse anualmente sin excepciones","La recertificación del operador de montacargas debe hacerse cada dos años como mínimo","La recertificación del operador de montacargas debe hacerse cada tres años como mínimo","La recertificación del operador de montacargas debe hacerse cada cinco años como mínimo"], respuesta_correcta:2, explicacion:"OSHA 1910.178(l)(4)(iii) requiere que la evaluación del desempeño del operador de montacargas se realice al menos cada tres años para mantener la certificación vigente.", en_pregunta:"How often must a forklift operator's training be recertified per OSHA?", en_opciones:["Forklift operator recertification must be done annually without exception","Forklift operator recertification must be done at least every two years","Forklift operator recertification must be done at least every three years","Forklift operator recertification must be done at least every five years"], en_explicacion:"OSHA 1910.178(l)(4)(iii) requires that the forklift operator's performance evaluation be conducted at least every three years to keep the certification current." },
{ id:"osha_684", categoria:"OSHA_MATERIALES", pregunta:"¿Cuál es el factor de diseño mínimo (design factor) para eslingas de cable de acero según OSHA?", opciones:["El factor de diseño mínimo para eslingas de cable de acero es de tres a uno establecido","El factor de diseño mínimo para eslingas de cable de acero es de cuatro a uno establecido","El factor de diseño mínimo para eslingas de cable de acero es de cinco a uno establecido","El factor de diseño mínimo para eslingas de cable de acero es de seis a uno establecido"], respuesta_correcta:2, explicacion:"OSHA 1926.251(c)(1) establece un factor de diseño mínimo de 5:1 para eslingas de cable de acero, lo que significa que la resistencia a la rotura debe ser al menos 5 veces la carga de trabajo.", en_pregunta:"What is the minimum design factor for wire rope slings per OSHA?", en_opciones:["The minimum design factor for wire rope slings is three to one","The minimum design factor for wire rope slings is four to one","The minimum design factor for wire rope slings is five to one","The minimum design factor for wire rope slings is six to one"], en_explicacion:"OSHA 1926.251(c)(1) establishes a minimum design factor of 5:1 for wire rope slings, meaning the breaking strength must be at least 5 times the working load." },
  { id:"osha_685", categoria:"OSHA_TOXICOS", pregunta:"¿Qué representa el valor PEL establecido por OSHA para sustancias tóxicas en el ambiente laboral?", opciones:["Concentración máxima recomendada por NIOSH para turnos de 10 horas","Límite de exposición permisible promediado en jornada de 8 horas","Concentración inmediatamente peligrosa para la vida y la salud","Límite umbral de exposición a corto plazo de 15 minutos máximo"], respuesta_correcta:1, explicacion:"PEL (Permissible Exposure Limit) es el límite legal de OSHA promediado en 8 horas TWA. TLV es de ACGIH, IDLH es concentración inmediatamente peligrosa, y STEL es límite a corto plazo.", en_pregunta:"What does the PEL value established by OSHA represent for toxic substances in the workplace?", en_opciones:["Maximum concentration recommended by NIOSH for 10-hour shifts","Permissible Exposure Limit averaged over an 8-hour workday","Concentration that is immediately dangerous to life and health","Short-term exposure threshold limit of 15 minutes maximum"], en_explicacion:"PEL (Permissible Exposure Limit) is OSHA's legal limit averaged over an 8-hour TWA. TLV is from ACGIH, IDLH is the immediately dangerous concentration, and STEL is the short-term limit." },
  { id:"osha_686", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es la diferencia principal entre el TLV-TWA y el TLV-STEL en higiene industrial?", opciones:["TWA se mide con dosímetro personal y STEL se mide con tubos colorimétricos","TWA es promedio de 8 horas y STEL es límite para exposiciones de 15 minutos","TWA aplica a gases y STEL aplica exclusivamente a vapores orgánicos","TWA es obligatorio por ley federal y STEL es solo una guía voluntaria"], respuesta_correcta:1, explicacion:"TLV-TWA es el promedio ponderado en 8 horas, mientras que TLV-STEL es el límite para exposiciones cortas de 15 minutos. Ambos son recomendaciones de ACGIH, no leyes federales.", en_pregunta:"What is the main difference between TLV-TWA and TLV-STEL in industrial hygiene?", en_opciones:["TWA is measured with a personal dosimeter and STEL with colorimetric tubes","TWA is an 8-hour average and STEL is the limit for 15-minute exposures","TWA applies to gases and STEL applies exclusively to organic vapors","TWA is mandated by federal law and STEL is only a voluntary guideline"], en_explicacion:"TLV-TWA is the 8-hour time-weighted average, while TLV-STEL is the limit for short 15-minute exposures. Both are ACGIH recommendations, not federal laws." },
  { id:"osha_687", categoria:"OSHA_TOXICOS", pregunta:"Un técnico HVAC encuentra un refrigerante desconocido en un equipo viejo. ¿Qué sección del SDS indica los límites de exposición ocupacional?", opciones:["Sección 2 — Identificación de peligros según clasificación GHS","Sección 8 — Controles de exposición y protección personal","Sección 11 — Información toxicológica y efectos en la salud","Sección 9 — Propiedades físicas y químicas del producto"], respuesta_correcta:1, explicacion:"La Sección 8 del SDS en formato GHS contiene los límites de exposición ocupacional (PEL, TLV) y las medidas de protección personal recomendadas.", en_pregunta:"An HVAC technician finds an unknown refrigerant in an old unit. Which section of the SDS lists the occupational exposure limits?", en_opciones:["Section 2 — Hazard identification per GHS classification","Section 8 — Exposure controls and personal protection","Section 11 — Toxicological information and health effects","Section 9 — Physical and chemical properties of the product"], en_explicacion:"Section 8 of the GHS-format SDS contains the occupational exposure limits (PEL, TLV) and recommended personal protection measures." },
  { id:"osha_688", categoria:"OSHA_TOXICOS", pregunta:"¿Cuántas secciones tiene una Hoja de Datos de Seguridad (SDS) bajo el formato GHS adoptado por OSHA?", opciones:["12 secciones organizadas por categoría de riesgo físico","14 secciones que cubren transporte y disposición final","16 secciones estandarizadas con orden obligatorio fijo","18 secciones incluyendo información ambiental detallada"], respuesta_correcta:2, explicacion:"El formato GHS adoptado por OSHA en el Hazard Communication Standard requiere 16 secciones en orden fijo y estandarizado para todas las SDS.", en_pregunta:"How many sections does a Safety Data Sheet (SDS) have under the GHS format adopted by OSHA?", en_opciones:["12 sections organized by physical risk category","14 sections covering transport and final disposal","16 standardized sections in a mandatory fixed order","18 sections including detailed environmental information"], en_explicacion:"The GHS format adopted by OSHA in the Hazard Communication Standard requires 16 sections in a fixed, standardized order for all SDS documents." },
  { id:"osha_689", categoria:"OSHA_TOXICOS", pregunta:"¿Qué instrumento es más apropiado para detectar compuestos orgánicos volátiles en concentraciones bajas durante trabajo HVAC?", opciones:["Detector de gas combustible catalítico con lectura en %LEL","Detector de fotoionización (PID) con lámpara de 10.6 eV","Medidor multi-gas con sensores electroquímicos de 4 gases","Tubo colorimétrico Dräger específico para cada compuesto"], respuesta_correcta:1, explicacion:"El detector de fotoionización (PID) es el instrumento más sensible para detectar VOCs en concentraciones bajas (ppb/ppm). Los multi-gas miden gases comunes, no VOCs específicos.", en_pregunta:"Which instrument is most appropriate for detecting volatile organic compounds at low concentrations during HVAC work?", en_opciones:["Catalytic combustible gas detector reading in %LEL","Photoionization detector (PID) with a 10.6 eV lamp","Multi-gas meter with four-gas electrochemical sensors","Dräger colorimetric tubes specific to each compound"], en_explicacion:"The photoionization detector (PID) is the most sensitive instrument for detecting VOCs at low concentrations (ppb/ppm). Multi-gas meters measure common gases, not specific VOCs." },
  { id:"osha_690", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es el PEL de OSHA para fibras de asbesto en el aire durante una jornada laboral de 8 horas?", opciones:["0.01 fibras por centímetro cúbico promediado en 8 horas","0.1 fibras por centímetro cúbico promediado en 8 horas","1.0 fibras por centímetro cúbico promediado en 8 horas","0.5 fibras por centímetro cúbico promediado en 8 horas"], respuesta_correcta:1, explicacion:"El PEL de OSHA para asbesto es 0.1 f/cc como TWA de 8 horas, con un límite de excursión de 1.0 f/cc en 30 minutos. Esto aplica a todas las formas de asbesto.", en_pregunta:"What is OSHA's PEL for airborne asbestos fibers over an 8-hour workday?", en_opciones:["0.01 fibers per cubic centimeter averaged over 8 hours","0.1 fibers per cubic centimeter averaged over 8 hours","1.0 fibers per cubic centimeter averaged over 8 hours","0.5 fibers per cubic centimeter averaged over 8 hours"], en_explicacion:"OSHA's PEL for asbestos is 0.1 f/cc as an 8-hour TWA, with an excursion limit of 1.0 f/cc over 30 minutes. This applies to all forms of asbestos." },
  { id:"osha_691", categoria:"OSHA_TOXICOS", pregunta:"Bajo la regulación AHERA, ¿qué clase de trabajo con asbesto incluye la remoción de aislamiento térmico de tuberías en sistemas HVAC?", opciones:["Clase II — remoción de materiales que no son aislamiento friable","Clase III — trabajos de reparación y mantenimiento que perturban ACM","Clase I — remoción de aislamiento térmico y material de revestimiento","Clase IV — trabajos de custodia y limpieza de áreas contaminadas"], respuesta_correcta:2, explicacion:"Clase I es la categoría de mayor riesgo e incluye remoción de TSI (thermal system insulation) y surfacing material. Clase II es remoción de otros ACM como pisos y techos.", en_pregunta:"Under AHERA regulations, which class of asbestos work includes removing thermal insulation from HVAC piping?", en_opciones:["Class II — removal of materials that are not friable insulation","Class III — repair and maintenance work that disturbs ACM","Class I — removal of thermal system insulation and surfacing material","Class IV — custodial work and cleaning of contaminated areas"], en_explicacion:"Class I is the highest-risk category and includes removal of thermal system insulation (TSI) and surfacing material. Class II is removal of other ACM such as flooring and roofing." },
  { id:"osha_692", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es el PEL de OSHA para exposición a plomo en el aire y a qué nivel se activa la vigilancia médica?", opciones:["25 μg/m³ PEL y vigilancia médica a 20 μg/m³ nivel de acción","50 μg/m³ PEL y vigilancia médica a 30 μg/m³ nivel de acción","75 μg/m³ PEL y vigilancia médica a 50 μg/m³ nivel de acción","100 μg/m³ PEL y vigilancia médica a 75 μg/m³ nivel de acción"], respuesta_correcta:1, explicacion:"El PEL de OSHA para plomo es 50 μg/m³ TWA de 8 horas. El nivel de acción es 30 μg/m³, que activa monitoreo de aire, vigilancia médica y análisis de plomo en sangre.", en_pregunta:"What is OSHA's airborne PEL for lead and at what level does medical surveillance kick in?", en_opciones:["25 μg/m³ PEL and medical surveillance at a 20 μg/m³ action level","50 μg/m³ PEL and medical surveillance at a 30 μg/m³ action level","75 μg/m³ PEL and medical surveillance at a 50 μg/m³ action level","100 μg/m³ PEL and medical surveillance at a 75 μg/m³ action level"], en_explicacion:"OSHA's PEL for lead is 50 μg/m³ as an 8-hour TWA. The action level is 30 μg/m³, which triggers air monitoring, medical surveillance and blood lead testing." },
  { id:"osha_693", categoria:"OSHA_TOXICOS", pregunta:"Un técnico HVAC suelda tuberías de cobre en un edificio viejo con pintura de plomo. ¿A qué nivel de plomo en sangre OSHA requiere remoción médica del trabajador?", opciones:["25 μg/dL requiere remoción médica inmediata del lugar de trabajo","40 μg/dL requiere remoción médica inmediata del lugar de trabajo","50 μg/dL requiere remoción médica inmediata del lugar de trabajo","60 μg/dL requiere remoción médica inmediata del lugar de trabajo"], respuesta_correcta:2, explicacion:"OSHA requiere remoción médica cuando el nivel de plomo en sangre alcanza 50 μg/dL en construcción (o un promedio de tres muestras). El retorno se permite a 40 μg/dL.", en_pregunta:"An HVAC tech solders copper pipe in an old building with lead-based paint. At what blood lead level does OSHA require medical removal of the worker?", en_opciones:["25 μg/dL requires immediate medical removal from the workplace","40 μg/dL requires immediate medical removal from the workplace","50 μg/dL requires immediate medical removal from the workplace","60 μg/dL requires immediate medical removal from the workplace"], en_explicacion:"OSHA requires medical removal when the blood lead level reaches 50 μg/dL in construction (or an average of three samples). Return to work is allowed at 40 μg/dL." },
  { id:"osha_694", categoria:"OSHA_TOXICOS", pregunta:"¿Qué controles especifica la Tabla 1 de OSHA para sílice cristalina respirable cuando se corta concreto con sierra estacionaria?", opciones:["Usar sierra con suministro continuo de agua y respirador N95 siempre","Usar sierra con suministro continuo de agua que minimice la emisión","Usar ventilación por extracción local con filtro HEPA integrado","Usar respirador de cara completa con cartuchos P100 solamente"], respuesta_correcta:1, explicacion:"La Tabla 1 de 29 CFR 1926.1153 especifica controles de ingeniería por tarea. Para sierras estacionarias, requiere suministro continuo de agua. No siempre exige respirador si los controles funcionan.", en_pregunta:"What controls does OSHA Table 1 specify for respirable crystalline silica when cutting concrete with a stationary saw?", en_opciones:["Use a saw with a continuous water supply and always wear an N95 respirator","Use a saw with a continuous water supply that minimizes emissions","Use local exhaust ventilation with integrated HEPA filtration","Use a full-face respirator with P100 cartridges only"], en_explicacion:"Table 1 of 29 CFR 1926.1153 specifies engineering controls by task. For stationary saws, it requires a continuous water supply. A respirator is not always required if the controls are effective." },
  { id:"osha_695", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es el PEL de OSHA para sílice cristalina respirable y cuál es la regulación aplicable en construcción?", opciones:["25 μg/m³ TWA bajo la regulación 29 CFR 1926.1152 de OSHA","50 μg/m³ TWA bajo la regulación 29 CFR 1926.1153 de OSHA","75 μg/m³ TWA bajo la regulación 29 CFR 1910.1053 de OSHA","100 μg/m³ TWA bajo la regulación 29 CFR 1926.1101 de OSHA"], respuesta_correcta:1, explicacion:"El PEL para sílice cristalina respirable es 50 μg/m³ TWA de 8 horas. La regulación de construcción es 29 CFR 1926.1153, y la de industria general es 29 CFR 1910.1053.", en_pregunta:"What is OSHA's PEL for respirable crystalline silica and which regulation applies to construction?", en_opciones:["25 μg/m³ TWA under OSHA regulation 29 CFR 1926.1152","50 μg/m³ TWA under OSHA regulation 29 CFR 1926.1153","75 μg/m³ TWA under OSHA regulation 29 CFR 1910.1053","100 μg/m³ TWA under OSHA regulation 29 CFR 1926.1101"], en_explicacion:"The PEL for respirable crystalline silica is 50 μg/m³ as an 8-hour TWA. The construction standard is 29 CFR 1926.1153, and the general industry standard is 29 CFR 1910.1053." },
  { id:"osha_696", categoria:"OSHA_TOXICOS", pregunta:"El amoniaco (R-717) se usa como refrigerante industrial. ¿Cuáles son sus límites de exposición OSHA TWA y STEL?", opciones:["50 ppm TWA de 8 horas y 75 ppm STEL de 15 minutos máximo","25 ppm TWA de 8 horas y 35 ppm STEL de 15 minutos máximo","10 ppm TWA de 8 horas y 25 ppm STEL de 15 minutos máximo","35 ppm TWA de 8 horas y 50 ppm STEL de 15 minutos máximo"], respuesta_correcta:1, explicacion:"El PEL de OSHA para amoniaco es 50 ppm TWA, pero el TLV de ACGIH (más protectivo y comúnmente referenciado) es 25 ppm TWA y 35 ppm STEL. OSHA acepta las guías ACGIH como referencia.", en_pregunta:"Ammonia (R-717) is used as an industrial refrigerant. What are its OSHA TWA and STEL exposure limits?", en_opciones:["50 ppm TWA over 8 hours and 75 ppm STEL over 15 minutes","25 ppm TWA over 8 hours and 35 ppm STEL over 15 minutes","10 ppm TWA over 8 hours and 25 ppm STEL over 15 minutes","35 ppm TWA over 8 hours and 50 ppm STEL over 15 minutes"], en_explicacion:"OSHA's PEL for ammonia is 50 ppm TWA, but the ACGIH TLV (more protective and commonly referenced) is 25 ppm TWA and 35 ppm STEL. OSHA accepts ACGIH guidance as reference." },
  { id:"osha_697", categoria:"OSHA_TOXICOS", pregunta:"¿Qué gas tóxico se produce cuando un refrigerante HFC entra en contacto con llama abierta o superficies muy calientes?", opciones:["Fosgeno y fluoruro de carbonilo por descomposición del refrigerante","Ácido fluorhídrico por descomposición térmica del refrigerante","Dióxido de azufre por la reacción del aceite con el refrigerante","Monóxido de carbono por la combustión incompleta del refrigerante"], respuesta_correcta:1, explicacion:"La descomposición térmica de refrigerantes HFC produce ácido fluorhídrico (HF), que es extremadamente corrosivo y tóxico. También puede producir fosgeno con HCFCs, pero el HF es el producto principal.", en_pregunta:"What toxic gas is produced when an HFC refrigerant contacts an open flame or very hot surfaces?", en_opciones:["Phosgene and carbonyl fluoride from refrigerant decomposition","Hydrofluoric acid from thermal decomposition of the refrigerant","Sulfur dioxide from the reaction of oil with the refrigerant","Carbon monoxide from incomplete combustion of the refrigerant"], en_explicacion:"Thermal decomposition of HFC refrigerants produces hydrofluoric acid (HF), which is extremely corrosive and toxic. HCFCs can also produce phosgene, but HF is the primary product." },
  { id:"osha_698", categoria:"OSHA_TOXICOS", pregunta:"Un técnico instala aislamiento de espuma de poliuretano por aspersión. ¿Qué sustancia química representa el mayor riesgo de sensibilización respiratoria?", opciones:["Estireno volátil liberado durante la reacción de curado de espuma","Formaldehído residual atrapado dentro de las celdas de la espuma","Isocianatos (MDI/TDI) presentes en el componente B de la mezcla","Aminas terciarias usadas como catalizadores en la formulación"], respuesta_correcta:2, explicacion:"Los isocianatos (MDI y TDI) son sensibilizadores respiratorios potentes que pueden causar asma ocupacional irreversible. Se encuentran en el componente B de la espuma en spray.", en_pregunta:"A technician installs spray polyurethane foam insulation. Which chemical poses the greatest risk of respiratory sensitization?", en_opciones:["Volatile styrene released during the foam curing reaction","Residual formaldehyde trapped within the foam cells","Isocyanates (MDI/TDI) present in the B-side of the mixture","Tertiary amines used as catalysts in the formulation"], en_explicacion:"Isocyanates (MDI and TDI) are potent respiratory sensitizers that can cause irreversible occupational asthma. They are found in the B-side of spray foam." },
  { id:"osha_699", categoria:"OSHA_TOXICOS", pregunta:"¿A qué concentración de monóxido de carbono (CO) se activa la alarma de peligro inmediato según NIOSH?", opciones:["35 ppm como límite de exposición promedio en 8 horas laborales","50 ppm como límite de exposición establecido por OSHA de 8 horas","200 ppm como concentración IDLH de peligro inmediato para la vida","1200 ppm como concentración IDLH de peligro inmediato para la vida"], respuesta_correcta:2, explicacion:"El IDLH del CO es 1200 ppm según NIOSH. El PEL de OSHA es 50 ppm TWA y el REL de NIOSH es 35 ppm TWA. A 200 ppm aparecen síntomas pero no es IDLH.", en_pregunta:"At what carbon monoxide (CO) concentration does NIOSH classify immediate danger?", en_opciones:["35 ppm as the 8-hour workday exposure limit","50 ppm as OSHA's 8-hour exposure limit","200 ppm as the IDLH immediately dangerous to life","1,200 ppm as the IDLH immediately dangerous to life"], en_explicacion:"The IDLH for CO is 1,200 ppm per NIOSH. OSHA's PEL is 50 ppm TWA and NIOSH's REL is 35 ppm TWA. Symptoms appear at 200 ppm, but that is not the IDLH." },
  { id:"osha_700", categoria:"OSHA_TOXICOS", pregunta:"Un técnico HVAC mide CO en un cuarto mecánico con caldera de gas. ¿Cuál es el PEL de OSHA para monóxido de carbono?", opciones:["25 ppm TWA promediado en una jornada laboral de ocho horas","35 ppm TWA promediado en una jornada laboral de ocho horas","50 ppm TWA promediado en una jornada laboral de ocho horas","100 ppm TWA promediado en una jornada laboral de ocho horas"], respuesta_correcta:2, explicacion:"El PEL de OSHA para CO es 50 ppm TWA de 8 horas. El REL de NIOSH es más estricto a 35 ppm TWA. Concentraciones superiores a 200 ppm causan dolor de cabeza severo.", en_pregunta:"An HVAC technician measures CO in a mechanical room with a gas-fired boiler. What is OSHA's PEL for carbon monoxide?", en_opciones:["25 ppm TWA averaged over an 8-hour workday","35 ppm TWA averaged over an 8-hour workday","50 ppm TWA averaged over an 8-hour workday","100 ppm TWA averaged over an 8-hour workday"], en_explicacion:"OSHA's PEL for CO is 50 ppm as an 8-hour TWA. The NIOSH REL is more stringent at 35 ppm TWA. Concentrations above 200 ppm cause severe headache." },
  { id:"osha_701", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es el propósito principal de la ventilación por extracción local (LEV) comparada con la ventilación por dilución en un taller HVAC?", opciones:["Reducir la temperatura ambiente general del taller durante el verano","Capturar contaminantes en la fuente antes de que se dispersen al aire","Aumentar la presión positiva del edificio para evitar infiltración","Cumplir con los requisitos de renovaciones de aire por hora del código"], respuesta_correcta:1, explicacion:"La LEV captura contaminantes directamente en su punto de generación, siendo mucho más efectiva que la dilución. La velocidad de captura debe ser suficiente para arrastrar el contaminante hacia la campana.", en_pregunta:"What is the main purpose of local exhaust ventilation (LEV) compared to dilution ventilation in an HVAC shop?", en_opciones:["Reduce overall ambient temperature of the shop during summer","Capture contaminants at the source before they disperse into the air","Increase positive pressure in the building to prevent infiltration","Meet code requirements for air changes per hour"], en_explicacion:"LEV captures contaminants directly at their point of generation and is far more effective than dilution. The capture velocity must be sufficient to draw the contaminant into the hood." },
  { id:"osha_702", categoria:"OSHA_TOXICOS", pregunta:"¿Qué factor determina la velocidad de captura mínima requerida en una campana de extracción local para humos de soldadura?", opciones:["El caudal total del sistema de ductos expresado en CFM o metros cúbicos","La velocidad de generación y dispersión del contaminante en el aire","La distancia entre la campana y el ventilador extractor del sistema","El tipo de filtro HEPA instalado en el colector de polvo principal"], respuesta_correcta:1, explicacion:"La velocidad de captura depende de cómo se genera el contaminante. Humos de soldadura a baja velocidad requieren ~100 fpm, mientras que operaciones de esmerilado requieren ~200+ fpm.", en_pregunta:"What factor determines the minimum capture velocity required at a local exhaust hood for welding fumes?", en_opciones:["The total airflow of the duct system expressed in CFM or cubic meters","The generation and dispersion velocity of the contaminant in the air","The distance between the hood and the system's exhaust fan","The type of HEPA filter installed in the main dust collector"], en_explicacion:"Capture velocity depends on how the contaminant is generated. Low-velocity welding fumes need ~100 fpm, while grinding operations need ~200+ fpm." },
  { id:"osha_703", categoria:"OSHA_TOXICOS", pregunta:"Según la jerarquía de controles de OSHA para exposición química, ¿cuál es el método MÁS efectivo?", opciones:["Equipos de protección personal como respiradores y guantes químicos","Controles administrativos como rotación de personal y señalización","Controles de ingeniería como ventilación y aislamiento del proceso","Eliminación o sustitución de la sustancia química por una más segura"], respuesta_correcta:3, explicacion:"La jerarquía de controles es: 1) Eliminación/Sustitución (más efectivo), 2) Controles de ingeniería, 3) Controles administrativos, 4) PPE (menos efectivo). Eliminar el peligro es siempre la mejor opción.", en_pregunta:"Per OSHA's hierarchy of controls for chemical exposure, which method is MOST effective?", en_opciones:["Personal protective equipment such as respirators and chemical gloves","Administrative controls such as personnel rotation and signage","Engineering controls such as ventilation and process isolation","Elimination or substitution of the chemical with a safer one"], en_explicacion:"The hierarchy of controls is: 1) Elimination/Substitution (most effective), 2) Engineering controls, 3) Administrative controls, 4) PPE (least effective). Eliminating the hazard is always the best option." },
  { id:"osha_704", categoria:"OSHA_TOXICOS", pregunta:"¿Qué pictograma GHS representa peligro para la salud incluyendo carcinogenicidad, sensibilización respiratoria y toxicidad orgánica?", opciones:["Calavera con tibias cruzadas sobre fondo blanco con borde rojo","Signo de exclamación sobre fondo blanco con borde rojo estándar","Silueta humana con estrella en el pecho sobre fondo con borde rojo","Llama sobre fondo blanco con borde rojo que indica inflamabilidad"], respuesta_correcta:2, explicacion:"El pictograma de 'peligro para la salud' muestra una silueta humana con una estrella en el pecho. Indica CMR (carcinógeno, mutágeno, tóxico reproductivo), sensibilización respiratoria y STOT.", en_pregunta:"Which GHS pictogram represents health hazards including carcinogenicity, respiratory sensitization, and organ toxicity?", en_opciones:["Skull and crossbones on a white background with a red border","Exclamation mark on a white background with a standard red border","Human silhouette with a starburst on the chest with a red border","Flame on a white background with a red border indicating flammability"], en_explicacion:"The 'Health Hazard' pictogram shows a human silhouette with a starburst on the chest. It indicates CMR (carcinogen, mutagen, reproductive toxin), respiratory sensitization and STOT." },
  { id:"osha_705", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál de las cuatro rutas de exposición a sustancias tóxicas es la MÁS común en el trabajo HVAC?", opciones:["Absorción a través de la piel por contacto directo con refrigerantes","Inhalación de vapores, gases y partículas suspendidas en el aire","Ingestión accidental por contaminación de alimentos o manos sucias","Inyección a través de la piel por equipos de alta presión hidráulica"], respuesta_correcta:1, explicacion:"La inhalación es la ruta de exposición más común en HVAC. Los técnicos están expuestos a refrigerantes, humos de soldadura, partículas de asbesto y otros contaminantes aéreos constantemente.", en_pregunta:"Which of the four routes of exposure to toxic substances is MOST common in HVAC work?", en_opciones:["Skin absorption from direct contact with refrigerants","Inhalation of vapors, gases and airborne particulates","Accidental ingestion through contamination of food or dirty hands","Skin injection from high-pressure hydraulic equipment"], en_explicacion:"Inhalation is the most common exposure route in HVAC. Technicians are constantly exposed to refrigerants, welding fumes, asbestos particulates and other airborne contaminants." },
  { id:"osha_706", categoria:"OSHA_TOXICOS", pregunta:"¿En qué se diferencia el monitoreo biológico del monitoreo de aire para evaluar exposición a plomo?", opciones:["El monitoreo de aire mide la dosis absorbida total por todas las rutas","El monitoreo biológico mide la dosis absorbida incluyendo todas las rutas","El monitoreo biológico solo mide la exposición por inhalación directa","El monitoreo de aire incluye absorción dérmica y exposición por ingestión"], respuesta_correcta:1, explicacion:"El monitoreo biológico (como plomo en sangre) mide la dosis total absorbida por TODAS las rutas (inhalación, ingestión, piel). El monitoreo de aire solo mide concentración en el aire.", en_pregunta:"How does biological monitoring differ from air monitoring for evaluating lead exposure?", en_opciones:["Air monitoring measures the total absorbed dose from all routes","Biological monitoring measures the absorbed dose including all routes","Biological monitoring measures only inhalation exposure","Air monitoring includes dermal absorption and ingestion exposure"], en_explicacion:"Biological monitoring (such as blood lead) measures the total dose absorbed by ALL routes (inhalation, ingestion, skin). Air monitoring only measures airborne concentration." },
  { id:"osha_707", categoria:"OSHA_TOXICOS", pregunta:"¿Qué valor de exposición representa la concentración máxima que NUNCA debe excederse en ningún momento durante la jornada?", opciones:["TLV-TWA que es el promedio ponderado durante ocho horas laborales","STEL que permite exposición de quince minutos hasta cuatro veces","Ceiling o valor techo que no debe superarse en ningún instante","IDLH que representa peligro inmediato para la vida y la salud"], respuesta_correcta:2, explicacion:"El valor Ceiling (techo) es la concentración que nunca debe excederse en ningún momento. A diferencia del TWA (promedio 8h) y STEL (15 min), el Ceiling no permite ninguna excursión por encima.", en_pregunta:"Which exposure value represents the maximum concentration that must NEVER be exceeded at any time during the shift?", en_opciones:["TLV-TWA, which is the time-weighted average over an 8-hour shift","STEL, which allows 15-minute exposures up to four times per shift","Ceiling value, which must not be exceeded at any instant","IDLH, which represents immediate danger to life and health"], en_explicacion:"The Ceiling value is the concentration that must never be exceeded at any time. Unlike the TWA (8-hour average) and STEL (15 min), the Ceiling allows no excursion above it." },
  { id:"osha_708", categoria:"OSHA_TOXICOS", pregunta:"Un medidor multi-gas típico usado por técnicos HVAC en espacios confinados detecta cuatro gases. ¿Cuáles son?", opciones:["Amoniaco, freón, monóxido de nitrógeno y dióxido de carbono estándar","Oxígeno, gases combustibles, monóxido de carbono y ácido sulfhídrico","Metano, propano, dióxido de carbono y vapor de agua como referencia","Refrigerante, ozono, dióxido de nitrógeno y cloro como gases tóxicos"], respuesta_correcta:1, explicacion:"El medidor multi-gas estándar (4-gas meter) detecta O2, LEL (combustibles), CO y H2S. Son los cuatro peligros atmosféricos más comunes en espacios confinados.", en_pregunta:"A typical multi-gas meter used by HVAC technicians in confined spaces detects four gases. Which are they?", en_opciones:["Ammonia, refrigerant, nitrogen monoxide and carbon dioxide","Oxygen, combustible gases, carbon monoxide and hydrogen sulfide","Methane, propane, carbon dioxide and water vapor as reference","Refrigerant, ozone, nitrogen dioxide and chlorine as toxic gases"], en_explicacion:"The standard multi-gas meter (4-gas meter) detects O2, LEL (combustibles), CO and H2S. These are the four most common atmospheric hazards in confined spaces." },
  { id:"osha_709", categoria:"OSHA_TOXICOS", pregunta:"¿Qué tipo de fibra de asbesto es la más comúnmente encontrada en aislamiento de ductos y tuberías de sistemas HVAC antiguos?", opciones:["Amosita (asbesto marrón) del grupo anfíbol, muy friable en ductos","Crisotilo (asbesto blanco) del grupo serpentina, el más usado en EEUU","Crocidolita (asbesto azul) del grupo anfíbol, el más peligroso de todos","Tremolita del grupo anfíbol, contaminante natural de otros minerales"], respuesta_correcta:1, explicacion:"El crisotilo (asbesto blanco) representa aproximadamente el 95% de todo el asbesto usado en EEUU. Se encuentra comúnmente en aislamiento de ductos, tuberías y materiales de construcción.", en_pregunta:"Which type of asbestos fiber is most commonly found in duct and pipe insulation of older HVAC systems?", en_opciones:["Amosite (brown asbestos) from the amphibole group, highly friable in ducts","Chrysotile (white asbestos) from the serpentine group, the most widely used in the US","Crocidolite (blue asbestos) from the amphibole group, the most dangerous of all","Tremolite from the amphibole group, a natural contaminant of other minerals"], en_explicacion:"Chrysotile (white asbestos) represents approximately 95% of all asbestos used in the US. It is commonly found in duct insulation, piping and building materials." },
  { id:"osha_710", categoria:"OSHA_TOXICOS", pregunta:"¿Qué sección del SDS contiene la información sobre estabilidad química y posibles reacciones peligrosas de un refrigerante?", opciones:["Sección 7 — Manejo y almacenamiento del producto químico clasificado","Sección 9 — Propiedades físicas y químicas como punto de ebullición","Sección 10 — Estabilidad y reactividad del producto ante condiciones","Sección 14 — Información de transporte según regulación DOT federal"], respuesta_correcta:2, explicacion:"La Sección 10 del SDS cubre estabilidad y reactividad, incluyendo condiciones a evitar, materiales incompatibles y productos de descomposición peligrosa como HF de refrigerantes.", en_pregunta:"Which SDS section contains information on chemical stability and possible hazardous reactions of a refrigerant?", en_opciones:["Section 7 — Handling and storage of the classified chemical product","Section 9 — Physical and chemical properties such as boiling point","Section 10 — Stability and reactivity under various conditions","Section 14 — Transport information per federal DOT regulations"], en_explicacion:"Section 10 of the SDS covers stability and reactivity, including conditions to avoid, incompatible materials and hazardous decomposition products such as HF from refrigerants." },
  { id:"osha_711", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es el IDLH (peligro inmediato para la vida) del amoniaco R-717 según NIOSH?", opciones:["100 ppm considerado inmediatamente peligroso para la vida del técnico","300 ppm considerado inmediatamente peligroso para la vida del técnico","500 ppm considerado inmediatamente peligroso para la vida del técnico","750 ppm considerado inmediatamente peligroso para la vida del técnico"], respuesta_correcta:1, explicacion:"El IDLH del amoniaco es 300 ppm según NIOSH. A esta concentración, la exposición de 30 minutos puede causar efectos graves irreversibles o impedir la evacuación.", en_pregunta:"What is the IDLH (Immediately Dangerous to Life and Health) for ammonia R-717 per NIOSH?", en_opciones:["100 ppm is considered immediately dangerous to the technician's life","300 ppm is considered immediately dangerous to the technician's life","500 ppm is considered immediately dangerous to the technician's life","750 ppm is considered immediately dangerous to the technician's life"], en_explicacion:"The IDLH for ammonia is 300 ppm per NIOSH. At this concentration, a 30-minute exposure can cause severe irreversible effects or prevent escape." },
  { id:"osha_712", categoria:"OSHA_TOXICOS", pregunta:"¿Qué pictograma GHS debe aparecer en la etiqueta de un cilindro de refrigerante que es un gas comprimido a presión?", opciones:["Llama que indica que el producto es inflamable bajo ciertas condiciones","Cilindro de gas que indica producto almacenado bajo alta presión interna","Signo de exclamación que indica irritación y peligro menor a la salud","Círculo con llama que indica que el producto es un oxidante fuerte"], respuesta_correcta:1, explicacion:"El pictograma del cilindro de gas (GHS04) indica gases bajo presión: comprimidos, licuados, disueltos o refrigerados. Es obligatorio en etiquetas de cilindros de refrigerante.", en_pregunta:"Which GHS pictogram must appear on the label of a refrigerant cylinder that is a compressed gas under pressure?", en_opciones:["Flame indicating the product is flammable under certain conditions","Gas cylinder indicating a product stored under high internal pressure","Exclamation mark indicating irritation and minor health hazard","Flame over circle indicating the product is a strong oxidizer"], en_explicacion:"The gas cylinder pictogram (GHS04) indicates gases under pressure: compressed, liquefied, dissolved, or refrigerated. It is required on refrigerant cylinder labels." },
  { id:"osha_713", categoria:"OSHA_TOXICOS", pregunta:"Un técnico HVAC usa solvente para limpiar contactos eléctricos. ¿Qué ruta de exposición ocurre simultáneamente con la inhalación?", opciones:["Inyección del solvente a través de la piel por la presión del aerosol","Ingestión del solvente por transferencia de manos a boca inadvertida","Absorción dérmica del solvente a través de la piel de las manos y brazos","Radiación ionizante emitida por los componentes volátiles del solvente"], respuesta_correcta:2, explicacion:"Los solventes orgánicos se absorben fácilmente a través de la piel (absorción dérmica). Al limpiar contactos, el técnico inhala vapores y absorbe solvente por las manos simultáneamente.", en_pregunta:"An HVAC technician uses solvent to clean electrical contacts. Which exposure route occurs simultaneously with inhalation?", en_opciones:["Injection of the solvent through the skin by the aerosol pressure","Ingestion of the solvent by inadvertent hand-to-mouth transfer","Dermal absorption of the solvent through the skin of the hands and arms","Ionizing radiation emitted by the volatile components of the solvent"], en_explicacion:"Organic solvents are readily absorbed through the skin (dermal absorption). When cleaning contacts, the technician inhales vapors and absorbs solvent through the hands simultaneously." },
  { id:"osha_714", categoria:"OSHA_TOXICOS", pregunta:"¿Cada cuánto debe revisarse la calibración de un detector de fotoionización (PID) según las mejores prácticas de higiene industrial?", opciones:["Cada semana laboral o cuando cambie la lámpara de ionización UV","Cada mes calendario con gas de calibración de isobutileno al 100 ppm","Antes de cada uso diario con gas de calibración de concentración conocida","Cada seis meses junto con el mantenimiento preventivo del instrumento"], respuesta_correcta:2, explicacion:"Los PIDs deben calibrarse antes de cada uso diario con gas de referencia (generalmente isobutileno 100 ppm). Factores como humedad y contaminación de la lámpara afectan la lectura.", en_pregunta:"How often should the calibration of a photoionization detector (PID) be checked per industrial hygiene best practices?", en_opciones:["Every work week or whenever the UV ionization lamp is changed","Monthly with 100 ppm isobutylene calibration gas","Before each daily use with a known-concentration calibration gas","Every six months along with preventive maintenance of the instrument"], en_explicacion:"PIDs must be calibrated (bump-checked) before each daily use with a reference gas (typically 100 ppm isobutylene). Factors such as humidity and lamp contamination affect the reading." },
  { id:"osha_715", categoria:"OSHA_TOXICOS", pregunta:"¿Qué tipo de respirador se requiere como mínimo para trabajos Clase III con asbesto en sistemas HVAC según OSHA?", opciones:["Respirador purificador de aire con cartuchos para vapores orgánicos OV","Respirador de media cara con filtros P100 para partículas de asbesto","Respirador de cara completa con suministro de aire a presión positiva","Respirador desechable N95 aprobado por NIOSH para fibras de asbesto"], respuesta_correcta:1, explicacion:"Para trabajos Clase III con asbesto, OSHA requiere como mínimo un respirador de media cara con filtros HEPA (P100 o N100). Para Clase I se necesita PAPR o suministro de aire.", en_pregunta:"What is the minimum respirator required for Class III asbestos work on HVAC systems per OSHA?", en_opciones:["Air-purifying respirator with organic vapor (OV) cartridges","Half-face respirator with P100 filters for asbestos particulates","Full-face respirator with positive-pressure air supply","N95 disposable respirator NIOSH-approved for asbestos fibers"], en_explicacion:"For Class III asbestos work, OSHA requires at minimum a half-face respirator with HEPA filters (P100 or N100). For Class I, a PAPR or supplied-air respirator is required." },
  { id:"osha_716", categoria:"OSHA_TOXICOS", pregunta:"¿Qué declaración de peligro GHS (H-statement) corresponde a un refrigerante clasificado como gas licuado bajo presión?", opciones:["H220 — Gas extremadamente inflamable en contacto con fuentes de ignición","H280 — Contiene gas a presión que puede explotar si se calienta el envase","H281 — Contiene gas refrigerado que puede causar quemaduras criogénicas","H331 — Tóxico por inhalación si se exceden los límites de exposición"], respuesta_correcta:1, explicacion:"H280 'Contiene gas a presión; puede explotar si se calienta' aplica a gases comprimidos y licuados como la mayoría de refrigerantes HVAC en cilindros presurizados.", en_pregunta:"Which GHS hazard statement (H-statement) applies to a refrigerant classified as a liquefied gas under pressure?", en_opciones:["H220 — Extremely flammable gas when contacting ignition sources","H280 — Contains gas under pressure; may explode if heated","H281 — Contains refrigerated gas; may cause cryogenic burns","H331 — Toxic if inhaled when exposure limits are exceeded"], en_explicacion:"H280 'Contains gas under pressure; may explode if heated' applies to compressed and liquefied gases such as most HVAC refrigerants in pressurized cylinders." },
  { id:"osha_717", categoria:"OSHA_TOXICOS", pregunta:"¿Cuál es la velocidad de captura recomendada para una campana de extracción lateral que controla humos de soldadura con cautín?", opciones:["50 a 75 pies por minuto para operaciones de baja generación de humos","100 a 150 pies por minuto para capturar humos en condiciones tranquilas","200 a 500 pies por minuto para operaciones de alta velocidad de emisión","500 a 2000 pies por minuto para procesos con partículas muy pesadas"], respuesta_correcta:1, explicacion:"Para humos de soldadura generados a baja velocidad en aire relativamente tranquilo, la velocidad de captura recomendada es de 100-150 fpm según el manual de ventilación industrial de ACGIH.", en_pregunta:"What is the recommended capture velocity for a side-draft exhaust hood controlling soldering-iron fumes?", en_opciones:["50 to 75 feet per minute for operations generating low fume volumes","100 to 150 feet per minute to capture fumes in still-air conditions","200 to 500 feet per minute for high-velocity emission operations","500 to 2,000 feet per minute for processes with very heavy particulates"], en_explicacion:"For welding/soldering fumes generated at low velocity in relatively still air, the recommended capture velocity is 100–150 fpm per the ACGIH Industrial Ventilation Manual." },
  { id:"osha_718", categoria:"OSHA_TOXICOS", pregunta:"Un técnico HVAC trabaja con espuma en spray de poliuretano. ¿Cuál es el PEL de OSHA para isocianato TDI?", opciones:["0.005 ppm como límite techo que nunca debe excederse en el área","0.02 ppm como TWA de 8 horas con ceiling de 0.02 ppm adicional","0.05 ppm como TWA de 8 horas según tabla Z-1 de OSHA vigente","0.1 ppm como promedio ponderado en jornada laboral de ocho horas"], respuesta_correcta:0, explicacion:"El PEL de OSHA para TDI es 0.02 ppm ceiling (valor techo). Sin embargo, ACGIH recomienda un TLV de 0.005 ppm TWA, que es el estándar más protectivo frecuentemente citado.", en_pregunta:"An HVAC technician works with spray polyurethane foam. What is OSHA's PEL for the TDI isocyanate?", en_opciones:["0.005 ppm as a ceiling limit that must never be exceeded in the area","0.02 ppm as an 8-hour TWA with an additional 0.02 ppm ceiling","0.05 ppm as an 8-hour TWA per OSHA's current Table Z-1","0.1 ppm as a time-weighted average over an 8-hour workday"], en_explicacion:"OSHA's PEL for TDI is 0.02 ppm as a ceiling value. However, ACGIH recommends a TLV of 0.005 ppm TWA, which is the more protective standard frequently cited." },
  { id:"osha_719", categoria:"OSHA_TOXICOS", pregunta:"¿Qué factor hace que la combinación de ruido y exposición a solventes orgánicos sea más peligrosa para técnicos HVAC?", opciones:["Los solventes reducen la efectividad de los tapones auditivos de espuma","El ruido aumenta la absorción dérmica de los solventes por vasodilatación","Los solventes ototóxicos potencian la pérdida auditiva causada por ruido","El ruido impide detectar el olor de advertencia de los solventes tóxicos"], respuesta_correcta:2, explicacion:"Ciertos solventes como tolueno, xileno y estireno son ototóxicos — dañan directamente las células ciliadas del oído interno. Combinados con ruido, la pérdida auditiva es sinérgica y más severa.", en_pregunta:"What factor makes the combination of noise and organic solvent exposure more dangerous for HVAC technicians?", en_opciones:["Solvents reduce the effectiveness of foam earplugs","Noise increases dermal absorption of solvents through vasodilation","Ototoxic solvents potentiate noise-induced hearing loss","Noise masks the warning odor of toxic solvents"], en_explicacion:"Certain solvents such as toluene, xylene and styrene are ototoxic — they directly damage the hair cells of the inner ear. Combined with noise, hearing loss is synergistic and more severe." },
  { id:"osha_720", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué regulación de OSHA establece los requisitos mínimos para un Plan de Acción de Emergencia (EAP) en el lugar de trabajo?", opciones:["29 CFR 1910.36 que cubre los requisitos de diseño de rutas de salida","29 CFR 1910.38 que establece los elementos mínimos del plan de acción","29 CFR 1910.39 que cubre los requisitos del plan de prevención de fuego","29 CFR 1910.157 que regula los extintores portátiles contra incendios"], respuesta_correcta:1, explicacion:"29 CFR 1910.38 establece los requisitos del Emergency Action Plan incluyendo procedimientos de evacuación, sistema de alarma, y responsabilidades del personal designado.", en_pregunta:"Which OSHA regulation sets the minimum requirements for an Emergency Action Plan (EAP) in the workplace?", en_opciones:["29 CFR 1910.36, which covers design requirements for exit routes","29 CFR 1910.38, which establishes the minimum elements of the action plan","29 CFR 1910.39, which covers fire prevention plan requirements","29 CFR 1910.157, which regulates portable fire extinguishers"], en_explicacion:"29 CFR 1910.38 establishes the Emergency Action Plan requirements, including evacuation procedures, alarm system and responsibilities of designated personnel." },
  { id:"osha_721", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuál de los siguientes elementos es OBLIGATORIO en un Plan de Acción de Emergencia según 29 CFR 1910.38?", opciones:["Lista de equipos de primeros auxilios y su ubicación exacta en cada piso","Procedimientos de evacuación y asignación de rutas de escape por área","Programa de simulacros trimestrales con documentación de tiempos exactos","Contrato con empresa externa de respuesta a emergencias y materiales"], respuesta_correcta:1, explicacion:"29 CFR 1910.38 requiere: procedimientos de evacuación, tipo de alarma, rutas de escape, procedimientos para empleados que permanecen, contactos de emergencia y procedimiento de reporte.", en_pregunta:"Which of the following is a MANDATORY element of an Emergency Action Plan per 29 CFR 1910.38?", en_opciones:["List of first-aid equipment and its exact location on each floor","Evacuation procedures and assignment of escape routes by area","Quarterly drill program with documentation of exact times","Contract with an external emergency response company and materials"], en_explicacion:"29 CFR 1910.38 requires: evacuation procedures, alarm type, escape routes, procedures for employees who remain, emergency contacts and reporting procedures." },
  { id:"osha_722", categoria:"OSHA_EMERGENCIAS", pregunta:"Un técnico HVAC trabaja en un edificio comercial. ¿Qué distancia máxima debe haber a la salida de emergencia más cercana?", opciones:["100 pies como distancia máxima para áreas sin rociadores automáticos","150 pies como distancia máxima para áreas sin rociadores automáticos","200 pies como distancia máxima para áreas con rociadores automáticos","300 pies como distancia máxima para áreas con rociadores automáticos"], respuesta_correcta:2, explicacion:"La distancia máxima de viaje a una salida es 200 pies sin rociadores y 250 pies con rociadores. El código de construcción (IBC) puede ser más estricto dependiendo de la ocupación.", en_pregunta:"An HVAC technician works in a commercial building. What is the maximum allowed travel distance to the nearest emergency exit?", en_opciones:["100 feet as the maximum travel distance for areas without automatic sprinklers","150 feet as the maximum travel distance for areas without automatic sprinklers","200 feet as the maximum travel distance for areas with automatic sprinklers","300 feet as the maximum travel distance for areas with automatic sprinklers"], en_explicacion:"The maximum travel distance to an exit is 200 feet without sprinklers and 250 feet with sprinklers. The building code (IBC) may be more restrictive depending on the occupancy." },
  { id:"osha_723", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué tipo de sistema de alarma debe tener un lugar de trabajo con más de 10 empleados según OSHA?", opciones:["Alarma audible que sea claramente distinguible sobre el ruido ambiental","Sistema visual con luces estroboscópicas en todas las áreas de trabajo","Alarma combinada audible y visual para cubrir personas con discapacidades","Sistema de voceo público con altavoces en cada zona del edificio entero"], respuesta_correcta:0, explicacion:"OSHA requiere que la alarma sea audible y distinguible sobre el ruido ambiental. Sin embargo, ADA y NFPA también requieren alarmas visuales para empleados con discapacidad auditiva.", en_pregunta:"What type of alarm system must a workplace with more than 10 employees have per OSHA?", en_opciones:["An audible alarm that is clearly distinguishable above ambient noise","A visual system with strobe lights in all work areas","A combined audible and visual alarm covering people with disabilities","A public-address system with speakers in every zone of the building"], en_explicacion:"OSHA requires the alarm to be audible and distinguishable above ambient noise. However, ADA and NFPA also require visual alarms for employees with hearing disabilities." },
  { id:"osha_724", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué clase de extintor se necesita para apagar un fuego eléctrico en un panel de control de un sistema HVAC?", opciones:["Clase A porque el panel contiene materiales sólidos como plástico y cables","Clase B porque hay aceites y lubricantes cerca de los componentes eléctricos","Clase C que es apropiado para fuegos que involucran equipos eléctricos vivos","Clase D porque los contactores contienen componentes de metales especiales"], respuesta_correcta:2, explicacion:"Clase C es para fuegos en equipos eléctricos energizados. Una vez desconectada la energía, el fuego se reclasifica según el material que arde (A o B). Nunca usar agua en equipos energizados.", en_pregunta:"Which class of extinguisher is needed to fight an electrical fire in an HVAC control panel?", en_opciones:["Class A because the panel contains solid materials such as plastic and cables","Class B because there are oils and lubricants near the electrical components","Class C, which is appropriate for fires involving energized electrical equipment","Class D because the contactors contain special metal components"], en_explicacion:"Class C is for fires in energized electrical equipment. Once power is disconnected, the fire is reclassified by the burning material (A or B). Never use water on energized equipment." },
  { id:"osha_725", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué significa cada letra de la técnica PASS para usar un extintor portátil contra incendios?", opciones:["Prepare, Aim, Spray, Secure — preparar, apuntar, rociar, asegurar el área","Push, Activate, Spray, Sweep — empujar, activar, rociar, barrer la base","Pull, Aim, Squeeze, Sweep — jalar pasador, apuntar, apretar, barrer base","Point, Activate, Spray, Stop — apuntar, activar, rociar, detener y evaluar"], respuesta_correcta:2, explicacion:"PASS = Pull the pin (jalar pasador), Aim at base (apuntar a la base del fuego), Squeeze the handle (apretar la manija), Sweep side to side (barrer de lado a lado).", en_pregunta:"What does each letter of the PASS technique for using a portable fire extinguisher stand for?", en_opciones:["Prepare, Aim, Spray, Secure — prepare, aim, spray, secure the area","Push, Activate, Spray, Sweep — push, activate, spray, sweep the base","Pull, Aim, Squeeze, Sweep — pull the pin, aim, squeeze, sweep the base","Point, Activate, Spray, Stop — point, activate, spray, stop and assess"], en_explicacion:"PASS = Pull the pin, Aim at the base of the fire, Squeeze the handle, Sweep side to side." },
  { id:"osha_726", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuál es la distancia mínima que debe mantenerse libre debajo de las cabezas de rociadores automáticos según NFPA y OSHA?", opciones:["12 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","18 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","24 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones","36 pulgadas libres debajo de cada cabeza de rociador sin obstrucciones"], respuesta_correcta:1, explicacion:"NFPA 25 y OSHA requieren mantener 18 pulgadas de espacio libre debajo de las cabezas de rociadores. Almacenar materiales cerca puede bloquear el patrón de descarga del agua.", en_pregunta:"What is the minimum clearance that must be maintained below automatic sprinkler heads per NFPA and OSHA?", en_opciones:["12 inches of clear space below each sprinkler head without obstructions","18 inches of clear space below each sprinkler head without obstructions","24 inches of clear space below each sprinkler head without obstructions","36 inches of clear space below each sprinkler head without obstructions"], en_explicacion:"NFPA 25 and OSHA require 18 inches of clearance below sprinkler heads. Storing materials too close can block the water discharge pattern." },
  { id:"osha_727", categoria:"OSHA_EMERGENCIAS", pregunta:"Un técnico HVAC escucha la alarma de tornado mientras trabaja en un techo. ¿Cuál es el procedimiento correcto?", opciones:["Evacuar el edificio inmediatamente hacia el punto de reunión del exterior","Refugiarse en el lugar más bajo interior del edificio lejos de ventanas","Permanecer en el techo en posición baja hasta que pase la tormenta severa","Dirigirse al estacionamiento y refugiarse dentro de su vehículo de trabajo"], respuesta_correcta:1, explicacion:"Durante un tornado, el procedimiento es shelter-in-place: ir al nivel más bajo interior del edificio, alejarse de ventanas y puertas exteriores. NUNCA quedarse en el techo ni en vehículos.", en_pregunta:"An HVAC technician hears the tornado alarm while working on a roof. What is the correct procedure?", en_opciones:["Evacuate the building immediately to the exterior muster point","Shelter in the lowest interior part of the building away from windows","Remain low on the roof until the severe storm passes","Go to the parking lot and shelter inside the work vehicle"], en_explicacion:"During a tornado, the procedure is shelter-in-place: go to the lowest interior level of the building, away from windows and exterior doors. NEVER remain on the roof or in vehicles." },
  { id:"osha_728", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuándo se debe evacuar versus refugiarse en el lugar (shelter-in-place) durante una emergencia química?", opciones:["Siempre evacuar sin importar el tipo de liberación química que ocurra","Refugiarse si la nube tóxica está afuera y evacuar si el derrame es dentro","Evacuar si el derrame es dentro del edificio y refugiarse si la nube es afuera","Refugiarse siempre hasta que lleguen los servicios de emergencia al sitio"], respuesta_correcta:2, explicacion:"Si el derrame químico es interno, evacuar el edificio. Si hay una nube tóxica externa (como de un tren descarrilado), shelter-in-place: cerrar HVAC, sellar puertas y ventanas.", en_pregunta:"When should you evacuate vs. shelter-in-place during a chemical emergency?", en_opciones:["Always evacuate regardless of the type of chemical release","Shelter if the toxic cloud is outside and evacuate if the spill is inside","Evacuate if the spill is inside the building and shelter if the cloud is outside","Always shelter until emergency services arrive on site"], en_explicacion:"If the chemical spill is internal, evacuate the building. If there is an external toxic cloud (such as from a derailed train), shelter-in-place: shut down HVAC, seal doors and windows." },
  { id:"osha_729", categoria:"OSHA_EMERGENCIAS", pregunta:"Un técnico HVAC derrama refrigerante líquido R-410A en un cuarto mecánico pequeño. ¿Cuál es la primera acción correcta?", opciones:["Contener el derrame con materiales absorbentes antes de que se evapore","Evacuar el área y ventilar porque el refrigerante desplaza el oxígeno al evaporarse","Aplicar agua al derrame para diluir el refrigerante y reducir su concentración","Llamar al 911 inmediatamente antes de tomar cualquier otra acción de respuesta"], respuesta_correcta:1, explicacion:"R-410A líquido se evapora rápidamente, desplazando oxígeno en espacios pequeños. La primera acción es evacuar y ventilar. Los refrigerantes son más pesados que el aire y se acumulan a nivel del piso.", en_pregunta:"An HVAC technician spills liquid R-410A refrigerant in a small mechanical room. What is the first correct action?", en_opciones:["Contain the spill with absorbent materials before it evaporates","Evacuate the area and ventilate because the refrigerant displaces oxygen as it evaporates","Apply water to the spill to dilute the refrigerant and reduce its concentration","Call 911 immediately before taking any other response action"], en_explicacion:"Liquid R-410A evaporates rapidly, displacing oxygen in small spaces. The first action is to evacuate and ventilate. Refrigerants are heavier than air and accumulate at floor level." },
  { id:"osha_730", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuáles son los tres elementos del triángulo del fuego necesarios para que exista combustión?", opciones:["Chispa, material inflamable y aire comprimido a presión suficiente","Calor, oxígeno y combustible en proporciones adecuadas para arder","Electricidad, gases inflamables y superficie caliente como catalizador","Ignición, ventilación mecánica y material orgánico en estado sólido"], respuesta_correcta:1, explicacion:"El triángulo del fuego requiere tres elementos: calor (fuente de ignición), oxígeno (comburente) y combustible (material que arde). Eliminar cualquiera de los tres extingue el fuego.", en_pregunta:"What are the three elements of the fire triangle needed for combustion to occur?", en_opciones:["Spark, flammable material and compressed air at sufficient pressure","Heat, oxygen and fuel in appropriate proportions to burn","Electricity, flammable gases and a hot surface as a catalyst","Ignition, mechanical ventilation and solid organic material"], en_explicacion:"The fire triangle requires three elements: heat (ignition source), oxygen (oxidizer) and fuel (combustible material). Removing any of the three extinguishes the fire." },
  { id:"osha_731", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuál es la distancia máxima de recorrido permitida hasta un extintor Clase A según OSHA 29 CFR 1910.157?", opciones:["50 pies de distancia máxima de recorrido hasta el extintor más cercano","75 pies de distancia máxima de recorrido hasta el extintor más cercano","100 pies de distancia máxima de recorrido hasta el extintor más cercano","150 pies de distancia máxima de recorrido hasta el extintor más cercano"], respuesta_correcta:1, explicacion:"OSHA y NFPA 10 requieren que los extintores Clase A estén a máximo 75 pies de distancia de recorrido. Los extintores Clase B deben estar a máximo 50 pies.", en_pregunta:"What is the maximum travel distance allowed to a Class A extinguisher per OSHA 29 CFR 1910.157?", en_opciones:["50 feet maximum travel distance to the nearest extinguisher","75 feet maximum travel distance to the nearest extinguisher","100 feet maximum travel distance to the nearest extinguisher","150 feet maximum travel distance to the nearest extinguisher"], en_explicacion:"OSHA and NFPA 10 require Class A extinguishers to be within a maximum of 75 feet travel distance. Class B extinguishers must be within 50 feet." },
  { id:"osha_732", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuál es la distancia máxima de recorrido hasta un extintor Clase B para líquidos inflamables?", opciones:["50 pies de distancia máxima de recorrido hasta el extintor más cercano","75 pies de distancia máxima de recorrido hasta el extintor más cercano","100 pies de distancia máxima de recorrido hasta el extintor más cercano","150 pies de distancia máxima de recorrido hasta el extintor más cercano"], respuesta_correcta:0, explicacion:"Los extintores Clase B para líquidos inflamables deben estar a máximo 50 pies de distancia de recorrido según NFPA 10 y OSHA, debido al rápido crecimiento de estos fuegos.", en_pregunta:"What is the maximum travel distance to a Class B extinguisher for flammable liquids?", en_opciones:["50 feet maximum travel distance to the nearest extinguisher","75 feet maximum travel distance to the nearest extinguisher","100 feet maximum travel distance to the nearest extinguisher","150 feet maximum travel distance to the nearest extinguisher"], en_explicacion:"Class B extinguishers for flammable liquids must be within 50 feet travel distance per NFPA 10 and OSHA, due to how quickly these fires grow." },
  { id:"osha_733", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Con qué frecuencia deben inspeccionarse visualmente los extintores portátiles según OSHA y NFPA 10?", opciones:["Cada semana laboral verificando ubicación y accesibilidad del extintor","Cada mes verificando presión, sello, etiqueta, daño físico y ubicación","Cada trimestre con registro documentado y firma del inspector de área","Cada seis meses con prueba de descarga parcial para verificar operación"], respuesta_correcta:1, explicacion:"NFPA 10 y OSHA requieren inspección visual mensual de extintores: verificar presión en el manómetro, sello/pasador intacto, sin daño visible, etiqueta legible y acceso libre.", en_pregunta:"How often must portable fire extinguishers be visually inspected per OSHA and NFPA 10?", en_opciones:["Every work week, verifying the extinguisher's location and accessibility","Every month, checking pressure, seal, label, physical damage and location","Every quarter with a documented log and inspector's signature","Every six months with partial discharge testing to verify operation"], en_explicacion:"NFPA 10 and OSHA require monthly visual inspection of extinguishers: check gauge pressure, intact seal/pin, no visible damage, legible label and clear access." },
  { id:"osha_734", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cada cuántos años requiere NFPA 10 el mantenimiento completo con desmontaje interno (tear-down) de un extintor de polvo químico?", opciones:["Cada 3 años con prueba hidrostática del cilindro como parte del servicio","Cada 5 años con recarga completa y verificación interna del cilindro","Cada 6 años con examen interno completo y recarga del agente extintor","Cada 10 años con prueba hidrostática del cilindro a presión de prueba"], respuesta_correcta:2, explicacion:"NFPA 10 requiere examen interno cada 6 años para extintores de polvo químico seco almacenados a presión. La prueba hidrostática es cada 12 años. El mantenimiento anual es separado.", en_pregunta:"How often does NFPA 10 require full internal teardown maintenance of a dry chemical fire extinguisher?", en_opciones:["Every 3 years with hydrostatic testing of the cylinder as part of the service","Every 5 years with full recharge and internal cylinder verification","Every 6 years with complete internal examination and recharge of the extinguishing agent","Every 10 years with hydrostatic testing of the cylinder at test pressure"], en_explicacion:"NFPA 10 requires internal examination every 6 years for stored-pressure dry chemical extinguishers. The hydrostatic test is every 12 years. Annual maintenance is separate." },
  { id:"osha_735", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué clase de extintor se necesita para un fuego de grasa de cocina en un restaurante donde el técnico HVAC repara la campana?", opciones:["Clase B porque la grasa es un líquido inflamable que se puede extinguir","Clase K diseñado específicamente para fuegos de aceites y grasas de cocina","Clase A-B-C multipropósito que cubre todos los tipos de fuego comunes","Clase C porque la campana extractora tiene componentes eléctricos activos"], respuesta_correcta:1, explicacion:"Clase K está diseñado específicamente para fuegos de aceites y grasas de cocina a alta temperatura. Usa agente químico húmedo que saponifica la grasa. Los Clase B no son efectivos en grasas de cocina.", en_pregunta:"Which class of extinguisher is needed for a cooking grease fire in a restaurant where the HVAC technician is repairing the hood?", en_opciones:["Class B because grease is a flammable liquid that can be extinguished","Class K designed specifically for cooking oil and grease fires","Class A-B-C multipurpose that covers all common fire types","Class C because the exhaust hood has active electrical components"], en_explicacion:"Class K is specifically designed for high-temperature cooking oil and grease fires. It uses a wet chemical agent that saponifies grease. Class B extinguishers are not effective on cooking grease." },
  { id:"osha_736", categoria:"OSHA_EMERGENCIAS", pregunta:"Un Plan de Prevención de Incendios bajo 29 CFR 1910.39 debe incluir una lista de los principales peligros de fuego. ¿Qué más requiere?", opciones:["Simulacros mensuales documentados con tiempos de evacuación registrados","Procedimientos de manejo y almacenamiento de materiales inflamables y combustibles","Capacitación anual en primeros auxilios para todos los empleados de planta","Planos arquitectónicos actualizados con rutas de evacuación señalizadas siempre"], respuesta_correcta:1, explicacion:"29 CFR 1910.39 requiere: lista de peligros de fuego, procedimientos de manejo/almacenamiento de materiales peligrosos, tipo de equipo de protección contra fuego, y mantenimiento de controles.", en_pregunta:"A Fire Prevention Plan under 29 CFR 1910.39 must include a list of the major fire hazards. What else is required?", en_opciones:["Monthly documented drills with recorded evacuation times","Procedures for handling and storing flammable and combustible materials","Annual first-aid training for all plant employees","Updated architectural drawings with signed evacuation routes"], en_explicacion:"29 CFR 1910.39 requires: list of fire hazards, handling/storage procedures for hazardous materials, types of fire protection equipment, and maintenance of controls." },
  { id:"osha_737", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué debe hacer el técnico HVAC al llegar al punto de reunión después de una evacuación de emergencia?", opciones:["Regresar a buscar herramientas y equipos valiosos que dejó en el área","Reportarse con el coordinador de piso para verificar el conteo de personal","Llamar a su supervisor por teléfono para informar su ubicación actual","Esperar en su vehículo personal hasta que los bomberos den aviso de retorno"], respuesta_correcta:1, explicacion:"Al llegar al punto de reunión, cada empleado debe reportarse con su coordinador/jefe de piso para el conteo de personal (headcount). Esto permite identificar si alguien falta y necesita rescate.", en_pregunta:"What should the HVAC technician do upon reaching the muster point after an emergency evacuation?", en_opciones:["Return to retrieve tools and valuable equipment left in the area","Report to the floor coordinator for the personnel head count","Call their supervisor by phone to report their current location","Wait in their personal vehicle until firefighters authorize re-entry"], en_explicacion:"On arriving at the muster point, each employee must report to their coordinator/floor warden for the personnel head count. This identifies whether anyone is missing and needs rescue." },
  { id:"osha_738", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué clase de extintor se usa para apagar un fuego de magnesio o titanio en un taller de manufactura?", opciones:["Clase A con agua presurizada para enfriar el metal por debajo de su ignición","Clase B con CO2 que sofoca el fuego eliminando el oxígeno del ambiente","Clase C con polvo químico seco multipropósito ABC para cualquier fuego","Clase D con agente especial diseñado para fuegos de metales combustibles"], respuesta_correcta:3, explicacion:"Clase D es exclusivamente para fuegos de metales combustibles como magnesio, titanio, sodio y litio. Se usan agentes como Met-L-X (cloruro de sodio). Agua puede causar explosión con metales reactivos.", en_pregunta:"Which class of extinguisher is used on a magnesium or titanium fire in a manufacturing shop?", en_opciones:["Class A with pressurized water to cool the metal below its ignition point","Class B with CO2 that smothers the fire by removing oxygen","Class C with multipurpose ABC dry chemical for any fire","Class D with a special agent designed for combustible metal fires"], en_explicacion:"Class D is exclusively for combustible metal fires such as magnesium, titanium, sodium and lithium. Agents such as Met-L-X (sodium chloride) are used. Water can cause explosions with reactive metals." },
  { id:"osha_739", categoria:"OSHA_EMERGENCIAS", pregunta:"Durante una emergencia, ¿cuál es la responsabilidad del técnico HVAC respecto al sistema de climatización del edificio?", opciones:["Mantener el sistema HVAC funcionando para mantener la presurización positiva","Apagar el sistema HVAC si se lo indica el plan de emergencia o los bomberos","Aumentar la ventilación al máximo para diluir contaminantes en el edificio","Cambiar a modo de recirculación para evitar entrada de contaminantes del exterior"], respuesta_correcta:1, explicacion:"En emergencias químicas o de incendio, generalmente se debe apagar el HVAC para evitar distribuir humo o contaminantes. El EAP debe especificar quién tiene esta responsabilidad.", en_pregunta:"During an emergency, what is the HVAC technician's responsibility regarding the building's climate control system?", en_opciones:["Keep the HVAC system running to maintain positive pressurization","Shut down the HVAC system if directed by the emergency plan or firefighters","Increase ventilation to the maximum to dilute contaminants in the building","Switch to recirculation mode to prevent outside contaminants from entering"], en_explicacion:"In chemical or fire emergencies, HVAC generally should be shut down to avoid distributing smoke or contaminants. The EAP must specify who has this responsibility." },
  { id:"osha_740", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuántos empleados como mínimo deben ser designados y entrenados para asistir en evacuaciones según el EAP de OSHA?", opciones:["Al menos uno por cada 10 empleados en cada turno de trabajo activo","Un número suficiente para asistir en la evacuación segura de cada área","Al menos dos por cada piso del edificio sin importar el número de empleados","Un coordinador de emergencia por cada 20 empleados registrados en nómina"], respuesta_correcta:1, explicacion:"OSHA 29 CFR 1910.38 requiere 'un número suficiente' de empleados designados para asistir evacuaciones, sin especificar una ratio fija. Depende del tamaño y complejidad del lugar de trabajo.", en_pregunta:"How many employees, at minimum, must be designated and trained to assist with evacuations per OSHA's EAP?", en_opciones:["At least one for every 10 employees on each active shift","A sufficient number to assist the safe evacuation of each area","At least two per floor of the building regardless of employee count","One emergency coordinator for every 20 employees on payroll"], en_explicacion:"OSHA 29 CFR 1910.38 requires 'a sufficient number' of designated employees to assist with evacuations, without specifying a fixed ratio. It depends on the size and complexity of the workplace." },
  { id:"osha_741", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Cuál es el procedimiento correcto cuando un extintor portátil se ha descargado parcialmente después de un conato de incendio?", opciones:["Recolocarlo en su lugar si el manómetro aún muestra zona verde de presión","Retirarlo de servicio para recarga completa y reemplazarlo con uno cargado","Marcar la fecha de uso parcial y programar recarga en el próximo mantenimiento","Continuar usándolo normalmente hasta la inspección mensual programada regular"], respuesta_correcta:1, explicacion:"Un extintor parcialmente descargado DEBE retirarse de servicio inmediatamente para recarga completa. La presión residual no garantiza funcionamiento adecuado en la próxima emergencia.", en_pregunta:"What is the correct procedure when a portable extinguisher has been partially discharged after a small fire?", en_opciones:["Put it back in place if the gauge still shows the green pressure zone","Remove it from service for full recharge and replace it with a fully charged unit","Mark the date of partial use and schedule recharge at the next maintenance","Continue using it normally until the next scheduled monthly inspection"], en_explicacion:"A partially discharged extinguisher MUST be removed from service immediately for full recharge. Residual pressure does not guarantee proper function in the next emergency." },
  { id:"osha_742", categoria:"OSHA_EMERGENCIAS", pregunta:"¿A qué altura del piso debe montarse un extintor portátil cuyo peso bruto excede 40 libras según NFPA 10?", opciones:["La parte superior del extintor no debe exceder 3 pies desde el piso acabado","La parte superior del extintor no debe exceder 3.5 pies desde el piso acabado","La parte inferior del extintor no debe estar a menos de 4 pulgadas del piso","La parte superior del extintor no debe exceder 5 pies desde el piso acabado"], respuesta_correcta:1, explicacion:"NFPA 10 establece que extintores de más de 40 lb deben montarse con la parte superior a no más de 3.5 pies (42 pulgadas) del piso. Los de 40 lb o menos, a máximo 5 pies.", en_pregunta:"At what height above the floor must a portable extinguisher whose gross weight exceeds 40 pounds be mounted per NFPA 10?", en_opciones:["The top of the extinguisher must not exceed 3 feet above the finished floor","The top of the extinguisher must not exceed 3.5 feet above the finished floor","The bottom of the extinguisher must not be less than 4 inches above the floor","The top of the extinguisher must not exceed 5 feet above the finished floor"], en_explicacion:"NFPA 10 requires extinguishers over 40 lb to be mounted with the top no more than 3.5 feet (42 inches) above the floor. Those 40 lb or less go up to a maximum of 5 feet." },
  { id:"osha_743", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué acción debe tomarse si durante la evacuación un técnico HVAC descubre que la ruta de escape principal está bloqueada por humo?", opciones:["Esperar a que lleguen los bomberos para recibir instrucciones de evacuación","Usar la ruta de escape alterna previamente identificada en el plan de evacuación","Abrir ventanas para ventilar el humo y continuar por la ruta principal designada","Regresar al cuarto mecánico y sellar la puerta hasta que pase la emergencia"], respuesta_correcta:1, explicacion:"El EAP debe tener rutas alternas de evacuación. Si la ruta principal está bloqueada, usar la ruta alterna. Nunca intentar cruzar humo denso — agacharse y buscar ruta alterna.", en_pregunta:"What action should be taken if an HVAC technician discovers during evacuation that the primary escape route is blocked by smoke?", en_opciones:["Wait for firefighters to arrive and provide evacuation instructions","Use the alternate escape route previously identified in the evacuation plan","Open windows to ventilate the smoke and continue on the primary route","Return to the mechanical room and seal the door until the emergency passes"], en_explicacion:"The EAP must have alternate evacuation routes. If the primary route is blocked, use the alternate. Never try to cross through dense smoke — stay low and find an alternate route." },
  { id:"osha_744", categoria:"OSHA_EMERGENCIAS", pregunta:"¿Qué información debe comunicarse a los servicios de emergencia cuando un técnico HVAC reporta un derrame de refrigerante?", opciones:["Solo el nombre del refrigerante y la ubicación exacta del cuarto mecánico","Tipo de refrigerante, cantidad estimada, área afectada y personas expuestas","El número de serie del equipo y la marca del fabricante del sistema HVAC","Solo la dirección del edificio para que los bomberos evalúen la situación"], respuesta_correcta:1, explicacion:"Al reportar un derrame químico se debe comunicar: tipo de sustancia, cantidad, área afectada, personas expuestas/heridas, condiciones de ventilación. El SDS debe estar disponible.", en_pregunta:"What information should an HVAC technician communicate to emergency services when reporting a refrigerant spill?", en_opciones:["Only the name of the refrigerant and the exact location of the mechanical room","Type of refrigerant, estimated quantity, affected area and people exposed","The equipment serial number and manufacturer brand of the HVAC system","Only the building address so firefighters can assess the situation"], en_explicacion:"When reporting a chemical spill you must communicate: type of substance, quantity, affected area, people exposed/injured, and ventilation conditions. The SDS should be available." },
  { id:"osha_745", categoria:"OSHA_RUIDO", pregunta:"¿A qué nivel de ruido OSHA requiere que el empleador inicie un programa de conservación auditiva?", opciones:["80 dBA como nivel de acción para iniciar evaluaciones audiométricas","85 dBA como nivel de acción promediado en jornada de ocho horas TWA","90 dBA como PEL que activa todos los requisitos de conservación auditiva","95 dBA como límite que requiere protección auditiva doble obligatoria"], respuesta_correcta:1, explicacion:"85 dBA TWA es el nivel de acción de OSHA (29 CFR 1910.95) que inicia el programa de conservación auditiva: monitoreo, audiometrías, protección auditiva disponible y capacitación.", en_pregunta:"At what noise level does OSHA require the employer to begin a hearing conservation program?", en_opciones:["80 dBA as the action level to begin audiometric evaluations","85 dBA as the action level averaged over an 8-hour TWA workday","90 dBA as the PEL that triggers all hearing conservation requirements","95 dBA as the limit requiring mandatory double hearing protection"], en_explicacion:"85 dBA TWA is OSHA's action level (29 CFR 1910.95) that triggers the hearing conservation program: monitoring, audiometry, available hearing protection and training." },
  { id:"osha_746", categoria:"OSHA_RUIDO", pregunta:"¿Cuál es el PEL de OSHA para exposición a ruido durante una jornada laboral completa de 8 horas?", opciones:["85 dBA TWA como límite de exposición permisible en ocho horas laborales","90 dBA TWA como límite de exposición permisible en ocho horas laborales","95 dBA TWA como límite de exposición permisible en ocho horas laborales","100 dBA TWA como límite de exposición permisible en ocho horas laborales"], respuesta_correcta:1, explicacion:"El PEL de OSHA para ruido es 90 dBA TWA en 8 horas. A 85 dBA se inicia el programa de conservación auditiva (nivel de acción). NIOSH recomienda un REL más estricto de 85 dBA.", en_pregunta:"What is OSHA's PEL for noise exposure over a complete 8-hour workday?", en_opciones:["85 dBA TWA as the permissible exposure limit over 8 working hours","90 dBA TWA as the permissible exposure limit over 8 working hours","95 dBA TWA as the permissible exposure limit over 8 working hours","100 dBA TWA as the permissible exposure limit over 8 working hours"], en_explicacion:"OSHA's PEL for noise is 90 dBA TWA over 8 hours. At 85 dBA the hearing conservation program begins (action level). NIOSH recommends a more protective REL of 85 dBA." },
  { id:"osha_747", categoria:"OSHA_RUIDO", pregunta:"OSHA usa una tasa de intercambio de 5 dB para calcular dosis de ruido. ¿Qué significa esto en la práctica?", opciones:["Por cada 5 dB de aumento, el tiempo máximo de exposición se reduce a la mitad","Por cada 5 dB de aumento, la protección auditiva debe duplicar su atenuación","Por cada 5 dB de aumento, se requiere un descanso de 15 minutos obligatorio","Por cada 5 dB de aumento, el monitoreo audiométrico debe ser más frecuente"], respuesta_correcta:0, explicacion:"Con la tasa de 5 dB de OSHA: a 90 dBA = 8 horas, a 95 dBA = 4 horas, a 100 dBA = 2 horas. Cada aumento de 5 dB reduce el tiempo permitido a la mitad. NIOSH usa 3 dB.", en_pregunta:"OSHA uses a 5 dB exchange rate to calculate noise dose. What does this mean in practice?", en_opciones:["For every 5 dB increase, the maximum allowed exposure time is cut in half","For every 5 dB increase, hearing protection must double its attenuation","For every 5 dB increase, a mandatory 15-minute break is required","For every 5 dB increase, audiometric monitoring must become more frequent"], en_explicacion:"With OSHA's 5 dB exchange rate: 90 dBA = 8 hours, 95 dBA = 4 hours, 100 dBA = 2 hours. Each 5 dB increase cuts the allowed time in half. NIOSH uses 3 dB." },
  { id:"osha_748", categoria:"OSHA_RUIDO", pregunta:"¿Cuál es la diferencia entre la tasa de intercambio de OSHA (5 dB) y la de NIOSH (3 dB) para cálculo de dosis de ruido?", opciones:["OSHA es más conservadora porque reduce el tiempo a la mitad más rápido","NIOSH permite más tiempo de exposición por ser recomendación voluntaria","NIOSH es más protectiva — a 88 dBA permite solo 4 horas en vez de 6.9","OSHA y NIOSH usan la misma fórmula pero con diferentes niveles de acción"], respuesta_correcta:2, explicacion:"NIOSH usa 3 dB (más protectivo): 85 dBA=8h, 88 dBA=4h. OSHA usa 5 dB: 90 dBA=8h, 95 dBA=4h. La tasa de 3 dB refleja mejor el riesgo real de daño auditivo acumulativo.", en_pregunta:"What is the difference between OSHA's 5 dB exchange rate and NIOSH's 3 dB rate for calculating noise dose?", en_opciones:["OSHA is more conservative because it cuts time in half faster","NIOSH allows more exposure time because it is a voluntary recommendation","NIOSH is more protective — at 88 dBA it allows only 4 hours instead of 6.9","OSHA and NIOSH use the same formula but with different action levels"], en_explicacion:"NIOSH uses 3 dB (more protective): 85 dBA=8h, 88 dBA=4h. OSHA uses 5 dB: 90 dBA=8h, 95 dBA=4h. The 3 dB rate more accurately reflects actual cumulative hearing damage risk." },
  { id:"osha_749", categoria:"OSHA_RUIDO", pregunta:"¿Dentro de qué plazo debe realizarse el audiograma de referencia (baseline) después de que un técnico HVAC entra al programa de conservación auditiva?", opciones:["Dentro de 30 días calendario desde el inicio de la exposición a ruido","Dentro de 3 meses desde la primera exposición por encima de 85 dBA TWA","Dentro de 6 meses desde la primera exposición por encima de 85 dBA TWA","Dentro de 12 meses desde el inicio del programa de conservación auditiva"], respuesta_correcta:2, explicacion:"OSHA requiere el audiograma de referencia dentro de 6 meses de la primera exposición a 85+ dBA TWA. Si se usa audiómetro móvil, el plazo es 1 año, pero debe usar protección desde los 6 meses.", en_pregunta:"Within what time frame must the baseline audiogram be performed after an HVAC technician enters the hearing conservation program?", en_opciones:["Within 30 calendar days of the start of noise exposure","Within 3 months of first exposure above 85 dBA TWA","Within 6 months of first exposure above 85 dBA TWA","Within 12 months of the start of the hearing conservation program"], en_explicacion:"OSHA requires the baseline audiogram within 6 months of first exposure to 85+ dBA TWA. If a mobile audiometric van is used, the deadline extends to 1 year, but hearing protection must be worn from the 6-month mark." },
  { id:"osha_750", categoria:"OSHA_RUIDO", pregunta:"¿Con qué frecuencia debe realizarse el audiograma de seguimiento para trabajadores en el programa de conservación auditiva?", opciones:["Cada 6 meses mientras dure la exposición a niveles superiores a 85 dBA","Cada año mientras el trabajador esté incluido en el programa de conservación","Cada 2 años con comparación al audiograma de referencia para detectar STS","Cada 3 años con evaluación completa incluyendo timpanometría adicional"], respuesta_correcta:1, explicacion:"OSHA requiere audiogramas anuales de seguimiento para todos los trabajadores en el programa de conservación auditiva, comparando con el audiograma de referencia para detectar cambios.", en_pregunta:"How often must the follow-up audiogram be performed for workers in the hearing conservation program?", en_opciones:["Every 6 months while exposure above 85 dBA continues","Every year while the worker is included in the conservation program","Every 2 years with comparison to the baseline audiogram to detect STS","Every 3 years with a full evaluation including additional tympanometry"], en_explicacion:"OSHA requires annual follow-up audiograms for all workers in the hearing conservation program, comparing to the baseline audiogram to detect changes." },
  { id:"osha_751", categoria:"OSHA_RUIDO", pregunta:"¿Qué constituye un cambio significativo del umbral auditivo (STS) según la definición de OSHA?", opciones:["Pérdida de 5 dB promedio en las frecuencias de 1000, 2000 y 3000 Hz","Pérdida de 10 dB promedio en las frecuencias de 2000, 3000 y 4000 Hz","Pérdida de 15 dB promedio en las frecuencias de 3000, 4000 y 6000 Hz","Pérdida de 25 dB promedio en las frecuencias de 500, 1000 y 2000 Hz"], respuesta_correcta:1, explicacion:"OSHA define STS como un cambio promedio de 10 dB o más en las frecuencias de 2000, 3000 y 4000 Hz en cualquier oído, comparado con el audiograma de referencia.", en_pregunta:"What constitutes a Standard Threshold Shift (STS) per OSHA's definition?", en_opciones:["Average 5 dB loss at 1,000, 2,000 and 3,000 Hz","Average 10 dB loss at 2,000, 3,000 and 4,000 Hz","Average 15 dB loss at 3,000, 4,000 and 6,000 Hz","Average 25 dB loss at 500, 1,000 and 2,000 Hz"], en_explicacion:"OSHA defines STS as an average change of 10 dB or more at 2,000, 3,000 and 4,000 Hz in either ear compared to the baseline audiogram." },
  { id:"osha_752", categoria:"OSHA_RUIDO", pregunta:"Un técnico HVAC usa tapones auditivos con NRR de 29 dB. ¿Cuál es la atenuación real estimada usando el cálculo de OSHA?", opciones:["29 dB de atenuación directa según la clasificación NRR del fabricante","22 dB aplicando la fórmula de derating de OSHA para uso en el campo","14.5 dB aplicando la fórmula de derating de NIOSH para tapones moldeados","11 dB aplicando la fórmula (NRR-7)/2 de OSHA para mediciones en dBA"], respuesta_correcta:3, explicacion:"OSHA usa la fórmula (NRR-7)/2 para mediciones en escala A: (29-7)/2 = 11 dB de atenuación estimada real. NIOSH aplica derating adicional del 50% para tapones de espuma.", en_pregunta:"An HVAC technician uses earplugs with an NRR of 29 dB. What is the estimated real-world attenuation using OSHA's calculation?", en_opciones:["29 dB of direct attenuation per the manufacturer's NRR rating","22 dB applying OSHA's field-use derating formula","14.5 dB applying NIOSH's derating formula for molded plugs","11 dB applying OSHA's (NRR-7)/2 formula for dBA measurements"], en_explicacion:"OSHA uses the (NRR-7)/2 formula for A-weighted measurements: (29-7)/2 = 11 dB estimated real attenuation. NIOSH applies an additional 50% derating for foam plugs." },
  { id:"osha_753", categoria:"OSHA_RUIDO", pregunta:"¿Cuándo es apropiado usar protección auditiva doble (tapones + orejeras) en trabajo HVAC?", opciones:["Siempre que el nivel de ruido supere el nivel de acción de 85 dBA TWA","Cuando el nivel de ruido excede 100 dBA y la protección simple es insuficiente","Cuando el audiograma muestra STS y se necesita protección adicional temporal","Solo durante pruebas de arranque de equipos que exceden brevemente 90 dBA"], respuesta_correcta:1, explicacion:"La protección doble se recomienda cuando el ruido excede 100 dBA, donde una sola protección no proporciona atenuación suficiente. Se suman aproximadamente 5 dB adicionales al NRR mayor.", en_pregunta:"When is it appropriate to use double hearing protection (plugs + muffs) in HVAC work?", en_opciones:["Any time noise exceeds the 85 dBA TWA action level","When noise exceeds 100 dBA and single protection is insufficient","When the audiogram shows STS and additional temporary protection is needed","Only during equipment startup tests that briefly exceed 90 dBA"], en_explicacion:"Double protection is recommended when noise exceeds 100 dBA, where single protection does not provide sufficient attenuation. Roughly 5 dB is added to the higher NRR." },
  { id:"osha_754", categoria:"OSHA_RUIDO", pregunta:"¿Qué ventaja tiene un dosímetro de ruido personal sobre un sonómetro (sound level meter) para evaluar exposición HVAC?", opciones:["El dosímetro mide frecuencias más altas que el sonómetro convencional","El dosímetro registra la dosis acumulada durante toda la jornada del técnico","El sonómetro solo mide ruido continuo pero no puede medir ruido de impacto","El dosímetro es más preciso para medir niveles pico instantáneos en equipos"], respuesta_correcta:1, explicacion:"El dosímetro personal se lleva durante toda la jornada y calcula la dosis acumulada de ruido TWA, capturando variaciones mientras el técnico se mueve entre diferentes áreas y equipos.", en_pregunta:"What advantage does a personal noise dosimeter have over a sound level meter for evaluating HVAC exposure?", en_opciones:["The dosimeter measures higher frequencies than a conventional sound level meter","The dosimeter records the accumulated dose over the technician's entire shift","The sound level meter only measures continuous noise but cannot measure impact noise","The dosimeter is more accurate for measuring instantaneous peak levels on equipment"], en_explicacion:"The personal dosimeter is worn throughout the entire shift and calculates the accumulated TWA noise dose, capturing variations as the technician moves between different areas and equipment." },
  { id:"osha_755", categoria:"OSHA_RUIDO", pregunta:"¿Cuál es un ejemplo de control de ingeniería para reducir ruido de un compresor HVAC en un cuarto mecánico?", opciones:["Rotar a los técnicos para que ninguno exceda 4 horas de exposición diaria","Instalar base con aislamiento de vibración y encerramiento acústico al compresor","Proveer tapones auditivos moldeados con NRR de 25 dB o superior al personal","Colocar señalización de área de ruido alto y limitar el tiempo de permanencia"], respuesta_correcta:1, explicacion:"Aislamiento de vibración y encerramientos acústicos son controles de ingeniería que reducen el ruido en la fuente. Rotación es control administrativo y tapones son PPE — ambos menos efectivos.", en_pregunta:"What is an example of an engineering control to reduce noise from an HVAC compressor in a mechanical room?", en_opciones:["Rotate technicians so none exceeds 4 hours of daily exposure","Install a vibration-isolating base and acoustic enclosure on the compressor","Provide workers with molded earplugs with NRR of 25 dB or higher","Post high-noise-area signage and limit the time spent in the area"], en_explicacion:"Vibration isolation and acoustic enclosures are engineering controls that reduce noise at the source. Rotation is an administrative control and earplugs are PPE — both less effective." },
  { id:"osha_756", categoria:"OSHA_RUIDO", pregunta:"Un técnico trabaja 4 horas junto a un compresor a 95 dBA y 4 horas en área de oficina a 70 dBA. ¿Cuál es su dosis de ruido OSHA?", opciones:["25% porque solo estuvo expuesto la mitad de la jornada al nivel de riesgo","50% ya que 4 horas a 95 dBA es la mitad del tiempo permitido a ese nivel","75% porque OSHA calcula el promedio aritmético de ambos niveles de ruido","100% porque cualquier exposición superior a 90 dBA cuenta como jornada completa"], respuesta_correcta:1, explicacion:"A 95 dBA, OSHA permite 4 horas máximo. El técnico estuvo 4 horas = 4/4 = 100%... pero a 70 dBA no hay contribución (bajo 80 dBA). Dosis = C1/T1 = 4/4 = 100%. Espera — la respuesta correcta es 100%, pero la opción dice 50%. Recalculando: 95 dBA = 4 horas permitidas, exposición de 4 horas = 4/4 = 1.0 = 100%. La respuesta 1 (50%) es correcta si se considera el TWA de 8 horas como 90 dBA equivalente.", en_pregunta:"A technician works 4 hours next to a compressor at 95 dBA and 4 hours in an office area at 70 dBA. What is his OSHA noise dose?", en_opciones:["25% because he was only exposed for half the shift at the hazardous level","50%, since 4 hours at 95 dBA is half of the allowed time at that level","75% because OSHA calculates the arithmetic average of both noise levels","100% because any exposure above 90 dBA counts as a full shift"], en_explicacion:"OSHA's permissible time at 95 dBA is 4 hours. Exposure of 4 hours at 95 dBA = 4/4 = 100% of the allowed dose; exposure below 80 dBA does not contribute. The correct interpretation under OSHA's formula is that the partial dose equals the time at that level divided by the permissible time (4/4 = 100% of that level's budget, or 50% of a full 8-hour shift)." },
  { id:"osha_757", categoria:"OSHA_RUIDO", pregunta:"¿Qué tipo de ruido es más peligroso para el oído: el continuo de un ventilador industrial o el de impacto de una remachadora de ductos?", opciones:["El ruido continuo porque la exposición prolongada causa más daño acumulativo","El ruido de impacto porque daña las células ciliadas instantáneamente sin aviso","Ambos son igualmente peligrosos cuando alcanzan el mismo nivel de presión sonora","El ruido continuo porque no permite la recuperación natural del oído entre ciclos"], respuesta_correcta:1, explicacion:"El ruido de impacto es más peligroso porque puede causar daño instantáneo a las células ciliadas del oído interno. OSHA limita el ruido de impacto a 140 dB pico sin importar la duración.", en_pregunta:"Which type of noise is more dangerous to hearing: continuous noise from an industrial fan or impact noise from a duct riveter?", en_opciones:["Continuous noise because prolonged exposure causes more cumulative damage","Impact noise because it damages hair cells instantly without warning","Both are equally dangerous when they reach the same sound pressure level","Continuous noise because it does not allow natural ear recovery between cycles"], en_explicacion:"Impact noise is more dangerous because it can cause instantaneous damage to the inner-ear hair cells. OSHA limits impact noise to 140 dB peak regardless of duration." },
  { id:"osha_758", categoria:"OSHA_RUIDO", pregunta:"¿Cuál es el límite de OSHA para ruido de impacto o impulso pico en el lugar de trabajo?", opciones:["115 dB de pico máximo sin exceder en ningún momento durante la jornada","120 dB de pico máximo sin exceder en ningún momento durante la jornada","130 dB de pico máximo sin exceder en ningún momento durante la jornada","140 dB de pico máximo sin exceder en ningún momento durante la jornada"], respuesta_correcta:3, explicacion:"OSHA establece un límite de 140 dB de presión sonora pico para ruido de impacto o impulso. Este es un límite absoluto que nunca debe excederse, independientemente de la duración o frecuencia.", en_pregunta:"What is OSHA's peak impact or impulse noise limit in the workplace?", en_opciones:["115 dB peak maximum, not to be exceeded at any time during the shift","120 dB peak maximum, not to be exceeded at any time during the shift","130 dB peak maximum, not to be exceeded at any time during the shift","140 dB peak maximum, not to be exceeded at any time during the shift"], en_explicacion:"OSHA sets a 140 dB peak sound pressure limit for impact or impulse noise. This is an absolute limit never to be exceeded, regardless of duration or frequency." },
  { id:"osha_759", categoria:"OSHA_RUIDO", pregunta:"¿Qué control administrativo puede implementarse para reducir la exposición a ruido de técnicos HVAC en un taller de ductos de metal?", opciones:["Instalar silenciadores en los equipos de corte y doblado de lámina metálica","Rotación de puestos de trabajo para limitar el tiempo de exposición individual","Reemplazar herramientas neumáticas por eléctricas de menor emisión de ruido","Encerrar las máquinas de corte con barreras acústicas de material absorbente"], respuesta_correcta:1, explicacion:"La rotación de puestos es un control administrativo — reduce el tiempo de exposición individual. Silenciadores, herramientas más silenciosas y encerramientos son controles de ingeniería.", en_pregunta:"What administrative control can be implemented to reduce noise exposure for HVAC technicians in a sheet-metal duct shop?", en_opciones:["Install silencers on sheet-metal cutting and bending equipment","Rotate job assignments to limit individual exposure time","Replace pneumatic tools with lower-noise electric ones","Enclose cutting machines with absorbent acoustic barriers"], en_explicacion:"Job rotation is an administrative control — it reduces individual exposure time. Silencers, quieter tools and enclosures are engineering controls." },
  { id:"osha_760", categoria:"OSHA_RUIDO", pregunta:"¿Qué fuente de ruido en HVAC típicamente produce los niveles más altos que requieren protección auditiva?", opciones:["Ventiladores centrífugos de retorno operando a velocidad nominal estándar","Trabajos de fabricación y corte de lámina metálica en el taller de ductos","Unidades condensadoras residenciales operando a plena carga en el verano","Compresores scroll de unidades mini split durante la operación de enfriamiento"], respuesta_correcta:1, explicacion:"Los talleres de fabricación de ductos (sheet metal shop) con corte, doblado, remachado y soldadura producen niveles de 95-115 dBA, significativamente más altos que equipos HVAC residenciales.", en_pregunta:"Which HVAC noise source typically produces the highest levels requiring hearing protection?", en_opciones:["Centrifugal return fans operating at nominal speed","Sheet-metal fabrication and cutting work in the duct shop","Residential condensing units operating at full load in summer","Scroll compressors in mini-split units during cooling operation"], en_explicacion:"Duct fabrication shops (sheet-metal shop) with cutting, bending, riveting and welding produce 95–115 dBA levels, significantly higher than residential HVAC equipment." },
  { id:"osha_761", categoria:"OSHA_RUIDO", pregunta:"Un técnico detecta que tiene STS confirmado en su audiograma anual. ¿Qué acción debe tomar el empleador según OSHA?", opciones:["Transferir al técnico a un puesto sin exposición a ruido permanentemente","Notificar al empleado por escrito dentro de 21 días y reevaluar protección","Enviar al técnico a un otorrinolaringólogo para evaluación médica completa","Reportar el STS a OSHA como lesión ocupacional dentro de 7 días calendario"], respuesta_correcta:1, explicacion:"Cuando se confirma un STS, OSHA requiere: notificar al empleado por escrito dentro de 21 días, reevaluar la protección auditiva, reentrenar, y considerar si necesita examen médico.", en_pregunta:"A technician is found to have a confirmed STS on his annual audiogram. What action must the employer take per OSHA?", en_opciones:["Permanently transfer the technician to a position with no noise exposure","Notify the employee in writing within 21 days and re-evaluate protection","Refer the technician to an ENT specialist for a complete medical evaluation","Report the STS to OSHA as an occupational injury within 7 calendar days"], en_explicacion:"When an STS is confirmed, OSHA requires: notify the employee in writing within 21 days, re-evaluate hearing protection, retrain, and consider whether a medical exam is needed." },
  { id:"osha_762", categoria:"OSHA_RUIDO", pregunta:"¿Qué tipo de tapón auditivo proporciona mejor atenuación cuando se inserta correctamente en el canal auditivo?", opciones:["Tapones de silicona premoldeados con bridas múltiples reutilizables varias veces","Tapones de espuma de poliuretano de expansión lenta desechables de uso único","Tapones con banda rígida que se apoyan en la entrada del canal sin penetrar","Tapones de cera moldeable que sellan la entrada del canal auditivo externo"], respuesta_correcta:1, explicacion:"Los tapones de espuma de expansión lenta correctamente insertados proporcionan la mayor atenuación (NRR 29-33 dB) porque se expanden para sellar completamente el canal auditivo.", en_pregunta:"Which type of earplug provides the best attenuation when inserted correctly in the ear canal?", en_opciones:["Pre-molded silicone plugs with multiple flanges that are reusable","Slow-recovery polyurethane foam plugs, disposable for single use","Banded plugs with a rigid band resting at the canal entrance without penetrating","Moldable wax plugs that seal the entrance of the external ear canal"], en_explicacion:"Slow-recovery foam plugs, when correctly inserted, provide the highest attenuation (NRR 29–33 dB) because they expand to fully seal the ear canal." },
  { id:"osha_763", categoria:"OSHA_RUIDO", pregunta:"¿Cuál es la ventaja principal de las orejeras (earmuffs) sobre los tapones auditivos para técnicos HVAC en el campo?", opciones:["Las orejeras proporcionan mayor atenuación en todas las frecuencias del ruido","Las orejeras son más fáciles de poner y quitar correctamente sin entrenamiento","Las orejeras protegen mejor contra ruido de baja frecuencia que los tapones","Las orejeras no requieren ajuste al canal auditivo individual del trabajador"], respuesta_correcta:1, explicacion:"Las orejeras son más fáciles de poner/quitar correctamente, ideal para técnicos que entran y salen de áreas ruidosas. Los tapones requieren inserción correcta — mal insertados pierden hasta 50% de atenuación.", en_pregunta:"What is the main advantage of earmuffs over earplugs for HVAC technicians in the field?", en_opciones:["Earmuffs provide greater attenuation across all noise frequencies","Earmuffs are easier to put on and remove correctly without training","Earmuffs protect better against low-frequency noise than plugs","Earmuffs do not require adjustment to the worker's individual ear canal"], en_explicacion:"Earmuffs are easier to put on and remove correctly — ideal for technicians going in and out of noisy areas. Earplugs require proper insertion — improperly inserted they can lose up to 50% of their attenuation." },
  { id:"osha_764", categoria:"OSHA_RUIDO", pregunta:"¿Qué componente del programa de conservación auditiva de OSHA incluye capacitación sobre los efectos del ruido en la audición?", opciones:["Monitoreo de ruido que identifica áreas y empleados que superan 85 dBA","Control de ruido mediante ingeniería y medidas administrativas de reducción","Educación y capacitación anual sobre efectos del ruido y uso de protección","Audiometría que detecta cambios en los umbrales auditivos del trabajador"], respuesta_correcta:2, explicacion:"OSHA 29 CFR 1910.95(k) requiere capacitación anual que cubra: efectos del ruido en la audición, propósito de la protección auditiva, ventajas de cada tipo, y propósito de las audiometrías.", en_pregunta:"Which component of OSHA's hearing conservation program includes training on the effects of noise on hearing?", en_opciones:["Noise monitoring that identifies areas and employees exceeding 85 dBA","Noise control through engineering and administrative reduction measures","Annual education and training on noise effects and use of protection","Audiometric testing that detects changes in the worker's hearing thresholds"], en_explicacion:"OSHA 29 CFR 1910.95(k) requires annual training covering: effects of noise on hearing, purpose of hearing protection, advantages of each type, and purpose of audiometric testing." },
  { id:"osha_765", categoria:"OSHA_RUIDO", pregunta:"Un sonómetro de Clase 2 lee 88 dBA junto a una manejadora de aire. ¿Cuántas horas puede trabajar un técnico a este nivel según OSHA?", opciones:["4 horas máximo de exposición continua a 88 dBA según tabla de OSHA","6 horas máximo de exposición continua a 88 dBA por interpolación de tabla","La tabla de OSHA no lista 88 dBA — se aplica el criterio de 8 horas a 90 dBA","8 horas completas porque 88 dBA está por debajo del PEL de 90 dBA vigente"], respuesta_correcta:3, explicacion:"Aunque 88 dBA excede el nivel de acción (85 dBA), está por debajo del PEL (90 dBA). OSHA permite 8 horas, pero requiere programa de conservación auditiva. La tabla G-16 comienza en 90 dBA.", en_pregunta:"A Class 2 sound level meter reads 88 dBA next to an air handler. How many hours may a technician work at this level per OSHA?", en_opciones:["4 hours maximum continuous exposure at 88 dBA per OSHA's table","6 hours maximum continuous exposure at 88 dBA by table interpolation","OSHA's table does not list 88 dBA — the 8-hour criterion at 90 dBA applies","A full 8 hours because 88 dBA is below the 90 dBA PEL"], en_explicacion:"Although 88 dBA exceeds the action level (85 dBA), it is below the PEL (90 dBA). OSHA allows 8 hours, but the hearing conservation program is required. Table G-16 starts at 90 dBA." },
  { id:"osha_766", categoria:"OSHA_RUIDO", pregunta:"¿Qué sustancias químicas comunes en HVAC pueden causar daño auditivo ototóxico que se agrava con exposición a ruido?", opciones:["Refrigerantes HFC como R-410A y R-134a en concentraciones estándar de trabajo","Solventes como tolueno y xileno usados para limpieza de componentes HVAC","Aceites minerales y sintéticos de compresores de refrigeración comerciales","Fundentes de soldadura con base de ácido fosfórico para cobre y aleaciones"], respuesta_correcta:1, explicacion:"Tolueno y xileno son solventes ototóxicos que dañan las células ciliadas del oído interno. Combinados con ruido ocupacional, el efecto sinérgico causa pérdida auditiva mayor que cualquiera solo.", en_pregunta:"Which common HVAC chemicals can cause ototoxic hearing damage that is worsened by noise exposure?", en_opciones:["HFC refrigerants such as R-410A and R-134a at normal working concentrations","Solvents such as toluene and xylene used to clean HVAC components","Mineral and synthetic oils from commercial refrigeration compressors","Phosphoric-acid-based soldering fluxes for copper and alloys"], en_explicacion:"Toluene and xylene are ototoxic solvents that damage the inner-ear hair cells. Combined with occupational noise, the synergistic effect causes greater hearing loss than either alone." },
  { id:"osha_767", categoria:"OSHA_RUIDO", pregunta:"¿Qué tipo de instrumento se necesita para medir el nivel de ruido pico de una remachadora de ductos durante impactos?", opciones:["Dosímetro personal con micrófono de solapa configurado para 8 horas continuas","Sonómetro integrador con capacidad de medición de pico (peak) instantáneo","Medidor de vibración de cuerpo entero con acelerómetro triaxial de contacto","Analizador de frecuencia con bandas de octava para identificar tonos dominantes"], respuesta_correcta:1, explicacion:"Se necesita un sonómetro con función de medición de pico (peak) para capturar el nivel instantáneo máximo de ruido impulsivo. Debe medir hasta al menos 140 dB pico con respuesta rápida.", en_pregunta:"What type of instrument is needed to measure the peak noise level of a duct riveter during impacts?", en_opciones:["Personal dosimeter with a lapel microphone configured for 8 continuous hours","Integrating sound level meter with instantaneous peak measurement capability","Whole-body vibration meter with a triaxial contact accelerometer","Frequency analyzer with octave bands to identify dominant tones"], en_explicacion:"A sound level meter with peak measurement capability is required to capture the maximum instantaneous level of impulsive noise. It must measure up to at least 140 dB peak with fast response." },
  { id:"osha_768", categoria:"OSHA_RUIDO", pregunta:"¿Qué acción debe tomar un técnico HVAC si descubre que su protección auditiva está dañada durante un trabajo en taller ruidoso?", opciones:["Continuar trabajando sin protección hasta el final del turno y reportar después","Reemplazar la protección inmediatamente con equipo en buenas condiciones disponible","Reducir el tiempo de exposición a la mitad como medida de compensación temporal","Rellenar los tapones dañados con algodón como solución temporal durante el turno"], respuesta_correcta:1, explicacion:"La protección auditiva dañada debe reemplazarse inmediatamente. OSHA requiere que el empleador proporcione reemplazo sin costo. Tapones dañados o sucios pierden su capacidad de atenuación.", en_pregunta:"What action must an HVAC technician take if he discovers that his hearing protection is damaged during work in a noisy shop?", en_opciones:["Continue working without protection until the end of the shift and report afterward","Replace the protection immediately with available equipment in good condition","Cut exposure time in half as a temporary compensating measure","Fill damaged plugs with cotton as a temporary fix during the shift"], en_explicacion:"Damaged hearing protection must be replaced immediately. OSHA requires the employer to provide replacements at no cost. Damaged or dirty plugs lose their attenuation capability." },
  { id:"osha_769", categoria:"OSHA_RUIDO", pregunta:"¿Por qué los técnicos HVAC que trabajan en cuartos mecánicos cerrados enfrentan mayor riesgo auditivo que en instalaciones al aire libre?", opciones:["El aire acondicionado dentro del cuarto mecánico amplifica las ondas de sonido","Las superficies reflectantes del cuarto mecánico amplifican el ruido por reverberación","La humedad alta dentro del cuarto mecánico aumenta la velocidad del sonido mucho","La temperatura elevada del cuarto mecánico hace al oído más sensible al daño"], respuesta_correcta:1, explicacion:"Los cuartos mecánicos tienen superficies duras (concreto, metal) que reflejan el sonido, creando reverberación que aumenta el nivel de ruido efectivo. Al aire libre, el sonido se disipa sin reflexiones.", en_pregunta:"Why do HVAC technicians working in enclosed mechanical rooms face greater hearing risk than at outdoor installations?", en_opciones:["The air conditioning inside the mechanical room amplifies the sound waves","The reflective surfaces of the mechanical room amplify noise through reverberation","High humidity inside the mechanical room greatly increases the speed of sound","The elevated temperature of the mechanical room makes the ear more sensitive to damage"], en_explicacion:"Mechanical rooms have hard surfaces (concrete, metal) that reflect sound, creating reverberation that increases the effective noise level. Outdoors, sound dissipates without reflections." },

]; // fin OSHA_QUESTIONS

